window.__D("text/tikkunei-zohar/c003",{"p":[[9500011133,"<p>ערב ויהי בקר יום הששי, דהאי) ה' דְהַשִּׁשִּׁי אִיהוּ מַלְכוּת שְׁבִיעָאָה, וְאִיהִי אִתְקְרִיאַת ע\"ב, וּבָהּ רְכִיב ו' לְמִפְרַק לְיִשְׂרָאֵל, הֲדָא הוּא דִכְתִיב (ישעיה יט א) הִנֵּה יהו\"ה רוֹכֵב עַל עָ\"ב קַל, בְּגִין דְּאִיהִי כְּלָלָא דִתְלַת אֲבָהָן, דְּתַלְיָין מִנְּהוֹן ע\"ב שְׁמָהָן, וְאִתְכְּלִילָן בָּהּ, וְלָקֳבֵל תְּלַת אֲבָהָן אִתְּמַר בְּוַיְכֻלּוּ תְּלַת זִמְנִין שְׁבִיעִי, וְדָא אִיהִי רָזָא דְשַׁבָּ\"ת, בַּ\"ת ש, דְּאִינוּן וַיִּסַּע וַיָּבֹא וַיֵּט דְּאִתְכְּלִילָן בְּבַ\"ת, בְּהַהִיא זִמְנָא חָלָה זְכוּת אֲבָהָן, דְּמִיּוֹמָא דְאִתְחֲרִיב בֵּי מַקְדְּשָׁא עָלְמָא אִתְקְרִי תֹהוּ וָבֹהוּ, מִתַּמָּן וְאֵילֵךְ אִתְקַיַּים קְרָא (תהלים פט ג) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה, חֶסֶ\"ד סְלִיק לְחוּשְׁבַּן ע\"ב שְׁמָהָן.</p>\n<p>וְדָא רָזָא דְאִתְקַשַּׁר שְׁבִיעִי בְּיוֹמָא קַדְמָאָה, וּמָאן שְׁבִיעִי דָּא צַדִּיק אוֹת דְּשַׁבָּת וְיוֹמִין טָבִין, וְרָזָא דְמִלָּה חַי יהו\"ה שִׁכְבִי עַד הַבֹּקֶר (רות ג יג), וְדָא בֹּקֶר דְּאַבְרָהָם, הַהוּא דְאִתְּמַר בֵּיהּ (בראשית יט כז) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר, וְאִיהוּ חֶסֶד דִּילֵיהּ, בְּגִין דִּבְהַאי חֶסֶד אִתְתַּקַּן כָּרְסַיָּיא דְאִיהִי נְפִילָה, הֲדָא הוּא דִכְתִיב (ישעיה טז ה) וְהוּכַן בַּחֶסֶד כִּסֵּא, וּבֵיהּ תָּקוּם, וְרָזָא דְמִלָּה וּבְחֶסֶד עוֹלָם רִחַמְתִּיךְ (שם נד ח), וְכָל סְפִירָן מִתְקַשְּׁרִין בִּימִינָא, בְּגִין דַּעֲלֵיהּ אִתְּמַר (דברים לג ב) מִימִינוֹ אֵשׁ דָּת לָמוֹ, מִימִינָא אִתְיַיהִיב אוֹרַיְיתָא, בְּגִין דָּא מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ, וּבוֹקֵעַ מַיִם (ישעיהו סג יב) דְּאוֹרַיְיתָא מִתַּמָּן, מִה' דְאַבְרָהָם, לְמֶהֱוִי לֵיהּ בָּהּ שֵׁם עוֹלָם, וּבָהּ אִשְׁתַּלִּים ה' דְמֹשֶׁה, דְּאִיהִי בְמַשְׁכּוֹנָא לְגַבֵּיהּ דְאַבְרָהָם בְּמֹשֶׁה, דְאַיְיתֵי אוֹרַיְיתָא, עַד דְּיִפְרוֹק לִבְנוֹי, וְרָזָא דְמִלָּה כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת (מיכה ז טו).</p>\n<p>וְרָזָא דְפוּרְקָנָא בְּהַאי חוֹתָמָא אִיהוּ, דַּעֲלֵיהּ אִתְּמַר (ישעיהו נה יב) כִּי בְשִׂמְחָה תֵצֵאוּ וּבְשָׁלוֹם תּוּבָלוּן, בְּשִׂמְחָה סָלִיק לְחוּשְׁבַּן אָדֶ\"ן דְּאִיהוּ אדנ\"י, אֲרוֹן הַבְּרִית אָדוֹן כָּל הָאָרֶץ אִתְקְרֵי, בַּר מֵאָת ש' דְּאִיהוּ תְּלַת מֵאָה, וְאִינוּן תְּלַת אֲבָהָן דְּאִתְחַבְּרוּ בָהּ, וְאַתְוָון בְּשִׂמְחָ\"ה אִיהִי מַחֲשָׁבָ\"ה, ש תְּלַת אֲבָהָן בְּחַמָּה ה\"ן, וְאִיהִי שְׁכִינְתָּא דְלֵית לָהּ יִחוּדָא אֶלָּא בְמִינָהּ, כְּמָה דְאַתְוָותָא דְה\"ן, וְאִתְעֲבִידוּ עֲשָׂרָה וְאִתְעֲבִידוּ מֵאָה, כְּמָה דִשְׁכִינְתָּא כְּלִילָא כֻּלְּהוּ עֲשָׂרָה וְכֻלְּהוּ מֵאָה, וְהַיְינוּ דִכְתִיב (דברים י יד) הֵן לַיהו\"ה אלהי\"ך הַשָּׁמַיִם וּשְׁמֵי הַשָּׁמַיִם, וְרָזָא דְמִלָּה הֵן אדנ\"י.</p>\n<p>וּבְשָׁלוֹם תּוּבָלוּן (ישעיהו נה יב), ש תְּלַת אֲבָהָן, ו\"ו תְּרֵין מְשִׁיחִין, מ' ל\"ב דְּוּבְשָׁלוֹ\"ם סְלִיק ע\"ב, וְדָא אִיהוּ דְאִתְּמַר (בראשית כח כא) וְשַׁבְתִּי בְשָׁלוֹם אֶל בֵּית אָבִי, שִׂמְחָה אִיהוּ דְאִתְּמַר בֵּיהּ (קהלת ט ז) לֵךְ אֱכוֹל בְּשִׂמְחָה לַחְמֶךָ וּשְׁתֵה בְלֶב טוֹב יֵינֶךָ, דָּא יַיִן הַמְשׁוּמָר בַּעֲנָבָיו, וַעֲלֵיהּ אִתְּמַר (תהלים כה יד) סוֹד יהו\"ה לִירֵיאָיו, יַיִן טוֹב דָּא צַדִּיק, דְּאִתְּמַר בֵּיהּ (ישעיה נז א) הַצַּדִּיק אָבָד, וּמַאי אָבָד אָבַד הַהוּא נְבִיעוּ, וְאִשְׁתָּאַר נֶחרַב וְיָבֵשׁ בְּבַיִת רִאשׁוֹן וְשֵׁנִי.</p>\n<p>קָם סָבָא וְאָמַר אדנ\"י בְּמַחֲשָׁבָה סָלְקָא, וְלַאו בְּחֻשְׁבַּן, וַעֲלֵיהּ אִתְּמַר (זכריה ב יז) הַ\"ס כָּל בָּשָׂר מִפְּנֵי יהו\"ה כִּי נֵעוֹר מִמְּעוֹן קָדְשׁוֹ, יִתְעַר בֵּיהּ כְּמָה דְאִתְעַר מִשִּׁנְתֵיהּ וְחָזַר לְשִׁנְתֵיהּ, עַד דְּיִתְעַר יהו\"ה דְּאִיהוּ רַחֲמֵי, לְקַיְימָא בֵּיהּ וּבְרַחֲמִים גְּדוֹלִים אֲקַבְּצֵךְ (ישעיה נד ז), גְּדוֹלִים אִתְקְרִיאַת מִסִּטְרָא דְהָאֵ\"ל הַגָּדוֹל דְּאִיהוּ חֶסֶד, וּשְׁכִינְתָּא בֵּיהּ סָלְקָא לְאִתְקְרֵי גְדוֹלָה, וּבֵיהּ וַדַּאי רָזָא דְפוּרְקָנָא, כְּגַוְונָא דָא יו\"ד ה\"א וא\"ו ה\"א יהו\"ה, וָא\"ו בֵּיהּ רָזָא דְפוּרְקָנָא, דְאִיהוּ רָשִׁים בִּשְׁמָא דְע\"ב, דְּאִינוּן וָה\"וּ אֲנִ\"י וָה\"וּ רֵישֵׁי תֵּיבִין וָא\"ו, תְּלַת עֲשַׂר מְכִילָן דְּרַחֲמֵי דְאוֹרַיְיתָא, דְאִתְיְיהִיבַת מִימִינָא.</p>\n<p>אִשְׁתָּאַר יו\"ד ה\"א ה\"א דְסָלִיק לְחֻשְׁבַּן ל\"ב, וְאִיהוּ ב' מִן בְּרֵאשִׁית ל' לְעִינֵי כָּל יִשְׂרָאֵל, וְעוֹד אִיהוּ ל\"ב אלהי\"ם דְּעוֹבָדָא דִבְּרֵאשִׁית, דַּעֲלֵיהּ אִתְּמַר (ישעיהו סג ד) כִּי יוֹם נָקָם בְּלִבִּי וּשְׁנַת גְּאוּלַי בָּאָה, וּשְׁמָא דְע\"ב אִיהוּ וַיְכֻלּ\"וּ, בֵּיהּ אִשְׁתַּלִּים רָזָא דְפוּרְקָנָא, וַעֲלֵיהּ אִתְּמַר לְלִבִּ\"י גִלִּיתִי דְאִיהוּ חוּשְׁבַּן וַיְכֻלּ\"וּ, וּבֵיהּ אִתְקַיַּים קְרָא (תהלים פט ג) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה, וּכְמָה דְנָפְקוּ מִמִּצְרַיִם בְּרָזָא דְע\"ב שְׁמָהָן, כַּךְ יִפְקוּן בְּהוֹן כַּד יִפְרְקוּן בְּבַתְרַיְיתָא, בְּהַהוּא זִמְנָא חֶסֶד יהו\"ה מָלְאָה הָאָרֶץ (שם לג ה), וַעֲלֵיהּ אִתְּמַר (ישעיהו נד ח) וְחַסְדִּי מֵאִתֵּךְ לֹא יָמוּשׁ, וּבְחֶסֶד עוֹלָם רִחַמְתִּיךְ, וּבְגִין דָּא שַׁבַּח דָּוִד לְקוּדְשָׁא בְּרִיךְ הוּא בְּגָלוּתָא דְאִיהִי שְׁאוֹל בְּהַאי חֶסֶד, כְּמָה דְאַתְּ אָמַר (תהלים פו יג) כִּי חַסְדְּךָ גָּדוֹל עָלָי וְהִצַּלְתָּ נַפְשִׁי מִשְּׁאוֹל תַּחְתִּיָּה.</p>\n<p>וְאִי אוּמִין</p>"],[9500011134,"<p>דְּעָלְמָא דָחֲקִין לְהוּ לְיִשְׂרָאֵל יוֹתֵר מִדַּאי, קוּדְשָׁא בְּרִיךְ הוּא חָס עַל ד' מִן חֶסֶד דְּאִיהִי דָּלֵ\"ת בְּגָלוּתָא, וְאִתְקַיַּים קְרָא בֵיהּ (ישעיה סו ז) בְּטֶרֶם תָּחִיל יָלָדָה, וְשַׁבְעִין תֵּיבִין דְּמִזְמוֹר יַעַנְךָ יהו\"ה בְּיוֹם צָרָה (תהלים כ ב) אִינוּן לָקֳבֵל שִׁבְעִים שָׂרִים, דְּאִינוּן צִירִים וַחֲבָלִים דִּשְׁכִינְתָּא עִלָּאָה וְתַתָּאָה, דְּאַתְוָון ב' בֵּיהּ אִתְקְרִיאָן פַּלְטְרִין גְּדוֹלִים, הֲדָא הוּא דִכְתִיב (תהלים קיא ב) גְּדֹלִים מַעֲשֵׂי יהו\"ה, וְקוּדְשָׁא בְּרִיךְ הוּא בֵּיהּ אִתְקְרִי גָּדוֹל, כְּמָה דְאַתְּ אָמַר (שם קמז ה) גָּדוֹל אֲדוֹנֵינוּ וְרַב כֹּחַ, וּבֵיהּ סָלְקִין יִשְׂרָאֵל לִגְדוּלָה.</p>\n<p>וּשְׁכִינְתָּא בָּהּ אִתְּמַר (שמות לג כא) הִנֵּה מָקוֹם אִתִּי, בְּהַהוּא זִמְנָא אִתְקַיַּים בָּהּ קְרָא (תהלים לד ד) גַּדְּלוּ לַיהו\"ה אִתִּי, וּבָהּ (נ\"א וביה) אִתְּמַר בְּקוּדְשָׁא בְּרִיךְ הוּא בְּהַהוּא זִמְנָא כִּי גָדוֹל אַתָּה וְגוֹמֵר (שם פו י), וּבֵיהּ עוֹשֶׂה גְדוֹלוֹת עַד אֵין חֵקֶר (איוב ט י), וְדָא אִיהוּ חֶסֶ\"ד, בֵּיהּ וַיְכֻלּוּ, ה' בַּשִּׁשִּׁי (נ\"א וביה ויכלו בהששי), בְּגִין דְּבֵיהּ ה' דְאַבְרָהָם אָזִיל ו' לְגַבָּהּ, מִיָּד יִתְעַר י\"ה לִקְרָבָא, הֲדָא הוּא דִכְתִיב (שמות יז טז) כִּי יָד עַל כֵּס י\"ה, וְשִׁשִּׁי אִיהוּ אֶלֶף שְׁתִיתָאָה, שְׁבִיעִי יְסוֹד, בֵּיהּ אִתְכְּלִילוּ וְאִתְיַיחֲדוּ שִׁית סְפִירָן, הֲדָא הוּא דִכְתִיב (בראשית ב א) וַיְכֻלּוּ הַשָּׁמַיִם וְהָאָרֶץ, דָּא קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתָּא, דְאִינוּן ו\"ה, יוֹם הַשִּׁשִּׁי בְּגִין דַּעֲלֵיהּ אִתְּמַר (ד\"ה א כט יא) כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ, וְתַרְגּוּמוֹ דַאֲחִיד בִּשְׁמַיָּא וּבְאַרְעָא, וְדָא אִיהוּ כֹ\"ל, וַעֲלֵיהּ אִתְּמַר (בראשית ב א) וְכָל צְבָאָם, מַאי צְבָאָם תְּרֵי סַמְכֵי קְשׁוֹט.</p>\n<p>וּבֵיהּ אִתְקְרִיאוּ תְּלַת אֲבָהָן שְׁבִיעִיּוֹת, כְּמָה דְאַתְּ אָמַר (שם) וַיְכַל אלהי\"ם בַּיּוֹם הַשְּׁבִיעִי, וַיִּשְׁבּוֹת בַּיּוֹם הַשְּׁבִיעִי, וַיְבָרֶךְ אלהי\"ם אֶת יוֹם הַשְּׁבִיעִי, וַיְבָרֶךְ אוֹתוֹ מִסִּטְרָא דִבְרָכָה, וַיְקַדֵּשׁ אוֹתוֹ מִסִּטְרָא דִקְדוּשָׁה, וַיִּשְׁבּוֹת בּוֹ מִסִּטְרָא דְיִחוּד, וְדָא אִיהוּ וַיְכֻלּוּ, דְאִתְכְּלִילוּ בֵּיהּ תְּלַת אֲבָהָן, דְּאִינוּן בְּרָזָא דִשְׁמָא דְע\"ב, כְּגַוְונָא דְע\"ב תֵּיבִין, גְּבוּרָ\"ה כְּלָלָא דְרי\"ו אַתְוָון דְּאִית בִּשְׁמָא דְע\"ב, עַמּוּדָא דְאֶמְצָעִיתָא דְאִיהוּ ו' כְּלִיל כֹּלָּא, וְדָא אִיהוּ רָזָא (שמות לד ו) וַיַּעֲבֹר יהו\"ה עַל פָּנָיו, ע\"ב רי\"ו יהו\"ה, עַל פָּנָיו מַאי פָּנָיו, אַנְפּוֹי דָּא וָא\"ו י\"ג מְכִילָן דְּרַחֲמֵי, דְאִתְּמַר בְּהוֹן (ישעיהו נד ז) וּבְרַחֲמִים גְּדוֹלִים אֲקַבְּצֵךְ, גְּדוֹלִים וַדַּאי מִסִּטְרָא דְחֶסֶד, דְּאִיהוּ הָאֵ\"ל הַגָּדוֹל.</p>\n<p>וְכֹלָּא אִתְכְּלִיל בַּשְּׁבִיעִית דְּאִיהִי מַלְכוּת, הַ שְׁבִיעִי ה' וַדַּאי בְּכָל שְׁבִיעִיּוֹת כְּלִילָא, וְאִיהִי ה' דְיוֹם הַשִּׁשִּׁי, יוֹם דָּא צַדִּיק, עֲלֵיהּ אִתְּמַר (זכריה יד ט) וְהָיָה יהו\"ה לְמֶלֶךְ עַל כָּל הָאָרֶץ וְגוֹמֵר, אִיהוּ יוֹם הַשִּׁשִּׁי, וְיוֹם הַשְּׁבִיעִי יוֹם דְּכֻלְּהוּ יוֹמִין, וַעֲלֵיהּ אִתְּמַר (רות ג יג) שִׁכְבִי עַד הַבֹּקֶר, וְדָא הוּא בֹּקֶר דְּאַבְרָהָם, דִּכְתִיב (בראשית יט כז) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר, וַיַּשְׁכֵּם לְפוּרְקָנָא, וּבֵיהּ הַבֹּקֶר אוֹר, דְּאִתְּמַר בֵּיהּ (משלי ו כג) וְתוֹרָה אוֹר, וְהַאי אִיהוּ אוֹר דְּאִתְּמַר בֵּיהּ (שמות י כג) וּלְכָל בְּנֵי יִשְׂרָאֵל הָיָה אוֹר, וְאִיהוּ פֶּסַח דְּרוֹעָא יְמִינָא, וּבֵיהּ עֲתִידִין לִיגָאֵל.</p>\n<p>דָּבָר אַחֵר שִׂימֵנִי כַחוֹתָם עַל לִבֶּךָ (שיר ח ו), הַאי קְרָא עַל שְׁכִינְתָּא אִתְּמַר דְּאִיהִי בְגָלוּתָא, חוֹתָם לָא כְּתִיב, אֶלָּא כַחוֹתָם, כְּהַהוּא חוֹתָם דְּגוּשְׁפַּנְקָא דְאִיהִי חוֹתָם אֱמֶת, וּבָהּ (נ\"א ודא) חָתְמֵנוּ לְחַיִּים, וּמַאי נִיהוּ הַאי חוֹתָם דְּבָהּ חַיִּים, אֶלָּא דָא עִץ הַחַיִּים, דְּבֵיהּ בָּנֵי חַיֵּי וּמְזוֹנֵי נָפְקִין, עִץ וַדַּאי הַהוּא דְאִתְּמַר בֵּיהּ עִץ הַחַיִּים מַהֲלַךְ חָמֵשׁ מֵאוֹת שָׁנָה, וְהַאי עִץ אִיהוּ ו', מַהֲלַךְ חָמֵשׁ מֵאוֹת שְׁנִין דָּא ה', הַחַיִּים אִינוּן אַבָּא וְאִימָּא דְאִינוּן י\"ה, י' אִיהוּ חָכְמָה, וּמְנָלָן דְּאִתְקְרֵי חַיִּים, כְּמָה דְאַתְּ אָמַר (קהלת ז יב) וְהַחָכְמָה תְּחַיֶּה בְעָלֶיהָ, ה' בֵּיהּ אִימָּא עִלָּאָה, מְנָא לָן דְּאִתְקְרֵי חַיִּים, כְּמָה דְאַתְּ אָמַר (משלי ג יא) עִץ חַיִּים הִיא וַדַּאי, וְתַרְוַיְיהוּ (שם ד כב) כִּי חַיִּים הֵם לְמוֹצְאֵיהֶם.</p>\n<p>וּשְׁכִינְתָּא תַּתָּאָה אִיהוּ רִישּׁוּמָא בְּהַאי חוֹתָמָא דְאִיהוּ חוֹתָם אֱמֶת, וְכָל צִיּוּרִין דְּהַאי חוֹתָמָא אִינוּן רְשִׁימִין בָּהּ, לְאִשְׁתְּמוֹדְעָא דְאִיהִי צִיּוּרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, דְאִיהוּ אֱמֶת, אָדָם (ס\"א דא איהו) חוֹתָם דִּילֵיהּ יו\"ד ה\"א וא\"ו ה\"א, אִיהוּ חָתִים בֵּיהּ לְחַיִּים, וּמִנֵּיהּ יָרְתִין בְּנֵי יִשְׂרָאֵל בָּנֵי חַיֵּי וּמְזוֹנֵי, חַיֵּי מִסִּטְרָא דְאַבָּא וְאִימָּא דְאִינוּן י\"ה, בָּנֵי מִסִּטְרָא</p>"],[9500011135,"<p>דְעַמּוּדָא דְאֶמְצָעִיתָא, דְעַל (נ\"א ועל) שְׁמֵיהּ אִתְקְרִיאוּ יִשְׂרָאֵל לְתַתָּא בְּנִי בְכֹרִי יִשְׂרָאֵל, וְאִיהוּ ו', מְזוֹנֵי, מִסִּטְרָא דְה' דְאִיהִי הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ, וּבְזִמְנָא דְיָרְתִין מִנֵּיהּ אִלֵּין תְּלַת (נ\"א תרין) דַּרְגִּין דִּכְלִילָן בִּשְׁמֵיהּ, אִתְקְרִיאוּ יִשְׂרָאֵל לְתַתָּא בְּנוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְאַתְּ אָמַר (דברים יד א) בָּנִים אַתֶּם לַיהו\"ה אלהיכ\"ם, וּבְזִמְנָא דְיָרְתִין יִשְׂרָאֵל מִשְּׁמוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא אִלֵּין תְּלַת בָּנֵי חַיֵּי וּמְזוֹנֵי, אִתְּמַר בְּהוֹן (שיר ח ו) כִּי עַזָּה כַמָּוְת אַהֲבָה, תַּקִּיפָא אִיהִי מִמִּיתָה אַפְרָשׁוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא מִבְּנוֹי, וּמְנָלָן דְּאַפְרָשׁוּתָא אִית בֵּין קוּדְשָׁא בְּרִיךְ הוּא וּבְנוֹי, הָכָא אוֹכַח, (ישעיה נט ב) כִּי אִם עֲוֹנוֹתֵיכֶם הָיוּ מַבְדִּילִים וכו', וְקָשָׁה אִיהִי מִמִּיתָה, וַעֲלָהּ אִתְּמַר (רות א יז) כִּי הַמָּוְת יַפְרִיד בֵּינִי וּבֵינֵךְ.</p>\n<p>וּבְזִמְנָא דְיִשְׂרָאֵל מְקַיְּימִין פִּקּוּדַיָּא דְאוֹרַיְיתָא בִּרְחִימוּ, קָשָׁה כִשְׁאוֹל קִנְאָה (שיר ח ו), דִמְקַנֵּא קוּדְשָׁא בְּרִיךְ הוּא עַל סמא\"ל וְעַל נוּקְבֵיהּ, דְּאִינוּן גָּרְמִין לְבַר נַשׁ מִיתָה בְּחוֹבַיְיהוּ, וְגָרְמִין לוֹן לְמֶחטֵי, וּבְגִין דָּא עָתִיד קוּדְשָׁא בְּרִיךְ הוּא לְנַטְלָא נוּקְמָא מִנַּיְיהוּ, וּלְאַעֲבָרָא לוֹן מִן עָלְמָא, דְסמא\"ל וְנוּקְבָא דִילֵיהּ אִיהִי מִיתָה, דְאִיהִי לִילִי\"ת מַלְאַךְ הַמָּוְת יֵצֶר הָרָע, דְּנוּקְבָא אִיהִי עִם דְּכוּרָא, וּדְכוּרָא עִם נוּקְבָא, וְהַאי מְנָלָן, קְרָא אוֹכַח דִּכְתִיב (בראשית ג יז) בְּעִצָּבוֹן תֹּאכֲלֶנָּה, אָדָם חָאב בְּנוּקְבָא אִתְיַיהִיב לֵיהּ יֵצֶר הָרָע נוּקְבָא, חַוָּה חָבַת בִּדְכוּרָא אִתְיַיהִיב לָהּ יֵצֶר הָרָע מִדְּכוּרָא, וַעֲלָהּ אִתְּמַר (שם טז) בְּעִִצֶב תֵּלְדִי בָנִים, וְדָא אִיהוּ כִּי עַזָּה כַמָּוְת אַהֲבָה וכו' (שיר ח ו).</p>\n<p>וְעוֹד כִּי עַזָּה כַמָּוְת אַהֲבָה, אִם יִשְׂרָאֵל יִתְעַרוּן לָהּ לְהַאי אַהֲבָה קֳדָם זִמְנָא, צְרִיכִין לְאַתְעָרָא לָהּ כִּדְקָא יָאוּת, וְאִי לַאו לָא יִתְעַרוּן לָהּ, הֲדָא הוּא דִכְתִיב (שיר השירים ג ה) הִשְׁבַּעִִתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלַם בִּצבאו\"ת אוֹ בְּאַיְלוֹת הַשָּׂדֶה וְגוֹמֵר, דְּאוֹמָאָה אִיהִי דְלָא שַׁרְיָא עַל כָּרְסַיָּיא עַד דְּנָטִיל נוּקְמָא מֵעֲמָלֵק, דְּחִלֵּל תְּרֵין אַתְוָון דְּאִינוּן י\"ה, דְּנָפִיק מִן מִילָ\"ה מָ\"ל י\"ה, וּבְגִין דָּא (שמות יז טז) כִּי יָד עַל כֵּס י\"ה וְדָא א.</p>\n<p>וְכַד מָטָא זִמְנָא לְנַקְמָא מִנֵּיהּ, וְשַׁלְהוֹבִין דְּאֶשָּׁא נָפְקִין מֵהַאי י\"ה, כְּמָה דְאַתְּ אָמַר (שיר ח ו) רְשָׁפֶיהָ רִשְׁפֵּי אֵשׁ שַׁלְהֶבֶת י\"ה, וְאִינוּן שַׁלְהוֹבִין דְּאִישׁ וְאִשָּׁה, דְּתַמָּן אֵ\"שׁ אֵ\"שׁ, וְתַמָּן י\"ה, אִישׁ כְּמָה דְאַתְּ אָמַר (שמות טו ג) יהו\"ה אִישׁ מִלְחָמָה, דְנָטִיל נוּקְמִין מִפַּרְעֹה וּמֵעַמֵּיהּ, אִשָּׁה דָא שְׁכִינְתָּא דְאִתְּמַר בָּהּ (משלי יח כב) מָצָא אִשָּׁה מָצָא טוֹב וְגוֹמֵר.</p>\n<p>דָּבָר אַחֵר שִׂימֵנִי כַחוֹתָם, כֹּ\"חַ תָּ\"ם, כֹּ\"חַ דָּא שְׁכִינְתָּא עִלָּאָה, כֹּ\"חַ מָ\"ה מִן חָכְמָה, וַעֲלָהּ אִתְּמַר (במדבר יד יז) וְעַתָּה יִגְדַּל נָא כֹּחַ אדנ\"י, תָּ\"ם דָּא יִשְׂרָאֵל דִּלְעִילָא, דְעַל שְׁמֵיהּ אִתְקְרִי יַעֲקֹב תָּם, כְּמָה דְאַתְּ אָמַר (בראשית כה כז) וְיַעֲקֹב אִישׁ תָּם, וּבְגִין דְּאִיהוּ דִיּוֹקְנָא דְחוֹתָם אֱמֶת דִּלְעִילָא, אִתְּמַר בֵּיהּ (מיכה ז כ) תִּתֵּן אֱמֶת לְיַעֲקֹב, וּמָאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא דְאִתְקְרֵי תּוֹרַת אֱמֶת, דִּיּוֹקְנֵיהּ חֲקִיקָא לְעִילָא בְּהַהוּא חוֹתָם אֱמֶת, וּמָאן דִּמְשַׁקֵּר בָּהּ כְּאִלּוּ אַפִּיל אוֹרַיְיתָא לְתַתָּא, הֲדָא הוּא דִכְתִיב (דניאל ח יב) וְתַשְׁלֵךְ אֱמֶת אַרְצָה, וּבְהַהוּא זִמְנָא נָפִיל דִּיּוֹקְנֵיהּ וְחוֹתָמֵיהּ לְתַתָּא, וְנָפִיל מַזָּלֵיהּ, וְאִסְתַּלַּק הַהוּא כֹּחַ מִנֵּיהּ, בְּהַהוּא זִמְנָא סמא\"ל וְחֵילֵיהּ דְּאִינוּן חֵיוָון וּבְעִירָן וְעוֹפִין מְסָאֲבִין רָדְפִין אַבַּתְרֵיהּ, הֲדָא הוּא דִכְתִיב (איכה א ו) וַיֵּלְכוּ בְלֹא כֹחַ לִפְנֵי רוֹדֵף.</p>\n<p>אִם תָּב בִּתְיוּבְתָּא תָּב הַהוּא כֹּחַ לְגַבֵּיהּ דְּאִיהִי שְׁכִינְתָּא עִלָּאָה, בְּהַהוּא זִמְנָא אִתְקַיַּים בֵּיהּ (ישעיה מג ד) וְאֶתֵּן אָדָם תַּחְתֶּיךָ וּלְאֻמִּים תַּחַת נַפְשֶׁךָ, מַאי אָדָם הָא אוּקְמוּהוּ אַל תִּקְרֵי אָדָם אֶלָּא אֱדוֹם, וּלְאוּמִּים וּלְאֹם מִלְאוֹם יֶאֱמָץ (בראשית כה כג), בְּהַהוּא זִמְנָא אוּמָה דְיִשְׂרָאֵל יִתְקְפוּן (נ\"א יתגברון) עַל אוּמָה דְעִשָׂו, בְּחֵילָא דְהַאי כֹּחַ דְּאִתְלַבַּשׁ בְּשֶׁבַע תֵּיבִין דְּעוֹבָדָא דִבְּרֵאשִׁית, כ\"ח אַתְוָון שְׁכִינְתָּא עִלָּאָה, שֶׁבַע תֵּיבִין כְּלִילָן בִּשְׁכִינְתָּא תַּתָּאָה.</p>\n<p>וְהַאי כֹּ\"חַ אִיהוּ רָזָא דְכ\"ח פִּרְקִין דְּעִִשֶׂר אֶצְבָּעוֹת, דִּבְהוֹן וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל (שמות יז יא), וּבְגִין דָּא אוּקְמוּהוּ זִכְרוֹנָם לִבְרָכָה לְמִי נוֹשְׂאִים כַּפַּיִם לְרוּם הַשָּׁמַיִם, דְּצָרִיךְ הַאי כֹּחַ לְסַלְקָא לֵיהּ לְגַבֵּי חָכְמָה, וְדָא אִיהוּ רוּם שָׁמַיִם, וְאִיהוּ יו\"ד ה\"א וא\"ו ה\"א דְשָׁארֵי בְּעִִשֶׂר אֶצְבְּעָן, עַל הַאי כֹּחַ, וְאִיהוּ חָכְמָה כֹּ\"חַ מָ\"ה, וְהַאי כֹּחַ עֲלֵיהּ אִתְּמַר (דניאל א ד) וַאֲשֶׁר כֹּחַ בָּהֶם לַעֲמוֹד בְּהֵיכַל הַמֶּלֶךְ, לַעֲמוֹד בִּצְלוֹתָא דַעֲמִידָה, בְּהֵיכַל הַמֶּלֶךְ סְתָם דָּא אדנ\"י דְּסָלִיק לְחוּשְׁבַּן הֵיכָ\"ל, וְהַאי כֹּ\"חַ אִיהוּ רָזָא (דברים ו ד) דְיהו\"ה אלהינ\"ו</p>"],[9500011136,"<p>יהו\"ה, כוז\"ו במוכס\"ז כוז\"ו, וַעֲלֵיהּ אִתְּמַר כָּל הָעוֹנֶה אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ בְּכָל כֹּחוֹ, דְאִיהוּ כֹחַ דְּאִתְלַבַּשׁ בִּתְרֵין דְּרוֹעִין דְּאִינוּן חֶסֶד וּגְבוּרָה, וְצָרִיךְ לְסַלְקָא לֵיהּ לְגַבֵּי י' דְּאִיהוּ רוּם שָׁמַיִם, וּלְנַחְתָא לֵיהּ לְגַבֵּי ו' דְאִיהוּ שָׁמַיִם, דַּעֲלֵיהּ אִתְּמַר (מלכים א א לב) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם, כַּד נָחֲתָא לֵיהּ לְגַבֵּי עַמּוּדָא דְאֶמְצָעִיתָא, לְמִפְרַק בָּהּ לְיִשְׂרָאֵל בְּנוֹי, וְכַד סָלִיק לָהּ לְגַבֵּי רוּם הַשָּׁמַיִם דְּאִיהִי י', לְמֵיטַל נוּקְמָא מֵעֲמָלֵק.</p>\n<p>וְדָא אִיהוּ וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָד\"וֹ (שמות יז יא), וְאִיהוּ יַד ו', וְאִיהוּ יוּ\"ד, וְאִיהוּ י\"ה, וּלְבָתַר נָחִית הַאי כֹּ\"חַ לְגַבֵּי וָא\"ו, דְּאִיהוּ י\"ג מְכִילָן דְּרַחֲמֵי, לְמִפְרַק לִבְנוֹי דְּיִשְׂרָאֵל, כְּמָה דְאַתְּ אָמַר (ישעיה נד ז) וּבְרַחֲמִים גְּדוֹלִים אֲקַבְּצֵךְ, וְכ\"ח בְּהַאי וָא\"ו אִשְׁתַּלִּים וְאִתְעֲבִיד אֵ\"ם, בְּהַהוּא זִמְנָא (בראשית ג כ) כִּי הִיא הָיְתָה אֵ\"ם כָּל חָ\"י, וְדָא חַ\"י עָלְמִין, דְּבָהּ אִתְמַלֵּי וְאִשְׁתַּלִּים בְּחַ\"י בִּרְכָאָן דִּצְלוֹתָא.</p>\n<p>הֵ\"א הֵ\"א תַּלְיָין מִן תְּרֵין ה\"ה, דְּאִינוּן הֵ\"א הֵ\"א בְּחוּשְׁבָּנָא י\"ב, וּמִנַּיְיהוּ תַּלְיָין אַתְוָון כְּפוּלִים, וְאִינוּן תַּלְיָין מִן תְּרֵין ה\"ה פְּשׁוּטוֹת, וּבְהוֹן סָלְקִין לְחוּשְׁבַּן יָ\"ד, וְדָא אִיהִי כִּי יָ\"ד עַל כֵּס י\"הּ (שמות יז טז), וְכֵן וָא\"ו י\"ג מְכִילִין דְּתַלְיָין מִן ו\"ו פְּשׁוּטָה, וּבָהּ אִשְׁתַּלִּים י\"ד, וְדָא אִיהוּ יָד לְיָד לֹא יִנָּקֶה רָע (משלי יא כא), דָּא עֲמָלֵק, לְעִילָא וְתַתָּא נָטִיל נוּקְמָא מִינֵיהּ, נָטִיל נוּקְמָא לְעִילָא בְּיָ\"ד, וּלְתַתָּא בְּיָ\"ד, וְדָא אִיהוּ הִנֵּה יַ\"ד יהו\"ה הוֹיָה (שמות ט ג), ו' ו' הֵ\"א (נ\"א ו' וה\"א עם ו') וְה\"ה אִינוּן כ\"ח, יוּ\"ד כ' וְתַלְיָין מִן י' פְּשׁוּטָה הֲרֵי כ\"א, כְּחוּשְׁבַּן אהי\"ה, וְסָלִיק כֹּלָּא מ\"ט אַנְפִּין דְּאוֹרַיְיתָא, כְּגַוְונָא דָא כֹּ\"חַ דְּאִיהוּ תְמַנְיָא וְעִִשְׂרִין, אהי\"ה דְּאִיהוּ כ\"א, הֲרֵי מ\"ט, וְכֹלָּא יו\"ד ה\"א וא\"ו ה\"א, יהו\"ה, יו\"ד ה\"א וא\"ו ה\"א מ\"ה, יהו\"ה ד', סָלִיק מ\"ט.</p>\n<p>לְבוּשָׁא דְיוּ\"ד חֶסֶד, לְבוּשָׁא דְהֵ\"א גְבוּרָה, לְבוּשָׁא דְוָא\"ו תִּפְאֶרֶת, לְבוּשָׁא דְהֵ\"א מַלְכוּת, נֶצַח קִשּׁוּרָא דִילֵיהּ חֶסֶד, הֲדָא הוּא דִכְתִיב (תהלים טז יא) נְעִימוֹת בִּימִינְךָ נֶצַח, הוֹד קִשּׁוּרָא דִילֵיהּ גְּבוּרָה, צַדִּיק קִשּׁוּרָא דִילֵיהּ עַמּוּדָא דְאֶמְצָעִיתָא, דְּגוּף וּבְרִית חַשְׁבִינָן חָד, מַלְכוּת שְׁלִימוּ דִלְהוֹן, אִיהִי שְׁלִימוּ דְעִלָּאִין וְתַתָּאִין.</p>\n<p>כֶּתֶר עִִלְיוֹן דָּא אִיהוּ שְׁלִימוּ דְחַמְשִׁין שַׁעֲרֵי בִינָה, וְדָא אִיהוּ דְלָא אִתְיַיהִיב לְמֹשֶׁה, דַעֲלֵיהּ אִתְּמַר (איוב כא ז) נָתִיב לֹא יְדָעוֹ עָיִט, וַעֲלֵיהּ אָמְרוּ זִכְרוֹנָם לִבְרָכָה בְּמוּפְלָא מִמָּךְ אַל תִּדְרוֹשׁ וכו', בְּגִין דְּאִיהוּ מָקוֹר דְּלֵית לֵיהּ סוֹף, וּבִמְקוֹרָא דְלֵית לֵיהּ סוֹף מָאן יְכִיל לְאַשָּׂגָא וּלְאַשְׁכָּחָא לֵיהּ (סיפא).</p>\n<p>קָם סָבָא וְשָׁאִיל וְאַמַּאי אִתְקַשַּׁר נֶצַח עִם חֶסֶד כְּמָה דְאוּקִימְנָא נְעִימוֹת בִּימִינְךָ נֶצַח (תהלים טז יא), וְכֵן הוֹד עִם גְּבוּרָה, אֶלָּא בְּגִין דִּדְרוֹעָא יְמִינָא לָא אִית בֵּיהּ אֶלָּא תְּלַת פִּרְקִין, וְכֵן בִּשְׂמָאלָא, וּבְגִין דָּא אִתְקַשַּׁר שׁוֹקָא יְמִינָא דְאִית בָּהּ תְּלַת פִּרְקִין עִם דְּרוֹעָא יְמִינָא לְשַׁרְיָא בֵּיהּ הֵ\"א, וְכֵן דְּרוֹעָא שְׂמָאלָא עִם שׁוֹקָא שְׂמָאלָא לְשַׁרְיָא בֵּיהּ הֵ\"א, וְכֵן גּוּף וּבְרִית אִינוּן ו' ו', וְשַׁרְיָא בְהוֹן א דְּאִיהִי אִימָּא, וְאִתְעֲבִידוּ י\"ג וָא\"ו, יוּ\"ד שַׁרְיָין בְּעִִשֶׂר אֶצְבְּעָאן דִּידַיִן וּבְעִִשֶׂר אֶצְבְּעָאן דְּרַגְלִין, מִשׁוּם דְּאַתְחַלְתָּא דִשְׁמָא קַדִּישָׁא מֵחָכְמָה שַׁרְיָא דְאִיהִי בְאֶצְבְּעָן.</p>\n<p>כֶּתֶר עִלָּאָה שַׁרְיָא בְרֵישָׁא דְבַר נַשׁ, דְּתַמָּן מַחֲשָׁבָה סְתִימָאָה, וּכְמָה דְמַחֲשָׁבָה אִיהִי סְתִימָא, כַּךְ אִיהוּ סָתִים, אֵין סוֹף אִתְקְרֵי מִלְּגָאו, כֶּתֶר עִלָּאָה מִלְּבָר, כִּתְרָא דְרֵישָׁא עִלָּאָה, אַרְבַּע יְסוֹדִין דְּגוּפָא בְּהוֹן שַׁרְיָא יהו\"ה, וְדָא אִיהוּ כֹּל הַנִּקְרָא בִשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו יְצַרְתִּיו אַף עֲשִׂיתִיו (ישעיה מג ז), בְּרָאתִיו דָּא נִשְׁמָתָא קַדִּישָׁא דְאִיהִי עוֹלָם הַמַּחֲשָׁבָה, יְצַרְתִּיו דָּא רוּחַ מְמַלְּלָא דְמִינֵיהּ חֵיוָון (נ\"א חיין) מְמַלְּלִין, עֲשִׂיתִיו דָּא נֶפֶשׁ דְּתַמָּן עֲשִׂיָּיה, דְשַׁרְיָא בְּרַמַ\"ח פִּקּוּדִין.</p>"],[9500011137,"<p>בְּרֵאשִׁית בְּרִי\"ת אֵ\"שׁ, בְּרִית דָּא צַדִּיק, כָּל אִתְקְרֵי, קִשּׁוּרָא דְכָל אֵבָרִין דְּגוּפָא, ח' דְּאִיהוּ תְמַנְיָא יוֹמִין, אִינוּן שִׁעוּרָא דְשַׁבָּת, דְּאִיהוּ תְּרֵין אַלְפִין אַמִּין לְכָל סְטַר, לְנַטְרָא בְּהוֹן אוֹת שַׁבָּת, כְּגַוְונָא דָא אִינוּן תְּמַנְיָא יוֹמִין תְּחוּם לְקַבָּלָא בְּהוֹן אוֹת בְּרִית, וּלְנַטְרָא לֵיהּ בְּהוֹן, דְּלָא אִתְעֲבִיד בְּאוֹת בְּרִית חִלּוּל.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר אַבָּא יוֹמָא חַד הֲוִינָא אָזְלֵי אֲנָא וְרַבִּי יוֹסֵי, וַאֲתָא בְּרֵיהּ דְּרַב הַמְנוּנָא סָבָא מֵהַהוּא עָלְמָא, בְּדִיּוֹקְנָא דְהַאי עָלְמָא וְאִזְדַּמַּן לָן בְּאָרְחָא כְּגַוְונָא דִמְחַמֵּר בִּתְרֵין חַמָּרִין, וְשָׁאִילְנָא (נ\"א ושאיל לן) מַאי אֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ וּמִקְדָּשִׁי תִּירָאוּ (ויקרא יט ג), וְאָמַר אִיהוּ מִילִין שַׁפִּירִין, אֲבָל עִם כָּל דָּא בָּעִינָא לְמִשְׁמַע מִפּוּמָךְ, אָמַר לֵיהּ בְּרִי בְּוַדַּאי בְּרִית אִיהוּ שָׁקִיל לְשַׁבָּת, וּבְגִין דָּא (בראשית ירא שבת וכו').</p>\n<p>בְּרֵאשִׁית יָרֵ\"א שַׁבָּ\"ת, (ובה) שַׁבְּתוֹתַי תְּהֵא דָחִיל, יָרֵ\"א תּוֹרָ\"ה, יָרֵ\"א בְּרִי\"ת, כְּמָה דְצָרִיךְ נְטִירוּ דִבְּרִית, דְּלָא יֵעוּל לֵיהּ בִּרְשׁוּ נוּכְרָאָה, כְּגַוְונָא דָא צָרִיךְ בַּר נַשׁ נְטִירוּ דְשַׁבָּת, דְּלָא לְאַפָּקָא מֵרְשׁוּת הַיָּחִיד וְיֵעוּל בִּרְשׁוּת הָרַבִּים, רְשׁוּת הַיָּחִיד אִיהִי שְׁכִינְתָּא, רָחְבּוֹ ד' וְאִינוּן יהו\"ה, וְגָבְהוֹ עֲשָׂרָה יו\"ד ה\"א וא\"ו ה\"א, רְשׁוּת הָרַבִּים נָחָשׁ אֵשֶׁת זְנוּנִים, סַם דְּאֵל אַחֵר דְּאִיהוּ סמא\"ל, וְאִיהוּ כְּלָלָא דְשַׁבְעִין אוּמִין, וְאִיהִי חֲלָלָה זוֹנָה, וּבַעִִלָהּ חִלּוּל שַׁבָּת אִיהוּ, וּבְגִין דָּא מָאן דְּאַפִּיק מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הָרַבִּים חַיָּיב סְקִילָה.</p>\n<p>עִרוּב אִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, וּבֵיהּ מְטַלְטְלִין מִבַּיִת לְבַיִת, דְּאִנּוּן שְׁכִינָה עִלָּאָה וְתַתָּאָה, וַעֲלַיְיהוּ אִתְּמַר אֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ וּמִקְדָּשִׁי תִּירָאוּ, דָא מִקְדָּשׁ יו\"ד, אוֹת שַׁבָּת (דא ברית) דְּצָרִיךְ לְנַטְרָא לֵיהּ בְּבַת זוּגֵיהּ, דְּאִיהִי קְדוּשָׁה דִילֵיהּ, בְּרָכָה דִילֵיהּ, דַּעֲלָהּ אִתְּמַר (בראשית ב ג) וַיְבָרֶךְ אלהי\"ם אֶת יוֹם הַשְּׁבִיעִי וַיְקַדֵּשׁ אוֹתוֹ, וַיְבָרֶךְ דָּא בְּרָכָה, וַיְקַדֵּשׁ דָּא קְדוּשָׁה, וּלְגַבֵּי תַּרְוַיְיהוּ הֲווֹ נָפְקֵי קַדְמָאֵי לָקֳדָמוּת כַּלָּה, וַהֲווֹ אָמְרֵי תְּרֵי זִמְנֵי בֹּאִי כַלָּה בֹּאִי כַלָּה, בְּהַהוּא זִמְנָא קוֹל חָתָן וְקוֹל כַּלָּה.</p>\n<p>וְעוֹד מִקְדָּשִׁי בְּאָת יוּ\"ד, בְּגִין דְּלֵית קְדוּשָׁה פָּחוּת מֵעֲשָׂרָה, וְצָרִיךְ לְבָרְכָא לוֹן וּלְקַדֵּשׁ לוֹן בְּקִדּוּשׁ עַל הַיַּיִן, בְּשַׁבְעִין תֵּיבִין דְּקִדּוּשׁ וּוַיְכֻלּ\"וּ כְּחוּשְׁבַּן בַּיַּיִ\"ן, וְצָרִיךְ לְמֵימַר סַבְרִי מָרָנָן, וְאִינוּן דְּאָמְרִין וְעָנוּ לְחַיֵּי, בְּגִין דְּאִתְקַשְּׁרוּ בְּאִילָנָא דְחַיֵּי, וְלָא בְּאִילָנָא דְמוֹתָא, דְאִיהוּ גֶפֶן דְּחָב בֵּיהּ אָדָם קַדְמָאָה, דְּחַד אָמַר חִטָּה הָיָה, וְחַד אָמַר גֶּפֶן, וְכֹלָּא קְשׁוֹט.</p>\n<p>שֶׁבַע מִינִין אִינוּן חִטָּה וּשְׂעוֹרָה גֶפֶן וּתְאֵנָה וְרִמּוֹן זֵית שֶׁמֶן וּדְבָשׁ, חִטָּה וּשְׂעוֹרָה וְהָא אִתְּמַר, וְצָרִיךְ לְאַחֲזָרָא עֲלַיְיהוּ, חִטָּה הָא אִתְּמַר, שְׂעוֹרָ\"ה דְאַפִּיק ה' מִשִּׁעוּר דִּילָהּ, גֶּפֶן סָחֲטָה עֲנָבִים בִּרְשׁוּ אָחֳרָא, וְעָבַד יַיִן נֶסֶךְ, וְאִתְעֲבִיד אִילָנָא דְטוֹב וָרָע, תְּאֵנָה לָקִיט תְּאֵינֵי קֳדָם זִמְנַיְיהוּ קֳדָם דְּאִתְבַּשְׁלוּ, כַּךְ לָקִיט הוּא מֵעָלְמָא קוֹדֶם זִמְנֵיהּ, וְדָא אִיהוּ רָזָא מָאן דְּגָרִים דִּי יְמוּתוּן בְּנוֹי קֳדָם זִמְנַיְיהוּ, הֲדָא הוּא דִכְתִיב (קהלת ה ה) לָמָּה יִקְצוֹף הָאלהי\"ם עַל קוֹלֶךָ וְחִבֵּל אֶת מַעֲשֵׂה יָדֶיךָ, וְרָזָא דְמִלָּה (ירמיהו ב ל) לַשָּׁוְא הִכֵּיתִי אֶת בְּנֵיכֶם וְגוֹמֵר, וּבְגִין דָּא (שמות כ ז) לֹא תִשָּׂא אֶת שֵׁם יהו\"ה אלהי\"ך לַשָּׁוְא. רִמּוֹן, בֶּן זוֹמָא בֵּיהּ חָב, אֲבָל רַבִּי מֵאִיר תּוֹכוֹ אָכַל קְלִיפָתוֹ זָרַק, דִּקְלִיפִין אִינוּן אוּמוֹת הָעוֹלָם, יִשְׂרָאֵל מוֹחָא בֵּינַיְיהוּ, כֵּן כְּגַוְונָא דָא שְׁכִינְתָּא אִיהִי פַּרְדֵּס</p>"],[9500011138,"<p>בְּגָלוּתָא, וְאִיהִי מוֹחָא מִלְּגָו, אֱגוֹז קָרִינָן לֵיהּ, כְּמָה דְאָמַר שְׁלֹמֹה מַלְכָּא, אֶל גִּנַּת אֱגוֹז יָרַדְתִּי (שיר ו יא), וְאִיהִי שְׁכִינְתָּא אִיבָּא מִלְּגָאו, הֲדָא הוּא דִכְתִיב (תהלים מה יד) כָּל כְּבוּדָּה בַת מֶלֶךְ פְּנִימָה מִמִּשְׁבְּצוֹת זָהָב לְבוּשָׁהּ, וּקְלִיפִין הֵן כַּמָּה רְשׁוּיוֹת נוּכְרָאִין, וּבְשַׁבָּת מִכֹּלָּא אִתְפַּשְּׁטַת, וְאִתְלַבְּשַׁת בִּלְבוּשִׁין שַׁפִּירָאן, וְכֵן צְרִיכִין יִשְׂרָאֵל לְתַתָּא, לְאִתְחַדְּשָׁא בְשַׁבָּת בִּלְבוּשִׁין שַׁפִּירָאן, וְכֵן לְאַטְעָמָא בְשַׁבָּת מִכָּל מַאֲכָלִין טָבִין, בְּגִין לְקַשְׁרָא וּלְאַרְקָא בִּרְכָאָן לְגַבָּהּ מִכָּל סְפִירָן, וּלְמֶהֱוֵי אִשְׁתַּקְיָא מִכֻּלְּהוּ.</p>\n<p>וְצָרִיךְ לְקַיְימָא בָּהּ עֹנֶג, דְּאִיהוּ צַדִּיק דְּנָפִיק מֵעִדֶן, דְּאִיהִי בִּינָה עָלְמָא דְאָתֵי, לְהַשְׁקוֹת אֶת הַגָּן דָּא שְׁכִינְתָּא תַּתָּאָה, וְנַהֲרָא אִיהוּ ו' דְּנָפִיק מִן י\"ה, וְאָזִיל חֲמֵשׁ מֵאָה שְׁנִין, דְּאִינוּן חָמֵשׁ סְפִירָאן, וּמָטֵי לַצַּדִּיק, לְאַשְׁקָאָה מִנֵּיהּ גִּנְתָא דְאִיהִי ה', וְעַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו וְאֶת אִמּוֹ וְדָבַק בְּאִשְׁתּוֹ וְגוֹמֵר (בראשית ב כד).</p>\n<p>וְכֵן בְּרִית מִילָה אִיהִי כְּגַוְונָא דֶאֱגוֹז, צָרִיךְ לְתַבְּרָא קְלִיפִין דְּעָרְלָה וּפְרִיעָה, וּלְאַעֲבָרָא לוֹן מִתַּמָּן, וּלְאִתְגַּלְיָיא מוֹחָא מִלְּגָו, וְדָא אוֹת בְּרִית, וְדָא עִץ חַיִּים, אֲבָל בְּרִית דְּאִיהוּ בְּעָרְלָתֵיהּ וְלָא אִית בֵּיהּ פְּרִיעָה, עֲלֵיהּ אִתְּמַר (שם יז) וּמֵעִץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ, כִּי בְּיוֹם אֲכָלְךָ מִמֶּנּוּ מוֹת תָּמוּת, מוֹת בָּעוֹלָם הַזֶּה, תָּמוּת בָּעוֹלָם הַבָּא.</p>\n<p>וְעוֹד לִבָּא הוּא אֶגוֹז, וּמָאן דְּתַבַּר קְלִיפָה דִילֵיהּ דְּאִיהוּ יֵצֶר הָרָע, עֲלֵיהּ אִתְּמַר (תהלים נא יט) לֵב נִשְׁבָּר וְנִדְכֶּה אלהי\"ם לֹא תִבְזֶה וְגַסּוּת לִבָּא דְהוּא שְׁלִים בִּקְלִיפִין דִּילֵיהּ וְלָא אִתְּבַר, עֲלֵיהּ אִתְּמַר (משלי טז ה) תּוֹעֲבַת יהו\"ה כָּל גְּבַהּ לֵב, וּשְׁכִינְתָּא לָא שַׁרְיָא עֲלֵיהּ, וּמִסִּטְרָא דִקְלִיפִין אִתְקְרִיאוּ בְנֵי נָשָׁא עַרְלֵי לֵב.</p>\n<p>וּבְשַׁבָּת גֵּיהִנָּם לָא שָׁלְטָא בְעָלְמָא, וְלָא מְמַנָּן דִּילֵיהּ, בְּגִין דָּא מַנִּי לְיִשְׂרָאֵל לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מוֹשְׁבוֹתֵיכֶם בְּיוֹם הַשַּׁבָּת (שמות לה ג), וְאִי בַּר נַשׁ אוֹקִיד בְּשַׁבָּת, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אֲנָא הֲוִיתִי מְכַבֶּה לְנוּרָא דְלָא אוֹקִיד, וְאַתּוּן מוֹקְדִין לֵיהּ, אַתּוּן תִּתּוֹקְדוּן בְּגֵיהִנָּם, בְּגִין דָּא לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מוֹשְׁבוֹתֵיכֶם, וַאֲפִילוּ בְגוּפָא, וּמַאי נִיהוּ גֵיהִנָּם בְּגוּפָא, כָּבֵד דְּבֵיהּ מָרָה דְאִיהוּ גֵיהִנָּם, סַם הַמָּוְת סַם דְּאֵל אַחֵר, חַרְבָּא דְמַלְאַךְ הַמָּוְת, וַעֲלֵיהּ אִתְּמַר (משלי ה ד) וְאַחֲרִיתָהּ מָרָה כַלַּעֲנָה, חַדָּה כְּחֶרֶב פִּיּוֹת.</p>\n<p>וְצָרִיךְ דְּלָא יַתְעַר (נ\"א לאתערא) עֲצִיבוּ וּקְטָטָה מִסִּטְרָא דִטְחוֹל, אֶלָּא דִתְהֵא לֵב נָטִיר מִכֻּלְּהוּ, דְאִיהוּ שַׁבָּת שָׁמוֹר, וּמוֹחָא זָכוֹר, וְצָרִיךְ לְקַבָּלָא אוֹשְׁפִּיזִין דְּאִינוּן מַלְאָכִין, עוּלֵימָן דִּנְשָׁמָה יְתֵירָה דְאִיהִי שְׁכִינְתָּא עִלָּאָה, וְנֶפֶשׁ יְתֵירָה דְאִיהִי שְׁכִינְתָּא תַּתָּאָה, וְאוֹשְׁפִּיזִין דְּנָחֲתִין עִמָּהּ.</p>\n<p>וְצָרִיךְ אִתְּתָא לְתַקְנָא שְׁרַגָּא בְּלֵיל שַׁבָּת לִימִינָא, וְאִתְחֲשִׁיב לָהּ כְּאִלּוּ תִּקְנָהּ מְנַרְתָּא בְדָרוֹם, וּפָתוֹרָא בְצָפוֹן, וַעֲלַיְיהוּ אִתְּמַר הָרוֹצֶה לְהַחְכִּים יַדְרִים, הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין, וְאִינוּן שְׁכִינְתָּא עִלָּאָה וְתַתָּאָה, שְׁכִינְתָּא עִלָּאָה מְנַרְתָּא לְדָרוֹם, צְרִיכָא לְאַתְקָנָא לָהּ, בְּגִין דְּתַמָּן חָכְמָה, וּבְגִין דָּא הָרוֹצֶה לְהַחְכִּים יַדְרִים,</p>\n<p>וּבְהַהוּא בֵיתָא דְאַשְׁכְּחִין דִּירָה דָא מְתַקְּנָא בְהַאי סִדּוּרָא, מְנַרְתָּא בְדָרוֹם וְשֻׁלְחָן בְּצָפוֹן וּמִטָּה בֵּין צָפוֹן לְדָרוֹם, אָמְרִין אִלֵּין מַלְאָכִין דְּקָא נָחֲתִין עִם שְׁכִינְתָּא דְאִיהִי נְשָׁמָה יְתֵירָה, לֵית דִּין אֲתַר הֶדְיוֹט דְּעַם הָאָרֶץ, אֱלָהֵין אֲתַר דְּרַעֲוָא בֵיהּ מִן קֳדָם יהו\"ה.</p>\n<p>פָּתוֹרָא צְרִיכָא לְתַקְנָא לָהּ לְגַבֵּי צָפוֹן, וּפָתוֹרָא אִיהִי שְׁכִינְתָּא תַּתָּאָה, דְאִתְּמַר בָּהּ (תהלים מה ד) כָּל כְּבוּדָּה בַת מֶלֶךְ פְּנִימָה מִמִּשְׁבְּצוֹת זָהָב לְבוּשָׁהּ, מַאי זָהָב דָּא גְבוּרָה, דְאִתְּמַר בָּהּ (איוב לז כב) מִצָּפוֹן זָהָב יֶאֱתֶה, מִמִּשְׁבְּצוֹת זָהָב תְּרֵי סַמְכֵי קְשׁוֹט, מִטָּה לְמַעֲרָב בֵּין צָפוֹן לַדָּרוֹם, לְתַקְנָא לֵיהּ לְגַבֵּי עַמּוּדָא דְאֶמְצָעִיתָא, דְאִתְּמַר בֵּיהּ (שמות ד כב) בְּנִי בְכוֹרִי יִשְׂרָאֵל, וּבְבֵיתָא דְלַאו אִינוּן מִתְתַּקְנִין אִלֵּין תִּקּוּנִין בְּלֵיל שַׁבָּת, אוּשְׁפִּיזִין אָמְרִין לַאו אִיהִי דָא דִירָה דְיִשְׂרָאֵל, דְּאִתְּמַר בָּהּ (שם לא טז) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת</p>"],[9500011139,"<p>הַשַּׁבָּת, לַעֲשׂוֹת אֶת הַשַּׁבָּת, לְדוֹרוֹתָם, לְדֹרֹתָם כְּתִיב חָסֵר, מִלָּשׁוֹן דִּירָה, וְכָל אִלֵּין תִּקּוּנִין צְרִיכִין לְתַקְנָא בְּלֵיל שַׁבָּת דְּאִיהִי מַמָּשׁ אוֹת בְּרִית מִילָה.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, וְכִי בְּרִית מִילָה לְכָל בְּנֵי נָשָׁא אִיהוּ שָׁוָה, אָמַר לֵיהּ, לָא, דִּבְּרִית מִילָה לְחַיָּיבַיָּא, עַפְרָא דְתַקִּין בְּמָנָא אִיהוּ מְזוֹנָא לְחִוְיָא, דְאַפְרִישׁ מִנֵּיהּ, הֲדָא הוּא דִכְתִיב (ישעיהו סה כה) וְנָחָשׁ עָפָר לַחְמוֹ, וְדַם בְּרִית אִיהוּ מְזוֹנָא לְסמא\"ל דְּאִיהוּ רוֹצֵחַ, דְּאַפְרִישׁ מִנֵּיהּ, וְרָזָא דְמִלָּה אִם רָעִב שׂוֹנַאֲךָ הַאֲכִילֵהוּ לָחֶם וְאִם צָמֵא הַשְׁקֵהוּ מָיִם (משלי כה כא).</p>\n<p>לְבֵינוּנִיִּים אִתְחֲשִׁיב בְּרִית מִילָה אַעַבְרוּ דִדְמָא וּבִשְׂרָא כְּקָרְבָּנָא, הֲדָא הוּא דִכְתִיב (שמות כ כד) וְזָבַחְתָּ עָלָיו אֶת עוֹלוֹתֶיךָ וְאֶת שְׁלָמֶיךָ, לְצַדִּיקַיָּא וַדַּאי בַּאֲתַר דְּמִילָה וּפְרִיעָה שַׁרְיָא יהו\"ה, וְדָא אִיהוּ וּמִבְּשָׂרִי אֶחזֶה אֱלוֹ\"הַ (איוב יט כב), וַעֲלַיְיהוּ אִתְּמַר (יחזקאל טז ו) וָאֹמַר לָךְ בְּדָמַיִךְ חֲיִי לַצַּדִּיקַיָּא, (וכתיב (זכריה ט יא), גם את בדם בריתך שלחתי אסיריך מבור, דאיהו גיהנם).</p>\n<p>בְּרֵאשִׁית דָּא אוֹרַיְיתָא, הֲדָא הוּא דִכְתִיב (משלי ח כב) יהו\"ה קָנָנִי רֵאשִׁית דַּרְכּוֹ קֶדֶם מִפְעָלָיו מֵאָז, מֵהַהוּא אֲתַר דְּאִתְּמַר בֵּיהּ (תהלים צג ב) נָכוֹן כִּסְאֲךָ מֵאָז, וְאוֹרַיְיתָא תְּרֵין פִּקּוּדִין אִית בָּהּ, חַד וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה (יהושע א ח), תִּנְיָינָא לְמֶהֱוֵי לְמַלְכָּא סֵפֶר תּוֹרָה, דְאָזִיל עִמֵּיהּ בְּכָל אֲתַר, הֲדָא הוּא דִכְתִיב (דברים יז יט) וְהָיְתָה עִמּוֹ וְקָרָא בוֹ כָּל יְמֵי חַיָּיו, סֵפֶר תּוֹרָה אַמַּאי לַמֶּלֶךְ, בְּגִין דְּאִיהוּ לַאו אִיהוּ מַלְכָּא אֶלָּא מִסִּטְרָא דְמַלְכוּת, וְצָרִיךְ לְמֶהֱוִי לֵיהּ עִמֵּהּ בְּכָל אֲתַר סֵפֶר תּוֹרָה דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, לְאִתְקַשְׁרָא בֵיהּ קוּדְשָׁא בְּרִיךְ הוּא עִם שְׁכִינְתֵּיהּ, וְסֵפֶר תּוֹרָה הִיא דַרְגָּא דְיַעֲקֹב, דְּאִתְּמַר בֵּיהּ (בראשית כה כז) וְיַעֲקֹב אִישׁ תָּם, וְסֵפֶר תּוֹרָה כַּךְ צָרִיךְ לְמֶהֱוִי תָּם בְּלָא פְּסוֹלֶת, וְאִם סֵפֶר תּוֹרָה אִיהוּ חָסֵר בַּאֲתַר דְּמָלֵא, אוֹ מָלֵא בַּאֲתַר דְּחָסֵר, אוֹ אוֹת חַד חַסִּיר, אוֹ יַתִּיר, אוֹ חֲלִיף, סֵפֶר תּוֹרָה פָּסוּל, לַאו אִיהוּ כְּדִיּוֹקְנָא דְסֵפֶר תּוֹרָה דִלְעִילָא.</p>\n<p>כְּגַוְונָא דָא אִינוּן חָמֵשׁ כַּנְפֵי רֵיאָה, כְּגַוְונָא דַחֲמִשָּׁה חוּמְשֵׁי תוֹרָה, וּוַרְדָּא כְּגַוְונָא דְזֶה סֵפֶר דְּאִיהוּ סֵפֶר יְשָׁרִים, אִי אוּנֵי חַסִּיר אוֹ יַתִּיר אוֹ חֲלִיף, אִיהוּ אִמְרָא פָּסוּל, וּמָאן דְּעָבַר עֲלַיְיהוּ כְּאִלּוּ עָבַר עַל אוֹרַיְיתָא וַחֲמִשָּׁה חוּמְשֵׁי דִילָהּ, דַּחֲמִשָּׁה כַנְפֵי רֵיאָה וּוַרְדָּא אִינוּן שִׁית, דָּא ו', כָּל מָאן דְּעָבַר (על דא, כאלו עבר) עַל דָּא.</p>\n<p>וַחֲמִשָּׁה דְבָרִים הַמַּפְסִידִין אֶת הַשְּׁחִיטָה, (כל מאן דאעבר עלייהו) כְּאִלּוּ אַעֲבַר בְּה' מִן יהו\"ה, כַּנְפֵי רֵיאָה צָרִיךְ דְּלָא יְהֵא בְּהוֹן סִרְכוֹת, תַּמְנֵי סְרֵי סִרְכוֹת אִינוּן, מָאן דְּאַעֲבַר עֲלַיְיהוּ כְּאִלּוּ אַעֲבַר בְּרִית דְּאִיהוּ חַ\"י עָלְמִין, וְסִירְכָא אִיהוּ סַם הַמָּוְת, סַם דְּאֵל אַחֵר, דְּאִיהוּ סמא\"ל, עֲלָהּ אִתְּמַר (משלי ה ה) רַגְלֶיהָ יוֹרְדוֹת מָוְת, בְּכָל אֲתַר דְּאִסְתַּרִיךְ קְטִילַת, וְכַנְפֵי רֵיאָה אִינוּן כַּנְפֵי חֵיוָון, וּצְרִיכִין לְמֶהֱוֵי פְּרוּדוֹת מִלְמָעִִלָה, הֲדָא הוּא דִכְתִיב (יחזקאל א יא) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת מִלְמָעִִלָה, אִם אִינוּן בְּחִבּוּר טְרֵיפָה, וּתְרֵי אוּמוֹת אִינוּן בְּרֵיאָה, וּבְהוֹן שִׁית גַּדְפִין, חָמֵשׁ אוּנוֹת וּוַרְדָּא, וַעֲלַיְיהוּ נֶאֱמַר (ישעיהו ו ב) שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ שֵׁשׁ כְּנָפַיִם שֵׁשׁ כְּנָפַיִם לְאֶחָד, שִׁיתָּא אִינוּן מִסִּטְרָא דְאָת ו', דְּאִיהוּ סֵפֶר תּוֹרָה.</p>\n<p>אֲרוֹנָא דְסֵפֶר תּוֹרָה דָא כִּיסָא דְלִבָּא, וְאִיהוּ נוּר דָּלֵיק, וְאִי לָא כַּנְפֵי רֵיאָה דְאִינוּן נָשְׁבִין עֲלֵיהּ, הֲוָה לִבָּא אוֹקִיד כָּל גּוּפָא, וְהַהוּא נוּרָא דְאִיהוּ דְּדָם דְּעַרְקִין דְּלִבָּא, רוּחָא נָשִׁיב אַבַּתְרֵיהּ בְּעַרְקִין דִּדְמָא, וְכֻלְּהוּ מִתְנַהֲגִין אַבַּתְרֵיהּ, וְדָא הוּא דִכְתִיב (יחזקאל א יב) אֶל אֲשֶׁר יִהְיֶה שָׁמָּה הָרוּחַ</p>"],[9500011140,"<p>לָלֶכֶת יֵלֵכוּ וְגוֹמֵר, וְלִבָּא כַּד סָלִיק מִנֵּיהּ רוּחָא (ואתפרש מן נפשא דאיהו ו') עַל דְּמָא נוּר דָּלֵיק, אִתְּמַר בְּנַפְשָׁא (שיר ה ב), אֲנִי יְשֵׁינָה, וְכַד יֵיתֵי רוּחָא לְגַבֵּיהּ אִתְּמַר וְלִבִּי עִר, וְדָא אִיהוּ (ישעיהו כו ט) נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה, אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ, וְכַד יֵיתֵי רוּחָא לְגַבֵּי לִבָּא דְתַמָּן נַפְשָׁא, אִתְּמַר בֵּיהּ (שיר ה ב) קוֹל דּוֹדִי דוֹפֵק, דָּפִיק לְתַרְעָא דְלִבָּא שִׁית דְּפִיקִין, לְאִשְׁתְּמוֹדָע דְּאִיהוּ ו' דְּיֵיתֵי לְגַבֵּי ה' (נ\"א ד'), דְּאִיהִי נֶפֶשׁ, וּבָהּ אִינוּן עֲשָׂרָה, וְכֻלְּהוּ בְּפִיּוּסָא, הֲדָא הוּא דִכְתִיב (שם ה ב) פִּתְחִי לִי אֲחוֹתִי רַעִִיָתִי יוֹנָתִי תַמָּתִי שֶׁרֹאשִׁי נִמְלָא טָל.</p>\n<p>וּבְתִקּוּנָא תַּמְנֵי סְרֵי, (נ\"א ובתקונא דא שית אתוון), דְּאִיהוּ בָּרָ\"א שִׁי\"ת, אִינוּן רְמִיזִין כְּגַוְונָא דָא, פִּתְחִי לִי בְּאָת ב' דְּאִיהִי תַּרְעָא, אֲחוֹתִי בְּאָת א', רַעִִיָתִי בְּאָת ר', יוֹנָתִי בְּאָת י', תַמָּתִי בְּאָת ת', שֶׁרֹאשִׁי נִמְלָא טָל דָּא יוּ\"ד נְקוּדָה דְאָת ב', קֶּוֵצּוֹתָיו אִלֵּין שִׁית סִטְרִין, דְּאִתְּמַר בְּהוֹן (שם טו) שׁוֹקָיו עַמּוּדֵי שֵׁשׁ, וְאִינוּן דְּפִיקִין בְּמוֹלִיךְ וּמֵבִיא לְמָאן דְּאַרְבַּע סִטְרִין דִּילֵיהּ, וּמַעֲלֶה וּמוֹרִיד לְמָאן דִּשְׁמַיָּא וְאַרְעָא דִילֵיהּ, וְשִׁית סִטְרִין אִינוּן שִׁית סְפִירָן, וּדְפִיקוּ סָלִיק וְנָחִית בְּהוּ, בַּאֲרִיכוּ דְחֶסֶד כְּגַוְונָא דָא תְּקִיעוֹת, בִּתְּבִירוּ דִגְבוּרָה דְאִינוּן שְׁבָרִים, בִּמְהִירוּ דְעַמּוּדָא דְאֶמְצָעִיתָא דְאִיהוּ תְּרוּעָה, בְּחֶסֶד גְּבוּרָה תִּפְאֶרֶת סָלְקִין, בְּנֶצַח וְהוֹד יְסוֹד נָחֲתִין.</p>\n<p>וְכֻלְּהוּ דָפְקִין לְגַבֵּי שְׁכִינְתָּא דְאִיהִי סֻלָּם, דְּבֵיהּ שִׁית דַּרְגִּין, וְדָא לִבָּא, וּבֵיהּ מַלְאֲכֵי אלהי\"ם סָלְקִין וְנָחֲתִין, דְּאִינוּן דְּפִיקִין דְּרוּחָא, וְאִינוּן שִׁית סָלְקִין לְעִִשֶׂר, וְדָא י', וְאִינוּן קַשְׁרַ\"ק קְשַׁ\"ק קְרַ\"ק, עַד דְּאִתְכְּלִילוּ בַּעֲשָׂרָה זִכְרוֹנוֹת וּבְעִִשֶׂר מַלְכִיּוֹת וּבְעִִשֶׂר שׁוֹפָרוֹת, תְּלָתִין סָלְקִין מִתַּתָּא לְעִילָא, וּתְלָתִין נָחְתִין מֵעִילָא לְתַתָּא, וְסָלְקִין כֻּלְּהוּ לְשִׁתִּין, שִׁית זִמְנִין עִִשֶׂר, כַּד סָלִיק דְּפִיקוּ בִתְּקִיפוּ דִגְבוּרָה בִּגְבִירוּ אִיהוּ דִינָא תַּקִּיפָא, כַּד סָלִיק דְּפִיקוּ וְאִתְאָרַךְ, מַרְעָא אִתְאָרַךְ דְּהָא מַטֶּה כְּלַפֵּי חֶסֶד.</p>\n<p>קָם סָבָא מֵאִינוּן מָארֵי מְתִיבְתָּא, וְאָמַר בּוֹצִינָא קַדִּישָׁא, הָא סִמָּנִין אִלֵּין אִינוּן דְּמַרְעָא בְגָלוּתָא, כַּד דְּפִיקוּ אִתְקַצַּר וְגָלוּתָא אִתְקַצַּר, הָא מַטֶּה כְּלַפֵּי גְבוּרָה בֵּי דִינָא רַבְרְבָא, וּמוֹתָנָא קָא אַחֲזֵי לְמָשִׁיחַ וּשְׁבָטִין, וּבְגִין דָּא אוֹמִיאַת הַהִיא חוֹלָה בְּגָלוּתָא לְיִשְׂרָאֵל (שם ב ז), אִם תָּעִירוּ וְאִם תְּעוֹרְרוּ, דְּלָא יְהֵא בִמְהִירוּ, אֶלָּא עַד שֶׁתֶּחְפָּץ.</p>\n<p>וְאִם דְּפִיקוּ אִתְאָרַךְ, הָא מַטֶּה כְּלַפֵּי חֶסֶד, וְעִם כָּל דָּא מַרְעָא בְגָלוּתָא אִתְאָרַךְ, וְאִי דְפִיקוּ אִיהוּ לָא אֲרִיךְ וְלָא קְצִר, הָא אִתְעַר רַחֲמֵי לְגַבֵּי חוֹלֶה בְגָלוּתָא דְאִיהִי לִבָּא, וּלְגַבֵּי עַרְקִין דִּילָהּ דְּאִינוּן בְּנָהָא יִשְׂרָאֵל, וְדָא אִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, עֲלֵיהּ אִתְּמַר (ישעיהו נד ז) וּבְרַחֲמִים גְּדוֹלִים אֲקַבְּצֵךְ.</p>\n<p>וְעוֹד כַּד דְּפִיקוּ אִיהוּ בִּתְרוּעָה בִּמְהִירוּ, דוֹחֲקָא בָּתַר דּוֹחֲקָא, יֵיתֵי פּוּרְקָנָא, וְעוֹד הַהִיא חוֹלָה דְאִיהוּ לִבָּא, כַּד רוּחָא לָא נָשִׁיב לְגַבָּהּ, דְּאִתְּמַר בֵּיהּ (בראשית א ב) וְרוּחַ אלהי\"ם מְרַחֶפֶת עַל פְּנֵי הַמָּיִם, אִיהִי לָא דְפִיקַת בְּעַרְקִין דִּילָהּ, וְכֻלְּהוּ חֲשִׁיבִין בְּגָלוּתָא כַּמֵּתִים, וְאִתְּמַר בְּהוּ (איכה ג ו) בְּמַחֲשַׁכִּים הוֹשִׁיבַנִי כְּמֵתֵי עוֹלָם, וּבְגִין דָּא בְגָלוּתָא אֲנִי יְשֵׁנָה, וְאִיהִי חוֹלָה בְגָלוּתָא, וְכַמָּה אַסְיָין תַּלְמִידֵי חֲכָמִים קָא מִשְׁתַּדְלָן לְגַבָּהּ, בְּכַמָּה בוּסְמִין וְרֵיחִין דְּשׁוֹשַׁנִּים תַּפּוּחִים וְאֱגוֹזִים וְרִמּוֹנִים, וְלָא אִתְחַזְרַת רוּחָא לְגַבָּהּ בְּהוֹן בְּגָלוּתָא בְּמַרְעָא דִילָהּ, וְלָא דְפִיקוּ אִתְחַזְרַת לְגַבָּהּ, עַד דְּיֵיתֵי רַעִִיָא מְהֵימְנָא רְחִימוּ דִילָהּ, דְּאִתְּמַר בֵּיהּ (שיר ב טז) הָרוֹעִִה בַּשּׁוֹשַׁנִּים, וְאַיְיתֵי לָהּ תַּפּוּחַ, וְשַׁוִּי לְחוֹטָמָא, וְאַרְחָא בֵיהּ, וְאִשְׁתְּמוֹדְעַת לְגַבֵּיהּ, הֲדָא הוּא דִכְתִיב (איכה א טז) מְנַחֵם מֵשִׁיב נַפְשִׁי, מִיָּד חָזְרַת רוּחָא וּדְפִיקוּ לְגַבָּהּ.</p>\n<p>בְּהַהוּא זִמְנָא שַׁבַחַת לֵיהּ (שיר ב ג) כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר כֵּן דּוֹדִי בֵּין הַבָּנִים וכו', וּלְבָתַר יֵעוּל לְגִנְּתָא וְאַפִּיק מִתַּמָּן רִמּוֹנִים, וְיָהִיב לָהּ מֵעֲסִיס רִמּוֹנִים, וְלָקִיט אֱגוֹז וְתַבַּר</p>"],[9500011141,"<p>קְלִיפִין, וְיָהִיב לָהּ מוֹחָא מִלְּגָאו, וְאִיהִי אָכְלָה, וְשָׁתִית מֵעֲסִיס הָרִמּוֹנִים, וְאִתְּסִיאַת, וְדָא הוּא דְאָמַר קְרָא (שיר ו יא) אֶל גִּנַּת אֱגוֹז יָרַדְתִּי, אַדְהָכִי הָא נִשְׁרָא קָא אַתְיָא, הַנֶּשֶׁר הַגָּדוֹל בַּעַל הַכְּנָפַיִם, וִיהִיבַת תְּלַת קָלִין, וּסְלִיקַת לְטוּרִין, אָמַר רַבִּי שִׁמְעוֹן לְחַבְרוֹי בְּוַדַּאי רַעֲוָא אִשְׁתַּכַּח לְעִילָא, וְרַחֲמִים אִשְׁתַּכְּחוּ לְגַבֵּי שְׁכִינְתָּא וְיִשְׂרָאֵל בְּגָלוּתָא, דְּוַדַּאי תְּלַת חֵיוָון אִינוּן בְּמֶרְכַּבְתָּא, אַרְיֵה שׁוֹר נֶשֶׁר, וּבְכֻלְּהוּ לֵית רַחֲמִים כַּנִּשְׁרָא, וּבְגִין דָּא אָמַר לְיִשְׂרָאֵל וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים וָאָבִיא אֶתְכֶם אֵלָי (שמות יט ד), אַדְהָכִי הָא נִשְׁרָא קָא אַתְיָא לְגַבַּיְיהוּ זִמְנָא אָחֳרָא, וּבָטְשַׁת בְּגַדְפָהָא עֲלַיְיהוּ, וְרָמַת קָלִין וְסָלִיק לְטוּרָא, אָמַר רַבִּי שִׁמְעוֹן בְּוַדַּאי אִיהִי דְקָא בָטְשַׁת בְּגַדְפָהָא עֲלָנָא וְסָלִיק הָתָם, אָמְרוּ לֵיהּ סְלִיק וְהָא אֲנָן אַבַּתְרָךְ, סְלִיקוּ כֻּלְּהוּ אַבַּתְרֵיהּ לְטוּרָא, וְאִיהִי סְלִיקַת לְעִילָא, עַד דְּלָא אִתְחֲזִיאַת.</p>\n<p>לְפוּם שַׁעִִתָּא הָא נִשְׁרָא קָא אַתְיָא, וּתְרֵין שׁוֹשַׁנִּים בְּפוּמָהָא, וְזָרִיק לוֹן עַל (ידהא) רֵישַׁיְיהוּ (נ\"א על ידוי) מִיָּד חָדָא רַבִּי שִׁמְעוֹן חֶדְוָה סַגִּיא, אָמַר לוֹן חַבְרַיָּא בְּוַדַּאי חֶדְוָה אִזְדַּמְנַת לְגַבֵּי שְׁכִינְתָּא דְאִיהִי חוֹלָה, דְּהָא אִם שׁוֹשַׁנָּה חֲדָא יְהִיב בֵּינָנָא לָא הֲוָה אַסְוָותָא, בְּגִין דְּשׁוֹשַׁנִּים אִינוּן רְמִיזִין לָקֳבֵל בַּיִת רִאשׁוֹן וְשֵׁנִי, דְּאוֹמֵי קוּדְשָׁא בְּרִיךְ הוּא דְלָא יֵעוּל דָּא בְּלָא דָא, וּבְגִין דִּזְרִיקַת תְּרֵין, רְמִיזַת דָּא תְּרֵי שׁוֹשַׁנִּים, כְּעַן אִיהִי אַסְוָותָא שְׁלֵימָתָא, וּכְדֵין צָרִיךְ לְמִפְתַּח עֲלַיְיהוּ כְּמָה דַהֲוִינָן.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר אֲנִי לְדוֹדִי וְדוֹדִי לִי הָרוֹעִִה בַּשּׁוֹשַׁנִּים (שיר ו ג), מַאי שׁוֹשַׁנִּים אֶלָּא שׁוֹשַׁנָּה עִלָּאָה שְׁכִינְתָּא עִלָּאָה, וְאִיהִי קְרִיאַת שְׁמַע דְּשַׁחֲרִית, וְשׁוֹשַׁנָּה תִּנְיָינָא קְרִיאַת שְׁמַע דְּעַרְבִית שְׁכִינְתָּא תַּתָּאָה, דָא לִימִינָא, וְדָא לִשְׂמָאלָא, הָרוֹעִִה בַּשּׁוֹשַׁנִּים דָּא עַמּוּדָא דְאֶמְצָעִיתָא, וְשׁוֹשַׁנָּה עִלָּאָה דִקְרִיאַת שְׁמַע דְּשַׁחֲרִית, דְּאִיהוּ בֹּקֶר יְמִינָא דְאַבְרָהָם, אִית לֵיהּ חָמֵשׁ טַרְפִין, וְאִינוּן שְׁמַע יִשְׂרָאֵל יהו\"ה אלהינ\"ו יהו\"ה (דברים ו ד), וּתְלַת עֲשַׂר עַלִּין מִלְּגָו אֶחָ\"ד, שִׁית סוּמְקֵי, וְשִׁית חִוְורֵי, וְשׁוֹשַׁנָּה דְּאִתְכְּלִילַת בְּהוֹן הָא תְּלַת עִִשֶׂר כְּחוּשְׁבַּן אֶחָ\"ד, וְכֵן שׁוֹשַׁנָּה בָּהּ כ\"ה גַרְעִינִין כְּתַפּוּחַ דִּילָהּ, כְּחֻשְׁבַּן כ\"ה אַתְוָון דְּיִחוּדָא, וְכֵן בַּשּׁוֹשַׁנָּה תִּנְיָינָא כ\"ה גַרְעִינִין, וְסָלְקִין כֻּלְּהוּ לַחֲמִשִּׁים, שׁוֹשַׁנָּה בֵּין הַחוֹחִים דָּא בְּרֵאשִׁית בָּרָא, וְדָא (בראשית ב' שושנה י').</p>\n<p>בְּרֵאשִׁית ב' שׁוֹשַׁנָּה, חָמֵשׁ עַלִּין דִּילָהּ רֵאשִׁי\"ת, בְּרֵאשִׁית לְחֻשְׁבָּן זְעִיר דַּחֲנוֹךְ תְּלַת עֲשַׂר, חוֹחִים דִּילָהּ תְּלַת עֲשַׂר תֵּיבִין מִן אלהי\"ם וְעַד אלהי\"ם, וְאִלֵּין אִינוּן. אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם וְרוּחַ אלהי\"ם (בראשית א א), חָמֵשׁ חוֹחִים אָחֳרָנִין, מְרַחֶפֶת עַל פְּנֵי הַמָּיִם וַיֹּאמֶר.</p>\n<p>מַאי אִיהִי בֵּין הַחוֹחִים, אֶלָּא מִדְּחָרַב בֵּי מַקְדְּשָׁא וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ, וְנָפְלַת שׁוֹשַׁנָּה בֵּין הַחוֹחִים, כַּד יֵיתֵי פוּרְקָנָא תִהְיֶה כַּשּׁוֹשַׁנָּה דְשַׁחֲרִית, דְּאִתְּמַר בָּהּ (בראשית מד ג) הַבֹּקֶר אוֹר (והאנשים שלחו), וְאִינוּן חָמֵשׁ אוֹר חָמֵשׁ עַלִּין דְּשׁוֹשַׁנָּה עִלָּאָה, חַד וַיֹּאמֶר אלהי\"ם יְהִי אוֹר, תִּנְיָינָא וַיְהִי אוֹר, תְּלַת וַיַּרְא אלהי\"ם אֶת הָאוֹר, אַרְבַּע וַיַּבְדֵּל אלהי\"ם בֵּין הָאוֹר, חָמֵשׁ וַיִּקְרָא אלהי\"ם לָאוֹר יוֹם, תְּלַת עֲשַׂר עַלִּין מִלְּגָו, וַיְהִי עִִרֶב וַיְהִי בֹקֶר יוֹם אֶחָד, אֶחָד אֶחָד בִּתְרֵין שׁוֹשַׁנִּים, דָּא יהו\"ה, עֲלֵיהּ אִתְּמַר (זכריה יד ט) בַּיּוֹם הַהוּא יִהְיֶה יהו\"ה אֶחָד וּשְׁמוֹ אֶחָד, וְאִיהוּ עַמּוּדָא</p>"],[9500011142,"<p>דְאֶמְצָעִיתָא הָרוֹעִִה בַשּׁוֹשַׁנִּים, וְחוּשְׁבָּנֵיהּ אֶחָ\"ד, שׁוֹשַׁנָּה תַּתָּאָה בָּהּ דְּחִילוּ וְאִיהוּ יִרְאָה, שׁוֹשַׁנָּה עִלָּאָה רְחִימוּ דְאַהֲבָה, וּבָהּ אִתְּמַר (שיר ג ה) אִם תָּעִירוּ וְאִם תְּעוֹרְרוּ אֶת הָאַהֲבָה עַד שֶׁתֶּחְפָּץ.</p>\n<p>בַּמֶּה יֵתוּן לְאַתְעָרָא לָהּ בִּימִינָא, וְאִיהִי לָא רְעִית בְּהוּ, עַד דְּיֵיתֵי רַעִִיָא מְהֵימְנָא, דְאִתְּמַר בֵּיהּ (בראשית א ב) וְרוּחַ אלהי\"ם מְרַחֶפֶת, דְּאִיהוּ רוּחַ דְּמָשִׁיחַ, דְּאִתְּמַר בֵּיהּ (ישעיה יא ב) וְנָחָה עָלָיו רוּחַ יהו\"ה, בְּרוּחָא דָא אָרְחַת הַהִיא חוֹלָה וְאִתְּסִיאַת, וּבְגִין דָּא הִשְׁבַּעִִתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלַםִ בִּצבאו\"ת אוֹ בְּאַיְלוֹת הַשָּׂדֶה אִם תָּעִירוּ וְאִם תְּעוֹרְרוּ אֶת הָאַהֲבָה עַד שֶׁתֶּחְפָּץ (שיר ג ה), וְאִיהוּ אָרַח רֵיחַ בִּתְרֵין תַּפּוּחִין (נ\"א ואיהו ריח דתרין תפוחין), דְּאִתְּמַר (ביה) בְּהוּ (שם ז ט) וְרֵיחַ אַפֵּךְ כַּתַּפּוּחִים, וּמַאי נִינְהוּ תְּרֵי סַמְכֵי קְשׁוֹט וְאִינוּן תְּרֵי רִמּוֹנִים, אֱגוֹז דָּא צַדִּיק גִּנַּת אֱגוֹז דָּא שְׁכִינְתָּא, וְדָא אִיהוּ דְאָמַר שְׁלֹמֹה (שם ו יא) אֶל גִּנַּת אֱגוֹז יָרַדְתִּי.</p>\n<p>גִּנַּ\"ת ג' גִּימַטְרִיָּאוֹת (אדנ\"י ביהו\"ה), דְּאִינוּן פַּרְפְּרָאוֹת לַחָכְמָה, נ' נוֹטְרִיקוּן, ת' תְּמוּרָה, גִּימַטְרִיָּאוֹת דָּא אדנ\"י יהו\"ה, סָלִיק בְּחֻשְׁבַּן אָמֵ\"ן, אהי\"ה אדנ\"י סָלִיק בְּחוּשְׁבַּן פ\"ו אלהי\"ם, דְּאִיהוּ כִּנּוּ\"י, מ\"ה מֵ\"ם הֵ\"א, מֵ\"ם הֵ\"א בְּגִימַטְרִיָּא אלהי\"ם, יו\"ד ה\"א וא\"ו ה\"א בְּגִימַטְרִיָּא מ\"ה, וְדָא אִיהוּ עִִשֶׂר סְפִירוֹת בְּלִימָ\"ה, וְאִיהוּ מֵעִיד עַל יִחוּדָא קַדִּישָׁא, וּבְגִין דָּא מָ\"ה אֲעִידֵךְ (איכה ב יג).</p>\n<p>דָּבָר אַחֵר א\"ב ג\"ד ה\"ו ז\"ח ט\"י בְּגִימַטְרִיָּא שְׁכִינָ\"ה, כְּגַוְונָא דָא, א' זִמְנָא חֲדָא, ב' תְּרֵי זִמְנִין, ג' תְּלַת זִמְנִין, ד' אַרְבָּעָה זִמְנִין, ה' חָמֵשׁ זִמְנִין, ו' שִׁית זִמְנִין, ז' שִׁבְעָה זִמְנִין, ח' תְּמַנְיָא זִמְנִין, ט' תִּשְׁעָה זִמְנִין, י' עִִשֶׂר זִמְנִין, כֻּלְּהוּ סָלְקִין לְחוּשְׁבַּן שְׁכִינָ\"ה. וְרָזָא דְחוּשְׁבָּנָא, לְקַיְימָא דְלֵית שְׁכִינָה נָחֲתָא פָּחוּת מֵעֲשָׂרָה, וְלָא סָלְקָא לְמַעִִלָה מֵעִִשֶׂר.</p>\n<p>וְעוֹד קוּדְשָׁא בְּרִיךְ הוּא הוּא אַתְרֵיהּ דְּעָלְמָא, וּמַלְאָכִין לָא יָדְעִין וְשָׁאֲלִין אַיֵּה מְקוֹם כְּבוֹדוֹ לְהַעֲרִיצוֹ וְאַשְׁכַּחִינָן לֵיהּ בְּגִימָטְרִיָא מָקוֹם נוֹטְרִיקוּ\"ן כְּגַוְונָא דָא, י' עִִשֶׂר זִמְנִין מֵאָה, ה' חָמֵשׁ זִמְנִין עִִשְׂרִין וְחָמֵשׁ, ו' שִׁית זִמְנִין תְּלָתִין וְשִׁית ה' חָמֵשׁ זִמְנִין עִִשְׂרִין וְחָמֵשׁ, בְּגִימַטְרִיָּא מָקוֹם, וַעֲלֵיהּ אָמְרוּ מַלְאָכַיָּא בָּרוּךְ כְּבוֹד יהו\"ה מִמְּקוֹמוֹ (יחזקאל ג יב), אִית אָחֳרָנִין בְּגִימַטְרִיָּאוֹת דְּלֵית לוֹן חוּשְׁבָּן, בְּגִין דְּאִינוּן פַּרְפְּרָאוֹת לַחָכְמָה דְלֵית לָהּ סוֹף, תְּמוּרוֹת אִלֵּין אַלְפָא בֵּיתוֹת כְּגוֹן כוז\"ו במוכס\"ז כוז\"ו, דְאִינוּן תְּמוּרוֹת (דברים ו ד) יהו\"ה אלהינ\"ו יהו\"ה, וְאִית תְּמוּרוֹת אָחֳרָנִין מִכַּמָּה מִינִין.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר וְהָא כְתִיב (מלאכי ג ו) אֲנִי יהו\"ה לֹא שָׁנִיתִי, אָמַר לֵיהּ בְּרִי, וַוי לִבְנֵי עָלְמָא דְאִינוּן אֲטִימִין לִבָּא, דְּחָשְׁבִין דְּיָדְעִין וְלָא יָדְעִין, וַדַּאי אֲנִי אִיהִי שְׁכִינְתָּא, הֲדָא הוּא דִכְתִיב (ויקרא כו כא) וְיִסַּרְתִּי אֶתְכֶם אַף אָנִי, אִיהִי לָא אִשְׁתַּנִּי וְלָא אִיהִי תְמוּרָה מִינֵיהּ בְּאָחֳרָא, וְאִיהוּ לָא אִשְׁתַּנִּי וְלָא אִסְתַּתַּר מִינָהּ, אֲבָל לְגַבֵּי חַיָּיבַיָּא אִשְׁתַּנִּי קוּדְשָׁא בְּרִיךְ הוּא וְאִסְתַּתַּר מִנַּיְיהוּ, הֲדָא הוּא דִכְתִיב (דברים לב כ) אַסְתִּירָה פָנַי מֵהֶם אֶרְאֶה מָה אַחֲרִיתָם, וְאַמַּאי בְּגִין כִּי דוֹר תַּהְפּוּכוֹת הֵמָּה בָּנִים לֹא אֵמוּן בָּם.</p>\n<p>מִיָּד קָמוּ כֻּלְּהוּ חַבְרַיָּא דְשָׁמְעוּ מִלִּין אִלֵּין, וְנָשְׁקוּ לֵיהּ עַל רֵישֵׁיהּ, וְאָמְרוּ אִלּוּ לָא אָתֵינָא לְעָלְמָא אֶלָּא לְמִשְׁמַע דָּא דַיֵּינוּ, דְּוַדַּאי קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ לָא אִשְׁתַּנִּי דָא מִן דָּא, אֲבָל לְגַבֵּי אָחֳרָנִין אִשְׁתַּנִּי וְאִסְתַּתַּר, בְּכַמָּה לְבוּשִׁין, וּבְכַמָּה כִּסּוּיִין, וּבְכַמָּה קְלִיפִין, וּבְגִין דָּא אָמַר שְׁלֹמֹה עָלָיו הַשָּׁלוֹם (שיר ו יא) אֶל גִּנַּת אֱגוֹז יָרַדְתִּי, דְאִיהוּ הֲוָה יָדַע בִּקְלִיפִין כֻּלְּהוּ, וּבְגִין דָּא לָא שְׁבִיק אֲפִילוּ מִינֵי דְכִשּׁוּף דְּלָא יָדַע, בְּגִין דְּיָדַע (נ\"א למנדע) בִּקְלִיפִין. וְרַעִִיָא מְהֵימְנָא אִיהוּ תַבַּר כָּל קְלִיפִין, וְנָפִיק מִתַּמָּן מוֹחָא דְאִיהוּ יהו\"ה לְאַרְבַּע סִטְרֵי דֶאֱגוֹזָא, (דאינון תהו ובהו וחשך ותהום), וּמְפַרְנֵס מִנֵּיהּ לְהַהִיא חוֹלָה דְּאִיהִי אדנ\"י, דִּבְאִלֵּין קְלִיפִין דִּי בֶאֱגוֹז דְּאִינוּן תֹּהוּ וָבֹהוּ וְחֹשֶׁךְ וּתְהוֹם אָמַר (דברים לב כ) אַסְתִּירָה פָנַי מֵהֶם, וְאִית שִׁנּוּיִין אוֹחֳרָנִין לְטַב לְכָל חַד כְּפוּם עוֹבָדֵיהּ.</p>"],[9500011143,"<p>זִמְנִין אִתְגַּלְיָא לוֹן בִּדְמוּת אַרְיֵה, הֲדָא הוּא דִכְתִיב (עמוס ג ח) אַרְיֵה שָׁאָג מִי לֹא יִירָא, זִמְנִין בְּדִיּוֹקְנָא דְשׁוֹר, הֲדָא הוּא דִכְתִיב (דברים לג יז) בְּכוֹר שׁוֹרוֹ הָדָר לוֹ וְקַרְנֵי רְאֵם קַרְנָיו, וְזִמְנִין בְּדִיּוֹקְנָא דְּנֶשֶׁר, הֲדָא הוּא דִכְתִיב (שם לב יא) כְּנֶשֶׁר יָעִיר קִנּוֹ, וְזִמְנִין בְּדִיּוֹקְנָא דְאָדָם סָבָא, כְּמָה דְּאִתְדַּמְיָא לְאִלֵּין דְּאָמְרֵי זֶה אֵלִי וְאַנְוִהוּ (שמות טו ב), דְּאִיהוּ הֲוָה אִתְדַּמְיָין לוֹן בִּדְמוּת סָבָא, וְאִתְּמַר בְּהוּ (נ\"א ביה) (דברים לב יג) וַיֵּנִיקֵהוּ דְבַשׁ מִסֶּלַע וְשֶׁמֶן מֵחַלְמִישׁ צוּר, אֲבָל לְאִלֵּין דְּתַלְיָין מִנֵּיהּ וּמִשְּׁכִינְתֵּיהּ לָא אִשְׁתַּנֵּי לְעוֹלָם.</p>\n<p>וְאִינוּן תְּמוּרוֹת אִינוּן רָזָא דְיִבּוּם, דְּאִתְּמַר בָּהּ בַּיְבָמָה (רות ד ז) עַל הַגְאוּלָה וְעַל הַתְּמוּרָה, לְקַיֵּים כָּל דָּבָר שָׁלַף אִישׁ נַעֲלוֹ וְנָתַן לְרֵעִהוּ, בְּהַהוּא נַעַל דְּנָתַן לְרֵעִהוּ אִית תְּמוּרָה, וְשִׁנּוּי רָצוֹן, וְתַמָּן צָרִיךְ שִׁנּוּי מָקוֹם וְשִׁנּוּי הַשֵּׁם וְשִׁנּוּי מַעֲשֶׂה לְקַיֵּים כָּל דָּבָר, נַעַל אִיהוּ גוּפָא.</p>\n<p>וְאַמַּאי בַּחֲלִיצַת נַעַל דְּנָתַן לְרֵעִהוּ אִית תְּמוּרָה וְשִׁנּוּי, אָמַר סָבָא חֲדָא, רַבִּי רַבִּי, לָא תֵימָא הָכִי, אֶלָּא אַמַּאי חֲלִיצָה בַּנַּעַל, אֶלָּא אִיהוּ קְלִיפָה לְאִתְטַמְרָא בָּהּ לְאִשְׁתֵּזָבָא מִנֵּיהּ, וְלָא אִשְׁתְּמוֹדָע לְגַבֵּי מְקַטְרְגִין דִּילֵיהּ, וּבַחֲלִיצָה דְּנַעַל חָלַץ לֵיהּ י\"ה, וּבְגִין דָּא שָׁלַף אִישׁ נַעֲלוֹ וְנָתַן לְרֵעִהוּ, נַעַל ו', גַּן נָעְִל, דְּאִיהוּ בֶּן י\"ה, לְאַעָלָא בֵּין ו\"ה, וְדָא אִיהוּ חָלַץ י\"ה.</p>\n<p>וּמֹשֶׁה אִתְּמַר בֵּיהּ (שמות ג ה) שַׁל נְעָלֶיךָ מֵעַל רַגְלֶיךָ, דָּא בְּהִפּוּכָא דְאָחֳרָנִין, דְּלָא צָרִיךְ לְאִתְחַזְיָא קֳדָם שְׁכִינְתָּא בִּקְלִיפָה, וְרָזָא דְמִלָּה כִּי אֵין לָבֹא אֶל שַׁעַר הַמֶּלֶךְ בִּלְבוּשׁ שָׂק (אסתר ד ב), וּלְגַבֵּי אֲבָהָן לָא אִתְחַזְיָא אֶלָּא בַּנְּעָלִים, הֲדָא הוּא דִכְתִיב (שיר ז ב) מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים בַּת נָדִיב, אֲבָל לְגַבֵּי מֹשֶׁה בְּלָא כִּסּוּיָא כְּלָל, וְרָזָא דְמִלָּה וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵ\"ל שׁד\"י, וּשְׁמִי יהו\"ה לֹא נוֹדַעִִתִּי לָהֶם (שמות ו ג), וּמֹשֶׁה אִתְּמַר בֵּיהּ (שם ג יג) וְאָמְרוּ לִ\"י מַ\"ה שְּׁמ\"וֹ מָ\"ה אוֹמַר אֲלֵיהֶם.</p>\n<p>וְעוֹד אַמַּאי צָרִיךְ חֲלִיצָה בַּנַּעַל בְּאִשָּׁה, בְּגִין דְּמָאן דְּיָמוּת בְּלָא בַּר אִיהוּ קָשִּׁיר בְּרַגְלֵיהּ דְּיָבָם, וְרָזָא דְמִלָּה הוּא יְשׁוּפְךָ רֹאשׁ וְאַתָּה תְּשׁוּפֶנוּ עָקֵב (בראשית ג יד), וּבְגִין דְּלָא יָמִית לֵיהּ חִוְיָא דְּאִיהוּ כָּרוּךְ עַל עֲקֵבוֹ, צָרִיךְ לַחֲלוֹץ לְגַבֵּי נַעַל דְּאִתְּתָא, וְאִתְפַּטַּר הַהוּא חִוְיָא מִנֵּיהּ.</p>\n<p>וְכֹלָּא עַל הַהִיא טִפָּה דְּאִיהִי י' דְפָרַח מִן יַעֲקֹב לְאַתְרֵיהּ, וְיַעֲקֹב בְּגִין דָּא קָנָה מִנֵּיהּ בְּכֵרוּתָא, לְאַחְזָרָא י' לְאַתְרֵיהּ, דְּאִיהִי טִפָּה בּוּכְרָא, דְּבָהּ חָאב אָדָם, וּפָרַח מִנֵּיהּ וְאִשְׁתָּאַר יָחִיד בְּלָא עִזֶר, וּבְגִין דָּא אָמַר (תהלים מט ו) לָמָּה אִירָא בִּימֵי רָע עֲוֹן עֲקֵבַי יְסוּבֵּנִי, וּבְגִין דָּא אַיְתִי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא תְּלַת זִמְנִין לְאָדָם קַדְמָאָה בְּגִלְגּוּלָא, הֲדָא הוּא דִכְתִיב (איוב לג כט) הֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר, וְדָא אִיהוּ שִׁנּוּי מָקוֹם וְשִׁנּוּי הַשֵּׁם וְשִׁנּוּי מַעֲשֶׂה.</p>\n<p>וְעַל הַהִיא טִפָּה אִתְּמַר בָּהּ (שיר ז ב) מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים בַּת נָדִיב, וְאִתְדַּבְּקַת בְּיַעֲקֹב, וְאַפִּיקַת מִנֵּיהּ י\"ב שִׁבְטִין, הֲדָא הוּא דִכְתִיב (תהלים קכב ד) שִׁבְטֵי י\"הּ עִדוּת לְיִשְׂרָאֵל, דְּאִתְּמַר בֵּיהּ אָדָם יִשְׂרָאֵל, וּבְהַהוּא זִמְנָא רָוַוח יַעֲקֹב מַה דְּאָבִיד דְאִיהוּ י' מִיַּעֲקֹב, הֲדָא הוּא דִכְתִיב (בראשית לב כט) לֹא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְךָ כִּי אִם יִשְׂרָאֵל.</p>\n<p>בְּאַבְרָהָם שֵׁזִיב מִסַּם הַמָוְת, חוֹבָא דְאָדָם, גֵּיהִנָּם, נָחָשׁ, אֵשֶׁת זְנוּנִים דְּאִתְּמַר בֵּיהּ (שמות כ יד) לֹא תִנְאָף. בְּיִצְחָק שֵׁזִיב מֵאֵל אַחֵר דְּאִתְּמַר בֵּיהּ (שם יג) לֹא תִרְצַח. בְּיַעֲקֹב אַשְׁכַּח אֲתַר לְיַנְקָא (נ\"א לנקאה) בְּנוֹי, וְדָא שִׁנּוּי מָקוֹם, וְלֵית חַד מִנַּיְהוּ דְּלָא אִתְכְּלִיל בִּתְלָתָא, לְקַיְימָא הֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלוֹשׁ עִם גָּבֶר (איוב לג כט).</p>\n<p>קָם סָבָא וְאָמַר רַבִּי רַבִּי בְּמַאי אוּקִימְתָּא סוֹד יִבּוּם וַחֲלִיצָה, דְּהָא בְּרִירָא דְמִלָּה שְׁמַעִִנָא, אָמַר לֵיהּ מַה דִּשְׁמַעִִתְּ אֵימָא, אָמַר וַדַּאי בְּרָזָא דְיִבּוּם אַשְׁכַּח אַתְרָא הַהִיא נִשְׁמָתָא עַרְטִילָאָה, הֲדָא הוּא דִכְתִיב (תהלים פד ד) גַּם צִפּוֹר מָצְאָה בַיִת, וְדָא נֶפֶשׁ דְּאַתְיָא בְּגִלְגּוּל זִמְנָא קַדְמָאָה, וּדְרוֹר קֵן לָהּ (שם), דָּא רוּחָא דְּאַתְיָא בְגִלְגּוּלָא זִמְנָא תִנְיָינָא, אֲשֶׁר שָׁתָה אֶפְרוֹחֶיהָ (שם), דָּא נִשְׁמָתָא דְאַתְיָא בְגִלְגּוּלָא זִמְנָא תְּלִיתָאָה, וּמִינָהּ נָפְקִין אֶפְרוֹחִין דְּאִינוּן בְּנִין, וּבְרָזָא דְיִבּוּם כֻּלְּהוּ תְּלַת נָחֲתִין בְּבַת אַחַת, הֲדָא הוּא דִכְתִיב (איוב לד יד) אִם יָשִׂים אֵלָיו לִבּוֹ רוּחוֹ וְנִשְׁמָתוֹ</p>"],[9500011144,"<p>אֵלָיו יֶאֱסוֹף, לִבּוֹ דְתַמָּן נֶפֶשׁ, רוּחַ בְּכַנְפֵי רֵיאָה, נִשְׁמָתָא בְמוֹחָא, וְכֻלְּהוּ חַד בְּקִשׁוּרָא חֲדָא, אֲבָל חֲלִיצָה אִיהִי שֵׁזְבַת הַהִיא נִשְׁמָתָא וְרוּחָא וְנַפְשָׁא דְּאִינוּן קְטִירִין בִּתְלַת קִשּׁוּרִין דְּחִוְיָא, וְרָזָא דְּמִלָּה נַפְשֵׁנוּ כְּצִפּוֹר נִמְלְטָה מִפַּח יוֹקְשִׁים הַפַּח נִשְׁבַּר וַאֲנַחְנוּ נִמְלָטְנוּ (תהלים קכד ז), קָם רַבִּי שִׁמְעוֹן כְּדֵי לְנַשְׁקָא לֵיהּ, פָּרַח מִיָּד וְלָא אִתְחֲזִי. (תקון כ\"ז נדפס בהקדמה כי שם ביתו)</p>\n<p>בְּרֵאשִׁית בֵּיהּ תְּלַת פִּקּוּדִין, חַד יִרְאַת יהו\"ה כְּגַוְונָא דָא בְּרֵאשִׁי\"ת יְרָ\"א בֹּשֶׁ\"ת וְהָא אוּקְמוּהוּ, תִּנְיָינָא בְּרִית כְּגַוְונָא דָא בְּרֵאשִׁי\"ת בְּרִי\"ת אֵ\"שׁ, תְּלִיתָאָה שַׁבָּת כְּגַוְונָא דָא שַׁבָּ\"ת יָרֵ\"א.</p>\n<p>פִּקּוּדָא קַדְמָאָה יִרְאַת יהו\"ה, עֲלֵיהּ אִתְּמַר (ישעיה לג ו) יִרְאַת יהו\"ה הִיא אוֹצָרוֹ, וְעוֹד אִתְּמַר בָּהּ (משלי א ז) יִרְאַת יהו\"ה רֵאשִׁית דָּעַת, רֵאשִׁית חָכְמָה יִרְאַת יהו\"ה (תהלים קיא י), וּבְוַדַּאי מָאן דְּלֵית בֵּיהּ דְּחִילוּ דְאִיהוּ אוֹצָר, לֵית תַּמָּן חָכְמָה, אוֹצָרָא דְהַאי חָכְמָה אִיהִי ב', וּבְתִקּוּנָא אָחֳרָא בְּרֵאשִׁית בּ' רֵאשִׁית, נְקוּדָה בְּהֵכָלֵיהּ, עֲלֵיהּ אִתְּמַר (שיר ד יב) גַּן נָעוּל אֲחוֹתִי כַלָּה גַּל נָעוּל מַעִִיָן חָתוּם, גַּן אִיהוּ אוֹרַיְיתָא דְבִכְתָב, דְּאִיהוּ גַּ\"ן סְדָרִים דְּאוֹרַיְיתָא, גַּל אִיהוּ אוֹרַיְיתָא דִבְעַל פֶּה, וְתַרְוַיְהוּ ב' מִבְּרֵאשִׁית, מַעִִיָן חָתוּם דָּא רֵאשִׁית נְקוּדָה בְהֵיכָלֵיהּ.</p>\n<p>וּבְמַאי אִיהוּ חָתוּם, בְּאוֹת ו', וְאִתְעֲבִידַת ב' עִם חֲתִימוּ דְו' ם, מַה דַּהֲוָה ב' אִתְעֲבִידַת ם, יַיִן סָתוּם וְחָתוּם, יֵינָא דְאוֹרַיְיתָא סָתִים וְחָתִים דְּלָא יֵעוּל נוּכְרָאָה תַּמָּן, וְדָא יַיִן הַמְּשׁוּמָּר בַּעֲנָבָיו מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית, וְלַאו לְמַגָּנָא תַקִּינוּ מָארֵי מַתְנִיתִין, חֲתִימַת יַיִן דְּלָא יִתְנַסֵּךְ וְיִתְעָרֵב בְּסִטְרָא אָחֳרָא, וְעַל הַאי יַיִן אִתְּמַר (תהלים קמז יב) לֹא עָשָׂה כֵן לְכָל גּוֹי וּמִשְׁפָּטִים בַּל יְדָעוּם, כֵּ\"ן וַדַּאי יַיִ\"ן שַׁבְעִין אַנְפִּין דְּאוֹרַיְיתָא, וַעֲלַיְיהוּ אִתְּמַר (שם כה יד) סוֹד יהו\"ה לִירֵיאָיו.</p>\n<p>קַנְקַן דְּהַאי יַיִ\"ן דָּא לִבָּא דְבַר נַשׁ, אִם הוּא קַנְקַנָּא חַדְתָּא וְאִתְנַסַּךְ בְּיַיִן נֶסֶךְ דְּאִיהוּ יִצְרָא בִישָׁא, צָרִיךְ תְּלָתָא זִמְנִין הֲדָחָה, וְהֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר (איוב לג כט), וְלַאו לְמַגָּנָא תַּקִּינוּ בְּכוֹס דִּבְּרָכָה אוּף הָכִי הֲדָחָה וּשְׁטִיפָה, הֲדָחָה מִבִּפְנִים שְׁטִיפָה מִבַּחוּץ, לְמֶהֱוֵי תּוֹכוֹ כְּבַרוֹ, וְרָזָא דְמִלָּה וְטִהֲרוֹ וְקִדְּשׁוֹ (ויקרא טז יט), וְכַד אִיהוּ קַנְקַן דְּאִיהוּ לִבָּא דַּכְיָא מִלְּגָאו וּמִלְּבָר, שַׁרְיָא תַמָּן חָכְמָה, דְּאִתְּמַר בָּהּ (משלי ח כב) יהו\"ה קָנָנִי רֵאשִׁית דַּרְכּוֹ קָנָנִי אִיהוּ קַנְקַן וַדַּאי, וְאִם הַאי קַנְקַן אִיהוּ דַכְיָא, אִתְּמַר בֵּיהּ וְנַקֵּה, וְאִם לַאו לֹא יְנַקֵּה כָּל הַנּוֹגֵעַ בָּהּ (שם ו כט).</p>\n<p>וְקַנְקַן דְּבַר נַשׁ דָּא אִתְּתָא, וְאִיהוּ כּוֹס, לְהָכִי צְרִיכָה שְׁטִיפָה וַהֲדָחָה, אִם הִיא כוֹס דִּבְרָכָה, וַעֲלָהּ אִתְּמַר (יחזקאל מד ל) לְהָנִיחַ בְּרָכָה אֶל בֵּיתֶךָ, וְאִם לַאו אִתְקְרִיאַת כּוֹס הַתַּרְעִלָה, וְיַיִן דִּילָהּ עֲלֵיהּ אִתְּמַר (משלי לא ו) תְּנוּ שֵׁכָר לְאוֹבֵד וְיַיִן לְמָרֵי נָפֶשׁ וכו', שָׁדַיִם דִּילָהּ אִינוּן אַשְׁכּוֹלוֹת מְרוֹרוֹת, אֲבָל יַיִן דְּכוֹס דִּבְרָכָה עֲלֵיהּ אִתְּמַר (תהלים קד טו) וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ דְּתַמָּן פִּקּוּדֵי יהו\"ה יְשָׁרִים מְשַׂמְּחֵי לֵב (שם יט טו), דְּאִינוּן אֶשְׁכּוֹלוֹת דִּילָהּ.</p>\n<p>בְּרֵאשִׁית בָּרָא אלהי\"ם, בּ' נְקוּדָה בְּהֵיכָלֵיהּ, עֲלֵיהּ אִתְּמַר (שיר ד יב) גַּן נָעוּל אֲחוֹתִי כַלָּה גַּל נָעוּל מַעִִיָן חָתוּם, מָאן מַעִִיָן חָתוּם דָּא נְקוּדָה, מָאן נִיהוּ נָעוּל</p>"],[9500011145,"<p>דִּילָהּ, דָּא ו' דְּסָתִים לְהֵיכָלָא וּבָהּ אִתְעֲבִיד ם סְתִימָא, אִיהִי ם רַבְּתָא מִלְּםַרְבֵּה הַמִּשְׂרָה (ישעיה ט ו), וְהַאי נְקוּדָה עֲלָהּ אִתְּמַר (איוב כח כא) וְנֶעִִלְמָה מֵעִינֵי כָל חָי וּמֵעוֹף הַשָּׁמַיִם נִסְתָּרָה, וְהַאי נְקוּדָה מִסִּטְרָא דִיְמִינָא אִתְקְרִיאַת אַהֲבָה, וּמִסִּטְרָא דִשְׂמָאלָא אִתְקְרִיאַת יִרְאָה, וּמִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא אִתְקְרִיאַת תּוֹרָה, וְאִיהִי מִצְוָה, דְּעַמּוּדָא דְאֶמְצָעִיתָא כְּלִיל תַּרְוַיְיהוּ, בְּגִין דְּאִיהוּ ו' כְּלִיל י\"ה דְּאִינוּן לִימִינָא וּשְׂמָאלָא, וְאִיהוּ ו' בְּאֶמְצָעִיתָא כְּלִיל תַּרְוַיְיהוּ, וּשְׁכִינְתָּא תַּתָּאָה מִצְוָה כְּלִילָא מֵאַרְבַּע אַתְוָון, אִיהִי אִתְקְרִיאַת י' מִסִּטְרָא דְחָכְמָה, ה' מִסִּטְרָא דְאִימָּא עִלָּאָה, וְאִתְקְרִיאַת תּוֹרָה מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, הֲדָא הוּא דִכְתִיב (משלי ח כב) יהו\"ה קָנָנִי רֵאשִׁית דַּרְכּוֹ, דַּרְכּוֹ דֶּרֶךְ ו', קָנָנִי דְּאִיהוּ קֵן דִּילָהּ, וּבְגִין דְּאִיהִי כְלִילָא מִכֻּלְּהוּ אַרְבַּע אִתְקְרִיאַת מִצְוָה, מ\"ץ בְּאוֹתִיּוֹת אַ\"תּ בַּ\"שׁ אִיהוּ י\"ה, י\"ם ה\"ץ, וּבָהּ כְּלִילָן פִּקּוּדִין דַּעֲשֵׂה וְלֹא תַעֲשֶׂה, פִּקּוּדִין דְּלֹא תַעֲשֶׂה מִסִּטְרָא דְּדִין דְּאִיהוּ אלהי\"ם דְּתַמָּן י\"ה, וַעֲלָהּ אִתְּמַר (שמות ג טו) זֶה שְּׁמִ\"י וְהָא אוּקְמוּהוּ, פִּקּוּדִין דַּעֲשֵׂה מִסִּטְרָא דִיְמִינָא דְאִיהוּ רַחֲמֵי דִּכְלִילָן בְּאַבְרָהָם, וַעֲלַיְיהוּ אִתְּמַר (חבקוק ג ב) בְּרוֹגֶז רַחֵם תִּזְכּוֹר</p>\n<p>קָם סָבָא חַד מִבָּתַר טוּלָא (כותלא), וְאָמַר רַבִּי רַבִּי בּוֹצִינָא קַדִּישָׁא, קוּם אַדְלֵיק שְׁרַגָּא דְאִיהִי מִצְוָה, שְׁכִינְתָּא קַדִּישָׁא, דַּעֲלָהּ אִתְּמַר (ויקרא ו ו) אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה, וַעֲלָהּ אִתְּמַר (שמות כז כ) לְהַעֲלֹת נֵר תָּמִיד, נֵר יהו\"ה אִתְקְרִיאַת וַדַּאי, אוֹר דְּנָהִיר בֵּיהּ נִשְׁמַת אָדָם, קוּם אַדְלֵיק בָּהּ.</p>\n<p>קָם רַבִּי שִׁמְעוֹן עַל רַגְלוֹי וְיָתִיב רִגְעָא חֲדָא וְאָמַר, רִבּוֹן עָלְמִין דְּאַנְתְּ אִיהוּ מָארֵי מַלְכִין וְגָלֵי רָזִין, יְהֵא רַעֲוָא דִילָךְ לְסַדְרָא מִלִּין בְּפִימָאִי, לְקַיְימָא בִּי הַאי קְרָא (שם ד יב) וְאָנֹכִי אֶהְיֶה עִם פִּיךָ, דְּלָא אֵעוּל בְּכִסּוּפָא קֳדָמָךְ, פָּתַח וְאָמַר.</p>\n<p>בְּרֵאשִׁית מָאן רֵאשִׁית דָּא חָכְמָה, דָּא נְקוּדָה דִלְגַאו, דְּאִתְּמַר בָּהּ (תהלים מה יד) כָּל כְּבוּדָּה בַת מֶלֶךְ פְּנִימָה, וְדָא יִרְאָה דְּאִיהִי פִּקּוּדָא קַדְמָאָה, וַעֲלָהּ אִתְּמַר (משלי א ז) יִרְאַת יהו\"ה רֵאשִׁית דָּעַת, וְאִיהִי רְמִיזָא בְמִלַּת בְּרֵאשִׁית, וְאִית יִרְאָה רָעָה רְצוּעָה לְאַלְקָאָה לְחַיָּיבַיָּא, וְהַאי נְקוּדָה אִיהִי אוֹת שַׁבָּת וְיוֹמִין טָבִין וְאוֹת דִּתְּפִלִּין וְאוֹת דִּבְּרִית מִילָה, הַהִיא רְצוּעָה אִיהִי יִרְאָה רָעָה אִיהִי עָרְלָה, זַכָּאָה אִיהוּ מָאן דְּאַעֲבַר לָהּ מִנֵּיהּ, דְּלֵית לָהּ רְשׁוּ לִרְצוּעָה לְאַלְקָאָה לֵיהּ, וְהַאי נְקוּדָה עֲלָהּ אִתְּמַר (שמת לא יד) מְחַלֲלֶיהָ מוֹת יוּמָת, מַאי מְחַלֲלֶיהָ אֶלָּא מָאן דְּאַעִיל רְשׁוּ נוּכְרָאָה בְּחָלָל דִּילָהּ דְּאִיהִי רְשׁוּת הַיָּחִיד, דַּעֲלָהּ אִתְּמַר (במדבר יט כ) וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא מִתּוֹךְ הַקָּהָל כִּי אֶת מִקְדַּשׁ יהו\"ה טִמֵּא.</p>\n<p>וְכֹלָּא אִתְרְמִיז בְּהַאי תֵּיבָה יִרְאָ\"ה בְּרִי\"ת שַׁבָּ\"ת, כְּגַוְונָא דָא יִרְאַ\"ת בְּרֵאשִׁי\"ת, בְּרִי\"ת בְּרֵאשִׁי\"ת, שַׁבָּ\"ת בְּרֵאשִׁי\"ת, וְהַאי נְקוּדָה אִיהִי רֵאשִׁית, יהו\"ה קָנָנִי רֵאשִׁית דַּרְכּוֹ (משלי א כב), כְּגַוְונָא דָא בְּרֵאשִׁית, כֹּלָּא אִיהִי נְקוּדָה חֲדָא, אִיהִי רֵאשִׁית, וְאִיהִי אוֹת בְּרִית, וְאִיהִי אוֹת שַׁבָּת, וְאִיהִי יִרְאַת יהו\"ה.</p>\n<p>מָאן חָלָל דִּילָהּ בּ, ו' אִיהוּ בַּעִִלָהּ, בֵּיהּ אִיהִי נְטִירָא וּסְתִימָא בְּגָלוּתָא, הֲדָא הוּא דִכְתִיב (יחזקאל מו א) יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה, כְּגַוְונָא דָא ם סְתִימָא, וְהָא אִתְּמַר, וּנְקוּדָה אִיהִי שְׁבִיעָאָה תַּגָּא עַל רֵישֵׁיהּ, תַּגָּא דְסֵפֶר תּוֹרָה, עֲטָרָה עַל בְּרִית, ז' דְּאִיהִי יוֹם שְׁבִיעִי יוֹם הַשַּׁבָּת, שְׁבִיעִי וַדַּאי, וַעֲלֵיהּ אִתְּמַר וּבְיוֹם הַשַּׁבָּת יִפָּתֵחַ, אֲבָל בְּיוֹמִין דְּחוֹל גַּן נָעוּל אֲחוֹתִי כַלָּה (שיר ד יב).</p>"],[9500011146,"<p>אִתְקְרִיאַת סְתִימָא בְאוֹת ו'.</p>\n<p>וְהַאי עָרְלָה וּפְרִיעָה אִינוּן כַּמּוֹץ וְתֶבֶן דְּחִטָּה, בְּיוֹמִין דְּחוֹל אִתְקְרִיאַת הֵ\"א, דְאִיהוּ הֶבֶ\"ל לַהַ\"ב הַמִּזְבֵּחַ, לְאַדְלָקָא מוֹץ וְתֶבֶן, וְאִשְׁתְּאָרַת אִיהִי סֹלֶת נְקִיָּה, אֲבָל בְּיוֹמִין דְּשַׁבָּת וְיוֹמִין טָבִין אִתְקְרִיאַת י' עֲטָרָה עַל כֹּלָּא, וּבֵיתָא, (נ\"א וכסא) דִּילָהּ, ל\"ב אלהי\"ם דְּעוֹבָדָא דִבְּרֵאשִׁית, וְאִיהִי ב' כְּלִילָא מֵעֲשַׂר אֲמִירָן בְּכָל סִטְרָא, הַאי י' אִתְקְרִיאַת יִרְאָה, בֵין בְּשַׁבָּת בֵּין בִּבְרִית מִילָה בֵין בְּדִינָא וְהָכִי בְכָל פִּקּוּדָא.</p>\n<p>אלהי\"ם דָּא נָתִיב קַדְמָאָה, עֲלֵיהּ אִתְּמַר (איוב כח ז) נָתִיב לֹא יְדָעוֹ עָיִט וְלֹא שְׁזָפַתּוּ עִין אַיָּה, מַאי עִין אַיָּה, אֶלָּא מֵאִינוּן מַלְאָכִין דְּאָמְרִין אַיֵּה מְקוֹם כְּבוֹדוֹ לְהַעֲרִיצוֹ, כַּד אִיהִי בְּהַאי נָתִיב לֵית לוֹן יְדִיעָה בָּהּ, דְּאִיהִי סְתִירָא מֵחֵיוָן דְּמֶרְכַּבְתָּא.</p>\n<p>וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ (בראשית א ב), מַאי וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ, אֶלָּא מָאן דְּאַפִּיק מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הָרַבִּים גָּרִים לִשְׁכִינְתָּא, לְמֶהֱוֵי תֹהוּ וָבֹהוּ חֹשֶׁךְ וּתְהוֹם, דְּאִתְלַבְּשַׁת בְּאִינוּן קְלִיפִין, דְּאִינוּן אַרְבַּע גָּלֻיּוֹת, וְלָא עוֹד אֶלָּא דְגָרִים לָהּ לְמֶהֱוִי יַבָּשָׁה תֹהוּ, דְּאִסְתַּלְּקַת נְקוּדָה מֵחָלָל דִּילָהּ דְּאִיהִי ב', וְאִשְׁתְּאָרַת יְבֵישָׁה.</p>\n<p>נָתִיב תִּנְיָינָא, וְרוּחַ אלהי\"ם מְרַחֶפֶת עַל פְּנֵי הַמָּיִם (שם), מַאי וְרוּחַ, אֶלָּא בְּוַדַּאי בְּזִמְנָא דִשְׁכִינְתָּא נָחֲתַת בְּגָלוּתָא, הַאי רוּחַ נָשִׁיב עַל אִינוּן דְּמִתְעַסְּקֵי בְּאוֹרַיְיתָא, בְּגִין שְׁכִינְתָּא דְאִשְׁתַּכְּחַת בֵּינַיְיהוּ, וְהַאי רוּחַ אִתְעֲבִיד קָלָא, וְיֵימָא הָכִי אִינוּן דְּמִיכִין דְּשִׁינְתָא בְּחוֹרֵיהוֹן, סְתִימִין עַיְינִין אֲטִימִין דְּלִבָּא, קוּמוּ וְאִתְעָרוּ לְגַבֵּי שְׁכִינְתָּא, דְּאִית לְכוֹן לִבָּא בְּלָא סֻכְלְתָנוּ לְמִנְדַּע בָּהּ, וְאִיהוּ בֵּינַיְכוּ.</p>\n<p>וְרָזָא דְמִלָּה קוֹל אוֹמֵר קְרָא (ישעיה מ ו), כְּגוֹן קְרָא נָא הֲיֵשׁ עוֹנֶךָּ וְאֶל מִי מִקְּדוֹשִׁים תִּפְנֶה (איוב ה א), וְהִיא אָמְרַת מָה אֶקְרָא, כָּל הַבָּשָׂר חָצִיר, כֹּלָּא אִינוּן כִּבְעִירָן דְּאָכְלִין חָצִיר, וְכָל חַסְדּוֹ כְּצִיץ הַשָּׂדֶה (שם), כָּל חֶסֶד דְּעָבְדִין לְגַרְמַיְיהוּ עָבְדִין, וַאֲפִילוּ כָּל אִינוּן דְּמִשְׁתַּדְּלִין בְּאוֹרַיְיתָא, כָּל חֶסֶד דְּעָבְדִין לְגַרְמַיְיהוּ עָבְדִין, בְּהַהוּא זִמְנָא וַיִּזְכּוֹר כִּי בָשָׂר הֵמָּה רוּחַ הוֹלֵךְ וְלֹא יָשׁוּב (תהלים עח לט) לְעָלְמָא, וְדָא אִיהוּ רוּחָא דְמָשִׁיחַ, וַי לוֹן מָאן דְּגָרְמִין דְּיֵזִיל לֵיהּ מִן עָלְמָא וְלָא יְתוּב לְעָלְמָא, דְּאִלֵּין אִינוּן דְּעָבְדִין לְאוֹרַיְיתָא יַבָּשָׁה, וְלָא בָעָאן לְאִשְׁתַּדְלָא בְחָכְמָה דְקַבָּלָה, דְגָרְמִין דְּאִסְתַּלַּק נְבִיעוּ דְחָכְמָה דְאִיהִי י' מִינָהּ, וְאִשְׁתְּאָרַת ב' יְבֵישָׁה, וַי לוֹן דְּגָרְמִין עֲנִיּוּתָא וְחַרְבָּא וּבִיזָה וְהֶרֶג וְאַבְּדָן בְּעָלְמָא, וְהַאי רוּחַ דְּאִסְתַּלַּק אִיהוּ רוּחַ דְמָּשִׁיחַ כְּמָה דְאִתְּמַר, וְאִיהוּ רוּחַ הַקֹּדֶשׁ, וְאִיהוּ רוּחַ חָכְמָה וּבִינָה רוּחַ עִצָה וּגְבוּרָה רוּחַ דַּעַת וְיִרְאַת יהו\"ה (ישעיה יא ב).</p>\n<p>פִּקּוּדָא תִּנְיָינָא וַיֹּאמֶר אלהי\"ם יְהִי אוֹר וַיְהִי אוֹר (בראשית א ג), וְדָא אַהֲבָה דְאִיהוּ אַהֲבַת חֶסֶד, הֲדָא הוּא דִכְתִיב (ירמיה לא ב) וְאַהֲבַת עוֹלָם אֲהַבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חָסֶד, וַעֲלָהּ אִתְּמַר (שיר ב ז) אִם תָּעִירוּ וְאִם תְּעוֹרְרוּ אֶת הָאַהֲבָה עַד שֶׁתֶּחְפָּץ, יִרְאָה אִתְקְרִיאַת מִסִּטְרָא דִשְׂמָאלָא, וְאַהֲבָה אִתְקְרִיאַת מִסִּטְרָא דִימִינָא.</p>\n<p>אִית יִרְאָה וְאִית יִרְאָה, אִית אַהֲבָה וְאִית אַהֲבָה, יִרְאָה דְּדָחִיל בַּר נַשׁ לְקוּדְשָׁא בְּרִיךְ הוּא בְּגִין דְּלָא נָחִית מִנִּכְסוֹי, אוֹ בְּגִין דְּלָא יְמוּתוּן בְּנוֹי בְּחַיּיוֹי, אִשְׁתַּכַּח דְּאִם הֲוָה נָחִית מִנִּכְסוֹי אוֹ אִם יְמוּתוּן בְּנוֹי בְּחַיּיוֹי דְּלָא הֲוָה דָחִיל לֵיהּ, וּבְגִין דָּא הֲוָה רָחִים לֵיהּ, הַאי יִרְאָה וְאַהֲבָה לָא שַׁוִּי לְיִרְאַת יהו\"ה וּלְאַהֲבָה דִילֵיהּ לְעִקָּרָא, אֲבָל רְחִימוּ וּדְחִילוּ עִיקָרָא דִילֵיהּ בֵּין טַב וּבֵין בִּישׁ, וּבְגִין דָּא אִתְקְרִיאַת הַאי יִרְאָה וְאַהֲבָה עַל מְנָת לְקַבֵּל פְּרָס.</p>\n<p>וּבְגִין דָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא (שם), הִשְׁבַּעִִתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלַם בִּצבאו\"ת אוֹ בְּאַיְלוֹת הַשָּׂדֶה, אִם תָּעִירוּ וְאִם תְּעוֹרְרוּ אֶת הָאַהֲבָה עַד שֶׁתֶּחְפָּץ, דְאִיהוּ רְחִימוּ (נ\"א דאיהי רחמי) בְּלַאו פְּרָס, (עד דאיהו יחפץ), וְלָא עַל מְנָת לְקַבֵּל פְּרָס, דְּיִרְאָה וְאַהֲבָה עַל מְנָת לְקַבֵּל פְּרָס</p>"],[9500011147,"<p>אִיהִי שֶׁל שִׁפְחָה, וְתַחַת שָׁלֹשׁ רָגְזָה אֶרֶץ וְגוֹמֵר (משלי ל לא) תַּחַת עִִבֶד כִּי יִמְלוֹךְ, וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ.</p>\n<p>אלהי\"ם דָּא מִן וַיֹּאמֶר אלהי\"ם יְהִי אוֹר, אִיהוּ נָתִיב תְּלִיתָאָה, יְהִי אוֹר י\"ה אַוִּי\"ר, אוֹ\"ר י', וְכַד הַאי נְקוּדָה אִתְעַטְּפַת (נ\"א אתפשטת) בְּהַאי אוֹר וְאִתְעֲבִידַת אַוִּיר, מֵהָכָא אִתְמַשְׁכוּ כָּל הַהֲוַיּוֹת.</p>\n<p>קָם סָבָא חַד פָּתַח וְאָמַר, יְהִי אוֹר וַיְהִי אוֹר, יְהִי אוֹר דָּא יְמִינָא, וַיְהִי אוֹר דָּא שְׂמָאלָא, דִּבְכָל אֲתַר וַיְהִי אִיהוּ לָשׁוֹן צַעַר, וּבְגִין דָּא וַיְהִי הַיּוֹם דְּדָא אִיהוּ רֹאשׁ הַשָּׁנָה דְאִיהוּ שְׂמָאלָא, דְאִיהוּ דָן דִּינָא דְכָל עָלְמָא, וּבְגִינָהּ אִתְּמַר (בראשית א ג) וַיְהִי אוֹר, וַיַּרְא אלהי\"ם אֶת הָאוֹר כִּי טוֹב, דָּא עַמּוּדָא דְאֶמְצָעִיתָא דְאִיהוּ טוֹב, וַיַּבְדֵּל אלהי\"ם בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ (שם), בֵּין הָאוֹר דָּא אַהֲרֹן כַּהֲנָא, וּבֵין הַחֹשֶׁךְ דָּא קֹרַח, אָמַר מֹשֶׁה לִי אִתְחֲזֵי לְאַפְרָשָׁא מַחֲלֹקֶת, דַּאֲנָא אִיהוּ דִיּוֹקְנָא דְּטוֹב דִּלְעִילָא, חָזָא דְאִתְדַּבַּק קֹרַח בַּחֲשׁוֹכָא דְסִטְרָא אָחֳרָא, וְאַכְחִישׁ עוֹבָדָא דִבְּרֵאשִׁית, דְּלָא בָעָא לְאִתְדַּבְּקָא בִשְׂמָאלָא דְאִיהוּ לֵוִי, אָמַר הִבָּדְלוּ מִתּוֹךְ הָעִדָה הַזֹּאת (במדבר טז כא).</p>\n<p>וְרָזָא דְמִלָּה וַיַּבְדֵל אלהי\"ם בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ (בראשית א ד), וַיִּקְרָא אלהי\"ם לָאוֹר יוֹם וְלַחֹשֶׁךְ קָרָא לָיְלָה (שם ה), שׁוֹקָא דִיְמִינָא דְהוּא אוֹר, דְּאִתְּמַר וַיַּבְדֵּל אלהי\"ם בֵּין הָאוֹר אִיהוּ שׁוֹקָא יְמִינָא כַּהֲנָא, דְּאִתְּמַר בֵּיהּ (תהלים טז יא) נְעִימוֹת בִּימִינְךָ נֶצַח, וּכְמָה דְנֶצַח אִתְקַשַּׁר בִּימִינָא, הָכִי הוֹד אִתְקַשַּׁר בִּשְׂמָאלָא, וַיְהִי עִִרֶב וַיְהִי בֹקֶר יוֹם אֶחָד, עִִרֶב דָּא עִִרֶב דְּיִצְחָק, בֹּקֶר דָּא בֹקֶר דְּאַבְרָהָם, יוֹם אֶחָד עַמּוּדָא דְאֶמְצָעִיתָא וְצַדִּיק דְּחַשְׁבִינָן חַד, וְלֵית יוֹם בְּלָא לַיְלָה דְאִיהִי שְׁכִינְתָּא.</p>\n<p>אַדְהָכִי הָא קָלָא סָלִיק וּמִתְפּוֹצֵץ בְּרוּמֵי רְקִיעִין, וַהֲוָה אָמַר, מַשִּׁרְיָין קַדִּישָׁאן דִּמְתִיבְתָּא דִרְקִיעָא דִלְעִילָא וְתַתָּא, אִזְדַּרְזוּ וְאִתַּקְנוּ לְקַדְמוּת מַטְרוֹנִיתָא, דְקָא אַתְיָא לְמֵיעָאל קֳדָם מַלְכָּא, בְּכַמָּה קִשּׁוּטִין דְּפִקּוּדִין דַּעֲשֵׂה, קוּמוּ מַשִּׁרְיָין לְקַדְמוּתָהּ, אַדְהָכִי הָא קָלָא תִנְיָנָא הֲוָה מִתְעָרָא לְגַבֵּי מָארֵי מַפְתְּחָן, הָא שְׁכִינְתָּא קָא אַתְיָא לְמֵיעָאל לְהֵיכָלָא דִילָהּ, אדנ\"י שְׂפָתַי תִּפְתָּח.</p>\n<p>בְּהַהוּא זִמְנָא מַטְרוֹנִיתָא עִלָּאָה קָא נָחֲתַת לְגַבָּהּ, לְקַבְּלָא לָהּ בְּפִקּוּדָא קַדְמָאָה, בְּכַמָּה קָלִין וְשׁוֹפָרוֹת, וְסָלְקִין תַּרְוַיְיהוּ לְגַבֵּי מַלְכָּא, וְכֻלְּהוּ הֲווֹ שָׁאֲלִין (שיר ה ה) מִי זֹאת עוֹלָה מִן הַמִּדְבָּר, מִ\"י דְאִיהִי אִימָּא עִלָּאָה, בְזֹא\"ת עוֹלָה, וְכַד סְלִיקַת לְעִילָא אִתְעֲבִידַת כִּסֵּא לְמַלְכָּא עִלָּאָה, וּבָהּ פָּתַח אָנֹכִ\"י, דְהָכִי סְלִיק לְחֻשְׁבַּן כִּסֵּ\"א, וְכַד אִתְחַבְּרוּ תַּרְוַיְיהוּ אִתְּמַר בְּהוּ (שמות כ ב) אָנֹכִי יהו\"ה אלהי\"ך אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם.</p>\n<p>אֲשֶׁר אִיהוּ רְמִיז בְּמִלַּת בְּרֵאשִׁית, אֲשֶׁר דָּא אִימָּא, דְאִיהִי אֲשֶׁר אֶהְיֶ\"ה, אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו, אֲשֶׁר קִדֵּשׁ יְדִיד מִבֶּטֶן, דְּאִיהִי בֶּטֶן דְּאִתְּמַר בֵּיהּ (איוב לט כט) מִבֶּטֶן מִי יָצָא הַקָּרַח, הַקֶּרַח הַנּוֹרָא (יחזקאל א כב), מַאי נוֹרָא דָא עַמּוּדָא דְאֶמְצָעִיתָא, מַאי קִדֵּשׁ יְדִיד מִבֶּטֶן, בֶּטֶן דְּאִתְּמַר בֵּיהּ דָּא צַדִּיק, אֲשֶׁר דְּאִיהִי אִימָּא עִלָּאָה, קִדְּשָׁנוּ בְּעַמּוּדָא דְאֶמְצָעִיתָא, וְצִוָּנוּ בְּצַדִּיק, עַל כָּל פִּקּוּדָא וּפִקּוּדָא, בְּגִין דְּחַד אִיהוּ מְצֻוְּה וְחַד עוֹשֶׂה, חַד מְצֻוְּה עַל הַמִּצְוָה דְאִיהִי שְׁכִינְתָּא, מִצְוַת יהו\"ה בָּרָה מְאִירַת עִינָיִם (תהלים יט ט), וְחַד עוֹשֶׂה עֲשִׂיָּיתָהּ דְּאִיהוּ מַעֲשֶׂה דְפִקּוּדָא, דְּהָכִי אוּקְמוּהוּ מָארֵי מַתְנִיתִין גָּדוֹל הַמְּצוּוְה וְעוֹשֶׂה מִמִּי שֶׁאֵינוֹ מְצוּוְה וְעוֹשֶׂה</p>\n<p>וְעוֹד מְצוּוְה דָא עַמּוּדָא דְאֶמְצָעִיתָא, דְאִיהוּ מְצוּוְה מִסִּטְרָא דְאַבָּא דְאִיהוּ רֹא\"שׁ, וּמִסִּטְרָא דְאִימָּא דְאִיהִי אֲשֶׁ\"ר, וְהָכִי צַדִּיק מְצוּוְה וְעוֹשֶׂה מִתַּרְוַיְיהוּ, וּבְגִין דָּא אִתְּמַר עַל תַּרְוַיְיהוּ אֲשֶׁר קִדְּשָׁנוּ, אִמָּא קִדְּשָׁנוּ וְאַבָּא צִוָּנוּ, עַל מָאן עַל שְׁכִינְתָּא תַּתָּאָה, דְאִיהִי פֶּטֶר כָּל רֶחֶם, פְּתִיחוּ דְרֶחֶם, דְּאִיהוּ רְמַ\"ח פִּקּוּדִין, אִיהִי מִצְוַת יהו\"ה בְּכָל אֵבֶר וְאֵבֶר דְּמַלְכָּא, אִיהִי מִצְוָה, וְעוֹד אֲשֶׁר קִדְּשָׁנוּ מִסִּטְרָא דְאַבָּא</p>"],[9500011148,"<p>וְאִימָּא, הֲדָא הוּא דִכְתִיב (בראשית א ג) וַיֹּאמֶר אלהי\"ם יְהִי אוֹר וַיְהִי אוֹר, וַיֹּאמֶר מִסִּטְרָא דְאַבָּא דְאִיהוּ י', יְהִי מִסִּטְרָא דְאִימָּא דְאִיהִי ה', חַד אֲמִירָה וְחַד הֲוַיָּה, עֲשִׂיָּיתָהּ דְּתַרְוַיְיהוּ יְהִי אוֹר.</p>\n<p>וְעוֹד אֲשֶׁר עַל שֵׁם בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָּנוֹת (בראשית ל יג), אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם (שמות כ ב), וְכִי עִִבֶד דְּאִיהוּ בְּבֵי אֲסִירֵי דְמַלְכָּא, וְאַבְטַח לֵיהּ מַלְכָּא לְאַפָּקָא לֵיהּ מִבֵּי אֲסִירֵי, אִית לֵיהּ לְמַלְכָּא לְשַׁבְּחָא גַרְמֵיהּ, אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם כַּמָּה זִמְנִין, אֶלָּא חַמְשִׁין זִמְנִין אַדְכִּיר בְּאוֹרַיְיתָא יְצִיאַת מִצְרַיִם, לָקֳבֵל חַמְשִׁין תַּרְעִין דְּבִינָה, לְאִשְׁתְּמוֹדְעָא לוֹן מֵאָן אֲתַר אַפִּיק לוֹן מִן גָּלוּתָא.</p>\n<p>וְכַד נָחֲתַת לְגַבַּיְיהוּ נָחֲתַת לְמִפְרַק לוֹן בְּכַמָּה קָלִין וּבְרָקִין, הֲדָא הוּא דִכְתִיב (שמות יט טז) וַיְהִי בַיּוֹם הַשְּׁלִישִׁי בִּהְיוֹת הַבֹּקֶר וַיְהִי קוֹלוֹת וּבְרָקִים וְגוֹמֵר, וַעֲלַיְיהוּ אִתְּמַר (שם כ יח) וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת, אֶת דָּא שְׁכִינְתָּא תַּתָּאָה, דַהֲוַת סָלְקָא בְּכָל קָלָא וְקָלָא מֵאִינוּן שֶׁבַע קָלִין, וְאִיהִי הֲוַת בַּת קוֹל דְּכָל חַד וְחַד, קוֹל דְּבָרִים אַתֶּם שֹׁמְעִים (דברים ד יב), דָּא קָלָא עִלָּאָה כְּלִילָא מִתְּלַת קָלִין עִלָּאִין, דְּאִינוּן תְּלַת סְפִירָן עִלָּאִין, וְעַל אִימָּא עִלָּאָה אִתְּמַר (שם) וּתְמוּנָה אֵינְכֶם רוֹאִים זוּלָתִי קוֹל, אֲבָל בַּת קוֹל עֲלָהּ אִתְּמַר וְכָל הָעָם רוֹאִים אֶת הַקּוֹלֹת, וְאֶת, וְאֶת וַדַּאי, דְּאִתְּמַר בָּהּ (במדבר יב ח) וּתְמוּנַת יהו\"ה יַבִּיט, קוֹלוֹת אִינוּן מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, אִיהוּ קוֹל הַשּׁוֹפָר שְׁבִיעָאָה בְּאִימָּא עִלָּאָה, וּלְתַתָּא שִׁית קָלִין.</p>\n<p>בְּרָקִים מִסִּטְרָא דְּצַדִּיק, דְּאִתְּמַר בֵּיהּ (זכריה ט יד) וְיָצָא כַבָּרָק חִצּוֹ, עָנָן דָּא שְׁכִינְתָּא כְּלִילָא מִשִּׁבְעָה עֲנָנֵי כָּבוֹד, דְּבָהּ מִתְכַּסִּין קָלִין וּבְרָקִין, וּמִסִּטְרָא דִימִינָא אִתְקְרִיאַת עֲנָנָא, וּמִסִּטְרָא דִשְׂמָאלָא עֲרָפֶל, הֲדָא הוּא דִכְתִיב (שמות כ כא) וּמֹשֶׁה נִגַּשׁ אֶל הָעֲרָפֶל אֲשֶׁר שָׁם הָאלהי\"ם. וְעוֹד אָנֹכִי דָא שְׁכִינְתָּא תַּתָּאָה, וְרָזָא דְמִלָּה אָנֹכִי אָנֹכִי הוּא מְנַחֶמְכֶם (ישעיה נא יב), אִימָּא עִלָּאָה אָנֹכִי לְעִילָא, אָנֹכִי אִימָּא תַּתָּאָה לְתַתָּא וְעַל תַּרְוַיְיהוּ אִתְּמַר (דברים לב לט) רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא, כְּשִׁמְךָ אלהי\"ם כֵּן תְּהִלָּתֶךָ עַל קַצְוִי אֶרֶץ (תהלים מח כא).</p>\n<p>הָא הָכָא פִּקּוּדָא קַדְמָאָה, וְלֵית פִּקּוּדָא דְלָא אִתְיְיהִיב בִּדְחִילוּ וּרְחִימוּ דְאִיהוּ ב', וְדָא ב' מִן בְּרֵאשִׁית דְּחִילוּ דְּיִרְאָה וּרְחִימוּ, דְאִינוּן ב' עִלָּאָה ב' תַּתָּאָה, ב' עִלָּאָה הָא אִתְּמַר דְּאִיהוּ דְחִילוּ וּרְחִימוּ, ב' בַּתְרָאָה (נ\"א תתאה) תּוֹרָה וּמִצְוָה, וְאִיהִי ב' מִבָּרָ\"א, בְּהִפּוּךְ אַתְוָון אֵבֶ\"ר, אִיהִי מִצְוָה בְכָל (נ\"א דכל) אֵבֶר וְאֵבֶר, פִּקּוּדָא קַדְמָאָה אִיהוּ אָנֹכִי יהו\"ה אלהי\"ך (שמות כ ב), וְאִיהוּ ב', דְחִילוּ וּרְחִימוּ, אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ (ויקרא יט ג) מִסִּטְרָא דִדְחִילוּ, כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ (שמות כ יב) מִסִּטְרָא דִרְחִימוּ, וְתַרְוַיְיהוּ אִינוּן זָכוֹר וְשָׁמוֹר.</p>\n<p>תְּפִלִּין דְּרֹאשׁ וּתְפִלִּין דְּיָד, אַבָּא תְּפִלִּין דְּרֵישָׁא (נ\"א על רישא) דְּאִיהוּ רֹאשׁ דְּבָרְךָ אֱמֶת (תהלים קיט קס) עַמּוּדָא דְּאֶמְצָעִיתָא, אִימָּא תְפִלִּין דְּיָד דְאִיהִי שְׁכִינְתָּא תַּתָּאָה, אַבָּא וְאִימָּא תְּפִלִּין דְּמָארֵי עָלְמָא, קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ דְּאִינוּן בְּרָא וּבְרַתָּא אִינוּן תְּפִלִּין דִּילָן.</p>\n<p>וְעוֹד נָתִי\"ב תְּלִיתָאָ\"ה, בֵּיהּ פִּקּוּדָא תְּלִיתָאָה דְאִיהוּ נְבוּאָ\"ה, הֲדָא הוּא דִכְתִיב (בראשית א ג) וַיֹּאמֶר אלהי\"ם יְהִי אוֹר וַיְהִי אוֹר, חָמֵשׁ אוֹר אִינוּן, וַעֲלַיְיהוּ אִתְּמַר (יחזקאל א א) נִפְתְּחוּ הַשָּׁמַיִם וָאֶרְאֶה מַרְאוֹת אלהי\"ם, אִימָּא עִלָּאָה מַרְאֶה סְתִימָא דְלֵית בָּהּ דִּמְיוֹן, אִימָּא תַּתָּאָה מַרְאֶה בְאִתְגַּלְיָיא דְאִית בָּהּ דִּמְיוֹן, וַעֲלָה אִתְּמַר (הושע יב יא) וּבְיַד הַנְּבִיאִים אֲדַמֶּה, אֲדַמֶּה אִיהִי דִמְיוֹן לְכָל נְבִיאַיָּא, וּלְכָל חַד כְּפוּם חֵילֵיהּ, וּבְגִין דְּאִיהִי שְׁלִטָּא עַל כָּל מֶרְכָּבוֹת דִּלְתַתָּא, וְעַל כָּל כֹּכְבַיָּא וּמַזָּלֵי, וְאִלָּנִין וּדְשָׁאִין, וְעַל כָּל עוֹפֵי שְׁמַיָּא וְחֵיוָן וְאַרְעָא, וְנוּנֵי יַמָּא, בְּגִין דָּא אִתְקְרִיאַת בִּשְׁמָא דְכֻלְּהוּ, מִסִּטְרָא דְחֵיוָון אִתְקְרִיאַת חַיָּה, וּמִסִּטְרָא דְעוֹפִין נֶשֶׁר יוֹנָה צִפּוֹר, וּמִסִּטְרָא דְנוּנִין הַדָּג, סִטְרָא (נ\"א שפחה) בִּישָׁא בְּהִפּוּכָא דָּגָה, וּמִסִּטְרָא דְעִשְׂבִּין אִתְקְרִיאַת שְׁכִינְתָּא שׁוֹשַׁנָּה.</p>"],[9500011149,"<p>נָתִיב רְבִיעָאָה וַיַּבְדֵּל אלהי\"ם בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ (בראשית א ד), דְּכַר וְנוּקְבָא אִינוּן, חֹשֶׁךְ לַיְלָה, הֲדָא הוּא דִכְתִיב (שם ה) וְלַחֹשֶׁךְ קָרָא לָיְלָה, וְאִית חֹשֶׁךְ מִסִּטְרָא דְּדַכְיוּ וְלַיְלָה מִסִּטְרָא דְּדַכְיוּ, הֲדָא הוּא דִכְתִיב (תהלים קלט יב) גַּם חֹשֶׁךְ לֹא יַחֲשִׁיךְ מִמֶּךָּ וְלַיְלָה כַּיּוֹם יָאִיר כַּחֲשֵׁכָה כָּאוֹרָה, וְחֹשֶׁךְ אִיהִי נוּקְבָא דִמְקַבֵּל מִנְּהוֹרָא דְאִיהוּ אוֹר דְּכַר, כְּגַוְונָא דְסִיהֲרָא דִמְקַבְּלַת מִן שִׁמְשָׁא, וְתַרְוַיְיהוּ אִינוּן אַסְפַּקְלַרְיָאָה דְנַהֲרָא וְאַסְפַּקְלַרְיָאָה דְלָא נַהֲרָא, וְאִית חֹשֶׁךְ דְּסִטְרָא אָחֳרָא דְאִית בָּהּ הַבְדָּלָה וְלַאו חִבּוּרָא, וְהַהוּא אוֹר אִיהוּ כְמוֹחָא בֶאֱגוֹזָא.</p>\n<p>אַדְהָכִי הָא קָלָא אִשְׁתַּמַּע בְּרוּמֵי רְקִיעִין, מָארֵי דְאוֹצָרִין מָארֵי דְהֵיכָלִין, אַפְתַּחוּ הֵיכָלִין הָא מַטְרוֹנִיתָא קָא בַעִִיָא לְאַעָלָא בְהֵיכָלֵיהּ, בְּהַהוּא זִמְנָא אדנ\"י שְׂפָתַי תִּפְתָּח, הֵיכָלָא כְּלִילָא מִשִּׁבְעָה הֵיכָלִין, בְּהַהוּא זִמְנָא כַּמָּה נְבִיאִים סָלְקִין עִמָּהּ וּמִתְכַּנְסִים עִמָּהּ, דְּאִית נְבִיאִים וְאִית נְבִיאִים, אִית נְבִיאִים דְּאִינוּן מָארֵי דְבֵיתָא דְמַטְרוֹנִיתָא, וְאִית נְבִיאִים דְּאִינוּן מָארֵי דְבֵיתָא דְמַלְכָּא, אִלֵּין מֵאַסְפַּקְלַרְיָאָ דְנַהֲרָא וְאִלֵּין מֵאַסְפַּקְלַרְיָא דְלָא נַהֲרָא, נְבִיאִים דְאַסְפַּקְלַרְיָא דְנַהֲרָא אִינוּן מִסִּטְרָא דְיהו\"ה, וּנְבִיאִים דְּאַסְפַּקְלַרְיָא דְלָא נַהֲרָא אִינוּן מִסִּטְרָא דְאדנ\"י, וְאִינוּן שְׁקִילִין לְאוֹרַיְיתָא דְבִכְתָב וְאוֹרַיְיתָא דִבְעַל פֶּה, נְבִיאִים מִסִּטְרָא דְאדנ\"י מִסִּטְרָא דְיִרְאָה, וּנְבִיאִים דְּאִינוּן מִסִּטְרָא דְיהוָֹ\"ה אִינוּן מִסִּטְרָא דְאַהֲבָה.</p>\n<p>בְּהַהוּא זִמְנָא כַּמָּה מָארֵי תַּרְעִין מִזְדַּעִִזְעִין וּמִזְדַּמְנִין לְהֵיכָלָא, וְכַמָּה מָארֵי חוֹתָמוֹת, וְכַמָּה מָארֵי שְׁאֵלְתִּין, וְכַמָּה מָארֵי תְשׁוּבוֹת, דִּבְהוֹן נָבִיא שׁוֹאֵל וּמֵשִׁיב, וְכַמָּה מָארֵי עֲתִידוֹת, מַה דַּהֲוָה וּמַה דְּעָתִיד לְמֶהֱוִי, וְכַמָּה מָארֵי דְעַיְינִין דְּאִינוּן מַרְאוֹת וְחוֹזִין דִּנְבִיאִים, וְכַמָּה מָארֵי דְאוּדְנִין דְּאִינוּן מָארֵי דְגַדְפִין, דְּאִתְּמַר בְּהוֹן (יחזקאל א כד) וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם, וְכַמָּה מָארֵי דְחוֹטָמָא דְתַמָּן רֵיחַ, דְּאִתְּמַר בְּהוֹן (ויקרא א יג) אִשֵּׁה רֵיחַ נִיחֹחַ, וְכַמָּה מָארֵי דְאַנְפִּין דְּאִתְּמַר בְּהוֹן (יחזקאל א ו) וְאַרְבָּעָה פָנִים לְאֶחָת, וְכַמָּה מָארֵי דְקָלִין וּמָארֵי דְּדִבּוּרִין, וּמָארֵי דַהֲבָלִים דְּאִינוּן לַהֲבוֹת אֵשׁ, הֲדָא הוּא דִכְתִיב (תהלים כט ז) קוֹל יהו\"ה חֹצֵב לַהֲבוֹת אֵשׁ, וְכַמָּה מָארֵי דִיָדִין, דְּאִתְּמַר בְּהוֹן (יחזקאל א ח) וִידֵי אָדָם מִתַּחַת כַּנְפֵיהֶם, וְכַמָּה מָארֵי דְקוֹמָה וְאִינוּן שִׁעוּר קוֹמָה דְכָרְסַיָּיא, וְכַמָּה מָארֵי דְאוֹת בְּרִית דְּאִתְּמַר בְּהוֹן (שמות ג יב) וְזֶה לְּךָ הָאוֹת, וְכַמָּה מָארֵי דְרַגְלִין דְּאִתְּמַר בְּהוֹן (יחזקאל א יד) וְהַחַיּוֹת רָצוֹא וָשׁוֹב.</p>\n<p>כָּל תִּקּוּנִין דִּנְבִיאַיָּא מִלְּבָר (נ\"א מלגאו) בְּגוּפָא, בְּאֵבָרִים דְּגוּפָא, מָארֵי דְחָכְמָה אִינוּן מִלְּגָאו בְּמוֹחָא, וּבְגִין דָּא חָכָם עָדִיף מִנָּבִיא, וּמִמּוֹחָא תַלְיָין ל\"ב נְתִיבוֹת, וְדָא ל\"ב דְּאִתְּמַר לֵב מֵבִין, וַיַּבְדֵּל אלהי\"ם בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ (בראשית א ד), הָכָא רָזָא דְנָתִיב רְבִיעָאָה, מַאי הַבְדָּלָה הָכָא בִּנְבוּאָה, אֶלָּא כַמָּה נְבִיאֵי שִׁקְרָא אִינוּן מִסִּטְרָא דְחֹשֶׁךְ, דְּאָזְלִין בְּאַוִּירָא לְאַטְעָאָה בְּנֵי נָשָׁא, בְּהַהוּא זִמְנָא דִיְהֵא קוּדְשָׁא בְּרִיךְ הוּא בִּשְׁכִינְתֵּיהּ, וַיַּבְדֵּל אלהי\"ם בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ.</p>\n<p>נָתִיב חֲמִשָּׁאָה, וַיִּקְרָא אלהי\"ם לָאוֹר יוֹם (שם ה), אִלֵּין מָארֵי מִקְרָא, דְּמָארֵי מִקְרָא אִינוּן פְּתִילָה, וּמָארֵי מִשְׁנָה זַיִת, וּמָארֵי תַלְמוּד דְּאִיהוּ קַבָּלָה לְמֹשֶׁה מִסִּינַי נֵר.</p>\n<p>פִּקּוּדָא רְבִיעָאָה לְאִתְעַסְקָא בְּאוֹרַיְיתָא דִבְעַל פֶּה, וּלְאַפְרָשָׁא בָהּ בְּשִׁית דַּרְגִּין, בְּאִסּוּר וְהֶתֵּר טוּמְאָה וְטַהֲרָה כָּשֵׁר וּפָסוּל, הֲדָא הוּא דִכְתִיב (שם ו) וַיֹּאמֶר אלהי\"ם יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם, וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם, בֵּין מַיִם דְּדַכְיוּ דְטַהֲרָה הֶתֵּר כָּשֵׁר, וּבֵין מַיִם דִּמְסָאֲבוּ דְאִינוּן אִסּוּר טָמֵא פָּסוּל, דְּאִינוּן מֵי בּוֹרוֹת נִשְׁבָּרִים מַיִם סְרוּחִים מַיִם מְטוּנָפִין, וַעֲלַיְיהוּ אִתְּמַר (שמות כ ג) לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים עַל פָּנָי, וְהַאי רָקִיעַ דְּאַפְרִישׁ בֵּינַיְיהוּ דָא רָקִיעַ דְּעַל רֵישֵׁי חֵיוָון, וְדָא מטטרו\"ן, דַּעֲלֵיהּ אִתְּמַר (יחזקאל א כב) וּדְמוּת עַל רָאשֵׁי</p>"],[9500011150,"<p>הַחַיָּה רָקִיעַ, וַעֲלֵיהּ אִתְּמַר (בראשית א ז) וַיַּעַשׂ אלהי\"ם וְגוֹמֵר, וְדָא נָתִיב שְׁתִיתָאָה, וְאִית רָקִיעַ לְעִילָא מֵרָקִיעַ, וְדָא צַדִּיק דְּאַפְרִישׁ בֵּין מַיִּין נוּקְבִין לְמַיִּין דְּכוּרִין, לְאִשְׁתְּמוֹדְעָא בֵּיהּ, וַעֲלֵיהּ אִתְּמַר (שם) וַיַּעַשׂ אלהי\"ם אֶת הָרָקִיעַ, וַיַּבְדֵּל בֵּין הַמַּיִם אֲשֶׁר מִתַּחַת לָרָקִיעַ וּבֵין הַמַּיִם אֲשֶׁר מֵעַל לָרָקִיעַ, וְדָא נָתִיב שְׁבִיעָאָה צַדִּיק.</p>\n<p>נָתִיב תְּמִינָאָה וַיִּקְרָא אלהי\"ם לָרָקִיעַ שָׁמָיִם (שם), וַיִּקְרָא אלהי\"ם דָּא אִימָּא עִלָּאָה, לָרָקִיעַ דָּא עַמּוּדָא דְאֶמְצָעִיתָא דְאִיהוּ בֵּין יְמִינָא וּשְׂמָאלָא וּכְלִיל תַּרְוַיְיהוּ, הֲדָא הוּא דִכְתִיב (שם) וַיְהִי עִִרֶב וַיְהִי בֹקֶר יוֹם אֶחָד, וְאִינוּן עִִרֶב דְּיִצְחָק וּבֹקֶר דְּאַבְרָהָם.</p>\n<p>בְּרֵאשִׁית בָּרָ\"א שְׁתֵּ\"י, וַעֲלַיְיהוּ אִתְּמַר (רות א יט) וַתֵּלַכְנָה שְׁתֵּיהֶם וְגוֹמֵר, וְאִינוּן תְּרֵי תּוֹרוֹת אוֹרַיְיתָא דְבִכְתָב וְאוֹרַיְיתָא דִּבְעַל פֶּה, וְעוֹד תְּרֵי לוּחוֹת אָזְלוּ לְטוּרָא דְסִינַי, מִיָּד וַתֵּהֹם כָּל הָעִיר עֲלֵיהֶן (שם) אִזְדַעִִזַע כָּל עָלְמָא, הֲדָא הוּא דִכְתִיב (שמות כ יח) וְכָל הָעָם רֹאִים אֶת הַקֹּלֹת וכו' וַיַּרְא הָעָם וַיָּנוּעוּ, וְאָמְרוּ הֲזֹאת נָעֳמִי, דָּא אִיהוּ נְעִימוּ דְאוֹרַיְיתָא, מִיָּד אִתְּמַר (שם לב יט) וַיְשַׁבֵּר אוֹתָם תַּחַת הָהָר, פָּרְחַת אוֹרַיְיתָא מִתַּמָּן, וְאָמְרַת (רות א כא) אֲנִי מְלֵאָה הָלַכְתִּי לְטוּרָא דְסִינַי, וּכְעַן וְרֵיקָם הֱשִׁיבַנִי יהו\"ה, מְלֵיאָ\"ה מָלֵ\"א י\"ה, וּכְעַן פָּרַח מִנִּי מָלֵ\"א י\"ה דְּאִיהוּ יה\"ו, וְאִשְׁתְּאָרַת ה' יְחִידָה אִלֵּ\"ם, נֶאֱלַמְתִּי דוּמִיָּ\"ה (תהלים לט ג), דוֹ\"ם י\"ה, הֶחשֵׁתִי מִטּוֹב דְאִיהוּ ו'.</p>\n<p>דָּבָר אַחֵר וַתֵּלַכְנָה שְׁתֵּיהֶן גּוּף וְנֶפֶשׁ, לְאָן אֲתַר אָזְלִי, לְבֵי קִבְרָא, גּוּף אִתְדַּן וְאִתְרַקַּב, נֶפֶשׁ אִתְּמַר בָּהּ (רות ג ז) וַתְּגַל מַרְגְּלוֹתָיו וַתִּשְׁכָּב.</p>\n<p>קָם סָבָא חַד וְאָמַר, בּוֹצִינָא קַדִּישָׁא חֲזוֹר בָּךְ, עָרְפָּה אִיהִי גוּף, רוּת אִיהִי נֶפֶשׁ, שׁוּתָּפוּ דִילָהּ נָעֳמִי נִשְׁמַת חַיִּים, מַחְלוֹן רוּחָא, גּוּפָא דְאִיהִי עָרְפָּה חָזְרָה עוֹרֶף לְגַבֵּי נְשָׁמָה (נ\"א שכינתא), נֶפֶשׁ אִתְדַּבַּק בָּהּ בְּנִשְׁמָתָא, הֲדָא הוּא דִכְתִיב (רות א טז) בַּאֲשֶׁר תֵּלְכִי אֵלֵךְ בְּפִקּוּדִין דַּעֲשֵׂה, וּבַאֲשֶׁר תָּלִינִי אָלִין בְּפִקּוּדִין דְּלֹא תַעֲשֶׂה.</p>\n<p>דָּבָר אַחֵר בַּאֲשֶׁר תֵּלְכִי אֵלֵךְ בְּגָלוּתָא, דְּאִתְּמַר בָּהּ (ישעיה נ א) וּבְפִשְׁעִיכֶם שֻׁלְּחָה אִמְּכֶם, וּבַאֲשֶׁר תָּלִינִי אָלִין דְּמִשְׁכָּבָא דִילָךְ בְּגָלוּתָא, הֲדָא הוּא דִכְתִיב (שיר ג א) עַל מִשְׁכָּבִי בַּלֵּילוֹת, עַמֵּךְ עַמִּי אִלֵּין יִשְׂרָאֵל, וִאלהי\"ך אלה\"י דָּא קוּדְשָׁא בְּרִיךְ הוּא, אֱלִימֶלֶךְ דָּא י', נָעֳמִי דָּא ה', מַחְלוֹן ו', רוּת בָּהּ אִתְדַּבְּקַת ה' וְאִתְעֲבִידַת תּוֹרָה, וַעֲלָהּ אִתְּמַר (שיר ב יב) וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ.</p>\n<p>עָרְפָּה אִימָּא דְעִרֶב רַב, דְּאִתְּמַר בְּהוֹן (שמות לד ט) כִּי עַם קְשֵׁה עוֹרֶף הוּא, דְּחָזְרַת לְסָרְחָנָה, וְחָזְרַת עֹרֶף לְגַבֵּי חֲמוֹתָהּ, כִּלְיוֹן בַּעִִלָהּ דְּעָרְפָּה, יֵצֶר הָרָע דְאַתְיָא כְּלָיָיה מִנֵּיהּ לְעָלְמָא, וְאִיהוּ כִּלְיוֹן, וְאִתְּתֵיהּ לִילִית כְּלָיָיה.</p>\n<p>נְשָׁמָה וְנֶפֶשׁ כַּד בַּר נַשׁ אִיהוּ מְחוּיָיב בְּחוֹבִין וּמִתְגַּבְּרִין עַל אֵבָרִים, נִשְׁמַת חַיִּים אִסְתַּלְּקַת מִן גּוּפָא, וְנֶפֶשׁ אִשְׁתְּאָרַת תַּמָּן, וְאִתְּמַר בָּהּ (רות ג ז) וַתְּגַל מַרְגְּלוֹתָיו, לְגַבֵּי מָאן לְגַבֵּי צַדִּיק וְדָא בְרִית מִילָה, דְאִיהוּ בּוֹעַז בּ\"וֹ עַ\"ז תַּקִּיף עַל יִצְרֵיהּ, וַיָּמָד שֵׁשׁ שְׂעוֹרִים וַיָּשֶׁת עָלֶיהָ (שם טז), שׁוֹקָיו עַמּוּדֵי שֵׁשׁ (שיר ה טז), שַׁוִּאיַת לוֹן עֲלָהָא לְאַגָּנָא עֲלָהּ, וְאוּקְמוּהָ וַתֵּלַכְנָה שְׁתֵּיהֶם בִּשְׁכִינְתָּא עִלָּאָה וְתַתָּאָה, וַעֲלַיְיהוּ אִתְּמַר (רות ד יז) וַתִּקְרֶאנָה לוֹ הַשְּׁכֵנוֹת שֵׁם, לֵאמֹר יֻלַּד בֵּן לְנָעֳמִי, דָא עַמּוּדָא דְאֶמְצָעִיתָא דְאִתְּמַר בֵּיהּ (שמות ד כב) בְּנִי בְכֹרִי יִשְׂרָאֵל, כַּד חָאבוּ יִשְׂרָאֵל וְגָרְמוּ לְאִסְתַּלְקָא שְׁכִינְתָּא, עֲלָהּ אִתְּמַר בִּשְׁכִינְתָּא תַּתָּאָה וַתְּגַל מַרְגְּלוֹתָיו (רות ג ז).</p>\n<p>דָּבָר אַחֵר וַתֵּלַכְנָה שְׁתֵּיהֶם, אִיהוּ מְמַלֵּל בְּגוּפָא וְנַפְשָׁא, וּמֵרְחִימוּ דְגוּפָא כַּד אִיהוּ בַּעַל תְּשׁוּבָה, יֵימָא נַפְשָׁא לְגַבָּהּ בַּאֲשֶׁר תָּמוּתִי אָמוּת וְשָׁם אֶקָּבֵר (שם א יז), וְלָא תָזוּז נַפְשָׁא בְקִבְרָא מִנֵּיהּ, וַעֲלָהּ אִתְּמַר (משלי ו כב) בְּהִתְהַלֶּכְךָ</p>"],[9500011151,"<p>תַּנְחֶה אוֹתָךְ בְּעָלְמָא דֵין, בְּשָׁכְבְּךָ תִּשְׁמוֹר עָלֶיךָ בְּקִבְרָא, וַהֲקִיצוֹתָ לִתְחִיַּית הַמֵּתִים (נ\"א לעולם הבא) הִיא תְשִׂיחֶךָ, דָּא נַפְשָׁא לְגַבֵּי גוּפָא, וּבוֹצִינָא קַדִּישָׁא אִם גּוּפָא לָא חָזַר בִּתְיוּבְתָּא, וְחָזַר עוֹרֶף לְגַבֵּי תְּיוּבְתָּא, נֶפֶשׁ אִתְפָּרַשׁ מִנֵּיהּ וְאִתְקְרֵי עָרְפָּ\"ה, וְגוּפָא דָא אִתְאֲבִיד מִתְּרֵין עָלְמִין.</p>\n<p>אָמַר לֵיהּ סָבָא סָבָא, וְהָא כַּמָּה קִבְרִין לְמַגָּנָא, וְהָא אִם גּוּפָא אִתְאֲבִיד עַל מַה תָּקוּם נַפְשָׁא לִתְחִיַּית הַמֵּתִים, דְּהָא וַדַּאי גּוּפָא אִתְאֲבִיד, וְאִתְּמַר דְּאִתְאֲבִיד מִתְּרֵין עָלְמִין, וְהָא נָחִית לִנְשִׁיָּיה דְתַמָּן אִתְנַשֵּׁי לְדָרֵי דָרִין, אִם כֵּן כַּמָּה קִבְרִין לְמַגָּנָא.</p>\n<p>אֶלָּא וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא לָא יְשַׁנִּי עוֹבְדֵי יְדוֹי, דְּוַדַּאי עָלְמָא דֵין וְעָלְמָא דְאָתֵי דְּאִינוּן שְׁמַיָּא וְאַרְעָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִינוּן, וַעֲלַיְיהוּ אָמַר דָוִד (תהלים קטו טז) הַשָּׁמַיִם שָׁמַיִם לַיהו\"ה, אַרְעָא אֶתְהַלֵּךְ לִפְנֵי יהו\"ה בְּאַרְצוֹת הַחַיִּים (שם קטז ט), עֲלַיְיהוּ אִתְּמַר עָלְמָא דֵין וְעָלְמָא דְאָתֵי בִּשְׁמָא דְיהו\"ה, הֲדָא הוּא דִכְתִיב (שם צו יא) יִ שְׂמְחוּ הַ שָּׁמַיִם וְ תָגֵל הָ אָרֶץ, אֵימָתַי בְּזִמְנָא דְאִתְּמַר לְגַבֵּי שָׁמַיִם וְהָאָרֶץ דְסמא\"ל וְנָחָשׁ, כִּי שָׁמַיִם כֶּעָשָׁן נִמְלָחוּ וְהָאָרֶץ כַּבֶּגֶד תִּבְלֶה (ישעיה נא ו), וּלְבָתַר דְּיִמְחֵי לוֹן וִישֵׁצֵי לְאִלֵּין מְמַנָּן דַּעֲלַיְיהוּ, מִיָּד יְחַדֵּשׁ לוֹן קוּדְשָׁא בְּרִיךְ הוּא לִשְׁמַיָּא וְאַרְעָא, דְיִתְמַחוּן בְּגִין אִלֵּין מְמַנָּן בִּישִׁין, הֲדָא הוּא דִכְתִיב (שם סו כב) כִּי כַאֲשֶׁר הַשָּׁמַיִם הַחֲדָשִׁים וְהָאָרֶץ הַחֲדָשָׁה אֲשֶׁר אֲנִי עֹשֶׂה וְגוֹמֵר, וְכֹלָּא בְּגִין דְּלָא יִשְׁתֵּצוּן עוֹבְדֵי יְדוֹי, דְּאִינוּן נִשְׁמָתִין וְגוּפִין דְּאִתְאֲבִידוּ מִתְּרֵין עָלְמִין, וְאִלֵּין עֲתִירִין דִּבְגָלוּתָא, בְּגִין דְּהַאי עָלְמָא אִיהוּ דִלְהוֹן.</p>\n<p>אֲבָל מִסְכְּנֵי דְאִינוּן צַדִּיקַיָּא, טוּבָא דִלְהוֹן לְאִינוּן עָלְמִין טָבִין, דִּי בְהוֹן אִתְבְּרִיאוּ תְּרֵי תּוֹרוֹת אוֹרַיְיתָא דְּבִכְתָב וְאוֹרַיְיתָא דִבְעַל פֶּה, דְאַגְרָא דִלְהוֹן תַּמָּן וּבְגִין דִּלְתַתָּא דְאֶרֶץ הַחַיִּים, תַּמָּן גּוּפִין לְנִשְׁמָתִין קַדִּישִׁין דְּאִתְבְּרִיאוּ בִּשְׁמָא דַיהו\"ה, וְגוּפָא דְמֹשֶׁה דְאִתְּמַר בֵּיהּ (דברים לד ז) לֹא כָהֲתָה עִינוֹ וְלֹא נָס לֵחֹה מִתַּמָּן הֲוָה, וּבְגִינֵיהּ הֲוָה אִיהוּ בָעָא רַחֲמֵי דְלָא יְמוּת וְיִפּוּק מִנֵּיהּ, וְלָא עַל גּוּפָא דְּהַאי עָלְמָא דְאִתְקְרֵי סַנְדָּל לְגַבֵּיהּ, דַּעֲלֵיהּ אִתְּמַר לֵיהּ (שמות ג ה) שַׁל נְעָלֶיךָ מֵעַל רַגְלֶיךָ.</p>\n<p>וְאָדָם וְחֵיוָן וּבְעִירָן וְעוֹפִין דְּתַמָּן אִינוּן עוֹבָדָא דִבְּרֵאשִׁית, וְאִינוּן בְּדִיּוֹקְנָא עִלָּאָה דְּאִלֵּין דְּאִתְּמַר בְּהוֹן בְּמֶרְכַּבְתָּא (יחזקאל א י) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם וְגוֹמֵר, דְּאִינוּן בְּעִירִין עִלָּאִין עֲלַיְיהוּ אִתְּמַר (ישעיה סד ג) יַעֲשֶׂה לִמְחַכֵּה לוֹ, וְתַמָּן עִץ חַיִּים דְּמָאן דְּאָכִיל מִנֵּיהּ אִתְּמַר בֵּיהּ (בראשית ג יב) וְאָכַל וָחַי לְעוֹלָם.</p>\n<p>וְתַמָּן כָּרְסְיָין דִּי דַּהֲבָא וְכַסְפָּא וְאַבְנִין יַקִּירִין, וְעַרְשִׂין דְּכַסְפָּא וְדַהֲבָא, וְרַמַ\"ח פִּקּוּדִין דְּמַנִּי לוֹן מֹשֶׁה לְיִשְׂרָאֵל בְּהַאי עָלְמָא, לְדַכָּאָה רְמַ\"ח אֵבָרִים דְהַהוּא גוּפָא, וְגוּפָא דְהַאי עָלְמָא שְׁפֵלָא אִיהוּ סַנְדָּל לְנִשְׁמָתָא, דְּאִתְטַנַּף (נ\"א ואתטנפת) בְּזוּהֲמָא דְהַאי עָלְמָא. הָא הָכָא תְּלָתִין וְחַד זִמְנִין דְּאִתְפַּרַשׁ בְּרֵאשִׁית, וַעֲשַׂר אֲמִירָן וּתְלָתִין וּתְרֵין שְׁבִילִין הָא שַׁבְעִין וּתְרֵין, וְצָרִיךְ לְפָרְשָׁא לוֹן. פָּתַח וְאָמַר בְּרֵאשִׁית</p>\n<p>בְּרֵאשִׁית מַאֲמַר קַדְמָאָה לְכֹלָּא, וְאִיהוּ כְּלִיל תְּרֵין דִּבּוּרִין אָנֹכִי וְלֹא יִהְיֶה לְךָ (שמות כ ב) דְאִתְּמְרוּ בְּדִבּוּרָא חֲדָא, וְתַרְוַיְיהוּ אִינוּן רְמִיזִין בְּמִלַּת בְּרֵאשִׁית, בְּגִין דָּא בְּרֵאשִׁי\"ת א\"ב רֵשִׁי\"ת, א\"ב א' אָנֹכִי ב' לֹא יִהְיֶה לְךָ, וְכֹלָּא בְּאָת אֶחָד ב', וְאִיהִי ב' מִבְּרֵאשִׁית.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, וְכִי מָאן דְּאִית לֵיהּ עַבְדָּא וְאַפִּיק לֵיהּ לְחֵירוּ מִשִּׁעִִבּוּדֵיהּ, אִית לֵיהּ לְרִבּוֹנֵיהּ לְשַׁבְּחָא גַרְמֵיהּ בְּמַפְּקָנוּתָא לְחֵירוּ לְעַבְדֵּיהּ, וְכִי קוּדְשָׁא בְּרִיךְ הוּא דְּאָמַר לְאַבְרָהָם (בראשית טו יג) כִּי גֵר יִהְיֶה זַרְעֲךָ וכו' אִית לְשַׁבְּחָא גַרְמֵיהּ כַּמָּה</p>"],[9500011152,"<p>זִמְנִין אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם (שמות כ ג), אָמַר לֵיהּ רַבִּי שִׁמְעוֹן הָכִי הוּא וַדַּאי, אֲבָל הָכָא לָא מְשַׁבַּח קוּדְשָׁא בְּרִיךְ הוּא גַרְמֵיהּ דְּאַפִּיק לוֹן מִן גָלוּתָא, אֶלָּא חַמְשִׁין זִמְנִין אַדְכִּיר בְּאוֹרַיְיתָא יְצִיאַת מִצְרַיִם, לְאִשְׁתְּמוֹדְעָא בְּדַרְגָּא דְאַפִּיק לוֹן דְּאִיהוּ יוֹבְלָא, דְאִתְּמַר בֵּיהּ (ויקרא כה יא) יוֹבֵל הִיא שְׁנַת הַחֲמִשִּׁים שָׁנָה, וְאִינוּן חַמְשִׁין תַּרְעִין דְּבִינָה דְּאִתְמַסְרוּ לְמֹשֶׁה בְּסִינַי בַּר חַד דְּלָא אִתְמַסַּר לֵיהּ, וּבְגִין דָּא אַדְכִּיר חַמְשִׁין זִמְנִין בְּאוֹרַיְיתָא יְצִיאַת מִצְרָיִם. אָמַר הָא וַדַּאי אִתְיַשֵּׁב דַעִִתָּאִי.</p>\n<p>מָאן אֱלֹהִים אֲחֵרִים, אִלֵּין מְמַנָּן דְּשַׁבְעִין אוּמִין, וְסמא\"ל וְנָחָ\"שׁ הָא ע\"ב, בְּגִין דָּא יְהִיב קוּדְשָׁא בְּרִיךְ הוּא אוֹרַיְיתָא מִימִינָא דְאִיהוּ חֶסֶד וּמִשְּׂמָאלָא דְאִיהוּ גְבוּרָה, דְּאִית בָּהּ שַׁבְעִין אַנְפִּין לְשֵׁזָבָא מִשַּׁבְעִין אוּמִין, וְאוֹרַיְיתָא אִתְיְיהִיבַת מִמַּיָּא וְאֶשָּׁא דְאִינוּן תְּרֵין, לְשֵׁזָבָא לְיִשְׂרָאֵל מִסמא\"ל וְנָחָשׁ דְּאִינוּן מִמַּיָּא וְאֶשָּׁא, וּבְגִינַיְיהוּ אִתְּמַר (שמות כ ג) לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים עַל פָּנָי, וְלָקֳבֵל שַׁבְעִין אוּמִין שַׁבְעִין נֶפֶשׁ, וּמָאן דְּעָבַר עַל שַׁבְעִין אַנְפִּין דְּאוֹרַיְיתָא דְּאִתְּמַר לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים עַל פָּנָי, שָׁלְטִין שַׁבְעִין מְמַנָּן וְאוּמִין דְּיֵצֶר הָרָע עַל שַׁבְעִין נֶפֶשׁ.</p>\n<p>וְכַמָּה גִלְגּוּלִין יֵתוּן לְבַר נַשׁ עַל חוֹבִין אִלֵּין, וְאִם לָא חָזַר בַּר נַשׁ בִּתְיוּבְתָּא בְּאִלֵּין גִּלְגּוּלִין, הַהוּא גוּפָא נָחִית בַּאֲבַדּוֹן, גִּלְגּוּלָא קַדְמָאָה אִצְטַבַּע בְּגַוָּון חִוָּור, וְרָכִיב נַפְשָׁא בְסוּסְיָא חִוְורָא דְאִיהוּ גוּפָא, אִם חָזַר בִּתְיוּבְתָּא אִתְּמַר בֵּיהּ (ישעיה א יח) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ, וְאִם לַאו יֵתֵי בְגִלְגּוּלָא תִּנְיָינָא, וְרָכִיב בְּסוּסְיָא סוּמְקָא, וְאִם חָזַר בִּתְיוּבְתָּא אִתְּמַר בְּחוֹבָא דִילֵיהּ (שם) אִם יַאְדִּימוּ כַתּוֹלָע כַּצֶּמֶר יִהְיוּ, וְאִם לָא, אִתְחַזַּר אִתְגַּלְגַּל בְּגִלְגּוּלָא תְּלִיתָאָה, וְרָכִיב בְּסוּסְיָא יְרוֹקָא וְדָא גּוּפָא.</p>\n<p>וְאִינוּן מַזָּל אַרְיֵה מַזָּל שׁוֹר מַזָּל נֶשֶׁר, דַּעֲלַיְיהוּ אִתְּמַר (איוב לג כט) הֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר, וְאִם שְׁלָשׁ אֵלֶּה לֹא יַעֲשֶׂה לָהּ (שמות כא יא) לְנַפְשָׁא בִּתְלַת גִּלְגּוּלִין, דְּעָבִיד לָהּ שְׁאֵר כְּסוּת וְעוֹנָה, וְיָצְאָה חִנָּם אֵין כָּסֶף (שם), וְעַל שְׁלֹשָׁה פִּשְׁעִי יִשְׂרָאֵל וְעַל אַרְבָּעָה לֹא אֲשִׁיבֶנּוּ (עמוס ב א), וְעַל אַרְבָּעָה דְאִיהוּ מַזָּל אָדָם לֹא אֲשִׁיבֶנּוּ, דְּלָא יְקַלְקְלוּ לֵיהּ.</p>\n<p>אֲבָל לְצַדִּיקַיָּא וְעֹשֶׂה חֶסֶד לַאֲלָפִים (שמות כ ה), אֲלָפִים וַדַּאי, תְּלַת גִּלְגּוּלִין בְּהוֹן אִיהוּ רָוַוח תְּלַת אַלְפִּין דְּאִינוּן עָלְמִין דִּכְסוּפִין, וּלְמָאן לְאֹהֲבָיו וּלְשֹׁמְרֵי מִצְוֹתָיו (שם ו), לְחַיָּיבַיָּא דְּאִינְהוּ לָא יַחְזְרוּן בִּתְיוּבְתָּא בִּתְלַת גִּלְגּוּלִין אִלֵּין, אִתְּמַר בְּהוֹן (ויקרא כג לא) וְהַאֲבַדְתִּי אֶת הַנֶּפֶשׁ הַהִיא מִקֶּרֶב עַמָּהּ, אָמַר רַבִּי אִם כֵּן אָנָה נָחִית, אֶלָּא שֶׁבַע אַרְעִין אִינוּן, וְסָלְקִין לְשַׁבְעִין לָקֳבֵל שִׁבְעִים נֶפֶשׁ, וְשֶׁבַע אַרְעִין אִינוּן אֶרֶץ אֲדָמָה אַרְקָא גֵּיא צִיָּה נְשִׁיָּה תֵּבֵל, וְאִינוּן שֶׁבַע מְדוֹרִין דְּגֵיהִנָּם, הַהִיא נַפְשָׁא דְלָא חָזְרָה בִּתְיוּבְתָּא בְּאִלֵּין תְּלַת, נָחִית לָהּ קוּדְשָׁא בְּרִיךְ הוּא בְּמָדוֹרִין דְּגֵיהִנָּם אִלֵּין, וְתַמָּן אִתְנַשֵּׁי לְדָרֵי דָרִין.</p>\n<p>וְאִם הוּא צַדִּיק אִתְּמַר בֵּיהּ (משלי כד טז) כִּי שֶׁבַע יִפּוֹל צַדִּיק וָקָם, אָמַר לֵיהּ רַבִּי אֶלְעָזָר, וְאִם הוּא צַדִּיק אַמַּאי נָחִית תַּמָּן, אֶלָּא בְּגִין לְאַפָּקָא מִתַּמָּן כָּל נַפְשָׁא וְנַפְשָׁא מֵאִלֵּין דְּהִרְהֲרוּ בִתְיוּבְתָּא וּמֵתוּ בְקַצְרוּת שְׁנִין, וְאִיהוּ טָרַח בְּגִינֵיהּ, דָּא אִיהוּ מַאֲמַר קַדְמָאָה דְאִיהוּ בְרֵאשִׁית.</p>\n<p>בְּרֵאשִׁית דָּא פִּקוּדָא קַדְמָאָה, דְאִתְרְמִיז בְּל\"ב שְׁבִילִין, דְּאִינוּן ל\"ב אלהי\"ם דְּעוֹבָדָא דִבְּרֵאשִׁית, כ\"ב אַתְוָון וַעֲשַׂר אֲמִירָן דְּאִתְכְּלִילָן בְּהוּ, תִּקּוּנָא קַדְמָאָה יִרְאָה, וַעֲלָהּ אִתְּמַר (תהלים קיא י) רֵאשִׁית חָכְמָה יִרְאַת יהו\"ה, דְאִית דְּחִילוּ וְאִית דְּחִילוּ,</p>"],[9500011153,"<p>יִרְאַת יהו\"ה דָא שְׁכִינְתָּא מַלְכוּת קַדִּישָׁא, יִרְאָה רָעָה דָּא רְצוּעָה לְאַלְקָאָה לְחַיָּיבַיָּא, וּמַאי נִיהוּ סַם הַמָּוְת דְּסמא\"ל, נוּקְבָא דִילֵיהּ, יִרְאַת יהו\"ה אִיהִי אַגְרָא לְמָאן דְּנָטִיר פִּקּוּדִין דְּלֹא תַעֲשֶׂה, יִרְאָה רָעָה אִיהִי רְצוּעָה לְאַלְקָאָה לְמָאן דְּאַעֲבַר עֲלַיְיהוּ.</p>\n<p>קָם רַבִּי שִׁמְעוֹן וְאָמַר אֶלְעָזָר בְּרִי, אִית מָאן דְּדָחִיל לְקוּדְשָׁא בְּרִיךְ הוּא בְּגִין דְּיֵיחוּן בְּנוֹי וְיִסְגֵּי עוּתְרֵיהּ בְּהַאי עָלְמָא, וְאִי חָסֵר מֵהַאי לָא דָחִיל לֵיהּ, הַאי לָא שַׁוִּי לֵיהּ יִרְאַת יהו\"ה לְעִקָּרָא, אֲבָל מָאן דְּדָחִיל לְקוּדְשָׁא בְּרִיךְ הוּא בֵּין בְּטִיבוּ בֵּין בְּעָאקוּ, הָא דָא שַׁוִּי יִרְאַת יהו\"ה בֵּיהּ לְעִקָּרָא, דִּתְלַת דַּרְגִּין אִינוּן דְּיִרְאָה, אִית יִרְאָה בֵּין בְּטִיבוּ בֵּין בְּעָאקוּ, וְאִית יִרְאָה דְּדָחִיל לְקוּדְשָׁא בְּרִיךְ הוּא בְּטִיבוּ וְלָא בְּעָאקוּ, וְאִית יִרְאָה דְּלָא שַׁוִּי לָהּ עֲלֵיהּ לְעִקָּרָא בֵּין לְטִיבוּ בֵּין לְעָאקוּ, צַדִּיק גָמוּר שַׁוִּי לָהּ עֲלֵיהּ לְעִקָּרָא בֵּין לְטִיבוּ בֵּין לְדִינָא, בֵּינוּנִי שַׁוִּי לֵיהּ עֲלֵיהּ לְטִיבוּ וְלָא לְדִינָא, רָשָׁע גָּמוּר לָא שַׁוִּי לֵיהּ עִקָּרָא לָא בְּטִיבוּ וְלָא בְּדִינָא.</p>\n<p>וּשְׁכִינְתָּא אַמַּאי אִתְקְרִיאַת יִרְאָה, דְּהָא הִיא מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא אִתְנְטִילַת, אֶלָּא כְּמָה דְּעַמּוּדָא דְאֶמְצָעִיתָא נָטִיל מֵרַחֲמֵי וְדִינָא דְאִינוּן יְמִינָא וּשְׂמָאלָא, הָכִי אִיהִי נָטְלָא מִתַּרְוַיְיהוּ, מִסִּטְרָא דִשְׂמָאלָא דָּא אִתְקְרִיאַת יִרְאָה פַּחַד יִצְחָק, דְּמִסִּטְרָא דִימִינָא אַהֲבָ\"ה אִתְקְרֵי, וְדָא פִּקּוּדָא תִנְיָנָא דְאִתְּמַר בָּהּ (ירמיה לא ב) וְאַהֲבַת עוֹלָם אֲהַבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חָסֶד.</p>\n<p>וּמִתְּרֵין סִטְרִין אִלֵּין אִתְקְרֵי עַמּוּדָא דְאֶמְצָעִיתָא אוֹר וְנֵר, וּשְׁכִינְתָּא אוֹרָה אֲבוּקָה, אוֹרָה, לַיְּהוּדִים הָיְתָה אוֹרָה (אסתר ח טז), אֲבוּקָה הָכִי אוּקְמוּהוּ מָארֵי מַתְנִיתִין דְּצַדִּיקִים קַיְימִין קַמֵּי שְׁכִינְתָּא כְּנֵר לִפְנֵי הָאֲבוּקָה. מִסִּטְרָא דִימִינָא יהו\"ה, וּמִסִּטְרָא דִשְׂמָאלָא אדנ\"י דְּתַמָּן דִּין, וּבְגִין דָּא בְּיוֹמָא קַדְמָאָה וַיֹּאמֶר אלהי\"ם יְהִי אוֹר (בראשית א ג), בְּגִין דְּחָמֵשׁ אוֹר אִינוּן בְּיוֹמָא קַדְמָאָה, וְאִינוּן ה' עִלָּאָה וּמִתַּמָּן נַהֲרִין, י' בִּשְׂמָאלָא וְדָא נֵר, וְדָא ה\"י מִן אלהי\"ם ה' לִימִינָא י' לִשְׂמָאלָא, (ו' מל\"א מתרוייהו עמודא דאמצעיתא, בן י\"ה, ודא איהו רזא אלהי\"ם מל\"א ה\"י, דא כתיבת קדמאה. ורזא דמלה ה\"א, אלהי\"ם דא מליא\"ה בהפוך אתוון, ודא ה' זעירא, דאיהי מליא מתלת אתוון, ואתעבידת היו\"ה, לעילא איהו הוי\"ה, ובה מתחילין אתוון דאורייתא ה\"ו ולבתר ט\"י, ואנה אשתכח ה' בתראה, אלא ד' הות למהוי ה', אלא מאן גרם דפרח מינה ו' דאיהו ירך דילה, אלא נתנני שוממה כל היום דוה (איכה א יג), דא הוד דאיהו ירך דילה דאתחזרת איהו דוה באלף חמשאה, בגין דפרח מניה ירך, דעליה אתמר (בראשית לב כג) ותקע כף ירך יעקב, אשתמודע דמימינא קא מתחלת לממני את ד' עד נצח, והוד איהו ירך שלימו דילה, ודא איהו דאתיהיב למשה, הדא הוא דאתמר ונתן הוד למשה).</p>\n<p>בְּרֵאשִׁית, ב' נוּקְבָא פְּתִיחָא לְקַבָּלָא מִימִינָא, לְהַהוּא (נ\"א מההוא) דְּגָמִיל חֶסֶד עִמָּהּ, וְאַמַּאי דְּאָת י' עַל רֵישֵׁיהּ כְּגַוְונָא דָא ג', וּבְגִין דָּא הָרוֹצֶה לְהַחְכִּים יַדְרִים, אִם כֵּן אַמַּאי ג' אָחוֹר לְב', אֶלָּא רָזָא דְּמִלָּה וְאִישׁ אֲשֶׁר יִקַּח אֶת אֲחֹתוֹ בַּת אָבִיו אוֹ בַת אִמּוֹ וְרָאָה אֶת עִִרְוָתָהּ וְהִיא תִרְאֶה אֶת עִִרְוָתוֹ חֶסֶד הוּא (ויקרא כ יז), ב' חָזְרַת אַנְפּוֹי מִא', ג' אַחְזַרַת אַנְפּוֹי מִב', ד' חָזְרַת אַנְפּוֹי מִג', ה' חָזְרַת אַנְפּוֹי מִד', כָּל אַתְוָון חָזְרִין אַנְפִּין</p>"],[9500011154,"<p>דָּא מִן דָּא, וְלַאו אִינוּן אַנְפִּין בְּאַנְפִּין, וְאַמַּאי אֶלָּא רָזָא דְמִלָּה וְרָאִיתָ אֶת אֲחֹרָי וכו' (שמות לג כג), וְאַמַּאי חָזְרִין אַנְפִּין דָּא מִן דָּא, בְּגִין עִִרְיָין דְּאִינוּן לְקִבְלַיְיהוּ, א' לְקִבְלֵיהּ אָרוּר דְּאִיהוּ עִִרְוָה, וַעֲלֵיהּ אִתְּמַר (דברים כז כב) אָרוּר שֹׁכֵב עִם אֲחֹתוֹ, דְּאִלֵּין עִִרְיָין כָּל חַד שָׁכִיב עִם אִמֵּיהּ וְעִם אֲחָתֵיהּ וְעִם בְּרַתֵּיהּ, וְחָזְרִין אַנְפִּין לְגַבַּיְיהוּ דְלֵית לוֹן בֹּשֶׁת פָּנִים, אֲבָל אַתְוָון קַדִּישִׁין חָזְרִין אַנְפַּיְיהוּ בְּבֹשֶׁת בַּעֲנָוָה, עִִרְיָה תֵעוֹר, וּבְגִינָהּ אִתְּמַר (ויקרא יט יד) וְלִפְנֵי עִוִּר לֹא תִתֵּן מִכְשׁוֹל, עִוֵּר דְאִיהוּ עוֹר, וְרָזָא דְמִלָּה עָרוּם רָאָה רָעָה וְנִסְתָּר (משלי כב ג).</p>\n<p>וּלְבָתַר דְּמִתְפַּשְּׁטִין מִנַּיְיהוּ מִתְיַחֲדִין כֻּלְּהוּ וְלָא יִתְבֹּשָׁשׁוּ, וּמִתְיַחֲדִין אַבָּא עִם אִימָּא, אָח עִם אֲחָתֵיהּ, כְּעַן דְּעִִרְוָה בֵּינַיְיהוּ אִית פִּרוּדָא בְּאַתְוָון דְּאִינוּן יהו\"ה, הֲדָא הוּא דִכְתִיב (רות א יז) כִּי הַמָּוְת יַפְרִיד (בין אחים) בֵּינִי וּבֵינֵךָ, לְבָתַר דְּאִתְעַבַּר עֲרָיוֹת מִנַּיְיהוּ, יְהֵא יהו\"ה אֶחָד וּשְׁמוֹ אֶחָד, וְרָזָא דְאֶחָד אָח ד', עִִרְוָה דְתַרְוַיְיהוּ אַחֵר, בְּזִמְנָא דְאִסְתַּלַּק קוֹצָא מִן ד' מִן אֶחָד אִשְׁתָּאַר אַחֵר, וַעֲלֵיהּ אִתְּמַר (משלי כה ט) וְסוֹד אַחֵר אַל תְּגָל.</p>\n<p>בְּרֵאשִׁית, בְּתִשְׁרִ\"י אִתְבְּרֵי עָלְמָא, חָסֵר א' לְמֶהֱוִי בְּרֵאשִׁית, דָּא אָדָם דְּאִתְבְּרֵי בְּתִשְׁרִי, וּבְגִין דַּעֲתִידָה אַרְעָא לְאִתְלַטְיָא בְּגִינֵיהּ, דָּא הוּא אֲרוּרָה הָאֲדָמָה בַּעֲבוּרֶךָ (בראשית ג יז), אִסְתַּלַּק מִן תִּשְׁרִי, וּפָתַח בְּבּ' דְּאִיהִי בְּרָכָה לְאִתְבָּרְכָא אַרְעָא, וּלְאַפָּקָא לָהּ מִן לְוָטַיָּא, וְלָא עוֹד אֶלָּא בְּגִין דְּתִשְׁרִי אִיהוּ דִּין, לָא אִדְכַּר תַּמָּן בְּתִשְׁרִי, דְּלָא יִתָּכֵן בֵּיהּ זִמְנָא אָחֳרָא, הֲדָא הוּא דִכְתִיב (משלי כ כז) נֵר יהו\"ה נִשְׁמַת אָדָם. (כך מצאתי)</p>\n<p>בְּרֵאשִׁית, דְּאִיהוּ שַׁבָּת בְּרֵאשִׁית, דְּהָא שֶׁבַע שַׁבָּתוֹת אִינוּן, וּלְכָל חַד אִית לֵיהּ שִׁית יְמֵי הַמַּעֲשֶׂה, וְכָל יוֹמָא דְקוּדְשָׁא בְּרִיךְ הוּא הוּא אֶלֶף שָׁנִים, הֲדָא הוּא דִכְתִיב (תהלים צ ד) כִּי אֶלֶף שָׁנִים בְּעִינֶיךָ וכו', וְשַׁבָּת בְּרֵאשִׁית שִׁית יוֹמִין דִּילֵיהּ אִינוּן שְׁנֵי אֲלָפִים תֹּהוּ, שְׁנֵי אֲלָפִים תּוֹרָה, שְׁנֵי אֲלָפִים יְמוֹת הַמָּשִׁיחַ.</p>\n<p>שְׁנֵי אֲלָפִים תֹּהוּ וְהָאָרֶץ הָיְתָה תֹהוּ, שְׁנֵי אֲלָפִים תּוֹרָה וְרוּחַ אלהי\"ם מְרַחֶפֶת עַל פְּנֵי הַמָּיִם (בראשית א ב), וְלֵית מַיִם אֶלָּא אוֹרַיְיתָא, פְּנֵי הַמָּיִם תְּרֵין אַנְפִּין דִּילָהּ, דְּאִינוּן מִצְוֹת עֲשֵׂה וּמִצְוֹת לֹא תַעֲשֶׂה, חִוָּור וְסוּמַק, יְמִינָא וּשְׂמָאלָא, וְאִלֵּין אִינוּן שְׁנֵי אֲלָפִים תּוֹרָה, שְׁנֵי אֲלָפִים יְמוֹת הַמָּשִׁיחַ, וַיֹּאמֶר אלהי\"ם יְהִי אוֹר וַיְהִי אוֹר (שם ג), עֲלַיְיהוּ אִתְּמַר (ישעיה כד טו) עַל כֵּן בָּאוּרִים כַּבְּדוּ יהו\"ה, עַל כֵּן וַדַּאי דְּאִתְּמַר בֵּיהּ וַיְהִי כֵּ\"ן, וְאִינוּן שַׁבְעִין, וְעַל תְּרֵין מְאוֹרוֹת אִלֵּין אִתְּמַר דּוּ פַּרְצוּפִין דְּכַר וְנוּקְבָא, יְהִי אוֹר דָּא פֶּסַח, אוֹר לְאַרְבָּעָה עָשָׂר, וַיְהִי אוֹר רֹאשׁ הַשָּׁנָה, דְּאִתְּמַר בֵּיהּ וַיְהִי הַיּוֹם, הָכָא וַיְהִי וְהָתָם וַיְהִי, וּבְכָל אֲתַר וַיְהִי לִישָׁנָא דְצַעֲרָא</p>\n<p>שַׁבָּת בְּרֵאשִׁית נְקוּדָה בְחָלָל דִּילָהּ, (דאיהי שבת ברית), י' שַׁבָּת חִלֵּל, חִלֵּל לְמָאן, לְהַהִיא נְקוּדָה, מְחַלְלֶיהָ מוֹת יוּמָת (שמות לא יד), לְמָאן דְּעָאל נוּכְרָאָה בֶּחָלָל דִּילָהּ, דְּאִיהִי רְשׁוּת הָרַבִּים יַיִן נֶסֶךְ זוֹנָה, וּבְגִין דָּא הָכָא צָרִיךְ דְּחִילוּ, וְדָא אִיהוּ בְּרֵאשִׁית יָרֵ\"א שַׁבָּ\"ת, הֲדָא הוּא דִכְתִיב (ויקרא יט ג) אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ וְאֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ, וּמָאן דְּעָאל רְשׁוּ נוּכְרָאָה בֶחָלָל</p>"],[9500011155,"<p>דִּילָהּ, דְּאִיהִי רְשׁוּת הָרַבִּים יַיִן נֶסֶךְ זוֹנָה, עֲלֵיהּ אִתְּמַר (במדבר יט יג) אֶת מִקְדַּשׁ יהו\"ה טִמֵּא וְנִכְרְתָה וכו', וְהַאי נְקוּדָה אִיהִי אוֹת דְּשַׁבָּת אוֹת דְּיֹמִין טָבִין אוֹת דִּתְּפִלִּין אוֹת דִּבְרִית מִילָה, עֲטֶרֶת דִּבְרִית, תַּגָּא דְסֵפֶר תּוֹרָה קָרִינָן לֵיהּ, כִּתְרָא בְרֵישׁ כָּל צַדִּיק, נְקוּדָה דַּעֲלָהּ אִתְּמַר אָדָם וְחַוָּה דַהֲווֹ דוּ פַרְצוּפִים, וַעֲלָהּ אָמְרָה סִיהֲרָא אִי אֶפְשַׁר לִשְׁנֵי מְלָכִים שֶׁיִּשְׁתַּמְשׁוּ בְּכֶתֶר אֶחָד.</p>\n<p>רָזָא דָא לְחַכִּימֵי לִבָּא אִתְמַסַּר, (דא) (נ\"א ד' ו') אִיהוּ ה' בַּתְרָאָה, דְּתַרְוַיְיהוּ י', וּבָהּ אִתְעֲבִידוּ חַד, וְהַאי נְקוּדָה אִיהִי סְתִימָא וַחֲתוּמָה בְּשִׁית יוֹמִין דְּחוֹל, הֲדָא הוּא דִכְתִיב (יחזקאל מו א) יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה בְּמַאי בְּאָת ו', (ב') סְתִים בְּאָת ו' בְּו' יוֹמֵי דְחוֹל, וּבְיוֹמָא שְׁבִיעָאָה אִתְפַּתְּחַת לְקַבָּלָא לְבַעִִלָהּ, וּבְגִין דָּא זִוּוּגָא דְתַלְמִידֵי חֲכָמִים מִשַּׁבָּת לְשַׁבָּת, וְיָרְתִין נִשְׁמָתִין קַדִּישִׁין חַדְתִּין לִבְנַיְיהוּ.</p>\n<p>וּבְגִין דָּא אִיהִי נְקוּדָה אִתְקְרִיאַת בְּתוּלָה וְאִישׁ לֹא יְדָעָהּ (בראשית כד טז), כַּד אִיהִי גַל (נ\"א גן) נָעוּל מַעִִיָן חָתוּם (שיר ד יב), עַד דְּאִתְפַּתְּחַת לְבַעִִלָהּ, וְכַד אִיהִי סְתִימָא אִתְקְרִיאַת יִרְאָה, בְּכָל ו' יוֹמֵי דְחוֹל דְּאִיהִי סְגִירָא וּנְטִירָא, בַּעֲשַׂר אֲמִירָן וְל\"ב אלהי\"ם דְּאִינוּן מ\"ב אַתְוָון דִּגְבוּרָה, דְתַמָּן בִּינָה, בְשַׁבָּת וַיְכֻלּוּ הַשָּׁמַיִם, וַיְכֻלּ\"וּ חֶסֶ\"ד דִּימִינָא כְּלִיל ע\"ב שְׁמָהָן, דְּתַמָּן חָכְמָה, כְּמָה דְּאַמְרָן הָרוֹצֶה לְהַחְכִּים יַדְרִים, דְּחִילוּ בְּשִׁית יוֹמִין דְּחוֹל אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ (ויקרא יט ג), רְחִימוּ בְשַׁבָּת כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ (שמות כ יב), כַּד אִתְפַּתְּחַת לְגַבֵּי בַּעִִלָהּ אִתְקְרִיאַת אַהֲבָה, וּמִדְּחִילוּ וּרְחִימוּ אִתְיְיהִיבוּ פִּקּוּדִין דַּעֲשֵׂה וְלֹא תַעֲשֶׂה.</p>\n<p>בְּרֵאשִׁית אִיהוּ בְּרִי\"ת, וַדַּאי כַּד אִיהוּ בִּלְבוּשִׁין דְּאִלֵּין קְלִיפִין דְּאִינוּן עָרְלָה וּפְרִיעָה, צָרִיךְ תַּמָּן דְּחִילוּ, וַעֲלַיְיהוּ אִתְּמַר (שמות כ ג) לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים עַל פָּנָי, וְהַאי אוֹת לָא יָרְתִין לֵיהּ אֶלָּא יִשְׂרָאֵל, דְּלֵית אוֹת בְּרִית עַד דְּעָבְרִין מִנַּיְיהוּ אִלֵּין קְלִיפִין, דְּאִינוּן עָרְלָה וּפְרִיעָה בְּאַטִּיפוּ דִדְמָא.</p>\n<p>תְּלַת קְלִיפִין אִינוּן בְּעָרְלָה לָקֳבֵל תְּלַת קְלִיפִין דֶּאֱגוֹזָא, וַעֲלַיְיהוּ אִתְּמַר (בראשית א ב) וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְחֹשֶׁךְ, תֹּהוּ קַו יָרוֹק קְלִיפָה קַדְמָאָה, בֹּהוּ קְלִיפָה תִנְיָינָא, חֹשֶׁךְ קְלִיפָה תְּלִיתָאָה, וּתְלַת אִלֵּין דָּא עַל גַּב דָּא, לָקֳבֵל תְּלַת גַּוָּונִין דְּעִינָא, דְאִתְּמַר בְּהוֹן (במדבר טו לט) וְלֹא תָתוּרוּ אַחֲרֵי לְבַבְכֶם וְאַחֲרֵי עִינֵיכֶם וכו', לְקִבְלַיְיהוּ תְּלַת גַּוָּונִין דְּקֶשֶׁת, דִּבְהוֹן נִקְרָא בַּת עָיִן דְּאִיהִי נְקוּדָה אוֹת בְּרִית, עֲלָהּ אִתְּמַר (בראשית ט טז) וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם, וַעֲלַיְיהוּ אִתְּמַר תְּלַת זִמְנִין כָּל גּוֹיִם וכו' כִּי אֲמִילַם (תהלים קיח יט), וְאֵימָתַי יַעֲבוֹר קוּדְשָׁא בְּרִיךְ הוּא הַנֵּי קְלִיפִין מֵעָלְמָא וַיִּזְכּוֹר בְּרִית עוֹלָם, בְּזִמְנָא דְפוּרְקָנָא, הֲדָא הוּא דִכְתִיב (ישעיה ל כ) וְלֹא יִכָּנֵף עוֹד מוֹרֶיךָ, אֵימָתַי לְבָתַר דְּמִתְעַבְּרִין תְּלַת קְלִיפִין בִּישִׁין מִינָהּ, וּבְזִמְנָא דְאִיהִי מִתְלַבְּשָׁא בְּאִלֵּין קְלִיפִין אִיהִי אָמְרַת אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחֹרֶת (שיר א ו), דִּבְאִלֵּין קְלִיפִין אִיהִי מִתְחַלֶּלֶת, וּבְגִין דָּא מְחַלְלֶיהָ מוֹת יוּמָת (שמות לא יד).</p>\n<p>תְּהוֹ\"ם אִיהוּ הַמָּוְ\"ת, לְגַבֵּיהּ צָרִיךְ פְּרִיעָה בְּאַטִּיפוּ דִדְמָא, וְעַד דְּאִתְפַּרַע הַאי פְּרִיעָה אִיהִי לָא אִתְגַּלְיָיא בְּעָלְמָא, וְלָא יְהֵא אוֹת בְּעָלְמָא, וְרָזָא דְמִלָּה כַּד אִתְעַבַּר מִינָהּ עָרְלָה וּפְרִיעָה רוֹמִי וְקוּשְׁטַאנְדִינָא, מִיָּד אִתְגַּלְיָיא אוֹת בְּעָלְמָא, לְהַהוּא דְאִתְּמַר בֵּיהּ (שם ג יב) וְזֶה לְּךָ הָאוֹת כִּי אָנֹכִי שְׁלַחְתִּיךָ, לְקַיְימָא בֵּיהּ קְרָא (מיכה ז טו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת.</p>\n<p>וּבְגִין דָּא אֶלְעָזָר בְּרִי לָא תִצְפֵּי לְרַגְלָא דִמְשִׁיחָא עַד דְּתֶחְזֵי קֶשֶׁת בְּגַוְּונוֹי נְהִירִין, אוֹ עַד דְּאִתְגַּלְיָיא אוֹת בְּעָלְמָא, מַאי אוֹת. אֶלָּא דָּרַךְ כֹּכָב מִיַּעֲקֹב (במדבר כד יז), דָּא אָת י' אוֹת בְּרִית, וּמִיָּד וְקָם שֵׁבֶט מִיִּשְׂרָאֵל לְגַבָּהּ, הַהוּא דְאִתְּמַר בֵּיהּ (דברים לג ה) וַיְהִי בִישֻׁרוּן מֶלֶךְ (חסר),</p>\n<p>תָּא חֲזִי יוֹמָא חֲדָא שְׁאִילְנָא</p>"],[9500011156,"<p>לְאֵלִיָּהוּ, עָרְלָה אַמַּאי שַׁוִּינָן בְּמָאנָא בְּעַפְרָא, אָמַר לִי שְׁמַעִִנָא בִּמְתִיבְתָּא, דְּעָרְלָה אִיהוּ נָחָשׁ, וְכֵיוָן דְּאַעִִבְּרִינָן לֵיהּ מֵאַתְרֵיהּ צָרִיךְ לְמֵיהַב לֵיהּ מְזוֹנֵיהּ, הֲדָא הוּא דִכְתִיב (ישעיה סה לה) וְנָחָשׁ עָפָר לַחְמוֹ, וּבְוַדַּאי בְּרִי בְּדָא אִשְׁתֵּזִיב בַּר נַשׁ מִדִּינָא דְחִבּוּט הַקֶּבֶר, וּדְמָא דְאַטִּיפִין מִפְּרִיעָה לְמֵיהַב מְזוֹנָא לְהַהוּא כַּלְבָּא דְאִיהוּ רוֹצֵחַ, וּבְדָא אִשְׁתֵּזִיב בַּר נַשׁ מֵחַרְבָּא דְמַלְאַךְ הַמָּוְת.</p>\n<p>וְעַל דָּא אָמַר אָדָם קַדְמָאָה קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, מִי מַצִּיל בָּנַי מֵחֶרֶב הַמִּתְהַפֶּכֶת, אָמַר לֵיהּ חַרְבָּא דְמִילָה, כְּמָה דְאַתְּ אָמַר (יהושע ה ב) עֲשֵׂה לְךָ חַרְבוֹת צוּרִים, וְחַרְבָּא דְקוּדְשָׁא בְּרִיךְ הוּא י\"ו פִּיפִיּוֹת, לָקֳבֵל מִילָה וּפְרִיעָה וּמְצִיצָה וְי\"ג בְּרִיתוֹת שֶׁנִּכְרְתוּ עָלֶיהָ, וְכֵן אוֹרַיְיתָא שֵׁזִיב לְבַר נַשׁ מִי\"ו פִּיּוֹת דְּחַרְבָּא, כְּמָה דְאָמַר שְׁלֹמֹה (משלי ג יב) עִץ חַיִּים הִי\"א דְסָלִיק לְי\"ו.</p>\n<p>וְלָקֳבֵל אִלֵּין תְּרֵין אָמְרַת אוֹרַיְיתָא לֹא תִרְצַח וְלֹא תִנְאָף (שמות כ יג יד), לֹא תִנְאָף לָקֳבֵל נָחָשׁ אֵשֶׁת זְנוּנִים, לֹא תִרְצַח לָקֳבֵל סמא\"ל, וְאָמַר דָּוִד עֲלֵיהּ (תהלים כב כא) הַצִּילָה מֵחֶרֶב נַפְשִׁי מִיַּד כֶּלֶב יְחִידָתִי, תְּלַת קְלִיפִין דְּעָרְלָה אִינוּן מַשְׁחִי\"ת אַ\"ף וְחֵימָ\"ה, לָקֳבֵל עָרְלָה אִיהוּ עָוֹן, וְהַיְינוּ דְתַקִּינוּ בִצְלוֹתָא לְגַבַּיְיהוּ, (שם עח לח) וְהוּא רַחוּם יְכַפֵּר עָוֹן דָּא עָוֹן, וְלֹא יַשְׁחִית דָּא מַשְׁחִית, וְהִרְבָּה לְהָשִׁיב אַפּוֹ דָא אַף, וְלֹא יָעִיר כָּל חֲמָתוֹ דָא חֵמָה, וּמָאן דְּאַעִיל אוֹת בְּרִית בִּרְשׁוּ נוּכְרָאָה אִלֵּין אַרְבָּעָה שָׁלְטִין עֲלֵיהּ, הֲדָא הוּא דִכְתִיב (בראשית ז יט) וְהַמַּיִם גָּבְרוּ מְאֹד מְאֹד עַל הָאָרֶץ, עַל הָאָרֶץ דָּא גוּפָא דִילֵיהּ, וְאַרְבַּע זִמְנִין אִתְּמַר בְּפַרְשַׁת נֹחַ (שם יח) וַיִּגְבְּרוּ הַמַּיִם, גָּבְרוּ, לְקִבְלַיְיהוּ, וְהָא אוּקְמוּהוּ.</p>\n<p>עָרְלָה וּפְרִיעָה שְׁמַעִִנָא דְאִינוּן רוֹמִי רַבְּתָא וְרוֹמִי זְעִירְתָא, בְּזִמְנָא דְמִתְעַבְּרִין מֵעָלְמָא אִתְגַּלְיָא אוֹת הַבְּרִית, דְּאִיהוּ בַת עַיִן צִיּוֹן דְּאִיהִי נְקוּדַת עָלְמָא, דִּבְזִמְנָא דְאִלֵּין קְלִיפִין שָׁלְטִין בְּעָלְמָא אִתְחַזַּר עָלְמָא לְתֹהוּ וָבֹהוּ, הֲדָא הוּא דִכְתִיב (בראשית א ב) וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ, בְּזִמְנָא דְיֵתֵי פוּרְקָנָא מִיָּד וַיֹּאמֶר אלהי\"ם יְהִי אוֹר וַיְהִי אוֹר (שם ג) הָיָה אוֹר לָא כְּתִיב אֶלָּא יְהִי (ויהי אור) אוֹר, וַיְהִי עִִרֶב וַיְהִי בֹקֶר יוֹם אֶחָד (שם ה), בַּיּוֹם הַהוּא יִהְיֶה יהו\"ה אֶחָד וּשְׁמוֹ אֶחָד (זכריה יד ט).</p>\n<p>בְּרֵאשִׁית בָּרָא אלהי\"ם, פָּתַח וְאָמַר כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים וכו' (שיר ב ב), שׁוֹשַׁנָּה אִית בָּהּ חָמֵשׁ עַלִּין מִלְּגָו וְחָמֵשׁ עַלִּין מִלְּבָר, וְאִינוּן ה\"ה, שַׁרְבִיט דִּילָהּ ו', תַּפּוּחַ דִּילָהּ י', וְכֹלָּא אלהי\"ם, חָמֵשׁ אַתְוָון דִּילֵיהּ ה' חָמֵשׁ עַלִּין מִלְּבָר, ה' חָמֵשׁ עַלִּין מִלְּגָאו, י' תַּפּוּחַ, ו' מָלֵ\"א שַׁרְבִיט.</p>\n<p>בְּזִמְנָא דְהַאי שׁוֹשַׁנָּה אִיהִי בְּגָלוּתָא אִיהִי אַטוּמָא, בְּזִמְנָא דִיְהֵא פּוּרְקָנָא בְּעָלְמָא אִתְפַּתְּחַת בְּחָמֵשׁ אוֹר, הֲדָא הוּא דִכְתִיב (בראשית א ג) וַיֹּאמֶר אלהי\"ם יְהִי אוֹר, וּבְהַהוּא זִמְנָא דְאִתְפַּתְּחַת אִתְלַבְּשַׁת בְּכַמָּה לְבוּשִׁין דִּנְהוֹרִין דְּאוֹרַיְיתָא, וְאִתְקַשְּׁטַת בְּכַמָּה קִשּׁוּטִין דְּפִקּוּדִין דַּעֲשֵׂה, וּבְזִמְנָא דְאִתְפַּתְּחַת וְאִתְקַשְּׁטַת בְּקִשּׁוּטָהָא, בְּאַרְבָּעָה בִּגְדֵי לָבָן דְּאִינוּן יהו\"ה, וּבְאַרְבָּעָה בִּגְדֵי זָהָב דְּאִינוּן אדנ\"י, בְּאַרְבַּע בָּתֵּי דִתְּפִלִּין דְּיָד, וּבְאַרְבַּע בָּתֵּי דִתְּפִלִּין דְּרֵישָׁא, דְּאִינוּן לְקִבְלַיְיהוּ, אַרְבַּע לְבוּשִׁין דְּכֹהֵן הֶדְיוֹט אִינוּן לָקֳבֵל אַרְבַּע כַּנְפוֹת כְּסוּתְךָ אֲשֶׁר תְּכַסֶּה בָּהּ (דברים כב יב).</p>\n<p>וְכַד אִתְתַּקְנַת בְּאִלֵּין לְבוּשִׁין, מִיָּד אִתְפַּתַּח הֵיכָלָא לְגַבָּהּ, הֲדָא הוּא דִכְתִיב (תהלים נא יז) אדנ\"י שְׂפָתַי תִּפְתָּח, וּלְקוֹל נְעִימוּ דְּרִמּוֹנִים וְזוּגִין דִּלְבוּשָׁא דִילָהּ, אִתְּמַר בְּחֵיוָון (יחזקאל א כד) וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם, וְכַד אָמְרִין יִשְׂרָאֵל קְרִיאַת שְׁמַע, מַה כְּתִיב בָּהּ (במדבר ז פט) וַיִּשְׁמַע אֶת הַקּוֹל מִדַּבֵּר אֵלָיו, קָלָא אִשְׁתַּמַּע לְגַבָּהּ מִבֵּין תְּרֵין כְּרוּבַיָּא דְאִינוּן דּוּ פַּרְצוּפִין, וְכַד מִתְיַחֲדָא דִבּוּר בְּקָלָא אִתְעֲבִידוּ קוֹל דְּמָמָה דַקָּה, וְדָא צְלוֹתָא בַחֲשַׁאי, וּבְהַהוּא זִמְנָא מָאן דְּבָעִי לְמִשְׁאַל שְׁאֶלְתּוֹי יִשְׁאַל, דִּבְהַהִיא זִמְנָא יְהֵא עִת רָצוֹן, דְּהָא תְּרֵין שְׁמָהָן כַּחֲדָא יאהדונה\"י, אָז תִּקְרָא וַיהו\"ה יַעֲנֶה (ישעיה נח ט), מִיָּד אָ\"ז יאהדונה\"י, תְּרֵין שְׁמָהָן וּתְמַנְיָא אַתְוָון דִּבְהוֹן הָא עִִשֶׂר, (ודא רזא ארור אשר לא יקים את דברי התורה הזאת וכו' (דברים כז כו), דא חבורא דחתן</p>"],[9500011157,"<p>וכלה כי אז אהפוך אל עמים שפה ברורה וכו' (צפניה ג ט), ודא רזא ואמר כל העם אמ\"ן) (דברים כז כו).</p>\n<p>וְעַד דְּיִפְקוּן יִשְׂרָאֵל מִן גָּלוּתָא לָא יְהוֹן בְּזִוּוּגָא חֲדָא, וּבְזִמְנָא דְיִפְקוּן יִשְׂרָאֵל מִן גָּלוּתָא יִתְחַבְּרוּן כַּחֲדָא, בְּהַהוּא זִמְנָא אָ\"ז יָשִׁיר מֹשֶׁה (שמות טו א), וּמִיָּד וַיֹּאמֶר אלהי\"ם יְהִי אוֹר דְּאִיהוּ מַפְּקָנוּ דְגָלוּתָא, בְּהַהוּא זִמְנָא דְמַטְרוֹנִיתָא בָעַאת לְאַעָלָא בְהֵיכָלָא דִילָהּ, קָלָא סָלִיק בְּרוּמֵי רְקִיעִין וְיֵימָא הָכִי, מַשִּׁרְיָין סַגִּיאִין דִּמְתִיבְתָּא עִלָּאָה וְתַתָּאָה דְנִשְׁמָתִין קַדִּישִׁין, אִתְתַּקְנוּ לְקַדְמוּת מַטְרוֹנִיתָא דְקָא אַתְיָא לְאִתְתַּקְנָא, לְמִפְרַק בְּנָהָא מִן גָּלוּתָא, בְּהַהוּא זִמְנָא כַּמָּה מָארֵי שׁוֹפָרוֹת וּמָארֵי דְקָלִין וּמָארֵי דִבְּרָקִים, דְּאִתְּמַר בְּהוֹן (שמות יט טז) וַיְהִי קוֹלוֹת וּבְרָקִים וְעָנָן כָּבֵד עַל הָהָר וְקוֹל שׁוֹפָר חָזָק מְאֹד וכו', מֹשֶׁה יְדַבֵּר וְהָאלהי\"ם יַעֲנֶנּוּ בְקוֹל, בְּהַהוּא זִמְנָא מֹשֶׁה יְמַלֵּל בִּשְׁכִינְתָּא, הֲדָא הוּא דִכְתִיב (במדבר יב ח) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ, וְהָאלהי\"ם דְּאִיהִי אִימָּא עִלָּאָה, יַעֲנֶנּוּ בְקוֹל דְּאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, וְהָא אוּקְמוּהוּ מָארֵי מַתְנִיתִין בְּקוֹלוֹ שֶׁל מֹשֶׁה.</p>\n<p>וּבְהַהוּא זִמְנָא שְׁכִינְתָּא עִלָּאָה וְתַתָּאָה סָלְקִין דָּא עַל גַּב דָּא, כְּגַוְונָא דְאִתְּמַר בְּטוּרָא דְסִינַי, דְּאִתְּמַר תַּמָּן (שיר ג ו) מִי זֹאת עוֹלָה מִן הַמִּדְבָּר, מִי בְזֹאת עוֹלָה, מִ\"י אִימָּא עִלָּאָה דְבָהּ פָּתַח קוּדְשָׁא בְּרִיךְ הוּא בְטוּרָא דְסִינַי אָנֹכִ\"י.</p>\n<p>קָם סָבָא חֲדָא מִבָּתַר טוּלָא דְרַבִּי שִׁמְעוֹן וְאָמַר רַבִּי רַבִּי, הָא חֲזֵינָא דְאִתְּמַר (דברים ד לו) מִן הַשָּׁמַיִם הִשְׁמִיעֲךָ אֶת קוֹלוֹ לְיַסְּרֶךָּ וכו', וּבַאֲתַר אָחֳרָא שְׁמַעִִנָא דְמַלִּיל עִם יִשְׂרָאֵל מִסִּטְרָא דְמַלְאָכַיָּא, דְהָכִי אוּקְמוּהוּ דְכָל דִּבּוּר וְדִבּוּר דְּנָפִיק מִפּוּמוֹי אִתְעֲבִיד מַלְאָךְ, וְדָא אִיהוּ וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת וְאֶת הַלַּפִּידִים (שמות כ יח), וּבַאֲתַר אָחֳרָא אָמַר קְרָא (תהלים סב יב) אַחַת דִּבֶּר אלהי\"ם שְׁתַּיִם זוּ שָׁמָעִִתִּי, מַאי הַאי.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן סָבָא סָבָא, שְׁמַעִִנָא דְבַר נַשׁ יְהִיב בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא תְּלַת קְטִירִין, נִשְׁמָתָא וְרוּחָא וְנַפְשָׁא, נִשְׁמָתָא מִכּוּרְסַיָּא יְקָרָא, תַּמָּן נְחִיתַת שְׁכִינְתָּא עִלָּאָה כְּלִילָא מִתְּלַת סְפִירָן עִלָּאִין, וַעֲלַיְיהוּ אִתְּמַר אַחַת דִּבֶּר אלהי\"ם שְׁתַּיִם זוּ שָׁמָעִִתִּי, אַחַת וּשְׁתַּיִם הָא תְּלַת סְפִירָן עִלָּאִין, דְּאִתְּמַר בְּהוֹן אַחַת, אַחַת וְאַחַת, תְּלַת אֲחָדִין, וְדָא אִיהוּ אַחַת דִּבֶּר אלהי\"ם שְׁתַּיִם זוּ שָׁמָעִִתִּי, ז\"וּ בֵּיהּ עָבִיד לוֹן אֶחָ\"ד.</p>\n<p>וּלְבָתַר מַלִּיל עִמֵּיהּ מֵרוּחָא דְאִיהוּ מטטרו\"ן, כְּלִיל כָּל צְבָא הַשָּׁמַיִם דִּלְתַתָּא, בְּגִין דְּאִתְלַבַּשׁ בֵּיהּ וְרָכִיב בֵּיהּ עַמּוּדָא דְאֶמְצָעִיתָא כְלִיל שִׁית סְפִירָן, וּבְגִין דָּא בְכָל דִּבּוּר וְדִבּוּר דְּנָפַק מִנֵּיהּ הֲוָה נָפִיק מִנֵּיהּ מַלְאָךְ, וְדָא אִיהוּ וְכָל הָעָם רוֹאִים אֶת הַקּוֹלֹת. לְבָתַר נָחִית שְׁכִינְתָּא תַּתָּאָה עֲשִׂירִית בְּאוֹפַן, דְּאִיהוּ נֶפֶשׁ דְּבַר נַשׁ מִתַּמָּן, וְאִתְּמַר בֵּיהּ (דברים ד לו) וְעַל הָאָרֶץ הֶרְאֲךָ אֶת אִשּׁוֹ הַגְּדוֹלָה בְּגִין דַּעֲלֵיהּ אִתְּמַר (יחזקאל א טו) וְהִנֵּה אוֹפַן אֶחָד בָּאָרֶץ, בְּגִין דְּיִשְׁתַּמַּע קָלֵיהּ וְדִבּוּרֵיהּ מִן כָּרְסַיָּא וּמַלְאָכַיָּיא וּשְׁמַיָּא וְאַרְעָא, דְיִשְׁתְּמוֹדְעוּן לֵיהּ בְּכֹלָּא עִילָא וְתַתָּא, כְּנִשְׁמָתָא דְשָׁלְטָנוּתָהּ בְּכָל גּוּפָא אֲפִילוּ בְאֵבֶר זְעִירָא וְלֵית אֵבֶר פָּנוּי מִינָהּ.</p>\n<p>בְּרֵאשִׁית תַּמָּן אֲשֶׁ\"ר דְּאִתְּמַר בֵּיהּ (שמות כ ב) אֲשֶׁר הוֹצֵאתִיךָ וכו', אֶהְיֶה אֲשֶׁר אֶהְיֶה, אָשֵׁר בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָּנוֹת (בראשית ל יג), וְדָא אִימָּא עִלָּאָה, אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ, עַל כָּל פִּקּוּדָא וּפִקּוּדָא, דְּאִינוּן פֶּטֶר כָּל רֶחֶם דְּאִינוּן רְמַ\"ח, דְּכֻלְּהוּ קְטִירִין בְּצַדִּיק דְּאִיהוּ כֹּל דְּאִיהוּ אוֹת בְּרִית, דְּאַפְתַּח (פטר כל) רֶחֶם דְּאִינוּן רְמַ\"ח פִּקּוּדִין דַּעֲשֵׂה, וַעֲלֵיהּ אִתְּמַר אֲשֶׁר קִדֵּשׁ יְדִיד מִבֶּטֶן, וְדָא אִימָּא דְאִתְּמַר בָּהּ (איוב לח כט) מִבֶּטֶן מִי יָצָא הַקָּרַח, (ודא איהו הקרח הנורא) (יחזקאל א כב), אֲשֶׁר דְּאִיהִי אִימָּא עִלָּאָה,</p>"],[9500011158,"<p>קִדְּשָׁנוּ בְּמִצְוֹתָיו בְּצַדִּיק, דְּאִיהוּ קִדֵּשׁ יְדִיד מִבֶּטֶן. וְצִוָּנוּ עֲלַיְיהוּ, בְּגִין דְּאִיהוּ מְצוּוְה וְעוֹשֶׂה, וְעוֹד אֲשֶׁר קִדְּשָׁנוּ דָא עַמּוּדָא דְאֶמְצָעִיתָא, דְאִתְּמַר בֵּיהּ (ירמיה ב ג) קֹדֶשׁ יִשְׂרָאֵל לַיהו\"ה, וְצִוָּנוּ דְאִיהוּ הָכִי מְצוּוְה וְעוֹשֶׂה, וְעוֹד קִדְּשָׁנוּ מִסִּטְרָא דִשְׂמָאלָא, דְאִתְּמַר בֵּיהּ וְקִדַּשְׁתָּ אֶת הַלְוִיִּם, וְלֵית קְדוּשָׁה פָּחוּת מֵעֲשָׂרָה, וְאִלֵּין עֲשָׂרָה מַאֲמָרוֹת, (דאיהי קדש לי כל בכור (שמות יג ב) דאיהו כתר עלאה וחכמה דאיהי ישראל עלה במחשבה) דְּאִתְּמַר בְּהוֹן (בראשית א ג) וַיֹּאמֶר אלהי\"ם יְהִי אוֹר.</p>\n<p>וְצִוָּנוּ עַל, מִסִּטְרָא דִימִינָא דְאִתְּמַר בֵּיהּ (שמואל ב כג א) הוּקַם עָל, דְּתַמָּן כָּל בִּרְכָאָן לִימִינָא, דְאִינוּן מֵאָה בִּרְכָאָן כְּחוּשְׁבַּן עַ\"ל, דְּאָת י' בְּק' אִסְתַּלִּיק לְמֵאָה, דְּאִיהִי קָרְבָּנָא דְכֹלָּא, מִסִּטְרָא דְאַבָּא רֹאשׁ, מִסִּטְרָא דְאִימָּא אֲשֶׁר, מִסִּטְרָא דְאַבָּא מְצוּוְה, וּמִסִּטְרָא דְאִימָּא עוֹשֶׂה, וּמְצוּוְה דָא עִץ פְּרִי, וְעוֹשֶׂה דָא עוֹשֶׂה פְּרִי, וְשַׁמְעִינָן דְּאִינוּן גּוּף וּבְרִית דְּחַשְׁבִינָן חָד, עֲלַיְיהוּ אִתְּמַר (שמות כח ז) שְׁתֵּי כְתֵפֹת חֹבְרֹת, כְּמָה דְאִינוּן חוֹבְרוֹת, הָכִי שְׁכִינְתָּא עִלָּאָה וְתַתָּאָה חוֹבְרוֹת אִשָּׁה אֶל אֲחוֹתָהּ.</p>\n<p>עוֹד אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ, וְלָא אָמַר קִדַּשְׁתָּנוּ וְצִוִּיתָנוּ, אֲשֶׁר אִיהוּ אֲשֶׁר אהי\"ה וַדַּאי, וְדָא כֶּתֶר עִלָּאָה, מִסִּטְרָא דְּנוּקְבָא אִתְקְרֵי אֲשֶׁר, וּמִסִּטְרָא דִדְכוּרָא אִתְקְרֵי רֹאשׁ, רֵישָׁא דְכָל רֵישִׁין, קִדְּשָׁנוּ דָא אַבָּא (סבא), דְּאִתְּמַר בֵּיהּ וַיֹּאמֶר אלהי\"ם יְהִי אוֹר, וְצִוָּנוּ דָּא אִימָּא, דְאִתְּמַר בָּהּ וַיְהִי אוֹר, וְלֵית הֲוַויָּה אֶלָּא עַל יְדֵי עֲשִׂיָּה, וְתַרְוַיְיהוּ לִימִינָא וּשְׂמָאלָא,</p>\n<p>וּמָאן מְצוּוְה וְעוֹשֶׂה עַל הַמִּצְוָה דְאִיהִי שְׁכִינְתָּא, דָּא עַמּוּדָא דְאֶמְצָעִיתָא, וְהָכִי צַדִּיק בְּצַלְמֵיהּ וְכִדְמוּתֵיהּ, וְעַל שְׁמֵיהּ אִתְקְרִיאוּ יִשְׂרָאֵל בְּנִי בְּכוֹרִי יִשְׂרָאֵל, וְעַל שֵׁם צַדִּיק אִתְקְרוּן צַדִּיקִים, הֲדָא הוּא דִכְתִיב (ישעיה ס כא) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִרְשׁוּ אָרֶץ.</p>\n<p>וְעוֹד אָנֹכִי יהו\"ה אלהי\"ך אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם (שמות כ ב), אָמַר רַבִּי אֶלְעָזָר אַבָּא וְכִי מָאן דְּאִיהוּ תְּחוֹת שִׁעִִבּוּדָא דְרִבּוֹנֵיהּ, וְרִבּוֹנֵיהּ אַבְטַח לֵיהּ לְאַפָּקָא לֵיהּ לְחֵירוּ וְאַפִּיק לֵיהּ, אִית לֵיהּ לְשַׁבְּחָא גַרְמֵיהּ דְּאַפֵּיק לֵיהּ מִגּוֹ שִׁעִִבּוּדָא, וְהָא קוּדְשָׁא בְּרִיךְ הוּא אָמַר לְאַבְרָהָם (בראשית טו יג) כִּי גֵר יִהְיֶה זַרְעֲךָ בְּאֶרֶץ לֹא לָהֶם, וְהָא אִיהוּ אַבְטַח לְאַפָּקָא לִבְנוֹי מִגָּלוּתָא, הֲדָא הוּא דִכְתִיב (שם יד) וְאַחֲרֵי כֵן יֵצְאוּ בִּרְכוּשׁ גָּדוֹל, וְאִיהוּ מְשַׁבַּח גַּרְמֵיהּ כַּמָּה זִמְנִין אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם.</p>\n<p>אָמַר לֵיהּ בְּרִי שַׁפִּיר קָאֲמַרְתְּ אֲבָל לַאו אִיהוּ דָא לְשַׁבְּחָא גַרְמֵיהּ, אֶלָּא כָּל סְפִירָה וּסְפִירָה אִתְקְרִיאַת רֹאשׁ לַחֲבֶרְתָּהּ, וּבְגִין לְאִשְׁתְּמוֹדְעָא לוֹן מֵאָן אֲתַר אַפִּיק לוֹן מִגּוֹ שִׁעִִבּוּדָא, פָּתַח בְּאָנֹכִי, וְאַדְכִּיר בֵּיהּ אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם וְגוֹמֵר, חַמְשִׁין זִמְנִין לָקֳבֵל חַמְשִׁין תַּרְעִין דְּבִינָה.</p>\n<p>וְעוֹד אֲשֶׁר קִדְּשָׁנוּ, אָמַר רַבִּי אֶלְעָזָר אַבָּא, הָא אִם עַמּוּדָא דְאֶמְצָעִיתָא אִיהוּ מְצוּוְה וְעוֹשֶׂה, הֲוָה לֵיהּ לְמֵימַר בְּגִינֵיהּ אֲשֶׁר קִדְּשָׁנִי וְצִוָּנִי, מַאי אֲשֶׁר קִדְּשָׁנוּ וְצִוָּנוּ, אָמַר לֵיהּ וַדַּאי שַׁפִּיר קָאֲמַרְתְּ, בְּוַדַּאי עַל עַמּוּדָא דְאֶמְצָעִיתָא וְצַדִּיק אִתְּמַר עַל תַּרְוַיְיהוּ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ, אֲשֶׁר וַדַּאי דְאִיהִי אֲשֶׁר אהי\"ה אִימָּא עִלָּאָה, מַנִּי לוֹן עַל שְׁכִינְתָּא דְאִיהִי מִצְוָה, לְכָל חַד מִנַּיְיהוּ, וְאִינוּן לְעִילָא תְּרֵין כְּעַנְפִין דְּאִילָנָא דְאִתְפָּרְשׁוּ לִימִינָא וְלִשְׂמָאלָא, וּלְתַתָּא אִתְעֲבִידוּ בָּהּ אֲגוּדָה חֲדָא, וּבְגִין דָּא אִינוּן לְעִילָא תְּרֵין, וּלְתַתָּא חָד, דְּיִחוּדָא לָא אִית בְּכָל עַנְפִין דְּאִילָנָא אֶלָּא בָהּ, דְּאִיהִי אֲגַד דְּכֻלְּהוּ, אִיהִי אֲגוּדָה דְכָל אֵבֶר וְאֵבֶר, וּבָהּ אִתְעֲבִידוּ כֻּלְּהוּ חָד.</p>\n<p>וְעוֹד וַיֹּאמֶר אלהי\"ם יְהִי אוֹר דָּא נְבוּאָה בַּמַּרְאָה, דְאִתְּמַר בָּהּ (במדבר יב ו) בַּמַּרְאָה אֵלָיו אֶתְוַדָּע, וְאִיהִי חָזוֹן דִּנְבִיאַיָּא, אִיהִי חָזוֹן וְקוּדְשָׁא בְּרִיךְ הוּא חוֹזֶה, דְּאִיהוּ יהו\"ה אדנ\"י, דְהָכִי סָלִיק חָזֹן חָסֵר ו' חָמֵשׁ וְשִׁתִּין כְּחֻשְׁבַּן אדנ\"י, בִּנְבוּאָ\"ה ס\"ו, ס\"ה כְּחֻשְׁבַּן אדנ\"י, וְתֵיבָה הָא ס\"ו,</p>"],[9500011159,"<p>וּבְמַאי הִיא חָזוֹן בְּאָת ו', בֵּיהּ אִתְעֲבִידַת אַסְפַּקְלַרְיָאָה דְנַהֲרָא אָדוֹן דִּילָהּ.</p>\n<p>בְּרֵאשִׁית, שִׁמְעִי בַת וּרְאִי וְהַטִּי אָזְנֵךְ וְגוֹמֵר (תהלים מה יא), בְּרֵאשִׁית תַּמָּן שִׁמְעִ\"י, תַּמָּן בַּ\"ת, תַּמָּן רְאִ\"י, שִׁמְעִ\"י ש' מִן בְּרֵאשִׁית, בַּ\"ת תַּמָּן אִשְׁתְּמוֹדָע בְּרֵישָׁא וְסוֹפָא דְתֵיבָה, רְאִ\"י תַּמָּן אִשְׁתְּמוֹדָע בְּאֶמְצָעִיתָא, כְּגַוְונָא דָא בְּרֵ\"אשִׁי\"ת, וְכַד תְּהֵא בְּחִבּוּרָא עִמֵּיהּ כְּגַוְונָא דָא יאהדונה\"י, אִיהוּ אָמַר לְגַבָּהּ וְשִׁכְחִי עַמֵּךְ וּבֵית אָבִיךְ (שם), דְּעַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו וְאֶת אִמּוֹ וְדָבַק בְּאִשְׁתּוֹ וְהָיוּ לְבָשָׂר אֶחָד (בראשית ב כד), כִּי הוּא אֲדוֹנַיִךְ וְהִשְׁתַּחֲוִי לוֹ (תהלים מה יב), אֲדוֹן כָּל הָאָרֶץ וַדַּאי.</p>\n<p>וּבְגִין דָּא מִסִּטְרָא דְיהו\"ה אִתְקְרִיאַת אַסְפַּקְלַרְיָאָה דְנַהֲרָא, וְכַד אִיהִי אדנ\"י בְּלָא בַעִִלָהּ אִתְקְרִיאַת אַסְפַּקְלַרְיָאָה דְלָא נַהֲרָא, וּנְבִיאַיָּא מִסִּטְרָא דְיהו\"ה אִינוּן מֵאַסְפַּקְלַרְיָאָה דְנַהֲרָא, וּנְבִיאַיָּא מִסִּטְרָא דְאדנ\"י אִינוּן מֵאַסְפַּקְלַרְיָאָה דְּלָא נַהֲרָא, דְאִלֵּין מִתְנַבְּאִין רַחֲמֵי, וְאִלֵּין מִתְנַבְּאִין דִּינָא, דִּנְבוּאָה אִיהִי שְׁקִילָא לְאוֹרַיְיתָא דְבִכְתָב וּלְאוֹרַיְיתָא דִבְעַל פֶּה.</p>\n<p>וּבְהַהוּא זִמְנָא דְמִתְפַּתְּחִין הֵיכָלִין דִּנְבוּאָה, כַּמָּה מָארֵי דַעֲתִידוֹת יִתְעָרוּן בְּעָלְמָא, הֲדָא הוּא דִכְתִיב (יואל ג א) וְנִבְּאוּ בְּנֵיכֶם וּבְנוֹתֵיכֶם וכו', וְכַמָּה מָארֵי דְאוֹתוֹת, וּמָארֵי דַעֲתִידוֹת, מִמַּה דַּהֲווֹ וַעֲתִידִין לְמֶהֱוִי, מִמַּה דַּהֲווֹ מִסִּטְרָא דְמַחֲשָׁבָה דְאִתְּמַר בָּהּ יִשְׂרָאֵל עָלָה בְּמַחֲשָׁבָה, וּמַה דְּעָתִיד לְמֶהֱוֵי מִסִּטְרָא דְאִימָּא עִלָּאָה, וְרָזָא דְמִלָּה (קהלת ג טו) מַה שֶּׁהָיָה כְּבָר הוּא, וַאֲשֶׁר לִהְיוֹת כְּבָר הָיָה.</p>\n<p>וְכַמָּה מָארֵי דְעַיְינִין דְּאִינוּן חוֹזִים וּנְבִיאַיָּא יִתְעָרוּן בְּעָלְמָא דְאִינוּן עִינֵי יהו\"ה, וְכַמָּה מָארֵי דְאוּדְנִין דְּתַמָּן שְׁמִיעָה דְאִתְּמַר בְּהוֹן (יחזקאל א כד) וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם, וּמָארֵי דְאַנְפִּין דְּאִתְּמַר בְּהוֹן (שם ו) וְאַרְבָּעָה פָנִים וְגוֹמֵר, וּמָארֵי דְקָלִין, וּמָארֵי דְּדִבּוּרִין, וּמָארֵי דְרוּחָא דְקוּדְשָׁא, וּמָארֵי דִיְדִין דְּאִתְּמַר בְּהוֹן (שם ח) וִידֵי אָדָם וְגוֹמֵר, וּמָארֵי דְקוֹמָה, וּמָארֵי דְאוֹת, וּמָארֵי דְרַגְלִין דְּאִתְּמַר בְּהוֹן (שם יד) וְהַחַיּוֹת רָצוֹא וָשׁוֹב, בְּהַהוּא זִמְנָא וַיַּבְדֵּל אלהי\"ם בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ (בראשית א ד), אִלֵּין אִינוּן נְבִיאֵי דְשִׁקְרָא, דְאִתְּמַר בְּהוֹן (שמות ז יא) וַיַּעֲשׂוּ גַּם הֵם חַרְטוּמֵי מִצְרַיִם וְגוֹמֵר, דְּאַפְרִישׁ לוֹן קוּדְשָׁא בְּרִיךְ הוּא מִנְּבִיאֵי קְשׁוֹט.</p>\n<p>וַיֹּאמֶר אלהי\"ם יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם (בראשית א ז), הָכָא רָזָא לְאִתְעַסְקָא בְאוֹרַיְיתָא דִבְעַל פֶּה, וּלְאַפְרָשָׁא בֵּין אִסּוּר וְהֶתֵּר, דְּאִינוּן מַיִּין מְתִיקָן, וּמַיִּין מְרִירָן מִסִּטְרָא דִשְׂמָאלָא, וְלֹא יָכְלוּ לִשְׁתּוֹת מַיִם מִמָּרָה כִּי מָרִים הֵם (שמות טו כג), וּמִסִּטְרָא דִימִינָא וַיִּמְתְּקוּ הַמָּיִם (שם כה), וְאִינוּן כְּגַוְונָא דְּדָם טָהוֹר וְדַם נִדָּה דְצָרִיךְ לְאַפְרָשָׁא בֵּינַיְיהוּ, בְּגִין דְּהַהוּא זוּהֲמָא דְהִטִּיל נָחָשׁ בְּחַוָּה גָרִים לְעָרְבָא מַיִּין דְּדַכְיוּ עִם מַיִּין דִּמְסָאֲבוּ, וּבְגִין דָּא תַּקִּינוּ תַּקָּנָה דָא לְחוֹבָה לְאַפְרָשָׁא בֵּינַיְיהוּ, וְהַהוּא דְאַפְרִישׁ בֵּינַיְיהוּ דָּא רָקִיעַ דְּעַל רָאשֵׁי חֵיוָון, דְּאִתְּמַר בֵּיהּ (יחזקאל א כב) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ דָּא מטטרו\"ן.</p>\n<p>וַיַּעַשׂ אלהי\"ם אֶת הָרָקִיעַ וַיַּבְדֵּל וכו' (בראשית א ז), הָכָא לֵית מַיָּא מִסִּטְרָא דִמְסָאֲבוּ, אֶלָּא מַיִּין מִסִּטְרָא דִשְׂמָאלָא הֲווֹ בָּעָאן לְאִתְגַּבְּרָא, וּמַיִּין מִסִּטְרָא דִימִינָא הֲווֹ בָּעָאן לְאִסְתַּלְקָא עֲלַיְיהוּ, עַד דְּאִלֵּין אָמְרִין אֲנַן בָּעִינָן לְמֶהֱוִי קֳדָם מַלְכָּא, וְאִלֵּין אָמְרִין אֲנַן בָּעִינָן לְמֶהֱוִי קֳדָם מַלְכָּא, עַד דְּאָתָא עַמּוּדָא דְאֶמְצָעִיתָא וְאַעִיל שְׁלָם בֵּינַיְיהוּ, וְקָשִׁיר לוֹן וְאִתְעֲבִיד שֶׁקֶל (נ\"א שלום) בֵּינַיְיהוּ, וְדָא מַחֲלוֹקֶת לְשֵׁם שָׁמַיִם, כְּגוֹן לֵאָה וְרָחֵל, דְּדָא בָעָא לְאִתְחַבְּרָא בְּבַעִִלָהּ, וְדָא בָעָא לְאִתְחַבְּרָא בְּבַעִִלָהּ, וְנָטִיל לוֹן יַעֲקֹב וְקָשִׁיר לוֹן בֵּיהּ</p>"],[9500011160,"<p>לְתַרְוַיְיהוּ, בְּגִין דַּהֲוָה קָא מַחֲשֶׁבֶת לֵאָה בְּלִבָּהּ אִם יַעֲקֹב נָטִיל לַאֲחָתִי נָטִיל לִי עִשָׂו חַיָּיבָא, וְהָכִי קָא חֲשִׁיבַת רָחֵל כְּגַוְונָא דָא, בְּגִין דָּא קוּדְשָׁא בְּרִיךְ הוּא יְהִיב לוֹן לְיַעֲקֹב תַּרְוַיְיהוּ, וְשֵׁזִיב לוֹן מֵהַהוּא חַיָּיבָא, וְאִתְחַבְּרוּ בְצַדִּיקָא.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר אַבָּא, יוֹמָא חֲדָא הֲוִינָן בְּבֵי מֶדְרָשָׁא, וְשָׁאִילוּ חַבְרַיָּא מַאי נִיהוּ דְאָמַר רַבִּי עֲקִיבָא לְתַלְמִידוֹי כְּשֶׁתַּגִּיעוּ לְאַבְנֵי שַׁיִשׁ טָהוֹר אַל תֹּאמְרוּ מַיִם מַיִם שֶׁמָּא תְּסַכְּנוּ עַצְמְכֶם, שֶׁנֶּאֱמַר (תהלים קא ז) דּוֹבֵר שְׁקָרִים לֹא יִכּוֹן לְנֶגֶד עִינָי, (נ\"א קם סבא דסבין עתיקא דעתיקין, ואמר רבי רבי מאי ניהו דאמר רבי עקיבא לתלמידוי כשתגיעו לאבני שיש טהור אל תאמרו מים מים שמא תסכנו בעצמכם, הדא הוא דכתיב דובר שקרים לא יכון לנגד עיני, הא כתיב (בראשית א ו) יהי רקיע בתוך המים ויהי מבדיל בין מים למים, ועוד מים עליונים ומים תחתונים אית תמן, למה אמר אל תאמרו מים מים, אמר ליה בוצינא קדישא, סבא דסבין לך יאות לגלאה רזא דא, דלית חבריא יכלין לקיימא ביה על בורייה, אמר ליה סבא דסבין, רבי רבי בוצינא קדישא, בודאי אבני שיש טהור אינון י' י', דאינון חד יו\"ד עלאה מן א, ותנינא יו\"ד תתאה מינה, והכא לית טומאה אלא אבני שיש טהור, ולית הפרשה בין מים למים, דכלא יחודא חדא, דאלין אינון מסטרא דאילנא דחיי דאיהו ו באמצעיתא דא, דאתמר ביה ולקח גם מעץ החיים ואכל וחי לעולם, אבל אילנא דעץ הדעת לתתא). אַדְהָכִי הָא סָבָא דְסָבִין עַתִּיקָא דְעַתִּיקִין קָא נָחִית וְאָמַר לוֹן, רַבָּנָן בְּמַאי עַסְקִיתּוּ, אָמְרוּ לֵיהּ וַדַּאי בְּהַאי דְאָמַר רַבִּי עֲקִיבָא לְתַלְמִידוֹי כְּשֶׁתַּגִּיעוּ לְאַבְנֵי שַׁיִשׁ טָהוֹר אַל תֹּאמְרוּ מַיִם מַיִם, וְאָמַר לוֹן וַדַּאי רָזָא עִלָּאָה אִית הָכָא, וְהָא אוּקְמוּהָ בִּמְתִיבְתָּא עִלָּאָה, וּבְגִין דְּלָא תִטְעוּן נְחִיתְנָא לְכוֹן, בְּגִין דְּיִתְגַּלֵּי רָזָא דָא בֵּינַיְיכוּ דְאִיהוּ רָזָא עִלָּאָה טְמִירָא מִבְּנֵי נָשָׁא (נ\"א דרא).</p>\n<p>בְּוַדַּאי אַבְנֵי שַׁיִשׁ טָהוֹר אִינוּן י' י', דְּמִנְּהוֹן מַיִּין דַּכְיָין נָפְקִין, וְאִינוּן רְמִיזִין בְּאָת א רֵישָׁא וְסוֹפָא י' י', ו' דְּאִיהוּ נָטוּי בֵּינַיְיהוּ אִיהוּ עִץ חַיִּים, מָאן דְּאָכַל מִנֵּיהּ וָחַי לְעוֹלָם.</p>\n<p>וְאִלֵּין תְּרֵין יוּדִי\"ן אִינוּן רְמִיזִין בְּוַיִּיצֶר, וְאִינוּן תְּרֵין יְצִירוֹת יְצִירָה דְעִלָּאִין וִיצִירָה דְתַתָּאִין, וְאִינוּן חָכְמָה בְּרֹאשׁ וְחָכְמָה בְּסוֹף, תַּעֲלוּמוֹת חָכְמָה, וַדַּאי אִינוּן תַּעֲלוּמוֹת מֵחָכְמָה עִלָּאָה (דאיהו) דִּתְּחוֹת כֶּתֶר עִלָּאָה.</p>\n<p>וְאִינוּן לָקֳבֵל תְּרֵין עַיְינִין, דִּבְהוֹן תְּרֵין דִּמְעִין נָחֲתִין בְּיַמָּא רַבָּא וְאַמַּאי נָחְתוּ, בְּגִין דְּאוֹרַיְיתָא מִתְּרֵין לוּחִין אִלֵּין הֲוָה מֹשֶׁה נָחִית לוֹן לְיִשְׂרָאֵל, וְלָא זָכוּ וְאִתְּבַרוּ וְנָפְלוּ, וְדָא גְרִים אִבּוּדָא דְּבַיִת רִאשׁוֹן וּבַיִת שֵׁנִי, וְאַמַּאי נָפְלוּ, בְּגִין דְּפָרַח ו' מִינַיְיהוּ דְאִיהוּ ו' מִן וַיִּיצֶר.</p>\n<p>וִיָהִיב לוֹן אָחֳרָנִין מִסִּטְרָא דְעִץ הַדַּעַת טוֹב וָרָע, דְּמִתַּמָּן אִתְיְיהִיבַת אוֹרַיְיתָא בְּאִסּוּר וְהֶתֵּר, מִימִינָא חַיֵּי וּמִשְּׂמָאלָא מִיתָה, וּבְגִין דָּא אָמַר רַבִּי עֲקִיבָא לְתַלְמִידוֹי כְּשֶׁתַּגִּיעוּ לְאַבְנֵי שַׁיִשׁ טָהוֹר אַל תֹּאמְרוּ מַיִם מַיִם, וְלָא תֶהֱוָון שְׁקִילִין אַבְנֵי שַׁיִשׁ טָהוֹר לַאֲבָנִים אָחֳרָנִין, דְּאִינוּן חַיֵּי וּמִיתָה, דְתַמָן לֵב חָכָם לִימִינוֹ (קהלת י ב) דְבַר נַשׁ, וְלֵב כְּסִיל לִשְׂמֹאלוֹ (שם), וְלָא עוֹד אֶלָּא אַתֶּם תְּסַכְּנוּ עַצְמְכֶם, בְּגִין דְּאִלֵּין אַבְנִין דְּעִץ הַדַּעַת טוֹב וָרָע אִינוּן בְּפִרוּדָא, וְאִלֵּין אַבְנֵי שַׁיִשׁ טָהוֹר אִינוּן בְּיִחוּדָא בְּלָא פִּרוּדָא כְּלָל, וְאִם תֹּאמְרוּ דְהָא אִסְתַּלַּק עִץ הַחַיִּים מִנַּיְיהוּ וְנָפְלוּ וְאִית פִּרוּדָא בֵּינַיְיהוּ, דּוֹבֵר שְׁקָרִים לֹא יִכּוֹן לְנֶגֶד עִינָי (תהלים קא ז), דְּהָא לֵית תַּמָּן פִּרוּדָא לְעִילָא, וְאִלֵּין דְּאִתְּבַרוּ מֵאִינוּן (מאנין) הֲווֹ, אָתוּ לְנַשְׁקָא לֵיהּ פָּרַח וְאִסְתַּלַּק מִנַּיְיהוּ. אָמַר</p>"],[9500011161,"<p>רַבִּי יִצְחָק כָּל אִינוּן מֵתִים דְּאַרְעָא דְיִשְׂרָאֵל, יִחְיוּן וִיקוּמוּן בְּקַדְמֵיתָא לְעִידָּן דִּיְחֵי קוּדְשָׁא בְּרִיךְ הוּא מֵיתַיָּא, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא יַתְעַר עֲלַיְיהוּ, הֲדָא הוּא דִכְתִיב (ישעיה כו יט) יִחְיוּ מֵתֶיךָ נְבֵלָתִי יְקוּמוּן, יִחְיוּ מֵתֶיךָ אִלֵין אִינוּן דְּאַרְעָא דְיִשְׂרָאֵל, נְבֵלָתִי יְקוּמוּן אִלֵּין אִינוּן דִּבְאַרְעָא נוּכְרָאָה, דְלָא כְתִיב בְּהוּ תְּחִיָּה אֶלָּא קִימָה, דְּהָא רוּחָא דְחַיֵּי לָא תִּשְׁרֵי עֲלַיְהוּ אֶלָּא בְאַרְעָא דְיִשְׂרָאֵל, וּבְגִין כַּךְ כְּתִיב בְּהוּ יִחְיוּ, נְבֵלָתִי יְקוּמוּן אִלֵּין דִּלְבָר, יִתְבְּרֵי גוּפָא דִלְהוֹן וִיקוּמוּן גּוּפָא בְּלָא רוּחָא, וּלְבָתַר יִתְגַּלְגְּלוּן מִתְּחוֹת עַפְרָא עַד דְּמָטוּ לְאַרְעָא דְיִשְׂרָאֵל, וְתַמָּן יְקַבְּלוּן נִשְׁמָתָא וְלָא בִּרְשׁוּ אָחֳרָא, בְּגִין דְּיִתְקַיְימוּן בְּעָלְמָא כִּדְקָא חָזֵי.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, תָּא חֲזִי, בְּשַׁעִִתָּא דְזָמִין קוּדְשָׁא בְּרִיךְ הוּא לְאַחָיָיא מֵיתַיָּא, כָּל אִינוּן נִשְׁמָתִין דְּיִתְעָרוּן, כֻּלְּהוֹן יְקוּמוּן בְּהַהוּא דִיּוֹקְנָא מַמָּשׁ דַּהֲווֹ בְּהַאי עָלְמָא, וְנָחִית לוֹן קוּדְשָׁא בְּרִיךְ הוּא וְקָרָא לוֹן בִּשְׁמָהָן, הֲדָא הוּא דִכְתִיב (ישעיה מ כו) לְכֻלָּם בְּשֵׁם יִקְרָא, וְכָל נִשְׁמָתָא תֵּיעוּל לְדוּכְתָּהָא, וִיקוּמוּן בְּקִיּוּמָא בְּעָלְמָא כְּדְקָא חַזִי, וּכְדֵין יְהֵא עָלְמָא שְׁלִים, וְעַל הַהוּא זִמְנָא כְּתִיב (שם כה ח) וְחֶרְפַּת עַמּוֹ יָסִיר, דָּא יֵצֶר הָרָע דְּאַחְשִׁיךְ אַפֵּי דְבַר נַשׁ וְשַׁלִּיט בֵּיהּ.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, אִי תֵּימָא דְכָל גּוּפִין דְּעָלְמָא יְקוּמוּן וְיִתְעָרוּן מֵעַפְרָא, אִינוּן גּוּפִין דְּאִתְנַטְעוּ בְּנִשְׁמָתָא חֲדָא מַה תְּהֵא מִנַּיְיהוּ, אָמַר רַבִּי יוֹסֵי אִינוּן גּוּפִין דְּלָא זָכוּ וְלָא אַצְלָחוּ הֲרֵי אִינוּן כְּלָא הֲווֹ, כְּמָה דַהֲווֹ עִץ יָבֵשׁ בְּהַאי עָלְמָא, הָכִי נַמִּי בְּהַהוּא זִמְנָא, וְגוּפָא בַתְרָאָה יְקוּם, הַהוּא דְאִתְנַטַּע וְאַצְלַח וְנָטַע שָׁרָשׁוֹי כִּדְקָא יָאוּת, וְעַל הַהוּא גוּפָא בַתְרָאָה כְּתִיב (תהלים א ג) וְהָיָה כְּעִץ שָׁתוּל עַל פַּלְגֵי מָיִם, דְּעָבַד אִבִּין וְנָטַע שָׁרָשִׁין וְאַצְלַח כִּדְקָא יָאוּת, וְעַל הַהוּא גוּפָא קַדְמָאָה כְּתִיב (ירמיה יז ו) וְהָיָה כְּעַרְעָר בָּעֲרָבָה וְלֹא יִרְאֶה כִּי יָבֹא טוֹב, כִּי יָבֹא טוֹב דָּא תְּחִיַּית הַמֵּתִים.</p>\n<p>וְאִתְנְהִיר הַהוּא נְהוֹרָא דְזַמִּין לְאַנְהָרָא לְצַדִּיקַיָּא, דַהֲוָה קַמֵּיהּ גָּנִיז מִיּוֹמָא דְאִתְבְּרִי עָלְמָא, הֲדָא הוּא דִכְתִיב (בראשית א ד) וַיַּרְא אלהי\"ם אֶת הָאוֹר כִּי טוֹב, בֵּיהּ זָמִין קוּדְשָׁא בְּרִיךְ הוּא לְאַחָיָא מֵיתַיָּא, הֲדָא הוּא דִכְתִיב (מלאכי ג כ) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא, וּכְדֵין יִתְגַּבַּר טוֹב בְּעָלְמָא, וְהַהוּא דְאִתְקְרֵי רָע יִתְעֲבַר מֵעָלְמָא, וּכְדֵין אִינוּן גּוּפִין קַדְמָאִין לִיהווּ כְלָא הֲווֹ.</p>\n<p>אָמַר רַבִּי יִצְחָק זָמִין קוּדְשָׁא בְּרִיךְ הוּא לְאַרָקָא עַל אִינוּן גּוּפִין רוּחִין, אִי זָכוּ בְּהוּ יְקוּמוּן לְעָלְמָא כִּדְקָא יָאוּת, וְאִם לַאו יְהוֹן קִטְמָא תְּחוֹת רַגְלֵיהוֹן דְּצַדִּיקַיָּא, הֲדָא הוּא דִכְתִיב (דניאל יב ב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ וְגוֹמֵר.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר וְהַאי מָאן דְּאִסְתַּלַּק מֵעָלְמָא עַד לָא מָטוּן יוֹמוֹי לְעִִשְׂרִין שְׁנִין, מֵאָן אֲתַר אִתְעֲנַשׁ, בְּגִין (דהוי מתליסר שנין ולעילא) דְּהָא מִתְּלֵיסַר וּלְתַתָּא לַאו בַּר עָנְשָׁא הוּא אֶלָּא בְּחֶטְאָה דַאֲבוֹי, אֲבָל מִתְּלֵיסַר וּלְעִילָא מַהוּ, אָמַר לֵיהּ, קוּדְשָׁא בְּרִיךְ הוּא חָס עֲלֵיהּ דְּלִימוּת זַכָּאָה, וְיָהִיב לֵיהּ אֲגַר טַב בְּהַהוּא עָלְמָא, וְלָא יָמוּת חַיָּיב דְּיִתְעֲנַשׁ בְּהַהוּא עָלְמָא, וְהָא אוּקְמוּהָ.</p>\n<p>אָמַר לֵיהּ אִי חַיָּיבָא הוּא וְלָא מָטוּן יוֹמוֹי לְעִִשְׂרִין שְׁנִין מַהוּ, כֵּיוָן דְּאִסְתַּלַּק מֵעָלְמָא בְּמַאי הוּא עוֹנְשֵׁיהּ, אָמַר לֵיהּ בְּדָא אִתְקַיַּים וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט (משלי יג כג), דְּכַד עָנְשָׁא נָחִית לְעָלְמָא אִיהוּ דְאַעִִרַע בְּהַהוּא מְחַבְּלָא אִתְעֲנַשׁ, דְּלָא אַשְׁגַּחוּ עֲלֵיהּ מִלְּעִילָא, וַעֲלֵיהּ כְּתִיב (משלי ה כב) עֲוֹנוֹתָיו יִלְכְּדוּנוֹ אֶת הָרָשָׁע, אֶת לְאַסְגָּאָה מָאן דְּלָא מָטוּן יוֹמוֹי לְאִתְעַנְשָׁא, עֲוֹנוֹתָיו יִלְכְּדוּנוֹ וְלָא בֵּי דִינָא דִלְעִילָא, וּבְחַבְלֵי חַטָּאתוֹ יִתָּמֵךְ (שם) וְלָא בֵּי דִינָא דִלְתַתָּא.</p>\n<p>בְּרֵאשִׁית תַּמָּן תִּשְׁרִ\"י, וְדָא דְרוֹעָא תִּנְיָינָא יוֹם תִּנְיָינָא, יָשֶׁ\"ת חֹשֶׁךְ סִתְרוֹ (תהלים יח יב).</p>"],[9500011162,"<p>אִשְׁתָּאַר ר' אִיהִי רֹא\"שׁ הַשָּׁנָה וְתַמָּן הַבְדָּלָה בֵּין טוֹב לְרָע, וּבְרֹאשׁ הַשָּׁנָה מַלְכָּא אִיהוּ דִין, וְכָל סְפִירָן אִתְקְרִיאוּ דִּינִין וּמִשְׁפָּטִין מִסִּטְרֵיהּ, וְכָל צְבָא הַשָּׁמַיִם קַיְימִין עֲלֵיהּ מִימִינֵיהּ וּמִשְּׂמָאלֵיהּ, אִלֵּין מַיְמִינִין לְכַף זְכוּת, וְאִלֵּין מַשְׂמְאִילִין לְכַף חוֹבָה, וְכַד יִשְׂרָאֵל יִתְעָרוּן בְּשׁוֹפָרוֹת, וְסָלְקִין תַּמָּן לִשְׁכִינְתָּא דְאִיהִי תְּרוּעַת מֶלֶךְ בַּעֲשָׂרָה שׁוֹפָרוֹת, בְּגִין דְּאִיהִי לָא סָלְקָא פָּחוּת מֵעֲשָׂרָה, בְּהַהוּא זִמְנָא וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם (בראשית א ו), אַפְרִישׁ קוּדְשָׁא בְּרִיךְ הוּא בֵּין אִלֵּין דְּמַיְמִינִים לְכַף זְכוּת, וּבֵין אִלֵּין דְּמַשְׂמְאִילִים לְכַף חוֹבָה, וְאִתְּמַר (במדבר יז כב) הִבָּדְלוּ מִתּוֹךְ הָעִדָה הַזֹּאת וַאֲכַלֶּה אוֹתָם כְּרָגַע.</p>\n<p>וְעַל הַאי תִּשְׁרִי אִתְּמַר בְּתִשְׁרִי נִבְרָא הָעוֹלָם, וְתַמָּן שַׁבָּת תִּנְיָינָא מֵאִלֵּין שֶׁבַע שַׁבָּתוֹת, (נ\"א ותמן בת שית בת מאלין שית), וַחֲמִשָּׁה רְקִיעִין, וּשְׁתִיתָאָה שָׁמַיִם, אִינוּן לָקֳבֵל שִׁית יוֹמֵי בְּרֵאשִׁית, וּבְכֻלְּהוּ אָמַר טוֹב, בַּר מִיּוֹמָא תִּנְיָינָא, בְּגִין דְּלֵית בְּתִשְׁרִי א' לְאַשְׁלָמָא בְּרֵאשִׁית, בְּגִין דְּאִסְתַּלַּק בְּחוֹבָה דְאָדָם, וּבְגִין דָּא צָפוֹן אִיהוּ פָּגִים, וּבְגִין דָּא מִצָּפוֹן תִּפָּתַח הָרָעָה (ירמיה א יד), עַד דְּאִשְׁתַּלִּים, וּכְמָה דְאַבְרָהָם דְּאִיהוּ יְמִינָא יוֹמָא קַדְמָאָה בֵּיהּ כְּלִילָן וְתַלְיָין מָאתָן וְאַרְבְּעִין וּתְמַנְיָא פִּקּוּדִין דַּעֲשֵׂה, הָכִי נַמִּי מִיִּצְחָק דְּאִיהוּ כְּגַוְונָא דְיוֹמָא תִנְיָינָא תַלְיָין בֵּיהּ שְׁסָ\"ה מִצְוֹת לֹא תַעֲשֶׂה, יוֹמָא תְּלִיתָאָה בֵּיהּ כְּלִיל כֹּלָּא, מִנֵּיהּ תַּלְיָין פִּקּוּדִין דַּעֲשֵׂה וְלֹא תַעֲשֶׂה, כְּעִנְבִין בְּאַתְכְּלָא.</p>\n<p>בְּרֵאשִׁית תַּמָּן אִישׁ, דְּאִתְּמַר בֵּיהּ (בראשית כה כז) וְיַעֲקֹב אִישׁ תָּם, וְדָא יוֹמָא תְּלִיתָאָה, דְּהָא תְּלַת אוּמָנִין הֲווֹ עַד הָכָא, יוֹמָא קַדְמָאָה וְיוֹמָא תִנְיָינָא וְיוֹמָא תְּלִיתָאָה, כָּל חַד אַפִּיק אוּמָנוּתֵיהּ, יוֹמָא קַדְמָאָה אָמַר לֵיהּ הַהוּא אָמוֹן מוּפְלָא וּמְכוּסֶה דְאִיהוּ אַיִ\"ן, כְּלִיל תְּלַת סְפִירָן א' כֶּתֶר י' חָכְמָה ן' בִּינָה, וְה' אַתְוָון מנצפ\"ך מֵעָלְמָא דְאָתֵי אִינוּן לָקֳבֵל ה' עִלָּאָה,</p>\n<p>אָמַר לְכָל אֶחָד מִתְּלַת יוֹמִין דְּיַפִּיק אוּמָנוּתֵיהּ, אָמַר לְיוֹמָא קַדְמָאָה יְהִי אוֹר מִיָּד אַפִּיק אוּמָנוּתֵיהּ וְעָבִיד לֵיהּ, הֲדָא הוּא דִכְתִיב (שם א ג) וַיְהִי אוֹר, וְהָא אוּקְמוּהוּ דְלֵית הֲוַיָּה אֶלָּא עַל יְדֵי עֲשִׂיָּה, א' מִן אַיִ\"ן דַּהֲוָה פָרַח בְּאַוִּיר אַפִּיק אוֹר, י' אַפִּיק רָקִיעַ, ן' מִן אַיִן אַפִּיק יַבָּשָׁה, הֲדָא הוּא דִכְתִיב (שם) וַיֹּאמֶר אלהי\"ם יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד וְתֵרָאֶה הַיַּבָּשָׁה, וַיֹּאמֶר אלהי\"ם יִקָּווּ הַמַּיִם, הָכָא כַּמָּה פִּקּוּדִין, פִּקּוּדָא דְיִחוּדָא וּפִקּוּדָא דְפִרְיָה וְרִבְיָה, פִּקּוּדָא דְיִחוּדָא דְאִיהוּ יִקָּווּ הַמַּיִם, מִתְכַּנְשִׁין יִחוּדָא דְכָל סְפִירָא וּסְפִירָא לַאֲתַר חַד דְּאִיהוּ כְנִישׁוּ דְכֹלָּא, אֶל מָקוֹם אֶחָד, דְּאִיהוּ מִקְוִה יִשְׂרָאֵל יהו\"ה.</p>\n<p>יוֹמָא תְּלִיתָאָה שְׁמַע יִשְׂרָאֵל יהו\"ה אלהינ\"ו יהו\"ה אֶחָד (דברים ו ד), וְאִיהוּ יהו\"ה מָקוֹם אִתְקְרֵי, וְהָא אוּקְמוּהָ מָארֵי מַתְנִיתִין, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְקְרֵי מְקוֹמוֹ שֶׁל עוֹלָם וְאֵין הָעוֹלָם מְקוֹמוֹ, כְּגַוְונָא דָא י' עִִשֶׂר זִמְנִין אִיהוּ ק' מִן מָקוֹם, ה\"ה חָמֵשׁ זִמְנִין כָּל חַד וְחַד סָלְקָן כ\"ה כ\"ה, כְּחוּשְׁבַּן אַתְוָון דְּיִחוּדָא תְּרֵין זִמְנִין דִּמְיַחֲדִין שְׁמַע יִשְׂרָאֵל דְּאִינוּן שִׁית תֵּיבִין, דִּבְהוֹן כ\"ה כ\"ה אַתְוָון, אִם כֵּן מַאי ק', מְאָה בִּרְכָאָן דְּחַיָּיב בַּר נַשׁ לְבָרְכָא לְקוּדְשָׁא בְּרִיךְ הוּא בְּכָל יוֹמָא, אִשְׁתָּאַר ו', שִׁית זִמְנִין שִׁית סָלְקִין תְּלָתִין וְשִׁית, כְּחוּשְׁבַּן גַּדְפִין דִּשְׂרָפִים דְּאִתְּמַר בְּהוֹן (ישעיהו ו ב) שְׂרָפִים עוֹמְדִים מִמַּעַל ל\"וֹ, וְאִלֵּין גַּדְפִין תַּלְיָין מִן ו' דְּאִיהוּ שִׁית תֵּיבִין דְּיִחוּדָא, וּבָהּ סָלְקִין אַרְבְּעִין וּתְרֵין אַתְוָון, דִּבְהוֹן אִתְבְּרִיאוּ שְׁמַיָּא וְאַרְעָא, תִּשְׁכַּח</p>"],[9500011163,"<p>מָקוֹ\"ם דְּסָלִיק יהו\"ה בְּחֻשְׁבָּנָא כְּגַוְונָא דָא, י' ק', ה\"ה כ\"ה כ\"ה, ו' ל\"ו, סָלִיק כֹּלָּא קפ\"ו כְּחוּשְׁבַּן מָקוֹ\"ם, וּבֵיהּ (ישעיה כח ז) פָּק\"וּ פְּלִילִיָה, וּבֵיהּ קָפ\"וּ תְהוֹמֵי בְּלִבָּא דְיַמָּא.</p>\n<p>בְּהַאי שְׁמָא דְאִיהוּ יהו\"ה צָרִיךְ לְאִתְכַּנְשָׁא דַרְגִּין דְּיִחוּדָא, וּלְאַכְלָלָא בֵּיהּ עִִשֶׂר סְפִירָן כְּגַוְונָא דָא, יו\"ד ה\"א וא\"ו ה\"א, דְאִינוּן עִִשֶׂר סְפִירוֹת בְּלִימָה, יהו\"ה מָקוֹם לְיו\"ד ה\"א וא\"ו ה\"א דְאִיהוּ סָתִים וְנֶעִִלָם, וּבְגִין דָּא אִתְקְרֵי עוֹלָם עִִלֶם, דְּצָרִיךְ לְאַעִִלָמָא לֵיהּ מִכּוּלֵי עָלְמָא, דְּאִיהוּ עֹלָם, וּשְׁכִינְתָּא נֶעֱלָמָה, הֲדָא הוּא דִכְתִיב (איוב כח כא) וְנֶעִִלְמָה מֵעִינֵי כָל חָי.</p>\n<p>לַאו סְפִירָה דְלֵית תַּמָּן יהו\"ה יו\"ד ה\"א וא\"ו ה\"א, וְהָכִי צָרִיךְ לְאִתְכַּנְשָׁא כֹּלָּא בֵיהּ בְּכָל אֲתַר, דְּכָל שְׁמָהָן אִינוּן כִּנּוּיִין לֵיהּ, וּשְׁכִינְתֵּיהּ אִיהִי יהו\"ה אִיהִי כְּלִילָא מֵאַרְבַּע אַתְוָון, וְלָא אִתְקְרֵי אִיהוּ מָקוֹם אֶלָּא בָּהּ, מָקוֹם אֶחָד וַדַּאי, אִיהוּ לָא אִתְקְרֵי אָדָם (נ\"א אחד) אֶלָּא בָהּ, כְּגַוְונָא דְאָדָם דִּלְתַתָּא דְבָרָא בְדִיּוֹקְנֵיהּ, דְּאִתְּמַר בֵּיהּ (בראשית ה ב) זָכָר וּנְקֵבָה בְּרָאָם וַיְבָרֶךְ אֹתָם וַיִּקְרָא אֶת שְׁמָם אָדָם.</p>\n<p>וְעוֹד כִּי אֶחָד קְרָאתִיו (ישעיה נא ב), כְּגַוְונָא דְעִִשֶׂר סְפִירוֹת, דְּאִינוּן א' כֶּתֶר עִלָּאָה, ח' תְּמַנְיָא סְפִירָן מֵחָכְמָה עַד צַדִּיק, ד' מַלְכוּתָא קַדִּישָׁא, עֲלָהּ אִתְּמַר (דברים יז כ) לְמַעַן יַאֲרִיךְ יָמִים עַל מַמְלַכְתּוֹ, וְאִם חַס וְשָׁלוֹם פָּחִית בַּר נַשׁ מֵעִִשֶׂר לְיַחֲדָא בָּהּ, אִסְתַּלַּק קוֹצָא מִן ד' מִן אֶחָד וְאִשְׁתְּאָרַת יַבָּשָׁה, וְרָזָא דְמִלָּה (בראשית א ט) יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם, דְּאִיהִי תַּחַת הַשָּׁמַיִם דְּאִיהוּ קוּדְשָׁא בְּרִיךְ הוּא, דְּאִתְּמַר בֵּיהּ (מלכים א ב לב) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם, דְּנוּקְבָא אִיהִי תְּחוֹת בַּעִִלָהּ.</p>\n<p>וְהָכִי כָּל מָאן דְּפָגִים אוֹת בְּרִית, בְּהַהִיא טִפָּה דְאִיהִי יִחוּדָא, וְזָרִיק לָהּ בַּאֲתַר אָחֳרָא, גָרִים לָהּ לְמֶהֱוִי יַבָּשָׁה מִסִּטְרֵיהּ, דְּאִסְתַּלַּק נְבִיעוּ וְיִחוּדָא מִינָהּ, וְאִשְׁתְּאָרַת אִיהִי יַבָּשָׁה, וְדָא גָרִים חָרְבַּן עָלְמָא, וּמִיָּד אִתְּמַר (ישעיה יט ה) וְנָהָר יֶחֱרַב וְיָבֵשׁ, דְּאִיהוּ נָהָר דְּנָפִיק מֵעִדֶן, דְּאַשְׁקֵי לֵיהּ לְגַן דְּאִיהִי אוֹרַיְיתָא שֶׁבְּעַל פֶּה, דְאִיהִי מִתְשַׁקְיָא מֵאוֹרַיְיתָא דְבִכְתָב, דִּכְלִילָא גַ\"ן סְדָרִים דְּאוֹרַיְיתָא.</p>\n<p>בְּרֵאשִׁית תַּמָּן אֲתַ\"ר יָבֵ\"שׁ, וְדָא אִיהוּ וְנָהָר יֶחרַב וְיָבֵשׁ (שם ה), בְּהַהוּא זִמְנָא דְאִיהוּ יָבֵשׁ וְאִיהִי יַבָּשָׁה, צָוְוחִין בְּנִין לְתַתָּא בְּיִחוּדָא וְאָמְרִין שְׁמַע יִשְׂרָאֵל, וְאֵין קוֹל וְאֵין עוֹנֶה, הֲדָא הוּא דִכְתִיב (משלי א כח) אָז יִקְרָאוּנְנִי וְלֹא אֶעֱנֶה.</p>\n<p>וְהָכִי מָאן דְּגָרִים דְּאִסְתַּלַּק קַבָּלָה וְחָכְמָתָא מֵאוֹרַיְיתָא דִבְעַל פֶּה וּמֵאוֹרַיְיתָא דְבִכְתָב, וְגָרִים דְּלָא יִשְׁתַּדְלוּן בְּהוֹן, וְאָמְרִין דְּלָא אִית אֶלָּא פְּשָׁט בְּאוֹרַיְיתָא וּבְתַלְמוּדָא, בְּוַדַּאי כְּאִלּוּ הוּא יְסַלֵּק נְבִיעוּ מֵהַהוּא נָהָר וּמֵהַהוּא גָן, וַוי לֵיהּ טַב לֵיהּ דְּלָא אִתְבְּרִי בְּעָלְמָא וְלָא יוֹלִיף הַהִיא אוֹרַיְיתָא דְבִכְתָב וְאוֹרַיְיתָא דִבְעַל פֶּה, דְּאִתְחַשַּׁב לֵיהּ כְּאִלּוּ אַחְזַר עָלְמָא לְתֹהוּ וָבֹהוּ, וְגָרִים עֲנִיּוּתָא בְּעָלְמָא וְאוֹרֶךְ גָּלוּתָא.</p>\n<p>וַיֹּאמֶר אלהי\"ם תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא וכו' (בראשית א יא), אָמַר רַבִּי אֶלְעָזָר אַבָּא וְהָא קָרָא לֵיהּ יַבָּשָׁה, מֵאָן תַּדְשֵׁא הָאָרֶץ, אָמַר לֵיהּ בְּרִי הָכִי אוֹלִיף תְּיוּבְתָּא לְכָל בְּנֵי עָלְמָא, דְּאִם בַּר נַשׁ יַחֲזוֹר בִּתְיוּבְתָּא, נָחִית לָהּ נְבִיעוּ דְאִסְתַּלַּק, וּמַה דַּהֲוָה יַבָּשָׁה קָרָא לָהּ אֶרֶץ, וְנָהָר דַּהֲוָה חָרֵב וְיָבֵשׁ קָרָא לֵיהּ מִקְוִה הַמַּיִם וְיַמִּים, הֲדָא הוּא דִכְתִיב (שם י) וַיִּקְרָא אלהי\"ם לַיַּבָּשָׁה אֶרֶץ וּלְמִקְוִה הַמַּיִם קָרָא יַמִּים, בְּהַהוּא זִמְנָא דְאִתְקְרֵי אֶרֶץ מַה כְּתִיב בֵּיהּ (שם יא) וַיֹּאמֶר אלהי\"ם תַּדְשֵׁא הָאָרֶץ, לְאַפָּקָא זַרְעִין וְאִיבִּין דְּאִינוּן נִשְׁמָתִין</p>"],[9500011164,"<p>כָּל חַד לִזְנַיְהוּ, אִלֵּין נִשְׁמָתִין דְּאִתְגַּזְרוּ מִכּוּרְסֵי יְקָרֵיהּ, וְאִלֵּין רוּחִין דְּאִתְגַּזְרוּ מִמַּלְאָכִים, וְאִלֵּין נַפְשִׁין דְּאִתְגַּזְרוּ מֵאוֹפַנִּים, כָּל חַד אַפִּיק לִזְנַיְיהוּ לְכָל חַד כִּדְקָא יָאוּת, עִץ פְּרִי דָא תַּלְמִיד חָכָם, עוֹשֶׂה פְּרִי דָא בַת זוּגֵיהּ, לְכָל חַד כִּדְקָא יָאוּת, (כל חד אפיק לזנוי).</p>\n<p>וְעוֹד עִץ פְּרִי דָא עַמּוּדָא דְאֶמְצָעִיתָא, עוֹשֶׂה פְּרִי דָא צַדִּיק, אֲשֶׁר זַרְעוֹ בוֹ עַל הָאָרֶץ דָּא שְׁכִינְתָּא, דְכָל זַרְעִין אִתְכְּלִילָן בָּהּ, וְהָכָא פִּקּוּדָא דְפִרְיָה וְרִבְיָה לְמֶעֱבַד אִבִּין וְזַרְעִין, הֲדָא הוּא דִכְתִיב (ישעיה מה יח) לֹא תֹהוּ בְרָאָהּ לָשֶׁבֶת יְצָרָהּ, וּמָאן דְּאִתְבַּטַּל מִפִּרְיָה וְרִבְיָה, כְּאִלּוּ אַחְזַר לְהַהִיא אֶרֶץ יַבָּשָׁה, וּמָנַע בִּרְכָאָן מִינָהּ, כָּל חַד לְפוּם דַּרְגֵּיהּ, מָאן דְּפָגִים לְתַתָּא פָגִים לְעִילָא, לַאֲתַר דְּאִתְגַּזַּר נִשְׁמָתֵיהּ.</p>\n<p>בְּרֵאשִׁית, תַּמָּן תְּרֵ\"י תַּמָּן אֵ\"שׁ, וַעֲלַיְיהוּ אִתְּמַר (בראשית א יד) וַיֹּאמֶר אלהי\"ם יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם, מְאֹרֹת כְּתִיב חָסֵר ו' דָּא אוֹרַיְיתָא דְבִכְתָב, מַאי מְאֹרֹת דָּא אוֹרַיְיתָא דִבְעַל פֶּה, וְאַף עַל גַּב דְּאוּקְמוּהָ מְאֹרֹת חָסֵר דָּא לִילִית, שַׁבְעִין אַנְפִּין לְאוֹרַיְיתָא, וּבְגִין דָּא מְאֹרֹת בְּהַאי אֲתַר, הַהִיא דְאִתְּמַר בָּהּ (משלי ו כג) כִּי נֵר מִצְוָה, וְתוֹרָה אוֹר עַמּוּדָא דְאֶמְצָעִיתָא, וַעֲלַיְיהוּ אִתְּמַר (בראשית א טז) אֶת הַמָּאוֹר הַגָּדוֹל לְמֶמְשֶׁלֶת הַיּוֹם וְאֶת הַמָּאוֹר הַקָּטֹן לְמֶמְשֶׁלֶת הַלַּיְלָה.</p>\n<p>הָכָא פִּקּוּדָא לְמֶעֱבַד צְדָקָה, אֶת הַמָּאוֹר הַגָּדוֹל רָזָא דַעֲתִירִין, וְאֶת הַמָּאוֹר הַקָּטֹן רָזָא דְמִסְכְּנִין, וּכְמָה דְסִיהֲרָא לווְֹה מִן שִׁמְשָׁא, וְלָא אִית לָהּ נְהוֹרָא אֶלָּא מִמַּה דְּיָהִיב לָהּ שִׁמְשָׁא, הָכִי שְׁכִינְתָּא אָמְרַת לְווּ עָלַי וַאֲנִי פּוֹרֵעַ, דְּהָכִי צָרִיךְ בַּר נַשׁ לְמֶהֱוִי מַלְוְה לְמִסְכְּנָא, וּכְגַוְונָא דָא לווִֹין כֹּכְבַיָּא וּמַזָּלֵי דָא מִן דָּא, וּמַלְאָכַיָּא דָא מִן דָּא, וְרָזָא דְמִלָּה וּמְקַבְּלִין דֵּין מִן דֵּין, הָכִי לווְֹה שְׁכִינְתָּא דְאִיהִי סִיהֲרָא קַדִּישָׁא מִקּוּדְשָׁא בְּרִיךְ הוּא, וּמְקַבֶּלֶת מִנֵּיהּ, דְּאִתְּמַר בֵּיהּ (תהלים פד יב) כִּי שֶׁמֶשׁ וּמָגֵן יהו\"ה אלהי\"ם, וְהָכִי הֲוָה מְקַבֵּל יְהוֹשֻׁעַ מִן מֹשֶׁה, כְּמָה דְאוּקְמוּהוּ פְּנֵי מֹשֶׁה כִּפְנֵי חַמָּה וּפְנֵי יְהוֹשֻׁעַ כִּפְנֵי לְבָנָה, וְהָכִי הֲווֹ כָל נְבִיאַיָּיא קֳדָם מֹשֶׁה כְּגוֹן סִיהֲרָא וְכֹכְבַיָּא קֳדָם שִׁמְשָׁא, דְלָא אִית לוֹן נְהוֹרָא אֶלָּא מִשִּׁמְשָׁא.</p>\n<p>בְּרֵאשִׁית בָּרָא אלהי\"ם, אֵ\"ל הַיָּ\"ם, יַמָּא דְאוֹרַיְיתָא, וַעֲלֵיהּ אִתְּמַר (בראשית א כ) וַיֹּאמֶר אלהי\"ם יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה וְעוֹף יְעוֹפֵף עַל הָאָרֶץ, הָכָא פִּקּוּדָא לְמִלְעִי בְּאוֹרַיְיתָא, דְאִתְּמַר בָּהּ (ישעיה נה א) הוֹי כָּל צָמֵא לְכוּ לַמַּיִם, וְאִלֵּין דְּעָסְקִין בְּאוֹרַיְיתָא יָרְתִין נֶפֶשׁ חַיָּה מִשְּׁכִינְתָּא, הֲדָא הוּא דִכְתִיב יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה, וְעוֹף יְעוֹפֵף דָּא רוּחַ דְּאִתְּמַר בֵּיהּ (קהלת י כ) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל וּבַעַל כְּנָפַיִם יַגִּיד דָּבָר, וְהַאי אִיהוּ יהו\"ה עַמּוּדָא דְאֶמְצָעִיתָא.</p>\n<p>לְקִבְלֵיהּ מטטרו\"ן דִּשְׁמֵיהּ כְּשֵׁם רַבֵּיהּ, י' רֵישָׁא דְעוֹפָא, ו' גּוּפָא דִילֵיהּ, ה\"ה תְּרֵי גַדְפוֹי דִבְהוֹן פָּרַח לְעִילָא וְנָחִית לְתַתָּא, וְאִלֵּין תְּרֵין גַּדְפִין אִינוּן תְּרֵין הֲבָלִים ה\"ה, דִבְהוֹן אִתְּמַר (יחזקאל א יד) וְהַחַיּוֹת רָצוֹא וָשׁוֹב, דְּאִינוּן י\"ו, הֶבֶל סָלִיק בְּי' הֶבֶל נָחִית בְּו', כְּהֶבֶל דְּנָפִיק מִפִּימָא דְכִבְשָׁן, וְהָכִי יַמָּא סָלִיק וְנָחִית, וְגַלְגַּלּוֹי רָצִים וְשָׁבִים.</p>"],[9500011165,"<p>וּבָעָאן לְאַחְזָרָא עָלְמָא לְתֹהוּ וָבֹהוּ, וּבְזִמְנָא דְמִסְתַּכְּלִין בִּשְׁכִינְתָּא דְאִיהִי תְּחוּם יַמָּא חָזְרִין לְאַתְרַיְיהוּ, תָּא חֲזִי י' אִיהִי אֲמִירָה וְדִבּוּר וּקְרִיאָה, ו' קוֹל, ה\"ה הֶבֶל נָחִית בְּדִבּוּר, הֶבֶל סָלִיק בְּקוֹל, קוֹל סָלִיק, דִּבּוּר נָחִית, וְכַד אִיהוּ סָלִיק וְנָחִית מַלְאֲכֵי אלהי\"ם סָלְקִין וְנָחֲתִין בֵּיהּ, דְּאִינוּן מַשִּׁרְיָין וַחֲיָלִין דִּילֵיהּ, וְדָא אִיהוּ רָזָא מִי עָלָה שָׁמַיִם וַיֵּרַד (משלי ל ד), זַכָּאָה אִיהוּ מָאן דְּסָלִיק צְלוֹתִין בֵּיהּ, דְּהָא צְלוֹתָא אִיהִי סֻלָּם, דְּבָהּ מַלְאֲכֵי אלהי\"ם סָלְקִין וְנָחֲתִין לָהּ.</p>\n<p>אִית לְמָאן דְּסָלְקִין לָהּ לְעִילָא, וְאִית לְמָאן דְּנָחֲתִין לָהּ לְתַתָּא, כַּד סָלְקִין לָהּ לְעִילָא סָלְקִין לָהּ בְּזַכְוָון, וְכַד נָחְתַת נָחְתַת בְּזַכְוָון, הַאי לְצַדִּיק גָּמוּר סְלִיקַת מִנֵּיהּ בְּזַכְוָון וּנְחִיתַת בֵּיהּ בְּזַכְוָון, לְבֵינוּנִי דְזַכְוָון דִּילֵיהּ שְׁקִילִין לְחוֹבִין, אִיהִי תַּלְיָא בְאַוִּירָא, אִם חוֹבִין מִתְרַבִּין עַל זַכְוָון (כחוט השערה), אִיהִי סָלְקָא לֵיהּ בְּחוֹבִין וְנָחְתָא לֵיהּ בְּזַכְוָון, וְנָטִיל בָּהּ אַגְרֵיהּ בְּהַאי עָלְמָא, לָרָשָׁע גָּמוּר דְּלֵית לֵיהּ זְכוּ בְעָלְמָא לָא לְעִילָא וְלָא לְתַתָּא, סָלְקָא מִנֵּיהּ בְּחוֹבִין וְנָחִית עֲלֵיהּ בְּחוֹבִין.</p>\n<p>הָא הָכָא כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל (קהלת י כ), דְּאִתְּמַר בֵּיהּ וְעוֹף יְעוֹפֵף, כְּגוֹן מוּעָף בִּיעָף (דניאל ט כא), עַל פְּנֵי רְקִיעַ הַשָּׁמָיִם דָּא נְשָׁמָה, דְּאִלֵּין דְּזַכָּאָן בְּאוֹרַיְיתָא אִתְּמַר בְּהוֹן יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה וְגוֹמֵר, דְּיָרְתִין נִשְׁמָתִין מֵאוֹרַיְיתָא, לְאָחֳרָנִין כָּל חַד לִזְנוֹי כְּפוּם עוֹבָדוֹי, הֲדָא הוּא דִכְתִיב בְּיוֹמָא שְׁתִיתָאָה (בראשית א כד) וַיֹּאמֶר אלהי\"ם תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ בְּהֵמָה וָרֶמֶשׂ וְגוֹמֵר, בְּהֵמָה אֵלּוּ עַמֵּי הָאָרֶץ דְּעוֹבָדֵהוֹן כִּבְעִירָן, עֲלַיְיהוּ אִתְּמַר תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ בְּהֵמָה וָרֶמֶשׂ.</p>\n<p>בְּרֵאשִׁית בָּרָא שִׁית, וְאִינוּן שִׁית גַּדְפִין דְּחַיָּה, דְאִתְּמַר בָּהּ (שם כ) וְעוֹף יְעוֹפֵף עַל הָאָרֶץ עַל פְּנֵי רְקִיעַ הַשָּׁמָיִם, אִינוּן שִׁית סְפִירָן דְּכָלִיל הַאי עוֹף דְּאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, אִית מָאן דְּיָרִית רוּחָא דְקוּדְשָׁא בְאֹרַח אֲצִילוּת מֵהַאי עוֹף, וְאִית מָאן דְּיָרִית רוּחָא מֵהַהוּא עוֹף דְּאִיהוּ נַעַר, שְׁמֵיהּ כְּשֵׁם רַבֵּיהּ, וְאִית מָאן דְּיָרִית רוּחָא מִלְּתַתָּא דְאַרְעָא, כְּמָה דְאָמַר קֹהֶלֶת (קהלת ג כא) מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא לְמָעִִלָה, וְרוּחַ הַבְּהֵמָה הַיֹּרֶדֶת הִיא לְמַטָּה לָאָרֶץ.</p>\n<p>בְּרֵאשִׁית בָּרָא שִׁית, וְדָא יוֹמָא שְׁתִיתָאָה, דְאִתְּמַר בֵּיהּ (בראשית א לא) וַיְהִי עִִרֶב וַיְהִי בֹקֶר יוֹם הַשִּׁשִּׁי, הָכָא תְּלַת אוּמָנִין תִּנְיָינִין, אוּמָן חַד אַפִּיק נְהוֹרִין בְּיוֹמָא רְבִיעָאָה, דַּהֲווֹ תַלְיָין בְּיוֹמָא קַדְמָאָה דְאִתְּמַר בֵּיהּ אוֹר, אוּמָנָא תִנְיָינָא אַפִּיק רִיחֲשָׁא מִמַּיָּא, הֲדָא הוּא דִכְתִיב (שם כ) יִשְׁרְצוּ הַמַּיִם, וְדָא הֲוָה תַלְיָא בְּיוֹמָא תִנְיָינָא, דְאִתְּמַר בֵּיהּ מַיִם, הֲדָא הוּא דִכְתִיב (שם ו) יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם, הָכָא מַיָּא וְהָכָא מַיָּא, אוּמָנָא תְּלִיתָאָה (אפיק עשבין וזרעין) לָקֳבֵל יוֹמָא תְּלִיתָאָה, דְאִתְּמַר בֵּיהּ (שם יא) תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עִשֶׂב מַזְרִיעַ זֶרַע לְמִינֵהוּ, וְאִתְּמַר בְּיוֹמָא שְׁתִיתָאָה (שם כח) פְּרוּ וּרְבוּ וּמִלְאוּ אֶת הָאָרֶץ, מַאי וּמִלְאוּ אֶת הָאָרֶץ אֶלָּא הַהִיא דַהֲוַת יַבָּשָׁה בְּיוֹמָא תְּלִיתָאָה, אִתְּמַר הָכָא וּמִלְאוּ אֶת הָאָרֶץ, הֲדָא הוּא דִכְתִיב (ישעיהו ו ג) מְלֹא כָל הָאָרֶץ</p>"],[9500011166,"<p>כְּבוֹדוֹ, וְדָא בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעִִד, קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ יהו\"ה צבאו\"ת (ישעיהו ו ג), לָקֳבֵל יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד (בראשית א ט) וְתֵרָאֶה הַיַּבָּשָׁה, לָקֳבֵל מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ. בְּיוֹמָא שְׁתִיתָאָה אִתַּקְנוּ שִׁית דַּרְגִּין דְּכָרְסַיָּיא, וּבֵיהּ אִתְבְּרִי אָדָם בְּצַלְמוֹ, דְאִיהוּ מוּכָן לָשֶׁבֶת עַל הַכִּסֵּא, הֲדָא הוּא דִכְתִיב (שם כז) וַיִּבְרָא אלהי\"ם אֶת הָאָדָם בְּצַלְמוֹ, וְהָכָא תְּרֵין פִּקּוּדִין, חַד נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ (שם כו), וְתִנְיָינָא וַיִּבְרָא אלהי\"ם אֶת הָאָדָם בְּצַלְמוֹ.</p>\n<p>נַעֲשֶׂה אָדָם, דָּא פִּקּוּדָא לְמִגְזַר יָת גִּיּוֹרָא, לְמֶהֱוִי בְּצַלְמֵנוּ בִּגְזִירוּ דְעָרְלָה, כִּדְמוּתֵנוּ בִּפְרִיעָה, וְאִם נָטִיר אוֹת בְּרִית בְּתַרְוַיְיהוּ אִיהוּ בְּצַלְמֵנוּ כִּדְמוּתֵנוּ וְאִם לַאו לַאו, וְאִי מְקַיֵּים זָכוֹר וְשָׁמוֹר בְּשַׁבָּת אִיהוּ בְּצַלְמֵנוּ כִּדְמוּתֵנוּ וְאִם לַאו לַאו, וְלָא אִית לֵיהּ חוּלָקָא בְזַרְעָא דְיִשְׂרָאֵל, וְאִם מְיַחֵד לְקוּדְשָׁא בְּרִיךְ הוּא תְּרֵין זִמְנִין בְּכָל יוֹמָא בִּקְרִיאַת שְׁמַע בִּימָמָא וּבְלֵילְיָא אִיהוּ בְּצַלְמֵנוּ כִּדְמוּתֵנוּ וְאִם לַאו לַאו, וְאִם הוּא מָנַח תְּפִלִּין דְּיָד וּתְפִלִּין דְּרֵישָׁא בְכָל יוֹמָא דְאִינוּן לָקֳבֵל זָכוֹר וְשָׁמוֹר אִיהוּ בְּצַלְמֵנוּ כִּדְמוּתֵנוּ וְאִם לַאו לַאו, וְאִי אִיהוּ מְקַיֵּים יִבּוּם וַחֲלִיצָה אִיהוּ בְּצַלְמֵנוּ כִּדְמוּתֵנוּ וְאִי לַאו לַאו, וְכֹלָּא בִּרְחִימוּ וּדְחִילוּ דְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וְעוֹד נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, לְמָאן אָמַר דָּא (לעילא), לְאִינוּן מַלְאָכַיָּא דִמְבָרְכִין וּמְקַדְּשִׁין לְקוּדְשָׁא בְּרִיךְ הוּא לְעִילָא בְכָל יוֹמָא בְּבָּרוּךְ וְקָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, הֲדָא הוּא דִכְתִיב (ישעיה ו ג) וְקָרָא זֶה אֶל זֶה וְאָמַר קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, וּמְנָלָן דִּמְבָרְכִין לֵיהּ, אֶלָּא כַד שָׁאֲלִין אַיֵּה מְקוֹם כְּבוֹדוֹ לְהַעֲרִיצוֹ, אָמְרִין בָּרוּךְ כְּבוֹד יהו\"ה מִמְּקוֹמוֹ (יחזקאל ג יב), וַאֲנַן לְקִבְלֵיהוֹן מְקַדְּשִׁין לֵיהּ בְּקָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, וּמְבָרְכִין לֵיהּ בָּרוּךְ כְּבוֹד יהו\"ה מִמְּקוֹמוֹ.</p>\n<p>וְאִינוּן אָמְרִין עַל יִשְׂרָאֵל נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ (בראשית א כו) בְּצַלְמֵנוּ דִמְקַדְשִׁין לְקִבְ\"ה כְּמָה דִאוֹקְימִנָא, וְקָרָא זֶה אֶל זֶה וְאָמַר קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, כִדֻמוּתֵנוּ לְעוּמָתָם מְשַׁבְּחִים וְאוֹמְרִים בָּרוּךְ כְּבוֹד יהו\"ה מִמְּקוֹמוֹ, וְעוֹד לְעִילָא נַעֲשֶׂה אָדָם, הָכָא אִתְכְּלִילוּ כָּל סְפִירָן, דְּאִינוּן יו\"ד ה\"א וא\"ו ה\"א דְאִינוּן עִִשֶׂר, וְסָלְקִין לְחוּשְׁבַּן אָדָם, וְאָמְרוּ בְּגִין יִשְׂרָאֵל לְתַתָּא נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, וְיִרְדּוּ בִדְגַת הַיָּם (שם) אִלֵּין תַּלְמִידֵי חֲכָמִים דְּמִתְרַבִּין בְּיַמָּא דְאוֹרַיְיתָא, דְיָרְתִין מִתַּמָּן נֶפֶשׁ חַיָּה, וּבְעוֹף הַשָּׁמַיִם אִלֵּין מָארֵי דְזַכְוָון, דְּבִזְכוּתְהוֹן (דזכותהון) פָּרְחִין לְעִילָא וְיָרְתִין מִתַּמָּן רוּחָא, דְאִיהוּ עוֹף יְעוֹפֵף בְּגַדְפִין דְּפִקּוּדִין דַּעֲשֵׂה, וּבַבְּהֵמָה אִלֵּין עַמֵּי הָאָרֶץ דְּאִתְּמַר בְּהוֹן (במדבר יד ט) אַל תִּירְאוּ אֶת עַם הָאָרֶץ כִּי לַחְמֵנוּ הֵם.</p>\n<p>וְעוֹד נַעֲשֶׂה אָדָם, שְׁכִינְתָּא תַּתָּאָה נְטִילַת עִצָה מִקּוּדְשָׁא בְּרִיךְ הוּא, דְאִתְּמַר בֵּיהּ (ישעיה מד יג) כְּתִפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת, דְּעַמּוּדָא דְאֶמְצָעִיתָא וּשְׁכִינְתָּא עֲלַיְיהוּ אִתְּמַר (בראשית ה ב) זָכָר וּנְקֵבָה בְּרָאָם, וְאִתְקְרִיאוּ אָדָם, וּכְגַוְונָא דִילֵיהּ אָמַר לְתַתָּא בָּאָדָם וְחַוָּה, זָכָר וּנְקֵבָה בְּרָאָם וַיִּקְרָא אֶת שְׁמָם אָדָם, וּכְמָה דְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ אִתְקְרֵי אֶחָד, הָכִי קָרָא לוֹן אֶחָד לְאָדָם וּלְאִתְּתֵיהּ, הֲדָא הוּא דִכְתִיב (ישעיה נא ב) כִּי אֶחָד קְרָאתִיו, דְּתִפְאֶרֶת אִיהוּ א\"ח כְּלִיל תֵּשַׁע סְפִירָן, מַלְכוּת ד' עֲשִׁירִית לֵיהּ, כְּלִילָא מֵעִִשֶׂר דְּאִינוּן יו\"ד ה\"א וא\"ו ה\"א, וְאִיהִי ד' כְּלִילָא מֵאַרְבַּע אַתְוָון דְּאִינוּן יהו\"ה, קוֹצָא דְאָת ד' מוֹרֶה עַל עִִשֶׂר, וְד' עַל אַרְבָּעָה, דְּהָכִי רְשׁוּת הַיָּחִיד רָחְבּוֹ אַרְבָּעָה וְגָבְהוֹ עֲשָׂרָה וְהָא אוּקְמוּהָ.</p>\n<p>וַיִּבְרָא אלהי\"ם אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אלהי\"ם בָּרָא אוֹתוֹ (בראשית ה ב), הָכָא פִקּוּדָא דִּתְּפִלִּין, תָּא חֲזִי כָּל מָאן דְּאַנַּח תְּפִלִּין עַל רֵישֵׁיהּ וְעַל דְּרוֹעִיהּ, קָלָא סָלִיק בְּכָל יוֹמָא לְכָל חֵיוָון מֶרְכָּבוֹת, וְאוֹפַנִּים וּשְׂרָפִים וּמַלְאָכִים דִּמְמַנָּן עַל צְלוֹתִין, הָבוּ יְקָר לְדִיּוֹקְנָא דְמַלְכָּא דְאִיהוּ מָאן דְּאַנַּח תְּפִלִּין, דַּעֲלֵיהּ אִתְּמַר (שם) וַיִּבְרָא אלהי\"ם אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אלהי\"ם בָּרָא אוֹתוֹ.</p>"],[9500011167,"<p>בְּצַלְמוֹ בִּתְּפִלִּין דְּרֵישָׁא, כְּגַוְונָא דִתְּפִלִּין דְּמָארֵי עָלְמָא, דְאִינוּן שְׁכִינְתָּא עִלָּאָה תְּפִלִּין עַל רֵישָׁא (דאיהו) דְעַמּוּדָא דְאֶמְצָעִיתָא, דְאִיהִי כְּלָלָא דִתְלַת סְפִירָן קַדְמָאִין, וְעַמּוּדָא דְאֶמְצָעִיתָא כְּלִיל שִׁית סְפִירָן, וְאִימָּא עִלָּאָה תְּפִלִּין עַל רֵישֵׁיהּ, אִיהוּ תְּפִלִּין דְּאַנַּח קוּדְשָׁא בְּרִיךְ הוּא בְּכָל יוֹמָא, בְּצֶלֶם אלהי\"ם תְּפִלִּין דְּיָד, דָּא שְׁכִינְתָּא תַּתָּאָה דְאִיהִי קְשִׁירָא לֵיהּ, וַעֲלָהּ אִתְּמַר (בראשית מד ל) וְנַפְשׁוֹ קְשׁוּרָה בְנַפְשׁוֹ, תַּרְוַיְהוּ בְּיִחוּדָא חֲדָא בְקִשּׁוּרָא חֲדָא, רְצוּעָה כְּרִיכָא בְאֶצְבָּעָא שְׂמָאלָא דָא קִדּוּשִׁין דִּילָהּ, דְּאִיהִי טַבַּעַת כְּרִיכָא בְּאֶצְבָּעָא דִילָהּ, וּבָהּ אִיהִי קְשִׁירָא עִמֵּיהּ וְאִיהוּ עִמָּהּ, הָא קְדוּשָׁה.</p>\n<p>בְּרָכָה כְּלָלָא דְשֶׁבַע סְפִירָן, וְאִינוּן שֶׁבַע בִּרְכָאָן דְּחָתָן, דְּאִינוּן ז' יוֹם הַשְּׁבִיעִי צַדִּיק, עֲלֵיהּ אִתְּמַר (משלי י ו) וּבְרָכוֹת לְרֹאשׁ צַדִּיק, דְּיָרִית מֵאִימָּא עִלָּאָה, וְאָת י' עַל רֵישֵׁיהּ אִיהוּ חָכְמָה י', בָּהּ אִתְעֲבִיד ז', שֶׁבַע בִּרְכָאָן דְּיָרִית חָתָן וְכַלָּה, וּכְלִילָן בְּצַדִּיק יוֹם הַשְּׁבִיעִי, דְּבֵיהּ מִתְיַחֲדִין חָתָן וְכַלָּה, דְאִיהוּ יאהדונה\"י, וְהָא אוּקְמוּהוּ כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ (ד\"ה א כט יא) וְתַרְגּוּם דַּאֲחִיד בִּשְׁמַיָּא וּבְאַרְעָא, וְאִיהוּ אוֹת בְּרִית, דְּלֵית יִחוּדָא לְחָתָן וְכַלָּה בַּר מִנֵּיהּ.</p>\n<p>וַיְכֻלּוּ הַשָּׁמַיִם וְהָאָרֶץ וְכָל צְבָאָם (בראשית ב א), וַיְכֻלּוּ בַצַּדִּיק אִתְכְּלִילָן כָּל אֵבָרִין וְכָל סְפִירָן, כָּל אֵבָרִין דְּאִינוּן פִּקּוּדִין דַּעֲשֵׂה, דְבֵיהּ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְמֶעֱבַד כָּל פִּקּוּדִין, דְּאִיהוּ כָּ\"ל כְּלִיל כֹּלָּא וְאִיהוּ כֹלָּא וּמִנֵּיהּ תָּלוּי כֹּלָּא, עַמּוּדָא דְאִיהוּ סָבִיל שְׁמַיָּא וְאַרְעָא עֲלֵיהּ, וּבֵיהּ אִתְעֲבִידוּ כְּלָל וּפְרָט וּכְלָל, וּבְגִין דָּא וַיְכֻלּוּ כְּלִיל שְׁמַיָּא וְאַרְעָא, שָׁמַיִם אֵשׁ וּמַיִם וְדָא שְׂמָאלָא וִימִינָא, שָׁמַיִם עַמּוּדָא דְאֶמְצָעִיתָא כְּלִיל תַּרְוַיְיהוּ, הָאָרֶץ שְׁכִינְתָּא תַּתָּאָה, וְכָל צְבָאָם נֶצַח וָהוֹד דְּאִינוּן צְבָא הַשָּׁמַיִם, בְּגִין דְּאִיהוּ כְּלִיל שֶׁבַע סְפִירָן דְּשַׁבַּח דָּוִד בְּהוֹן לְקוּדְשָׁא בְּרִיךְ הוּא הֲדָא הוּא, דִכְתִיב (ד\"ה א כט יא) לְךָ יהו\"ה הַגְּדוּלָה וְהַגְּבוּרָה וְגוֹמֵר, בְּגִין דָּא אִתְקְרֵי יוֹם הַשְּׁבִיעִי כְּלָל שֶׁבַע, וְסָלְקִין לְשַׁבְעִין דְּחֻשְׁבַּן תֵּיבִין דְּקִדּוּשׁ וּוַיְכֻלּוּ.</p>\n<p>וַיְכַל אלהי\"ם בַּיּוֹם הַשְּׁבִיעִי (בראשית ב ב), דָא אִימָּא עִלָּאָה דְאִיהִי אלהי\"ם בָּתַר דְּכָלִיל בֵּיהּ שֶׁבַע סְפִירָן, אִתְקְרִיאוּ עַל שְׁמֵיהּ כֻּלְּהוּ שַׁבָּתוֹת שֶׁבַע שַׁבָּתוֹת, לְבָתַר כְּלִיל בֵּיהּ תְּלַת סְפִירָן עִלָּאִין דְּכָלִיל בְּאִימָּא עִלָּאָה, וְקָרָא לוֹן שְׁבִיעִי שְׁבִיעִי שְׁבִיעִי עַל שְׁמֵיהּ, הֲדָא הוּא דִכְתִיב (שם) וַיְכַל אלהי\"ם בַּיּוֹם הַשְּׁבִיעִי הָא חַד דְּכָלִיל בֵּיהּ, וַיִּשְׁבּוֹת בַּיּוֹם הַשְּׁבִיעִי דָא תִנְיָינָא, וַיְבָרֶךְ אלהי\"ם אֶת יוֹם הַשְּׁבִיעִי הָא תְּלַת לְאִתְכַּלְלָא בְעִִשֶׂר סְפִירָן, דְּלֵית סְפִירָה דְלָא אִתְכְּלִילַת בְּעִִשֶׂר, כָּל חֲדָא בְמֶמְשָׁלָה דִּילָהּ, אֲבָל מֶמְשָׁלָה דְצַדִּיק יוֹם הַשְּׁבִיעִי בֵּיהּ אִתְקְרִיאוּ כָּל סְפִירָן שְׁבִיעִיּוֹת, שַׁבְעִין תֵּיבִין אִינוּן בְּקִדּוּשׁ וּוַיְכֻלּוּ, וְזָכוֹר וְשָׁמוֹר הָא שַׁבְעִין וּתְרֵין כְּחֻשְׁבַּן וַיְכֻלּוּ</p>\n<p>וְשַׁבָּת צָרִיךְ לְתַקְנָא בֵּיהּ פָּתוֹרָא בְּאַרְבַּע רַגְלִין, כְּגַוְונָא דְפָתוֹרָא דִלְעִילָא דְאִתְּמַר בֵּיהּ (יחזקאל מא כב) זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי יהו\"ה, וַעֲלָהּ אִתְּמַר (תהלים כג ה) תַּעֲרוֹךְ לְפָנַי שֻׁלְחָן, פָּתוֹרָא דְקוּדְשָׁא בְּרִיךְ הוּא דָא שְׁכִינְתָּא, אִיהִי מִסִּטְרָא דְצָפוֹן דְּאִיהוּ גְבוּרָה, וּבְגִין דָּא תַּקִּינוּ מָארֵי מַתְנִיתִין שֻׁלְחָן בַּצָּפוֹן, וְנֵר דָּלִיק לִימִינָא כְּגַוְונָא דִלְעִילָא, דְאִתְּמַר בֵּיהּ מְנוֹרָה בַּדָּרוֹם, מִטָּה בְּאֶמְצָעִיתָא מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא.</p>\n<p>תָּא חֲזִי שְׁכִינְתָּא אִתְקְרִיאַת פָּתוֹרָא מִסִּטְרָא דִשְׂמָאלָא, וּמְנַרְתָּא מִסִּטְרָא דִימִינָא, וּמִטָּה מְמוּצַעַת מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, וּבְגִין דָּא זִוּוּגָא דִּילֵיהּ בְּאֶמְצָעִיתָא בֵּין צָפוֹן לַדָּרוֹם, וְהָא אוּקְמוּהָ רַבָּנָן כָּל הַנּוֹתֵן מִטָּתוֹ בֵּין צָפוֹן לְדָרוֹם הַוְיָין לֵיהּ בָּנִים זְכָרִים וכו', פָּתוֹרָא אִיהִי סְמִיכָא עַל אַרְבָּעָה סָמְכִין, דְּאִיהִי כְּגַוְונָא דְגוּפָא דְסָמְכִין לֵיהּ דְּרוֹעִין וְשׁוֹקִין דְּאִינוּן אַרְבַּע, וְצָרִיךְ שִׁית נַהֲמִין מֵהַאי סִטְרָא וְשִׁית נַהֲמִין מֵהַאי סִטְרָא.</p>"],[9500011168,"<p>וְרָזָא דְמִלָּה זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי יהו\"ה (יחזקאל מא כב), זֶ\"ה בְּחֻשְׁבַּן ו' ו', דְּאִינוּן שִׁית פִּרְקִין דִּתְרֵין דְּרוֹעִין וְשִׁית פִּרְקִין דִּתְרֵין שׁוֹקִין, דְּהָא שְׁכִינְתָּא אִתְעֲבִידַת גּוּפָא לְמַלְכָּא בְּכָל תִּקּוּנָא דִילָהּ, וּבְאִלֵּין תְּרֵין עֲשַׂר פִּרְקִין דְּנוּקְבָא, וּתְרֵין עֲשַׂר פִּרְקִין דִּדְכוּרָא, מַלְאָכַיָּא אָמְרֵי וְקָרָא זֶה אֶל זֶה וְאָמַר קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ וְגוֹמֵר, זֶ\"ה עִם קוּדְשָׁא בְּרִיךְ הוּא אֶחָ\"ד, זֶ\"ה עִם שְׁכִינְתָּא אֶחָ\"ד, וְכֹלָּא יהו\"ה אֶחָד, מְיַחֵד תַּרְוַיְיהוּ, וְלָקֳבֵל זֶה אֶל זֶה אָמַר דָּוִד עִִשְׂרִים וְאַרְבַּע רְנָנוֹת, וְאִינוּן לָקֳבֵל עִִשְׂרִין וְאַרְבַּע סִפְרֵי אוֹרַיְיתָא.</p>\n<p>זֶה אִיהוּ לָקֳבֵל אַרְבַּע אַנְפִּין לְכָל חַיָּה לִתְלַת חֵיוָון, זֶה תִּנְיָינָא לָקֳבֵל אַרְבַּע גַּדְפִין לְכָל חֵיוָא לִתְלַת חֵיוָון, וְדָא אִיהוּ רָזָא דְמִלָּה וְאַרְבָּעָה פָנִים לְאֶחָת וְאַרְבָּעָה כְּנָפַיִם לְאַחַת לָהֶם (יחזקאל א ו), דְּכֻלְּהוּ פָרְחִין בְּפָתוֹרָא קֳדָם יהו\"ה בְּכַמָּה רְנָנוֹת, וְצָרִיךְ לְחַבְּרָא לְהַאי פָּתוֹרָא אוֹרַיְיתָא דְאִיהוּ קוּדְשָׁא בְּרִיךְ הוּא, וּבְגִין דָּא אוּקְמוּהוּ מָארֵי מַתְנִיתִין, שְׁנַיִם שֶׁאוֹכְלִין עַל שֻׁלְחָן אֶחָד וכו', וְאִם הוּא חַד אוֹרֵחַ וְחַד בַּעַל הַבַּיִת, בַּעַל הַבַּיִת בּוֹצֵעַ וְאוֹרֵחַ מְבָרֵךְ, בַּעַל הַבַּיִת בּוֹצֵעַ דָּא עַמּוּדָא דְאֶמְצָעִיתָא לְעִילָא, וְאוֹרֵחַ מְבָרֵךְ דָּא צַדִּיק דְּאִתְּמַר בֵּיהּ (משלי ד יח) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ וְגוֹמֵר, וְצַדִּיק אִיהוּ בְּשַׁבָּת כְּאוֹרֵחַ דְּאָתֵי וְאָזִיל בְּכָל שַׁבָּת וְשַׁבָּת.</p>\n<p>שַׁבָּת שְׁכִינְתָּא, בַּעַל הַבַּיִת דִּילָהּ עַמּוּדָא דְאֶמְצָעִיתָא, וְאִיהוּ בוֹצֵעַ וּפָרִיס פְּרוּסָא דְנַהֲמָא דְּאִיהִי טִפָּה, וְיָהִיב לְאוֹרֵחַ דְּאִיהוּ צַדִּיק וְעָנִי, וְאוֹרֵחַ מְבָרֵךְ לְבַעַל הַבַּיִת בַּכֹּל מִכֹּל כֹּל דְּאִינוּן תְּלַת אֲבָהָן, בְּבִרְכָן דְּאִתְבָּרְכוּ אִינוּן, דְּבִרְכָאָן עַל יְדֵי דְצַדִּיק נָחֲתִין לְעַמּוּדָא דְאֶמְצָעִיתָא, הֲדָא הוּא דִכְתִיב (משלי י ו) וּבְרָכוֹת לְרֹאשׁ צַדִּיק, מָאן רֹאשׁ צַדִּיק דָּא עַמּוּדָא דְאֶמְצָעִיתָא, תֵּשַׁע בִּרְכָאָן אִינוּן מֵעִילָא לְתַתָּא מִכֶּתֶר עַד צַדִּיק, וְתֵשַׁע אִינוּן מִתַּתָּא לְעִילָא מִצַּדִּיק עַד כֶּתֶר עִלָּאָה, וְכֻלְּהוּ סָלְקִין חַ\"י, וְכַלָה כְלִילָא מִנַּיְיהוּ.</p>\n<p>תְּפִלָּה לְמֹשֶׁה תְּפִלָּה לְדָוִד, בֵּית הַכְּנֶסֶת אִיהוּ כִּנּוּסְיָא דְכֻלְּהוּ בִרְכָאָן, תְּפִלָּה אִיהִי בְּגִין דְּאִיהוּ סוּס לְקוּדְשָׁא בְּרִיךְ הוּא, וְאִיהִי אִתְעֲבִידַת טְפֵלָה לְרוֹכֵב, הָכִי אוּקְמוּהוּ מָארֵי מַתְנִיתִין אֵין הָרוֹכֵב טָפֵל לַסּוּס אֶלָּא הַסּוּס טְפֵלָה לָרוֹכֵב, אִית טָפֵל בְּט' וְאִית תָּפֵל בְּת', כְּגוֹן הֲיֵאָכֵל תָּפֵל מִבְּלִי מֶלַח (איוב ו ו), וְהַאי תְּפִלָּה הָכִי אִיהִי בְּת'.</p>\n<p>וְאִיהִי כּוֹס דְּיַיִן, דְּאִיהוּ יַיִ\"ן חוּשְׁבַּן סוֹ\"ד מִן יְסוֹד, וְצָרִיךְ בֵּיהּ עֲשָׂרָה דְבָרִים כְּמָה דְאוּקְמוּהוּ מָארֵי מַתְנִיתִין, וְאִינוּן כְּחֻשְׁבַּן י' מִן יְסוֹד, וְאִינוּן עִטּוּר וְעִטּוּף הֲדָחָה וּשְׁטִיפָה חַ\"י וּמָלֵא, מְקַבְּלוֹ בִּתְרֵי יְדוֹי וְנוֹתְנוֹ בְּיָמִין, וְיָהֵיב עִינוֹי בֵּיהּ, וּמְסַלְּקוֹ מִן הַקַּרְקַע טֶפַח, וּמְשַׁגְּרֵיהּ בְּמַתָּנָה לְאַנְשֵׁי בֵיתֵיהּ, עִטּוּר מִסִּטְרָא דַעֲטָרָה דִבְּרִית מִילָה, עִטּוּף עוֹטֶה אוֹר כַּשַּׁלְמָה (תהלים קד ב), וְאִם הוּא עָנִי דְלֵית בֵּיהּ אֶלָּא רְבִיעִית לוֹג דְּאִיהִי שִׁעוּרָא דְאָת ד', אִתְּמַר (שם קב א) תְּפִלָּה לְעָנִי כִי יַעֲטוֹף, הֲדָחָה וּשְׁטִיפָה, הֲדָחָה מִלְּגָאו וּשְׁטִיפָה מִלְּבָר, וְרָזָא דְמִלָּה וְטִהֲרוֹ וְקִדְּשׁוֹ (ויקרא טז יט).</p>\n<p>קָם סָבָא חֲדָא מִבָּתַר טוּלָא דְרַבִּי שִׁמְעוֹן בֶּן יוֹחָאי, וְאָמַר רַבִּי רַבִּי שַׁפִּיר קָאֲמַרְתְּ, אֲבָל הַאי כּוֹס צָרִיךְ לְסַלְקָא לֵיהּ בְּדַרְגּוֹי, עִטּוּר מִסִּטְרָא דַעֲטָרָה דְאִיהִי כֶתֶר עִִלְיוֹן עַל רֵישָׁא דְצַדִּיק, עִטּוּף כְּגוֹן עוֹטֶה אוֹר כַּשַּׂלְמָה, מַאי עוֹטֶה דָא י' דְּאִתְעַטַּף בְּאוֹר וְאִתְעֲבִיד אַוִּיר, וְהַאי דְּאִתְעַטַּף אִיהוּ חָכְמָה, הֲדָחָה וּשְׁטִיפָה דְאִיהוּ וְטִהֲרוֹ וְקִדְּשׁוֹ, טַהֲרָה מִסִּטְרָא דְכַהֲנָא, דְאִתְּמַר בְּכַהֲנָא טָבַל וְעָלָה אִתְדַּכֵּי לְמֵיכַל בִּתְרוּמָה, וְקִדְּשׁוֹ מִסִּטְרָא דִשְׂמָאלָא, הֲדָא הוּא דִכְתִיב וְקִדַּשְׁתָּ אֶת הַלְוִיִּם, חַ\"י מִסִּטְרָא דְצַדִּיק חַ\"י עָלְמִין כְּלִיל חַ\"י בִּרְכָאָן דִּצְלוֹתָא, וּמָלֵא מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, וּמְקַבְּלוֹ בִּשְׁתֵּי יָדָיו וְנוֹתְנוֹ בְּיָמִין, דָּא הַהוּא דְאִתְּמַר בֵּיהּ (דברים לג ב) מִימִינוֹ אֵשׁ דָּת לָמוֹ, כִּי יְמִינְךָ פְּשׁוּטָה לְקַבֵּל שָׁבִים, וְאִיהוּ יְמִינְךָ יהו\"ה</p>"],[9500011169,"<p>נֶאְדָּרִי בַּכֹּחַ (שמות טו ו), תְּרֵין יְדַיִן אִינוּן ה\"ה, חַד שְׂמָאלָא וְחַד יְמִינָא, וּבְגִין דָּא צָרִיךְ לְאִתְיַיהֲבָא בְּחָמֵשׁ אֶצְבְּעָאן, מִשּׁוּם כּוֹס יְשׁוּעוֹת אֶשָּׂא (תהלים קיז יג), וְנוֹתֵן עִינָיו בּוֹ, עֲלַיְיהוּ אִתְּמַר (שם קמה טו) עִינֵי כֹל אֵלֶיךָ יְשַׂבֵּרוּ, וְאִינוּן תְּרֵי סַמְכֵי קְשׁוֹט דְּאִינוּן י' י', דְּאִינוּן בַּת עִינָא יְמִינָא וּבַת עִינָא שְׂמָאלָא, וּבֵינַיְיהוּ ו' זְעִירָא זְעִיר אַנְפִּין, דְּאִיהוּ שׁוֹקָיו עַמּוּדֵי שֵׁשׁ (שיר ה טו).</p>\n<p>וּמְסַלְּקוֹ מִן הַקַּרְקַע טֶפַח מִסִּטְרָא דְי' זְעִירָא חָכְמַת שְׁלֹמֹה, וּמְשַׁגְּרוֹ בְּמַתָּנָה לְאַנְשֵׁי בֵּיתוֹ דָא אִימָּא עִלָּאָה, דְאִתְּמַר בָּהּ יִשְׂמַח מֹשֶׁה בְּמַתְּנַת חֶלְקוֹ, וּבְגָלוּתָא לֵית לָן אֶלָּא אַרְבָּעָה, חַ\"י מָ\"לֵא שְׁ\"טִיפָה הֲ\"דָחָה, וְסִימָנִיךְ חֲמִשָּׁה, וְאִינוּן מִסִּטְרָא דְאָת ה' דְּאִיהִי רְבִיעִית לְחֻשְׁבָּנָא, וְאִיהִי דָלֵ\"ת עֲנִיָּה, בְּגִין דְּאִסְתַּלַּק מִינָהּ ו' דְּאִיהוּ שִׁית דַּרְגִּין, הַכּוֹס אִיהוּ בְּרָזָא דְיאהדונה\"י דְאִיהוּ כ\"ו ה\"ס, כּוֹס בְּחֻשְׁבָּנָא אלהי\"ם.</p>\n<p>בְּרֵאשִׁית תַּמָּן תְּרֵ\"י תַּמָּן שַׁבָּ\"ת, כְּגַוְונָא דָא בְּ' רֵאשִׁי\"ת בָּ\"רָא שִׁי\"ת, וְאִינוּן תְּרֵי שַׁבָּתוֹת, עֲלַיְיהוּ אִתְּמַר (שמות לא טז) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת לַעֲשׂוֹת אֶת הַשַּׁבָּת וְגוֹמֵר, תְּרֵין זִמְנִין אַדְכִּיר הָכָא שַׁבָּת, לָקֳבֵל שְׁכִינְתָּא עִלָּאָה וְתַתָּאָה, לְדֹרֹתָם מַאי לְדֹרֹתָם, אֶלָּא זַכָּאָה אִיהוּ מָאן דְּעָבִיד לוֹן דִּירָה בְּשַׁבָּת בִּתְרֵי בָתֵּי לִבָּא, וְאִתְפְּנֵי מִתַּמָּן יֵצֶר הָרָע דְּאִיהוּ חִלּוּל שַׁבָּת, בְּרִית עוֹלָם דָּא צַדִּיק, דְּשַׁרְיָין תַּרְוַיְיהוּ עֲלֵיהּ, חַד לְאַמְלָאָה לֵיהּ וְחַד לְאִתְמַלְיָא מִינֵיהּ.</p>\n<p>בְּנֵי יִשְׂרָאֵל אִינוּן תְּרֵין כֻּלְיָין נֶצַח וָהוֹד, בְּנוֹי דְּיִשְׂרָאֵל סָבָא עַמּוּדָא דְאֶמְצָעִיתָא, תְּלַת שְׁבִיעִי שְׁבִיעִי שְׁבִיעִי אִלֵּין תְּלַת אֲבָהָן, עֹנֶג שַׁבָּת וְנָ\"הָר יוֹצֵא מֵעִדֶ\"ן לְהַשְׁקוֹת אֶת הַגָּ\"ן (בראשית ב י), וְנָהָר, אִית נָהָר וְאִית נָהָר, אִית נָהָר דְּאִתְקְרֵי נָהָר פְּלָגָיו, וְאִית נָהָר דְּאִתְקְרֵי נַחַל קְדוּמִים, עִדֶן עִלָּאָה עֲלֵיהּ אִתְּמַר (ישעיה סד ג) עַיִן לֹא רָאֲתָה אלהי\"ם זוּלָתֶךָ, הַאי נָהָר אִיהוּ ו', דְּנָפִיק מֵעִדֶן עִלָּאָה דְאִיהוּ א', וְאַעֲבַר בֵּין אַבָּא וְאִימָּא, וְאָזִיל חֲמֵשׁ מֵאוֹת שָׁנָה, וּמָטֵי עַד צַדִּיק שְׁבִיעִי, וּמִתַּמָּן אַשְׁקֵי לְגִנְּתָא דְאִיהִי שְׁכִינְתָּא תַּתָּאָה.</p>\n<p>זַכָּאָה אִיהוּ מָאן דְּנָטִיר דִּירָה לְשַׁבָּת דְּאִיהוּ לִבָּא, דְלָא אִתְקְרִיב תַּמָּן עֲצִיבוּ דִטְחוֹל, וְכַעַס דְּמָרָה דְאִיהוּ נוּרָא דְגֵיהִנָּם, דַּעֲלָהּ אִתְּמַר (שמות לה ג) לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מוֹשְׁבוֹתֵיכֶם בְּיוֹם הַשַּׁבָּת, וְהָכִי הוּא וַדַּאי דְּכָל מָאן דְּכָעִיס כְּאִלּוּ אוֹקִיד נוּרָא דְגֵיהִנָּם, אַרְבָּעִים מְלָאכוֹת חָסֵר חַד אִינוּן לָקֳבֵל אַרְבָּעִים מַלְקִיּוֹת חָסֵר חַד בְּשַׁבָּת, וְאִינוּן עֲשָׂרָה דְלָקָה אָדָם וַעֲשָׂרָה לְחַוָּה וַעֲשָׂרָה לְנָחָשׁ וְתִשְׁעָה לְאַרְעָא, וּבְגִין דָּא אָמְרוּ מָארֵי מַתְנִיתִין אֵין לוֹקִין בְּשַׁבָּת, דְּאִלֵּין מְלָאכוֹת אִינוּן חֲשִׁיבִין לְיִשְׂרָאֵל לָקֳבֵל מַלְקִיּוֹת.</p>\n<p>יְצִיאוֹת הַשַּׁבָּת שְׁתַּיִם. אִינוּן עֲקִירָה וְהַנָּחָה, דְעָבִיד לוֹן בְּבַת אַחַת, מָאן דְּאַעֲקַר חֵפֶץ מֵאַתְרֵיהּ וְאַנַּח לֵיהּ לְבַר מֵאַתְרֵיהּ וּמֵרְשׁוּתֵיהּ, כְּאִלּוּ אַעֲקַר אִילָנָא דְחַיֵּי דְּאִיהוּ אוֹת בְּרִית, וְאַנַּח לֵיהּ בִּרְשׁוּ נוּכְרָאָה, מָאן דְּעָבִיד דָּא גְרִים דְּאַעֲקַר נִשְׁמָתֵיהּ מֵרְשׁוּת דִּילָהּ, וְאַנַּח לָהּ בִּרְשׁוּ אָחֳרָא דְאִיהִי מָרָה וּטְחוֹל, וְדָא גָרַם לְיִשְׂרָאֵל דְּאִתְעַקְרוּ מֵאַרְעָא דְיִשְׂרָאֵל, וְאִתְגַּלִּיאוּ בְּאַרְעָא נוּכְרָאָה דְאִיהִי רְשׁוּת הָרַבִּים, וְהָכִי אִיהוּ מָאן דְּאַעִיל אוֹת בְּרִית קֹדֶשׁ דִּילֵיהּ בִּרְשׁוּ נוּכְרָאָה, שַׁבְּתַא\"י אִיהוּ טְחוֹל חַמָּ\"ה, אִתְּתָא בִּישָׁא מָרָה, שַׁבְּתַא\"י עֲלֵיהּ אִתְּמַר (בראשית לז כד) וְהַבּוֹר רֵק אֵין בּוֹ מָיִם, מַיִם אֵין בּוֹ אֲבָל נְחָשִׁים וְעַקְרַבִּים יֶשׁ בּוֹ, וְאִיהוּ רָעָב וְצִמָּאוֹן וְקִינָה וְהֶסְפֵּד</p>"],[9500011170,"<p>וַחֲשׁוֹכָא וְקִבְלָא, וְאִיהִי גָלוּתָא לְיִשְׂרָאֵל. וּצְרִיכִין יִשְׂרָאֵל לְמֶעֱבַד לָהּ שִׁנּוּי בְּכֹלָּא וְהָא אוּקְמוּהָ, וְאִיהוּ דִבּוּר דְּחוֹל דְּאִיהוּ אָסוּר בְּשַׁבָּת, וְכַד לָא אַשְׁכַּחַת אֲתַר לְשַׁרְיָא תַּמָּן, אִיהִי בָרְחַת, כְּגַוְונָא דְשִׁפְחָה דְאַבְרָהָם דְּאִתְּמַר בָּהּ (בראשית טז ח) מִפְּנֵי שָׂרַי גְּבִרְתִּי אָנֹכִי בֹּרַחַת.</p>\n<p>טְחוֹל עֲלָהּ אִתְּמַר (שמות ג ה) שַׁל נְעָלֶיךָ מֵעַל רַגְלֶיךָ, נַעַל מְטוּנָף דְּטִפָּה סְרוּחָה, כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו אַדְמַת קֹדֶשׁ הוּא, דָא שַׁבָּת, וַעֲלֵיהּ אָמְרַת שְׁכִינְתָּא פָּשַׁטְתִּי אֶת כֻּתָּנְתִּי אֵיכָכָה אֶלְבָּשֶׁנָּה, רָחַצְתִּי אֶת רַגְלַי אֵיכָכָה אֲטַנְּפֵם (שיר ה ג), וּבְגִין דָּא צָרִיךְ בַּר נַשׁ בְּשַׁבָּת לְשַׁנּוּיֵי בִּלְבוּשִׁין בִּשְׁרַגָּא בְּמַאֲכָלִין, וְצָרִיךְ לְמֶהֱוִי מוֹסִיף מֵחוֹל עַל הַקֹּדֶשׁ, וְכָל הַמּוֹסִיף מוֹסִיפִין לֵיהּ נֶפֶשׁ יְתֵירָה בְּשַׁבָּת, וְכָל הַגּוֹרֵעַ גּוֹרְעִין לֵיהּ הַהִיא נֶפֶשׁ יְתֵירָה חַס וְשָׁלוֹם.</p>\n<p>בְּרֵאשִׁית בָּרָא אלהי\"ם. שְׂאוּ מָרוֹם עִינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה (ישעיה מ לו), מִי אֵלֶּה, הוּא אלהי\"ם, מִי בָּרָא לְאֵלֶּה, שְׂ אוּ מָ רוֹם עִ ינֵיכֶם דָּא קְרִיאַת שְׁמַ\"ע, רָאשֵׁי תֵּיבִין שְׁמַע דִּמְיַחֲדִין יִשְׂרָאֵל לְקוּדְשָׁא בְּרִיךְ הוּא פַּעֲמַיִם, וְתִשְׁכְּחוּ תַּמָּן מִ\"י דְּאִיהוּ כְלָלָא דְחַמְשִׁין אַתְוָון, וּבְמַאי צָרִיךְ לְיַחֲדָא לֵיהּ בְּשַׁחֲרִין, בְּהַהוּא דְאִתְּמַר בֵּיהּ (חבקוק ג י) רוֹם יָדֵיהוּ נָשָׂא, דְאִיהוּ מָרוֹם, בְּגִין דְּאִיהוּ מְרוֹמִים יִשְׁכּוֹן. וּרְא\"וּ דְתַמָּן אוֹ\"ר, וְדָא אוֹר הַכֹּכָבִים, דִּבְהוֹן שְׁכִינְתָּא נָפְקַת הֲדָא הוּא דִכְתִיב (ישעיה מ כו) הַמּוֹצִיא בְמִסְפָּר צְבָאָם, וּבְגִין דָּא קְרִיאַת שְׁמַע בְּלֵילְיָא, כְּמָה דְאוּקְמוּהָ מָארֵי מַתְנִיתִין בִּיצִיאַת הַכֹּכָבִים, עִִרֶב וָבֹקֶר צְרִיכִין לְיַחֲדָא לָהּ עִם מַלְכָּא, בְגִין דְּבָעִִרֶב הִיא בָאָה עִמֵּיהּ, וּבַבֹּקֶר הִיא שָׁבָה לְגַבֵּיהּ (אסתר ב יד), וְדָא עִִרֶב דְּיִצְחָק וּבֹקֶר דְּאַבְרָהָם, דְּתַמָּן בַּעִִלָהּ בֵּינַיְיהוּ יִשְׂרָאֵל.</p>\n<p>וְעוֹד הַמּוֹצִיא, דָא הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ, בְּגִינָהּ אִתְּמַר (ישעיה לג טז) לַחְמוֹ נִתָּן וכו', וְעוֹד הַמּוֹצִיא בְמִסְפָּר צְבָאָם, אִלֵּין רְמַ\"ח תֵּיבִין דִּקְרִיאַת שְׁמַע, לְכֻלָּם בְּשֵׁם יִקְרָא, הֲדָא הוּא דִכְתִיב (בראשית ב כ) וַיִּקְרָא הָאָדָם שֵׁמוֹת וְגוֹמֵר, דָּא הַהוּא דְאִתְּמַר בֵּיהּ (ישעיה מד יג) כְּתִפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת, דְּקָרָא שְׁמָהָן לְכָל חַיּוֹת הַקּוֹדֶשׁ וּלְכָל שְׂרָפִים וְאוֹפַנִּים וּצְבָא דִלְעִילָא, לְכָל חַד קָרָא לֵיהּ בְּשֵׁם יְדִיעַ וּבְדַרְגָּא יְדִיעָא, לְאִשְׁתְּמוֹדָע לְכָל חַד מֵאֲתַר דְּאִתְנְטִיל, כְּגַוְּונֵי דְנַחֲלֵי יַמָּא דְאִתְחַזְרוּ לַאֲתַר דְּאִתְנְטִילוּ בִּשְׁלִיחוּתָא, הֲדָא הוּא דִכְתִיב (קהלת א ז) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְגוֹמֵר, אֶל מְקוֹם שֶׁהַנְּחָלִים הוֹלְכִים שָׁם הֵם שָׁבִים לָלָכֶת, מֵאֲתַר דְּאָזְלִין תַּמָּן חָזְרִין בִּשְׁלִיחוּתָא.</p>\n<p>מֵרוֹב אוֹנִים (ישעיה מ כו) דָּא כֶתֶר עִלָּאָה, וְאַמִּיץ כֹּחַ דָּא חָכְמָה, מַאי כֹּחַ דִּילֵיהּ אִימָּא עִלָּאָה, אִישׁ לֹא נֶעִִדָּר אִיהוּ כְלָלָא דִתְלַת סְפִירָן, מַאי אִישׁ יהו\"ה אִישׁ מִלְחָמָה יהו\"ה שְׁמוֹ (שמות טו ג), אִישׁ א' כֶּתֶר עִלָּאָה י' חָכְמָה ש' שָׁרָשָׁא דְאִילָנָא דְאִיהִי אִימָּא עִלָּאָה תְּשׁוּבָה וַדַּאי, וְעוֹד מֵרוֹב אוֹנִים דָּא עַמּוּדָא דְאֶמְצָעִיתָא, אוֹנִים דִּילֵיהּ נֶצַח וָהוֹד, וְאַמִּיץ כֹּחַ דָּא צַדִּיק, אִישׁ לֹא נֶעִִדָּר יהו\"ה אִישׁ מִלְחָמָה, וְהָא אִתְּמַר.</p>\n<p>קָם סָבָא בָתַר טוּלָא דְרַבִּי שִׁמְעוֹן, וְאָמַר רַבִּי רַבִּי, הַאי קְרָא הָכִי שְׁמַעִִנָא לֵיהּ, שְׂאוּ מָרוֹם עִינֵיכֶם, שְׂאוּ כְּמוֹ שְׂאוּ יְדֵיכֶם קֹדֶשׁ (תהלים קלד ב), וְדָא קֹדֶשׁ יִשְׂרָאֵל לַיהו\"ה רֵאשִׁית (ירמיה ב ג), מָרוֹם דִּילֵיהּ כֶּתֶר עִלָּאָה, מִי אִימָּא עִלָּאָה דְבָרָא עָלְמָא בְּאֵלֶּה, מָאן אֵלֶּה, אֵלֶּה רָאשֵׁי בֵית אֲבוֹתָם (שמות ו יד), וְאִינוּן תְּלַת אֲבָהָן, הַמּוֹצִיא בְמִסְפָּר צְבָאָם (ישעיה מ כו) אִלֵּין צְבָא הַשָּׁמַיִם דְּאִינוּן נֶצַח וָהוֹד, מַאי מִסְפָּר דִּלְהוֹן, אֶלָּא מִסְפָּר וְחֶשְׁבּוֹן דְּכֹלָּא דָא שְׁכִינְתָּא עִלָּאָה, לְכֻלָּם בְּשֵׁם יִקְרָא (שם) דָא שְׁכִינְתָּא תַּתָּאָה, דְאִתְּמַר לְמֹשֶׁה בְּגִינָהּ (שמות לג יז) וָאֵדָעֲךָ</p>"],[9500011171,"<p>בְּשֵׁם, מֵרוֹב אוֹנִים (ישעיה מ כו), הַהוּא דְאִתְּמַר בֵּיהּ (בראשית מח טז) וְיִדְגּוּ לָרוֹב בְּקֶרֶב הָאָרֶץ וְדָא צַדִּיק, וְאִיהוּ אַמִּיץ כֹּחַ אִישׁ צַדִּיק, כֹּחַ דִּילֵיהּ אִיהִי כֹּחַ דְּעוֹבָדָא דִבְּרֵאשִׁית, דְּאִתְּמַר בָּהּ (במדבר יד יז) וְעַתָּה יִגְדַּל נָא כֹּחַ אדנ\"י, לֹא נֶעִִדָּר מִשְּׁכִינְתָּא לְעָלַם, וְהַאי וְהַאי כֹּלָּא קְשׁוֹט, שַׁבְעִין אַנְפִּין לְאוֹרַיְיתָא.</p>\n<p>אָמַר לֵיהּ סָבָא סָבָא, מֵרוֹב אוֹנִים וְאַמִּיץ כֹּחַ תַּמָּן אָדָם קַדְמָאָה, תַּמָּן אַבְרָהָם יִצְחָק וְיַעֲקֹב, תַּמָּן מֹשֶׁה וְאַהֲרֹן, תַּמָּן דָּוִד וּשְׁלֹמֹה, וּתְרֵין עֲשַׂר שִׁבְטִין, וְכָל נִשְׁמָתִין דְּשִׁתִּין רִבּוֹא דְיִשְׂרָאֵל, וּדְכָל דָּרִין עִלָּאִין וְתַתָּאִין, דְּאִתְּמַר בְּהוֹן (דברים כט יד) כִּי אֶת אֲשֶׁר יֶשְׁנוֹ פֹּה עִמָּנוּ עוֹמֵד הַיּוֹם וְגוֹמֵר, כֻּלְּהוּ תַּמָּן, אִישׁ לֹא נֶעִִדָּר לֹא חָסֵר מִנַּיְיהוּ חַד מֵחֻשְׁבָּנָא, כְּגַוְונָא דִצְבָא הַשָּׁמַיִם.</p>\n<p>וְעוֹד מֵרוֹב אוֹנִים דָּא כַהֲנָא, דְאִתְּמַר בֵּיהּ כֹּהֵן אוֹן, וְאַמִּיץ כֹּחַ דָּא אלהי\"ם דְּאִיהִי אִימָּא עִלָּאָה, דְאִתְלַבְּשַׁת בִּגְבוּרָה וּבָרָא עָלְמָא בְּמִדַּת הַדִּין, וּבְגִין דָּא אִיהוּ גִבּוֹר אַמִּיץ כֹּחַ, אִישׁ לֹא נֶעִִדָּר דָּא יַעֲקֹב, דְּאִתְּמַר בֵּיהּ (בראשית כה כז) וְיַעֲקֹב אִישׁ תָּם, מַה דְּאִתְּמַר בִּתְלַת אִלֵּין, אִתְּמַר בִּתְלַת עִלָּאִין, וְאִתְּמַר בִּתְלַת תַּתָּאִין, מִסְפָּר דְּכֻלְּהוּ שְׁכִינְתָּא אִיהִי מִסְפַּר הַיָּמִים.</p>\n<p>בְּרֵאשִׁית בָּרָא אלהי\"ם, פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, שְׂאוּ מָרוֹם עִינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה (בראשית כה כז), רָאשֵׁי תֵּיבִין שְׂ אוּ מָ רוֹם עִ ינֵיכֶם שַׁ חֲרִית מִ נְחָה עַ רְבִית, תְּלַת צְלוֹתִין, עֲלַיְיהוּ אִתְּמַר (איוב לג כט) הֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר, בְּגִין דְּאִינוּן מֶרְכָּבָה דִתְלַת אֲבָהָן, וַעֲלַיְיהוּ אִתְּמַר (בראשית ב ד) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, אֵלֶּה פִּסֵּל אֶת הָרִאשׁוֹנִים, אֵלֶּה וַדַּאי פָּסִיל לְקַדְמָאִין דְּאָמְרוּ (שמות לב ד) אֵלֶּה אלהי\"ך יִשְׂרָאֵל, דְּאִנּוּן תּוֹלָדִין דְּתֹהוּ, דְאִתְרְמִיז בְּרָאשֵׁי תֵּיבִין תּ וֹלְדוֹת הַ שָּׁמַיִם וְ הָאָרֶץ תֹּה\"וּ, וְאִינוּן חָמֵשׁ מִינִין דְּאִתְּמַר בְּהוֹן בְּה' בָּרְאָם, וְאִינוּן עֲמָלֵקִים גִּבּוֹרִים נְפִילִים עֲנָקִים רְפָאִים, וּבְגִין דָּא טָרְחַת ה' בְּגִינַיְיהוּ בְּגִין דִּבְה' בְּרָאָם ה' דְאַבְרָהָם, וַעֲלָהּ אִתְּמַר (ישעיה מה יח) לֹא תֹהוּ בְרָאָהּ לְמֵיתַב בֵּינַיְיהוּ, לָשֶׁבֶת יְצָרָהּ לְמֶעֱבַד יִשּׁוּבָא מִנַּיְיהוּ.</p>\n<p>וּבְגִין הַאי ה', אֵלֶּה דְאִינוּן תְּלַת אֲבָהָן תַּקִּינוּ תְלַת צְלוֹתִין, לְנַחְתָא בְּהוֹן לְקוּדְשָׁא בְּרִיךְ הוּא, לְסַלְקָא לִשְׁכִינְתָּא בְּהוֹן דְּאִיהִי ה' זְעִירָא, דְּעַמּוּדָא דְאֶמְצָעִיתָא אִיהוּ גוּפָא, וּתְרֵין דְּרוֹעִין דִּילֵיהּ יְמִינָא וּשְׂמָאלָא, דִּבְהוֹן אֲחִיד בָּהּ, וְעַל גּוּפָא אִסְתַּלְּקַת, וּמָאן סָלִיק לָהּ עַל גּוּפָא מִ\"י אִימָּא עִלָּאָה, מִי בָרָא אֵלֶּה, וְכַד סָלְקַת סָלְקִין עִמָּהּ כָּל צְבָא דִלְעִילָא, הֲדָא הוּא דִכְתִיב (שם מ כו) הַמּוֹצִיא בְמִסְפָּר צְבָאָם, וְכָל יִשְׂרָאֵל דְּאִינוּן שִׁתִּין רִבּוֹא מִתְיַחֲסִין בַּצָּבָא דִלְעִילָא, לְכֻלָּם בְּשֵׁם יִקְרָא, כֻּלְּהוּ אִתְקְרִיאוּ עַל שֵׁם צְבָא דִלְעִילָא, אִישׁ לֹא נֶעִִדָּר מֵחוּשְׁבָּנָא.</p>\n<p>וּשְׁכִינְתָּא בְגָלוּתָא בְזִמְנָא דְאִיהוּ מְרַחֲקָא בַעִִלָהּ מִינָהּ, לְזִמְנִין אִתְפַּרְנֶסֶת עַל יְדֵי שְׁלִיחַ, לְזִמְנִין עַל יְדֵי אֲבָהָן, לְזִמְנִין עַל יְדֵי אִימָּא, לְזִמְנִין עַל יְדֵי אַבָּא, לְזִמְנִין עַל יְדֵי בְּנִין, לְזִמְנִין עַל יְדֵי דְצַדִּיק, וְכֹלָּא יָהֵיב בַּעִִלָהּ דְּאִיהוּ ו', אִיהוּ בֵּין אַבָּא וְאִימָּא בֶּן י\"ה, וְכַד אִיהוּ בֵּין אַבָּא וְאִימָּא, נָחִית לָהּ פַּרְנָסָהָא עַל יְדֵי אַבָּא וְאִימָּא, וְכַד נָחִית בֵּין תְּרֵין דְּרוֹעִין דְּאִית בְּהוֹן שִׁית פִּרְקִין, נָחִית לָהּ פַּרְנָסָה בִּתְרֵין דְּרוֹעִין, וְכַד נָחִית בְּגוּפָא דְאִיהוּ יַעֲקֹב, נָחִית לָהּ מְזוֹנָא עַל יְדֵיהּ, וְכַד נָחִית בִּתְרֵין שׁוֹקִין דְּאִינוּן (שיר ה טו) שׁוֹקָיו עַמּוּדֵי שֵׁשׁ דְּאִית בְּהוֹן ו' פִּרְקִין, נָחִית לָהּ מְזוֹנָא עַל יְדַיְהוּ, וְכַד נָחִית בְּצַדִּיק נָחִית לָהּ מְזוֹנָא עַל יְדֵיהּ, וְכַד נָחִית בָּהּ</p>"],[9500011172,"<p>דְּאִתְחַבַּר ו' בְּה', לָא צָרִיךְ לְנַחְתָא מְזוֹנָא לָהּ עַל יְדֵי שְׁלִיחָא בְעָלְמָא, אֶלָּא עַל יְדֵיהּ, וְכַד נָפִיק בָּהּ, אִסְתַּלַּק עַד אֵין סוֹף דְּאִיהוּ א', מְזוֹנָא דִילָהּ לַאו בִּזְכוּתָא תַלְיָא מִלְתָא, וְלָא בְחַיִּים דְּאִינוּן אַבָּא וְאִימָּא, וְלָא בְּבָנֵי דְאִינּוּן נֶצַח וְהוֹד, אֶלָּא בְמַזָּלָא תַלְיָא מִלְתָא, וְכַד נְחִיתַת מֵאַתְרָהָא וְנָחִית קוּדְשָׁא בְּרִיךְ הוּא לְדַיְירָא עִמָּהּ, אִתְּמַר בֵּיהּ וּבִבְנָהָא אֵין מַזָּל לְיִשְׂרָאֵל, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא רָכִיב עַל כְּרוּ\"ב דְּאִיהוּ מטטרו\"ן וְאִיהוּ בָּרוּ\"ךְ, וּמִתְפַּרְנֶסֶת עַל יְדֵיהּ, דְּאִיהוּ עִִבֶד עוֹלָם עִִבֶד דִּילָהּ, וּבְהַהוּא זִמְנָא אִיהִי אִתְפַּרְנֶסָת עַל יְדֵי שָׁלִיחַ, וְכָל דָּא כְּפוּם עוֹבָדֵיהוֹן דְּיִשְׂרָאֵל הָכִי אִתְפַּרְנֶסָת.</p>\n<p>זַכָּאָה אִיהוּ מָאן דְּסָלִיק לָהּ לְאַתְרָהּ, וּלְקוּדְשָׁא בְּרִיךְ הוּא לְאַתְרֵיהּ, דְּאִתְּמַר בֵּיהּ (ישעיה יט א) (הנה יהו\"ה רוכב על עב קל), הִנֵּה יהו\"ה יוֹצֵא מִמְּקוֹמוֹ (שם כו כא), אָמַר לֵיהּ רַבִּי אֶלְעָזָר אַבָּא, וְכִי יָכוֹל בַּר נַשׁ לְאַחְזָרָא לְקוּדְשָׁא בְּרִיךְ הוּא לְאַתְרֵיהּ, אָמַר לֵיהּ אִין, כְּמָה דְאַשְׁכַּחְנָא בְּדָוִד דְּאָמַר (תהלים קלב ד) אִם אֶתֵּן שְׁנָת לְעִינָי לְעַפְעַפַּי תְּנוּמָה עַד אֶמְצָא מָקוֹם לַיהו\"ה כו', בְּהַהוּא זִמְנָא דְבַר נַשׁ אַחְזַר לֵיהּ לְאַתְרֵיהּ, מַה כְּתִיב בֵּיהּ מִמְּקוֹמוֹ יִפֶן בְּרַחֲמָיו לְעַמּוֹ, וּבְמַאי חָזְרִין לֵיהּ לְאַתְרֵיהּ, אֶלָּא בִשְׁלִימוּ דְתִקּוּנָא דְתַקִּינוּ בִצְלוֹתָא, וְאוֹכַח דְּבָתַר דְּאָמַר מִמְּקוֹמוֹ יִפֶן בְּרַחֲמָיו לְעַמּוֹ, אָמַר הַמְיַחֲדִים אֶת שְׁמוֹ עִִרֶב וָבֹקֶר תָּמִיד בְּכָל יוֹם אוֹמְרִים פַּעֲמַיִם, וְאִינוּן ה\"ה, דְּצָרִיךְ לְאַחְזָרָא י' לְגַבֵּי ה' דְּאִיהוּ מָקוֹם דִּלְעִילָא, וּלְאַחְזָרָא ו' לְגַבֵּי ה' דְּאִיהִי מָקוֹם דִּלְתַתָּא, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא אוֹמֵי דְלָא יַחֲזִיר לְה' דִּלְעִילָא, עַד דְּיַחֲזִיר לְה' דִּלְתַתָּא, וְרָזָא דְמִלָּה לֹא אָבֹא בְּעִיר וְגוֹמֵר (הושע יא ט) וְהָא אוּקְמוּהָ.</p>\n<p>בְּרֵאשִׁית בָּרָא אלהי\"ם אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, מַאי אֶת, אֶלָּא הָכִי אוּקְמוּהָ קַדְמָאִין, כָּל אֶתִין לְרִבּוּיָא, וְדָא אֶ\"ת אוֹרַיְיתָא כְלִילָא מֵא' וְעַד ת', דְּבָהּ אִתְבְּרִיאוּ שְׁמַיָּא וְאַרְעָא, וְעוֹד אֶת הַשָּׁמַיִם, שָׁמַיִם דָּא קוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב (מלכים א ח׳:ל״ב) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם, וְאֶת בַּת זוּגֵיהּ עִמֵּיהּ, וְאֶת דָּא צַדִּיק וּבַת זוּגֵיהּ, הָאָרֶץ מָאנָא דְכֻלְּהוּ לְאַפָּקָא בָּהּ זַרְעִין וְאִבִּין, וְרָזָא דְמִלָּה וְכָל שִׂיחַ הַשָּׂדֶה טֶרֶם יִהְיֶה בָאָרֶץ וְגוֹמֵר (בראשית ב ה).</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן בְּרִי, רָזָא עִלָּאָה הָכָא, אַף עַל גַּב דְּכֹלָּא אִתְבְּרִי וְאִתַּקַּן בִּשְׁמָא דְיהו\"ה, דְּאִינוּן אֶת הַשָּׁמַיִם, וְרָזָא דְמִלָּה י\"ה בַּשָּׁמַיִם, ו\"ה בָּאָרֶץ, הֲדָא הוּא דִכְתִיב (תהלים צו יא) יִ'שְׂמְחוּ הַ'שָּׁמַיִם וְ'תָגֵל הָ'אָרֶץ, עִם כָּל דָּא דְכֹלָּא אִתַּקַּן בְּד' אַתְוָון, לָא נָחִית נְבִיעוּ מִלְּעִילָא עַל זַרְעִין וְאִיבִּין דְּאִינוּן שִׂיחַ הַשָּׂדֶה דְאִיהוּ צַדִּיק, וְעִשֶׂב הַשָּׂדֶה דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, וְלָמָּה בְּגִין דְּאָדָם אַיִן, דְּאִיהוּ יו\"ד ה\"א וא\"ו ה\"א לַעֲבוֹד אֶת הָאֲדָמָה.</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר אַבָּא, שִׂיחַ מְנָא לָן דְּאִיהוּ צַדִּיק, אָמַר לֵיהּ בְּרִי בֵּיהּ תִּשְׁכַּח חַ\"י ש', אִיהוּ כְּלִיל תְּלַת עִִדְרֵי צֹאן, דְּאִינוּן שָׁרָשָׁא דְאִילָנָא, וְדָא חַי עָלְמִין, דְּאִיהוּ אוֹת בַּצָּבָא דִילֵיהּ, צבאו\"ת אִיהוּ עִמְּהוֹן, כְּלִיל תְּלַת דַּרְגִּין לָקֳבֵל תְּלַת עַנְפִין דְּש'.</p>\n<p>וְהָא ש' דִּתְלַת אֲבָהָן אִינוּן, אֶלָּא ש' עִלָּאָה עַנְפֵי אִילָנָא, ש' תַּתָּאָה שָׁרְשֵׁי אִילָנָא, וּבְגִין דָּא וְכָל שִׂיחַ דָּא צַדִּיק, וְכָל עִשֶׂב ע\"ב ש' דָּא יַעֲקֹב כְּלִיל תְּלַת אֲבָהָן, דְּאִינוּן עַנְפֵי אִילָנָא, וְסָלְקִין לְשַׁבְעִין וּתְרֵין שְׁמָהָן דְּוַיִּסַע וַיָּבֹא וַיֵּט, דִּבְהַאי שְׁמָא אִתְבְּרִיאוּ עִשְׂבִּין וְאִילָנִין דְּאִינוּן נִשְׁמָתִין דְּצַדִּיקַיָּא, וְהַאי עִשֶׂב עֲלֵיהּ אִתְּמַר (תהלים קד יד) וְעִשֶׂב לַעֲבוֹדַת הָאָדָם לְהוֹצִיא לֶחֶם מִן הָאָרֶץ, לֶחֶם אַבִּירִים אָכַל אִישׁ (שם עח כו), וְאִיהוּ נַהֲמָא דְאוֹרַיְיתָא.</p>"],[9500011173,"<p>דְאִתְּמַר בֵּיהּ (קהלת ט ז) לֵךְ אֱכוֹל בְּשִׂמְחָה לַחְמֶךָ, וְאִיהוּ לַעֲבוֹדַת הָאָדָם, ה' דְּאָדָם דְּאִתְּמַר בָּהּ הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ, מַאי לַעֲבוֹדַת הָאָדָם, לֵית עֲבוֹדָה הָכָא אֶלָּא צְלוֹתָא, דְּאִיהִי פּוּלְחָנָא דִשְׁכִינְתָּא, עֲבוֹדַת יהו\"ה וַדַּאי, וַעֲלָהּ אִתְּמַר (תהלים קד כג) יֵצֵא אָדָם לְפָעֳלוֹ וְלַעֲבוֹדָתוֹ עֲדֵי עָרֶב, יֵצֵא אָדָם לְפָעֳלוֹ דָּא צְלוֹתָא דְשַׁחֲרִית, וְלַעֲבוֹדָתוֹ עֲדֵי עָרֶב דָּא צְלוֹתָא דְמִנְחָה, דְאִתְּמַר בָּהּ (בראשית כד סג) וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׁדֶה לִפְנוֹת עָרֶב.</p>\n<p>בְּרֵאשִׁית בָּרָא אלהי\"ם אלהי\"ם. חָמֵשׁ אַתְוָון כְּחוּשְׁבַּן ה', א\"ד מִן אדנ\"י הָכִי סְלִיק לְחָמֵשׁ, וְרָזָא דְמִלָּה וְאֵד יַעֲלֶה מִן הָאָרֶץ וְהִשְׁקָה אֶת כָּל פְּנֵי הָאֲדָמָה (בראשית ב ו), תָּא חֲזִי אִתְעָרוּתָא צְרִיכָא מִתַּתָּא לְעִילָא, וּלְבָתַר וְהִשְׁקָה אֶת כָּל פְּנֵי הָאֲדָמָה, וְהִשְׁקָה ו' אִיהוּ שַׁקְיוּ מֵעִילָא לְתַתָּא, דְאִיהוּ נַחַל קְדוּמִים דְּאִתְמַשַּׁךְ מִן מוֹחָא, וְהָכִי צָרִיךְ לְאַתְעָרָא אִתְעָרוּתָא בְקַדְמֵיתָא מֵאִתְּתָא, וְרָזָא דְמִלָּה אִשָּׁה כִּי תַזְרִיעַ (ויקרא יב ב) וּמִיָּד וְיָלְדָה זָכָר, נוּקְבָא אדנ\"י, דְּכַר יהו\"ה, כַּד אַקְדִּימַת בְּרַתָּא שַׁלִּיט דְּכוּרָא וְאִתְעֲבִיד יאהדונה\"י, וְרָזָא דְמִלָּה יְהִוִֹ\"ה אדנ\"י חֵילִי (חבקוק ג יט), וְעַל בָּמוֹתַי יַדְרִיכֵנִי (שם) אִלֵּין אֲבָהָן, לַמְנַצֵּחַ בִּנְגִינוֹתָי (שם) אַמָּה וּתְרֵין שׁוֹקִין, מַאי חֵילִי תּוּקְפָא דְכֹלָּא מִלְּעִילָא, חֵילִי חֵיל י' וְדָא אַבָּא, תּוּקְפָא דִילֵיהּ נְבִיעוּ דְלֵית לֵיהּ סוֹף.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר אַבָּא וְהָא אוּקְמוּהוּ מָארֵי מַתְנִיתִין, דְּעַד אַרְבְּעִין יוֹמִין יָכִיל לְאַחֲזָרָא נוּקְבָא דְכוּרָא, וְאִתְהַפַּךְ מִדִּינָא לְרַחֲמֵי, וְאוּקְמוּהוּ בְּגִין דְּעַד כְּעַן לֵית תַּמָּן דִּיּוֹקְנָא, דְאִתְּמַר בֵּיהּ (בראשית ב ז) וַיִּיצֶר יהו\"ה אלהי\"ם, אִם כֵּן אַמַּאי נָטִיל שִׁעוּרָא בְּמ', בְּגִין דְּאִיהִי שִׁעוּרָא דִנְקוּדָה דְאִיהִי י' טִפָּה, (שעורא) דְּבָהּ אִתְעֲבִיד יָ\"ם מִ\"י, וַדַּאי נַחַל קְדוּמִים דָּא ו' דְּאִתְמַשַּׁךְ מִן י' (ס\"א ים), וְהִשְׁקָה אֶת כָּל פְּנֵי הָאֲדָמָה, מַאי פְּנֵי הָאֲדָמָה, אֶלָּא אִלֵּין אַנְפִּין דְּאִינוּן סוּמָק וְחִוָּור וְיָרוֹק וְאוּכָּם, בְּאִלֵּין גַּוָּונִין נְהִירָא הַהִיא מַבּוּעָא, דְּגַוָּונִין אִינוּן מֵהַאי יַבָּשָׁה, נְבִיעוּ נְהוֹרָא דִילָהּ (ס\"א דחילא), דְּהָכִי אִיהוּ נְבִיעוּ לְאַרְעָא כְּנִשְׁמָתָא לְגוּפָא, כְּמָה דְאִילָנָא לָא מִתְרַבֵּי אֶלָּא בְמַיָּא, הָכִי יִשְׂרָאֵל דְּאִינוּן עַנְפִין דְּאִילָנָא לָא מִתְרַבִּין אֶלָּא בִנְבִיעוּ דְאוֹרַיְיתָא.</p>\n<p>וְרָזָא דְמִלָּה מַעִִיַן גַּנִּים בְּאֵר מַיִם חַיִּים וְנוֹזְלִים מִן לְבָנוֹן (שיר ד טו), מַעִִיַן דָּא חָכְמָה כֶּתֶר אִיהוּ אָמוֹן מוּפְלָא, דְבָעָא לְנַטְעָא אִילָנִין בְּגִנְּתָא, אִסְתַּכַּל בְּכָל גִּנְתָא וְלָא אַשְׁכַּח תַּמָּן מַבּוּעָא דְמַיָּא, מֶה עָבַד, אָמַר אַפִּיק מַעִִיָן, וּלְבָתַר אֶטַּע גַּן, וְאִתְרַבֵּי אִילָנָא, וּבְגִין דָּא מַעִִיַן גַּנִּים, בְּקַדְמֵיתָא אַדְכִּיר מַעִִיַן וּלְבָתַר גַּנִּים, וְדָּא גַ\"ן סְדָרִים דְּאוֹרַיְיתָא, וּכְמָה דְאִית גַּן לְתַתָּא הָכִי אִית גַּ\"ן לְעִילָא, וְהַאי מַעִִיָן אִיהוּ בְּמוֹחָא, אִילָנָא גוּפָא, עַנְפִין דִּילֵיהּ דְּרוֹעִין וְרַגְלִין, וְנוֹזְלִים מִן לְבָנוֹן דָּא לִבָא (נ\"א לבנ\"ה) דְאִיהִי דָלֵ\"ת דַּלָּה בְּגָלוּתָא, וַעֲלָהּ אִתְּמַר (במדבר כד ז) יִזַּל מַיִם מִדָּלְיָו.</p>\n<p>וַי לוֹן לִבְנֵי נָשָׁא דְלָא מִשְׁתַּדְלִין בְּאוֹרַיְיתָא, דְאִתְקְרִיאוּ עִצִים יְבֵשִׁים דְּאִינוּן עֲתִידִין לְאִתּוֹקְדָא בְּנוּרָא דְגֵיהִנָּם, וְלַאו לְמַגָּנָא אָמְרוּ מָארֵי מַתְנִיתִין דְּאִינוּן עֲמֵלִין וְיָרְתִין גֵּיהִנָּם, וְאַף עַל גַּב דְּמִתְרַבֵּי אִילָנָא דְאִיהוּ גוּפָא דְאוֹרַיְיתָא, וְלֵית לֵיהּ אִיבָּא דְאִינוּן פִּקּוּדִין דַּעֲשֵׂה, מַה כְּתִיב בֵּיהּ (דברים פ כ) רַק עִץ אֲשֶׁר תֵּדַע כִּי לֹא עִץ מַאֲכָל הוּא אוֹתוֹ תַשְׁחִית וְכָרָתָּ, וּבְגִין דָּא אָמְרוּ מָארֵי מַתְנִיתִין דְּלֵית מֶדְרָשָׁא עִקָּר אֶלָּא הַמַּעֲשֶׂה אִיהוּ עִקָּר.</p>"],[9500011174,"<p>בְּרֵאשִׁית בָּרָא אלהי\"ם תַּמָּן בַּ\"ת, תַּמָּן אֵ\"ם דְּהוּא אֵ\"ם מֵאלהי\"ם, וְאִינוּן גַּן עִלָּאָה גַן תַּתָּאָה. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר (בראשית ב ל), וַיִּטַּע יהו\"ה אלהי\"ם גַּן בְּעִדֶן מִקֶּדֶם וַיָּשֶׂם שָׁם אֶת הָאָדָם אֲשֶׁר יָצָר, וַיִּטַּע יהו\"ה אלהי\"ם גַּן דָּא שְׁכִינְתָּא, בְּעִדֶן דָּא אִימָּא עִלָּאָה, מִקֶּדֶם אַבָּא עִלָּאָה, וַיָּשֶׂם שָׁם אֶת הָאָדָם אֲשֶׁר יָצָר דָּא עַמּוּדָא דְאֶמְצָעִיתָא, וַעֲלֵיהּ אִתְּמַר (שם ב ז) וַיִּיצֶר יהו\"ה אֱלֹהִי\"ם אֶת הָאָדָם עָפָר מִן הָאֲדָמָה וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים וְגוֹמֵר, וַיִּיצֶר צִיֵּיר לֵיהּ בִּתְרֵין עָלְמִין בְּעָלְמָא דֵין וּבְעָלְמָא דְאָתֵי, וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים דָּא נִשְׁמַת כָּל חַי, וַיְהִי הָאָדָם דָּא רוּחָא דְחַיֵּי, לְנֶפֶשׁ חַיָּה דָּא שְׁכִינְתָּא תַּתָּאָה.</p>\n<p>וְעוֹד וַיִּטַּע יהו\"ה אלהי\"ם גַּן דָּא אוֹרַיְיתָא דְבִכְתָב, עִדֶן דָּא עִדּוּנָא דְאוֹרַיְיתָא, וְשַׁוִּי תַמָּן אֶת הָאָדָם דִּבְּרִיאָה, וּמַה כְּתִיב בֵּיהּ (ישעיה יז יא) בְּיוֹם נִטְעִךְ תְּשַׂגְשֵׂגִי. וַיַּצְמַח יהו\"ה אלהי\"ם וכו' (בראשית ב ט), יהו\"ה אלהי\"ם אַבָּא וְאִימָּא, כָּל עִץ נֶחְמָד לְמַרְאֶה (שם) דָא עַמּוּדָא דְאֶמְצָעִיתָא, דְכָל גַּוָּונִין שַׁפִּירִין בֵּיהּ אִתְחַזְיָין, וּבְגִין דָּא נֶחְמָד לְמַרְאֶה, תִּפְאֶרֶת שַׁפִּירוּ דְכָל גַּוָּונִין, וְטוֹב לְמַאֲכָל דָּא צַדִּיק.</p>\n<p>אָמַר לֵיהּ רַבִּי יְהוּדָה, וְהָא כָּל עִץ כְּתִיב, אִי הֲוָה אָמַר עִץ שַׁפִּיר, אֲבָל כָּל עִץ כְּתִיב, אָמַר לֵיהּ וַדַּאי הָכִי הוּא, דִבְכָל אֲתַר. כָּ\"ל צַדִּיק אִיהוּ, אֲבָל כֹּלָּא חַד, כָּל דָּא צַדִּיק, עִץ דָּא עַמּוּדָא דְאֶמְצָעִיתָא, דְּגוּף וּבְרִית חַשְׁבֵינָן חַד, אֲבָל בְּהַאי קְרָא כָּל עִץ נֶחְמָד לְמַרְאֶה וְטוֹב לְמַאֲכָל דָּא צַדִּיק, לְמַרְאֶה דָא שְׁכִינְתָּא דְאִתְּמַר בָּהּ (במדבר יב ו) בַּמַּרְאָה אֵלָיו אֶתְוַדָּע, וְעִץ הַחַיִּים דָּא עַמּוּדָא דְאֶמְצָעִיתָא, דְאִיהוּ עִץ הַחַיִּים דִּלְעִילָא דְאִתְּמַר בָּהּ (קהלת ז יב) הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ.</p>\n<p>אָמַר לֵיהּ הָא שְׁכִינְתָּא תַּתָּאָה אִיהִי גַן, דְּמִתַּמָּן עִץ הַחַיִּים נָטוּעַ, כְּמָה דְאִתְּמַר (בראשית ב ט) וְעִץ הַחַיִּים בְּתוֹךְ הַגָּן, מַאי מִן הָאֲדָמָה, אֶלָּא דָא שְׁכִינְתָּא עִלָּאָה, דְמִינָהּ אִתְנַטַּע כָּל עִץ דְּאִיהוּ צַדִּיק, כָּ\"ל אִיהוּ מִסִּטְרָא דְמִ\"י, דְהָכִי סְלִיק לְחֻשְׁבַּן כָּ\"ל מִ\"י, וּבְגִינָהּ אִתְּמַר (איוב לח כט) מִבֶּטֶן מִי יָצָא הַקָּרַח וְגוֹמֵר, דְּאִיהוּ הַקֶּרַח הַנּוֹרָא.</p>\n<p>וְעִץ הַדַּעַת טוֹב וָרָע אִיהוּ לְתַתָּא, עִץ הַדַּעַת טוֹב דָּא מטטרו\"ן, וָרָע דָּא סמא\"ל וּבְגִין דָּא וְעִץ הַדַּעַת ו' אָתָא לְרִבּוּיָיא, דְאִיהוּ אָתֵי מֵאֲתַר אָחֳרָא, עִץ הַדַּעַת טוֹב וָרָע, וְעוֹד וַיַּצְמַח יהו\"ה אלהי\"ם מִן הָאֲדָמָה כָּל עִץ, דָּא אִיהוּ צֶמַח צַדִּיק (ירמיה כג ה) וּמִתַּחְתָּיו יִצְמָח (זכריה ו יב), תָּא חֲזִי כָּל מָאן דְּנָטִיר בְּרִית, הַהוּא בַר דְּיָהֵיב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, עֲלֵיהּ אִתְּמַר (בראשית ב ט) וַיַּצְמַח יהו\"ה אלהי\"ם כָּל עִץ נֶחְמָד לְמַרְאֶה בְּרָזִין דְּאוֹרַיְיתָא, וְטוֹב לְמַאֲכָל בְּפִקּוּדִין דְּאוֹרַיְיתָא, אֲבָל בְּרָא אָחֳרָא דְלָא אִתְעֲבִיד בִּדְחִילוּ וּרְחִימוּ דְקוּדְשָׁא בְּרִיךְ הוּא, מַה כְּתִיב בֵּיהּ (שם) וְעִץ הַדַּעַת טוֹב וָרָע, וְדָא עִרְבוּבְיָא דְטוֹב וָרָע, מְעוּרָב מִמַּצָּה וּשְׂאוֹר.</p>\n<p>וּבְגִין דָּא מַנִּי קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל לְנַטְרָא גַרְמֵיהּ בְּפִרְיָה וְרִבְיָה, הָדָא הוּא דִכְתִיב (שם יז) וּמֵעִץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ, טוֹב מִסִּטְרָא דְדַם טָהוֹר, וָרָע מִסִּטְרָא דְדַם נִדּוֹת, דְּהָאי בַּר גָּרים אִבּוּדָא דִתְרֵין עָלְמִין, הֲדָא הוּא דִכְתִיב (שם) כִּי בְּיוֹם אֲכָלְךָ מִמֶּנּוּ מוֹת תָּמוּת, מוֹת בְּעָלְמָא דֵין, תָּמוּת בְּעָלְמָא דְאָתֵי.</p>\n<p>בְּרֵאשִׁית בָּרָא אלהי\"ם, אֶת הַשָּׁמַיִם עִץ הַחַיִּים, וְאֶת הָאָרֶץ כָּל עִץ נֶחְמָד לְמַרְאֶה, וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ דָּא עִץ הַדַּעַת טוֹב וָרָע, וְדָא רָזָא תֹהוּ עֹמֶק רָע, בֹּהוּ עֹמֶק טוֹב, וְדָא עִץ הַדַּעַת טוֹב וָרָע, כִּי שָׁם בָּלַל יהו\"ה שְׂפַת כָּל הָאָרֶץ (שם יא ט), וּמֵהָכָא נָפַק כָּל עִרְבוּבְיָא דְטוֹב וָרָע, דְּאִיהוּ רָזָא דְצַדִּיק וְרַע לוֹ רָשָׁע וְטוֹב לוֹ.</p>"],[9500011175,"<p>בְּרֵאשִׁית בָּרָא בַּיִ\"ת רֹא\"שׁ, וְאִינוּן אַבָּא וְאִימָּא, בָּרָא תַּרְגּוּם בְּרָא. אִיהִי עַמּוּדָא דְאֶמְצָעִיתָא, וַעֲלֵיהּ אִתְּמַר (בראשית ב י) וְנָהָר יוֹצֵא מֵעִדֶן, אִית עִדֶן וְאִית עִדֶן, הֲדָא הוּא דִכְתִיב (תהלים לו ט) וְנַחַל עֲדָנֶיךָ תַשְׁקֵם, עֲדָנֶיךָ וַדַּאי, דָּא עִדֶן עִלָּאָה כֶּתֶר עִלָּאָה, עִדֶן דִּלְתַתָּא דָא י', וְאִית עִדֶן דִּלְתַתָּא וְדָא אִימָּא עִלָּאָה דְאִיהִי ד', אִיהִי עִדֶן לְגַבֵּי נָהָר דִּלְתַתָּא מִינָהּ, הֲדָא הוּא דִכְתִיב וְנָהָר יוֹצֵא מֵעִדֶן לְהַשְׁקוֹת אֶת הַגָּן.</p>\n<p>תָּא חֲזִי כַּמָּה נְהָרוֹת אִינוּן מְשַׁנְּיָין דָּא מִן דָּא, אִית נָהָר וְאִית נָהָר, אִית נָהָר מִנְּהוֹרָא דִלְעִילָא דְאִתְקְרֵי נַהֲרָא דְמַיָּא דְאוֹרַיְיתָא, דְאִתְּמַר בָּהּ (משלי יג יד) תּוֹרַת חָכָם מְקוֹר חַיִּים, וְאִית נָהָר דְּאִתְקְרֵי נָהָר פְּלָגָיו, דְּכַמָּה פַּלְגִין עֲמִיקִין תַּלְיָין מִנֵּיהּ, דְּאִתְּמַר בְּהוֹן (שם כא א) פַּלְגֵי מַיִם לֶב מֶלֶךְ וְגוֹמֵר, וְאִית נָהָר דְּאִתְקְרֵי נַחַל קְדוּמִים, דְּאִתְמַשַּׁךְ מֵעִלָּאִין, וּמִנֵּיהּ תַּלְיָין שִׁבְעָה נְהָרוֹת, דְּאִתְּמַר בְּהוֹן (תהלים צח ח) נְהָרוֹת יִמְחֲאוּ כָף יַחַד הָרִים יְרַנֵּנוּ, וְאִית נָהָר דְּאִתְקְרֵי נְהַר דִּינוּר מִסִּטְרָא דִשְׂמָאלָא, דְאִתְּמַר בֵּיהּ (דניאל ז י) נְהַר דִּינוּר נָגֵיד וְנָפֵיק מִן וְגוֹמֵר, וְנָהָר בְּכָל אֲתַר אִיהוּ ו', מִסִּטְרָא דְאַבָּא וְאִימָּא אִתְקְרֵי נַחַל קְדוּמִים, וּמִסִּטְרָא דְעִדֶן עִלָּאָה אִתְּמַר בֵּיהּ (תהלים לו ט) וְנַחַל עֲדָנֶיךָ תַשְׁקֵם.</p>\n<p>וּמִסִּטְרָא דִימִינָא אִתְקְרֵי נָהָר פְּלָגָיו, וּמִסִּטְרָא דִשְׂמָאלָא אִתְקְרֵי נְהַר דִּינוּר, וּמִנֵּיהּ תַּלְיָין שִׁתִּין עַנְפִין דְּנוּרָא דְאִתְקְרִיאוּ שִׁשִּׁים גִּבּוֹרִים, וְאִינוּן שִׁתִּין פּוּלְסִין דְּנוּרָא דְמַחְיוּהָ לְמטטרו\"ן, וּמִסִּטְרָא דִימִינָא וּשְׂמָאלָא אִתְּמַר בְּכָל נְחָלִין דְּתַלְיָין מִנַּיְיהוּ, נַהֲרֵי נַחֲלֵי דְּבַשׁ וְחֶמְאָה, וְנַחַל עֲדָנֶיךָ דָּא נָהָר דְּנָפִיק מֵעִדֶן, דְּאִתְּמַר בֵּיהּ (בראשית ב י) וְנָהָר יוֹצֵא מֵעִדֶן, וְהַאי אִיהוּ עִדֶן דְּעַיִן לֹא רָאָתָה אלהי\"ם וכו' (ישעיה סד ג), סָתִים וְגָנִיז, דְּאִיהוּ כֶתֶר עִלָּאָה, וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים (א דאיהו ד' אתוון דשם בן ד'), אִלֵּין יהו\"ה דְּאִינוּן אַבָּא וְאִימָּא בְרָא וּבְרַתָּא. תָּא חֲזִי קַרְקַפְתָּא דָא אל\"ף, כְּגַוְונָא דָא אַרְבַּע סִטְרִין דִּילֵיהּ בְּהוֹן הֲוָה יהו\"ה הוּא וּשְׁמֵיהּ חַד, (דברים ד לה) אֵין עוֹד מִלְבַדוֹ בְּלָא פִּרוּד וּבְלָא שִׁתּוּף כְּלָל.</p>\n<p>וְעוֹד וְנָהָר דָּא ו', יוֹצֵא מֵעִדֶן דָּא י', וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים דָּא ד', (אלין ארבע אתוון). וְעוֹד וְנָהָר יוֹצֵא מֵעִדֶן דָּא אִימָּא עִלָּאָה דְאִיהִי א' תִּנְיָינָא, כְּמָה דְאוּקְמוּהוּ מָארֵי מַתְנִיתִין מַאי אַלֶּ\"ף אַלֵּף בִּינָה, וּלְאָן אִתְמַשַּׁךְ בְּגוּפָא, וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים אִלֵּין תְּרֵין דְּרוֹעִין וּתְרֵין שׁוֹקִין, מָאן גַּן דְּאִתְשַׁקְיָיא מִנֵּיהּ לְתַתָּא דָא שְׁכִינְתָּא, דִתְרֵין גַּנִּין אִינוּן חַד לְעִילָא וְחַד לְתַתָּא, הֲדָא הוּא דִכְתִיב (שיר ח יג) הַיּוֹשֶׁבֶת בַּגַּנִּים וְהָא אוּקְמוּהָ.</p>\n<p>וְאִית נָהָר לְתַתָּא דְּאִיהוּ מטטרו\"ן, דְּאִתְפָּרַשׁ לְאַרְבַּע סִטְרִין דְּאִינוּן מִיכָאֵ\"ל גַּבְרִיאֵ\"ל נוּרִיאֵ\"ל רְפָאֵ\"ל, שֵׁם הָאֶחָד פִּישׁוֹן הוּא הַסֹּבֵב אֵת כָּל אֶרֶץ הַחֲוִילָה אֲשֶׁר שָׁם הַזָּהָב (בראשית ב יא), וְזָהָב אִיהוּ לַצָּפוֹן, הֲדָא הוּא דִכְתִיב (איוב לז כב) מִצָּפוֹן זָהָב יֶאֱתָה, וְרָזָא דְמִלָּה הוֹלֵךְ אֶל צָפוֹן דָּא גַבְרִיאֵ\"ל, וּלְבָתַר הוֹלֵךְ אֶל דָּרוֹם (קהלת א ו) וְדָא גִּיחוֹן דְּתַמָּן מִיכָאֵ\"ל, הִפּוּכָא מִלְּעִילָא, דְאָמַר קְרָא עֲלֵיהּ הוֹלֵךְ אֶל דָּרוֹם בְּקַדְמֵיתָא, וּלְבָתַר סוֹבֵב אֶל צָפוֹן, סוֹבֵב סוֹבֵב לִתְרֵין סִטְרִין דְּאִינוּן מִזְרָח וּמַעֲרָב, דְּאִינוּן חִדֶּקֶל וּפְרָת, דְּתַמָּן אוּרִיאֵ\"ל רְפָאֵ\"ל.</p>\n<p>פִּישׁוֹן לָקֳבֵל אוֹרַיְיתָא דִבְעַל פֶּה, וּמִתַּמָּן פִּישׁוֹן, פִּי שׁוֹנֶה הֲלָכוֹת, גִּ\"יחוֹ\"ן ג' גּ\"וֹמֵל חֶסֶד, וְתַמָּן חֵיוָון דְּאִתְקְרִיאוּ חַיּוֹת הַקֹּדֶשׁ מִסִּטְרָא דְאַרְיֵה מִסִּטְרָא דִימִינָא, מִסִּטְרָא דִשְׂמָאלָא נָחָשׁ, דְּאִתְּמַר בֵּיהּ (ויקרא יא מב) כָּל הוֹלֵךְ עַל גָּחוֹן, לְאַעֲנָשָׁא בֵיהּ לְמָאן דְּאַעֲבַר עַל אוֹרַיְיתָא דְאִתְיְהִיבַת מִימִינָא, פִּישׁוֹן</p>"],[9500011176,"<p>תַּמָּן שְׁפִיפוֹן, לְאַעֲנָשָׁא לְמָאן דְּאַעֲבַר עַל אוֹרַיְיתָא דִבְעַל פֶּה, חִדֶּקֶל חַ\"ד קַ\"ל, דָּא חֲרִיפָא בְּלִישָׁנֵיהּ וְחַד מִסִּטְרָא דִימִינָא, קַ\"ל מִסִּטְרָא דִשְׂמָאלָא, לְאוֹלָפָא תַּרְוַיְיהוּ, חַ\"ד בְּשִׁנַּיִם, וְקַ\"ל בְּשִׂפְוָון, וּבְגִין דָּא פִּישׁוֹן פִּי שׁוֹנֶה הֲלָכוֹת, גִּיחוֹן גַּיחוֹן הַהוּא דְאִתְּמַר בֵּיהּ (דברים לד ו) וַיִּקְבּוֹר אותו בגי, תמן שריא לסטרא דימינא, פרת כליל כלהו, האי פריה ורביה, עליה אתמר (תהלים סח יד) אם תשכבון בין שפתים, אם ודאי למעבד תמן פריה ורביה.</p>\n<p>ובאלין ארבעה עאלו לפרדס אלין ארבעה, אלין דעאלו בקליפין חד הציץ ומת, חד הציץ ונפגע, וחד אשתמד (נ\"א נפק לתרבות רעה), רביעאה דעאל במוחא דאגוזא עאל בשלם ונפק בשלם, האי דאתמר ביה הציץ ונפגע, עאל בענג ולא עאל ביה כדקא יאות, אתהפך ליה לנגע, ודא נהר דיוצא מעדן, דאיהו סימן ענ\"ג ע'דן נ'הר ג'ן, הכא אסור והתר טומאה וטהרה כשר ופסול.</p>\n<p>ויקח יהו\"ה אלהי\"ם את האדם ויניחהו בגן עדן לעבדה ולשמרה (בראשית ב טו), תא חזי קודשא בריך הוא אוליף לאדם אורייתא, הדא הוא דכתיב (איוב כח כז) אז ראה ויספרה הכינה וגם חקרה ויאמר לאדם, ודא איהו ויניחהו בגן עדן, דא גן דאורייתא, לעבדה בפקודין דאורייתא דעשה דאיהו זכור דכר, ולשמרה בפקודין דלא תעשה דאיהו שמור נוקבא, את האדם דהוה בדיוקנא דאורייתא, דא\"ת לרבות אורייתא דאתיהיבת לאדם מא' ועד ת', דאתיהיבת מימינא וּמִשְּׂמָאלָא, דְתַמָּן פִּקּוּדִין דַּעֲשֵׂה וְלֹא תַעֲשֶׂה, פִּקּוּדִין דַּעֲשֵׂה מִימִינָא לָקֳבֵל ו\"ה זִכְרִ\"י וְדָא זִכְרוֹנוֹת, פִּקּוּדִין דְּלֹא תַעֲשֶׂה מִשְּׂמָאלָא לָקֳבֵל י\"ה שְׁמִ\"י, עַמּוּדָא דְאֶמְצָעִיתָא כְּלִיל תַּרְוַיְיהוּ יהו\"ה שְׁמֵיהּ, וְאִיהוּ קוֹל הַשּׁוֹפָר מִסִּטְרָא דְאִימָּא עִלָּאָה דְאִיהִי שׁוֹפָר, תְּקִיעָה אִיהִי מִסִּטְרָא דִימִינָא, וּשְׁבָרִים מִסִּטְרָא דִשְׂמָאלָא, שַׁלְשֶׁלֶ\"ת דְּאִיהִי תְּרוּעָה מִסִּטְרָא דְתַרְוַיְיהוּ.</p>\n<p>בְּרֵאשִׁית (בר\"א שי\"ת) בָּרָא אלהי\"ם, הַאי אלהי\"ם אִיהִי אִימָּא עִלָּאָה, דִּרְכִיבַת וּסְלִיקַת בִּתְרוּעָה (דאיהי ראש השנה הדא הוא דכתיב (תהלים מז ו) עלה אלהי\"ם בתרועה), דְּאִתְּמַר בֵּיהּ (במדבר כג כא) לֹא הִבִּיט אָוְן בְּיַעֲקֹב וְלֹא רָאָה עָמָל בְּיִשְׂרָאֵל יהו\"ה אֱלֹהָי\"ו עִמּוֹ וּתְרוּעַת מֶלֶךְ בּוֹ, הֲרֵי לָךְ דִּתְרוּעָה אִיהִי בְּיַעֲקֹב, וְאִתְּמַר בֵּיהּ עָלָה אלהי\"ם בִּתְרוּעָה, יהו\"ה בְּקוֹל שׁוֹפָר סָלִיק. תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר (תהלים פא ד) דָּא תְקִיעָה, וְדָא יַרְחָא דְסִיהֲרָא אִתְכַּסְיָיא, מַלְכִיּוֹת מִסִּטְרָא דְמַלְכוּת דְּאִיהוּ זֶה שְּׁמִי (שמות ג טו), דְתַמָּן קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּמוֹדָע לְמֶלֶךְ עַל כָּל הָאָרֶץ, וּבָהּ אִיהוּ הַמֶּלֶךְ הַקָּדוֹשׁ הַמֶּלֶךְ הַמִּשְׁפָּט מִסִּטְרָא דִשְׂמָאלָא, מֶלֶךְ עַל כָּל הָאָרֶץ אלהי\"ם, וְדָא לִבָּא לִשְׂמָאלָא מַלְכוּת, זִכְרוֹנוֹת זָכוֹר לַזָּכָר וְדָא מוֹחָא לִימִינָא וְתַמָּן זִכְרוֹנוֹת, שׁוֹפָרוֹת דָּא קָנָה דְאִיהוּ שׁוֹפָר, וּמִתַּמָּן נָפִיק קוֹל הַשּׁוֹפָר דְּאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, וְאִיהוּ יהו\"ה, בְּמוֹחָא בְּלִבָּא בְגוּפָא.</p>\n<p>וְאוּקְמוּהוּ מָארֵי מַתְנִיתִין, דְּלֵית פּוֹחֲתִין בֵּיהּ מֵעֲשָׂרָה מַלְכִיּוֹת וּמֵעֲשָׂרָה זִכְרוֹנוֹת וּמֵעֲשָׂרָה שׁוֹפָרוֹת, דָּא יו\"ד ה\"א וא\"ו ה\"א (נ\"א יו\"ד ה\"י וא\"ו ה\"י), מַלְכִיּוֹת וְתִמְלוֹךְ אַתָּה הוּא יהו\"ה אלהינ\"ו, זִכְרוֹנוֹת אַתָּה זוֹכֵר זָכְרֵנוּ לְחַיִּים, שׁוֹפָרוֹת תְּקַע בְּשׁוֹפָר גָּדוֹל.</p>\n<p>וְעוֹד תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ, מַאי בַּכֶּסֶה דָא שְׁכִינְתָּא תַּתָּאָה, וּבָהּ כָּתְבֵנוּ לְחַיִּים, דְּאִיהִי כְּתִיבָה מִסִּטְרָא דִימִינָא וּמִסִּטְרָא דִשְׂמָאלָא, וּבְגִין דְּאִתְאַחַד בֵּיהּ אַדְכִּיר תְּרֵין זִמְנִין כְּתִיבָה (נ\"א דאיהו יד עלאה יד תתאה), (נ\"א אמא תתאה מסטרא דשמאלא איהי) בַּכֶּסֶה בְּהַהוּא דְאִתְּמַר בֵּיהּ בַּמְּכוּסֶה מִמָּךְ אַל תַּחְקוֹר, כָּתְבֵנוּ לְחַיִּים אִיהוּ בַּקְּרָא דָא (שמות לב) וְהַלֻּחוֹת מַעֲשֵׂה אלהי\"ם הֵמָּה וְהַמִּכְתָּב מִכְתַּב אלהי\"ם הוּא חָרוּת עַל הַלֻּחֹת (שמות לב טז), מַאי חָרוּת דָּא ה', דְּאִתְּמַר בָּהּ (ויקרא כה י) וּקְרָאתֶם דְּרוֹר בָּאָרֶץ, דְּרוֹר אִיהִי חֵרוּת, וְ\"הַלֻּחוֹ\"ת אִינוּן ו\"ה בְּרָא וּבְרַתָּא, וְאִינוּן מַעֲשֵׂה אלהי\"ם דְּאִיהִי אִימָּא עִלָּאָה, מַעֲשֶׂה אִיהוּ בִּתְרֵין יְדִין דְּתַמָּן עֲשִׂיָּה, וּמִכְתַּב אלהי\"ם בִּתְרֵין יְדַיִן</p>"],[9500011177,"<p>דְּתַמָּן כְּתִיבָה, וְאִיהִי חָרוּת עַל הַלֻּחֹת, יָד כּוֹתֶבֶת וְיָד חוֹתֶמֶת, וְאִיהִי חַד יָד הַגְּדוֹלָה דְאִתְּמַר בָּהּ (שמות יד לא) וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה, וְתִנְיָינָא יָד הַחֲזָקָה הֲדָא הוּא דִכְתִיב (דברים ד לד) וּבְיָד חֲזָקָה וכו', וְרָזָא דְמִלָּה יהו\"ה אלהינ\"ו יהו\"ה יָ\"ד הַגְּדוֹלָה. כוז\"ו במוכס\"ז כוז\"ו יָ\"ד הַחֲזָקָה, וְאִינוּן, יָד עִלָּאָה מִסִּטְרָא דִימִינָא, יָד תַּתָּאָה מִסִּטְרָא דִשְׂמָאלָא, וְכֹלָּא כ\"ח פִּרְקִין, דְּאִתְּמַר בְּהוֹן (במדבר יד יז) וְעַתָּה יִגְדַּל נָא כֹּחַ אדנ\"י, וְדָא כֹּחַ מַעֲשָׂיו הִגִּיד לְעַמּוֹ (תהלים קיא ו), כֹּחַ מַעֲשֵׂה בְּרֵאשִׁית.</p>\n<p>וְעוֹד אִית יָ\"ד דְּאִתְקְרֵי יָד רָמָה, וְדָא יהו\"ה יו\"ד ה\"א וא\"ו ה\"א, וְאִית יָד תִּנְיָינָא לְקַבָּלָה וְדָא אהי\"ה אל\"ף ה\"א יו\"ד ה\"א, וְדָא כ\"ח, בְּזִמְנָא דְחָאבוּ יִשְׂרָאֵל אִסְתַּלַּק הַאי כֹּחַ מִנַּיְיהוּ וְאִתְּמַר בְּהוֹן (איכה א ו) וַיֵּלְכוּ בְלֹא כֹחַ לִפְנֵי רוֹדֵף.</p>\n<p>וּבְמַלְאָכִים כתב\"יאל מְמַנָּא עַל הַכְּתִיבָה, חתמי\"אל עַל הַחֲתִימָה, כתבי\"אל כְּתָ\"ב אֵלִ\"י, אֵלִ\"י אִיהוּ אֵ\"ם בְּחוּשְׁבָּן, זֶה אֵלִי וְאַנְוִהוּ (שמות טו ב), כְּתָב כ' כֶּתֶר ת' תּוֹרָה ב' בְּרָכָה, וְכֹלָּא אִימָּא עִלָּאָה, אִיהִי כֶּתֶר בְּרֹאשׁ כָּל צַדִּיק, וְאִיהִי תּוֹרַת יהו\"ה תְּמִימָה (תהלים יט ח), וְאִיהִי בִּרְכַּת יהו\"ה הִיא תַּעֲשִׁיר (משלי י כב), חתמי\"אל מִסִּטְרָא דְחָכְמָה, וְתַרְוַיְיהוּ חַיִּים, חָכְמָה דִכְתִיב (קהלת ז יב) הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ, אִימָּא עִלָּאָה עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ (משלי ג יח), וְתַרְוַיְיהוּ לִימִינָא וּשְׂמָאלָא.</p>\n<p>תְּלַת אֶצְבָּעִין מִתְיַיחֲדִין בְּקוֹלְמוֹס לַכְּתִיבָה, וַעֲלַיְיהוּ אָמַר בֶּן זוֹמָא, אֵין בֵּין מַיִם הָעֶלְיוֹנִים לְמַיִם הַתַּחְתּוֹנִים, אֶלָּא כְשָׁלֹשׁ אֶצְבָּעוֹת, וּתְרֵין אֶצְבְּעָאן אִינוּן דְּסָמְכִין לוֹן, וְאִינוּן כִּתְרֵי גְלִימֵי דִסְחִיפֵי אַהֲדָדֵי, רזי\"אל אִיהוּ אוּרִיאֵ\"ל, וַעֲלֵיהּ אִתְּמַר (שמות ג טו) וְזֶה זִכְרִ\"י עִם ו\"ה רְמַ\"ח, וְדָא רזיא\"ל, שְׁמִי עִם י\"ה שְׁסָ\"ה ש מועא\"ל מ טטרו\"ן י הוא\"ל רָאשֵׁי תֵּיבִין שְׁמִי, חסדיא\"ל מִסִּטְרָא דְחֶסֶד, גַּבְרִיאֵ\"ל מִסִּטְרָא דִגְבוּרָה, אוּרִיאֵ\"ל מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, בְּכָל סִטְרָא אֵלִי אִיהוּ מִסִּטְרָא דְאֵם, וְאִינוּן אֵלִ\"י א' כֶּתֶר י' חָכְמָה ה' אִימָּא עִלָּאָה, דְאִיהִי מִגְדַּל עוֹז שֵׁם יהו\"ה (משלי יח י).</p>\n<p>וְעוֹד אָמַר הַהוּא סָבָא רַבִּי רַבִּי, וְהַמִּכְתָּב מִכְתַּב אלהי\"ם הוּא (שמות לב טז), תְּרֵין יְדַיִן כּוֹתְבוֹת מִימִינָא וּמִשְּׂמָאלָא, אֲבָל חָרוּת עַל הַלּוּחוֹת עַמּוּדָא דְאֶמְצָעִיתָא, (נ\"א בן י\"ה איהו ודאי), כַּמָּה מַלְאָכַיָּא סַפְרַיָּא אִית לְעֵילָא דְכָתְבִין זַכְוָון דְּיִשְׂרָאֵל, וְכַמָּה מַלְאָכַיָּא דְחוֹתָמָא דְמַלְכָּא בִּידֵיהוֹן דְּחָתְמִין זַכְוָון דְּיִשְׂרָאֵל, וְכַמָּה מַלְאָכַיָּא אִינוּן שָׁקְלִין קַלִּין וַחֲמוּרִין דְּאוֹרַיְיתָא, הֲדָא הוּא דִכְתִיב (ישעיה לג יח) אַיֵּה סוֹפֵר אַיֵּה שׁוֹקֵל, וְכַד אִיהוּ חָתִים בְּטַבַּעַת הַמֶּלֶךְ דְּאִיהוּ ו' (נ\"א י') אֵין לְהָשִׁיב, חוֹתָם אִיהוּ ו' חוֹתָם אֶמֶת, יָד כּוֹתֵב וְיָד חוֹתֵם ה' תַּתָּאָה כּוֹתֵב ה' עִלָּאָה חוֹתֵם, דְּאִינוּן ה' אֶצְבְּעָאן דְּיָד יְמִינָא וְה' אֶצְבְּעָאן דְּיָד שְׂמָאלָא, ה' תַּתָּאָה כּוֹתֵב בְּאָת ו' דְּאִיהוּ קוֹלְמוֹס, קָנֶה דִדְרוֹעָא ה' עִלָּאָה חוֹתָם בְּאָת י' דְּאִיהוּ כַּף הַיָּד.</p>\n<p>שֵׁ\"ם הַדּוֹרֵ\"שׁ אִיהוּ צַדִּיק, עֲלֵיהּ אִתְּמַר (ישעיה נ ד) יהו\"ה אלהי\"ם נָתַן לִי לְשׁוֹן לִמּוּדִים, וְדָא (ז') יו\"ד זְעִירָא, לָדַעַת לָעוּת אֶת יָעִף דָּבָר (שם), אִינוּן ה\"ה, דִּבְהוֹן וְעוֹף יְעוֹפֵף עַל הָאָרֶץ (בראשית א כ), וּנְקוּדָה דְשֵׁם הַכּוֹתֵב, וְהַמִּכְתָּב מִכְתַּב אלהי\"ם הוּא דָא יְהִוֶהוּ, שֵׁ\"ם הַדּוֹרֵ\"שׁ, יהו\"ה אלהי\"ם נָתַן לִי לְשׁוֹן לִמּוּדִים, לָדַעַת לָעוּת אֶת יָעִף דָּבָר וְדָא יָהָוְהָ, יְדִיעַת קוּדְשָׁא בְּרִיךְ הוּא בִּשְׁכִינְתֵּיהּ, בְּהַאי נְקוּדָה יִתְהַלֵּל הַמִּתְהַלֵּל הַשְׂכֵּל וְיָדוֹעַ (ירמיה ט כג), וְדָא יִהַהַוְ.</p>\n<p>כָּל אִלֵּין נְקוּדִין צָרִיךְ לְנַקְדָא לוֹן מִקְּרָאִין דְּאוֹרַיְיתָא, כְּמָה דְאִינוּן כְּתִיבִין בְּאֹרַח קְשׁוֹט, וְכָל הֲוַיָּ\"ה אִית לָהּ מְשַׁמְּשָׁא דְרָכִיב עֲלֵיהּ, וְאִיהִי מֶרְכָּבָה לֵיהּ, וְהַהִיא הֲוַיָּ\"ה אִית לָהּ מַנְהִיגָא דְשַׁלִּיט עֲלֵיהּ, כְּגוֹן דְּכוּרָא עַל נוּקְבָא, וְלֵית רְשׁוּ לְנוּקְבָא וְלָא לִשְׁלוּחָא דִילָהּ לְמֶעֱבַד מִדָּעַם בְּלָא רְשׁוּת בַּעִִלָהּ, דְּכָל מָאן דִּמְקַבֵּל</p>"],[9500011178,"<p>אִיהִי נוּקְבָא, מֵאֲתַר דְּאִיהוּ מְקַבֵּל, וְרָזָא דְמִלָּה (קהלת ה ז) כִּי גָבוֹהַּ מֵעַל גָּבוֹהַּ שׁוֹמֵר, וּכְגַוְונָא דָא שְׁלִיחָא לְעִילָא מטטרו\"ן, וְכַמָּה מְמַנָּן דִּתְּחוֹת יְדֵיהּ דְּאִינוּן שְׁלִיחָן דִּשְׁכִינְתָּא, וּשְׁכִינְתָּא אִיהִי נוּקְבָא, לֵית לָהּ רְשׁוּ לְאַזְלָא לְשׁוּם אֲתַר בְּלָא רְשׁוּ בַּעִִלָהּ, וְרָזָא דְמִלָּה וְיִקְחוּ לִי תְּרוּמָה (שמות כה ב), אִם אַתּוּן בְּעִיתוּן דְּשַׁרְיָא שְׁכִנְתִּי בֵינֵיכוֹן, וְיִקְחוּ לִי, נְסִיבוּ מִנִּי רְשׁוּ בְּקַדְמֵיתָא לְאִתְגַּלְיָא.</p>\n<p>בְּרֵאשִׁית בָּרָא אלהי\"ם, אלהי\"ם הָא אוּקְמוּהָ תַּמָּן דְּחִילוּ מִסִּטְרָא דְאָת ה' (נ\"א ה\"י), דְּאִיהִי לִשְׂמָאלָא, דְּאַף עַל גַּב דְּאָת י' אִיהוּ רַחֲמֵי, בַּאֲתַר דְּשַׁלְטָא ה' עֲלָהּ נוּקְבָא אִתְקְרִיאַת, כְּגַוְונָא דָא ה\"י, וְרָזָא דָא אִתְגַּלְיָיא (בי\"ה ה\"א וא\"ו ה\"א) יו\"ד ה\"י וא\"ו ה\"י (ס\"א ביו\"ד ה\"א וא\"ו ה\"א) דְּלֵית בִּרְיָה בְלָא דְכַר וְנוּקְבָא, דִּתְרֵין שׁוּתָּפִין אִינוּן בִּבְרָא וּבְרַתָּא, אַבָּא וְאִימָּא, חַד יָהֵיב טִפָּה דְכוּרָא וְחַד נוּקְבָא, וְכַד שַׁלִּיט דְּכוּרָא עַל נוּקְבָא אִיהוּ דְכַר, וְכַד שַׁלִּיט נוּקְבָא עַל דְּכוּרָא אִיהוּ נוּקְבָא, וְהָא אוּקְמוּהוּ בְּרָזָא דְאִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר (ויקרא יב ב).</p>\n<p>וְרָזָא עִלָּאָה הָכָא, לְזִמְנִין אִזְדַּרִיקוּ תְּרֵין טִפִּין, לְזִמְנִין תְּלַת, לְזִמְנִין אַרְבַּע, לְזִמְנִין ה', לְזִמְנִין ו', לְזִמְנִין ז', וְדָא רָזָא דִסְלִיקוּ לְמִטָּה תְּרֵין וְנָחְתוּ שִׁבְעָה, תְּרֵין טִפִּין אִינוּן לְזִמְנִין צֵרִ\"י וּלְזִמְנִין שְׁבָ\"א, תְּלַת לְזִמְנִין אִינוּן סֶגוֹ\"ל וּלְזִמְנִין שׁוּרֵ\"ק, לְזִמְנִין שֶׁבַע כְּגַוְונָא דָא ז' מִן זֶרַע, וּתְלַת טִפִּין צְרִיכִין נְטִירוּ מִן כָּבֵ\"ד טְחוֹ\"ל מָרָ\"ה, דְאִתְּמַר בְּהוֹן (בראשית ב טז) וַיְצַו יהו\"ה אלהי\"ם עַל הָאָדָם, וְאוּקְמוּהוּ לֵית צַו אֶלָּא עֲבוֹדָה זָרָה, וְדָא כָבֵד, דְּאִתְּמַר בָּהּ כָּל הַכּוֹעִס כְּאִלּוּ עוֹבֵד עֲבוֹדָה זָרָה, וּבְגִין דָּא לָא צָרִיךְ לְאַרָקָא טִפִּין אֶלָּא בִרְחִימוּ, וְלָא בְכַעִִסָא וּבִקְטָטָה, וְכַד זָרִיק בַּר נַשׁ אִלֵּין תְּלַת טִפִּין בִּרְחִימוּ אִתְקְרִיאוּ סֶגוֹלְתָּ\"א, וְרָזָא דְמִלָּה זַרְקָ\"א מַקַּ\"ף שׁוֹפָר הוֹלֵךְ סֶגוֹלְ\"תָּא. עַל הָאָדָם דָּא שְׁפִיכוּת דָּמִים, הֲדָא הוּא דִכְתִיב (שם ט ו) בָּאָדָם דָּמוֹ יִשָּׁפֵךְ, דָּא אִתְעָרוּתָא דְטִפָּה דְנוּקְבָא דְאִיהִי מִלֵּיחָה סוּמָקָא, וְאִי אִיהִי סֶגוֹ\"ל נְקוּדָה לְתַתָּא אִיהִי נוּקְבָא, נְקוּדָה דִלְעִילָא דְכַר, וְכַד זָרִיק לָהּ בְּמָרָ\"ה דְאִיהִי גֵיהִנָּם קְטִילַת (לה).</p>\n<p>לֵאמֹר (בראשית ב טז) דָּא גִלּוּי עֲרָיוֹת, וְדָא טְחוֹ\"ל, מָאן דְּזָרִיק טִפָּה בְּאִתְּתֵיהּ בַּעֲצִיבוּ וּבִקְטָטָה, אִתְגְּלִיאַת בֵּיהּ עִִרְיָיתָא, וּבְגִין דָּא עִִרְוַת אָבִיךָ וְעִִרְוַת אִמְּךָ לֹא תְגַלֵּה (ויקרא יח ז), אִיהִי טְחוֹל לִילִית, מָרָה אוּכְמָא עִִרְוָה דְכֹלָּא (נ\"א דכלה).</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אַבָּא, שִׁעוּרָא דַעֲרָיוֹת אִינוּן בַּאֲתַר יְדִיעַ אוֹ לָא, אָמַר לֵיהּ בְּרִי, יהו\"ה אִיהוּ י' אָב ה' אֵם ו' בֵּן ה' בַּת, ה\"ה אִינוּן אִשָּׁה וּבִתָּהּ כַּלָּה וַחֲמוֹתָהּ, כְּפוּם עַנְפִין דְּאִילָנָא הָכִי אִתְקְרִיאוּ, עַנְפִין דְּאִילָנָא מִתְפָּרְשִׁין לְעִילָא בְּאִילָנָא, כְּמָה דְאוּקְמוּהוּ וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת מִלְמָעִִלָה, וַעֲלֵיהֶן אִתְּמַר (דברים כג א) וְלֹא יְגַלֶּה כְּנַף אָבִיו, וְאִינוּן מִתְיַחֲדִין לְתַתָּא.</p>\n<p>כְּגוֹן לוּלָב דְּאִיהוּ אֲגוּדָה חֲדָא לְתַתָּא בְכָל אִלֵּין מִינִין דַּהֲדַס וַעֲרָבָה, דְאִינוּן תְּלַת הֲדַסִּין, וּתְרֵין עֲרָבוֹת, וְאִיהוּ בְּפִרוּדָא לְעִילָא, דְּעַנְפִין מִתְפָּרְדִין לִימִינָא וּשְׂמָאלָא, וּבְגִין דָּא נִפְרְצוּ עַלָּיו פָּסוּל, נִפְרְדוּ עַלָּיו כָּשֵׁר, וְהַאי פֶּרֶץ אִיהוּ פָּרוּץ בְּעִִרְוָה דְאִיהוּ בֵין עַנְפָא וְעַנְפָא, וּבְגִין דָּא אִתְּמַר תַּמָּן (ויקרא יח ו) לֹא תִקְרְבוּ לְגַלּוֹת עִִרְוָה, לַאו צָרִיךְ לְקָרְבָא אַתְוָון דְּאִינוּן יהו\"ה בַּאֲתַר</p>"]]});
